const e=[{id:0,oaid:"91deaf9d324c8feafc189da0da03e60a60287bca",doi:"10.1109/ICRA48891.2023.10160591",title:"Code as Policies: Language Model Programs for Embodied Control",authors:[{name:"Jacky Liang",institutions:[]},{name:"Wenlong Huang",institutions:[]},{name:"F. Xia",institutions:[]},{name:"Peng Xu",institutions:[]},{name:"Karol Hausman",institutions:[]},{name:"Brian Ichter",institutions:[]},{name:"Peter R. Florence",institutions:[]},{name:"Andy Zeng",institutions:[]}],authorString:"Jacky Liang; Wenlong Huang; F. Xia; Peng Xu; Karol Hausman; Brian Ichter; Peter R. Florence; Andy Zeng",institutions:[],countries:[],year:2022,journal:"IEEE International Conference on Robotics and Automation",citations:1741,abstract:"Large language models (LLMs) trained on code-completion have been shown to be capable of synthesizing simple Python programs from docstrings [1]. We find that these code-writing LLMs can be re-purposed to write robot policy code, given natural language commands. Specifically, policy code can express functions or feedback loops that process perception outputs (e.g., from object detectors [2], [3]) and parameterize control primitive APIs. When provided as input several example language commands (formatted as comments) followed by corresponding policy code (via few-shot prompting), LLMs can take in new commands and autonomously re-compose API calls to generate new policy code respectively. By chaining classic logic structures and referencing third-party libraries (e.g., NumPy, Shapely) to perform arithmetic, LLMs used in this way can write robot policies that (i) exhibit spatial-geometric reasoning, (ii) generalize to new instructions, and (iii) prescribe precise values (e.g., velocities) to ambiguous descriptions (‘faster’) depending on context (i.e., behavioral commonsense). This paper presents Code as Policies: a robot-centric formulation of language model generated programs (LMPs) that can represent reactive policies (e.g., impedance controllers), as well as waypoint-based policies (vision-based pick and place, trajectory-based control), demonstrated across multiple real robot platforms. Central to our approach is prompting hierarchical code-gen (recursively defining undefined functions), which can write more complex code and also improves state-of-the-art to solve 39.8% of problems on the HumanEval [1] benchmark. Code and videos are available at https://code-as-policies.github.io",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2209.07753",is_oa:!0,n_refs:61,n_refs_in_core:35,degree:48,community:4,deg_w:304,betweenness:.0672,pagerank:.00894,eigenvector:.0081},{id:1,oaid:"9e8b7b0d4c628c12b6a65ab56ac5f33a35eff2e6",doi:"10.1109/TKDE.2024.3352100",title:"Unifying Large Language Models and Knowledge Graphs: A Roadmap",authors:[{name:"Shirui Pan",institutions:[]},{name:"Linhao Luo",institutions:[]},{name:"Yufei Wang",institutions:["Macquarie University"]},{name:"Chen Chen",institutions:[]},{name:"Jiapu Wang",institutions:[]},{name:"Xindong Wu",institutions:[]}],authorString:"Shirui Pan; Linhao Luo; Yufei Wang; Chen Chen; Jiapu Wang; Xindong Wu",institutions:["Macquarie University"],countries:[],year:2023,journal:"IEEE Transactions on Knowledge and Data Engineering",citations:1655,abstract:"Large language models (LLMs), such as ChatGPT and GPT4, are making new waves in the field of natural language processing and artificial intelligence, due to their emergent ability and generalizability. However, LLMs are black-box models, which often fall short of capturing and accessing factual knowledge. In contrast, Knowledge Graphs (KGs), Wikipedia, and Huapu for example, are structured knowledge models that explicitly store rich factual knowledge. KGs can enhance LLMs by providing external knowledge for inference and interpretability. Meanwhile, KGs are difficult to construct and evolve by nature, which challenges the existing methods in KGs to generate new facts and represent unseen knowledge. Therefore, it is complementary to unify LLMs and KGs together and, simultaneously, leverage their advantages. In this article, we present a forward-looking roadmap for the unification of LLMs and KGs. Our roadmap consists of three general frameworks, namely: 1) KG-enhanced LLMs, which incorporate KGs during the pre-training and inference phases of LLMs, or for the purpose of enhancing understanding of the knowledge learned by LLMs; 2) LLM-augmented KGs, that leverage LLMs for different KG tasks such as embedding, completion, construction, graph-to-text generation, and question answering; and 3) Synergized LLMs + KGs, in which LLMs and KGs play equal roles and work in a mutually beneficial way to enhance both LLMs and KGs for bidirectional reasoning driven by both data and knowledge. We review and summarize existing efforts within these three frameworks in our roadmap and pinpoint their future research directions.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2306.08302",is_oa:!0,n_refs:275,n_refs_in_core:88,degree:102,community:1,deg_w:803,betweenness:.1777,pagerank:.02389,eigenvector:.3389},{id:2,oaid:"6c943670dca38bfc7c8b477ae7c2d1fba1ad3691",doi:null,title:"Program of Thoughts Prompting: Disentangling Computation from Reasoning for Numerical Reasoning Tasks",authors:[{name:"Wenhu Chen",institutions:["University of Waterloo"]},{name:"Xueguang Ma",institutions:["University of Waterloo"]},{name:"Xinyi Wang",institutions:["UC Santa Barbara"]},{name:"William W. Cohen",institutions:["Google"]}],authorString:"Wenhu Chen; Xueguang Ma; Xinyi Wang; William W. Cohen",institutions:["Google","UC Santa Barbara","University of Waterloo"],countries:[],year:2022,journal:"Trans. Mach. Learn. Res.",citations:1435,abstract:"Recently, there has been significant progress in teaching language models to perform step-by-step reasoning to solve complex numerical reasoning tasks. Chain-of-thoughts prompting (CoT) is by far the state-of-art method for these tasks. CoT uses language models to perform both reasoning and computation in the multi-step `thought' process. To disentangle computation from reasoning, we propose `Program of Thoughts' (PoT), which uses language models (mainly Codex) to express the reasoning process as a program. The computation is relegated to an external computer, which executes the generated programs to derive the answer. We evaluate PoT on five math word problem datasets (GSM, AQuA, SVAMP, TabMWP, MultiArith) and three financial-QA datasets (FinQA, ConvFinQA, TATQA) for both few-shot and zero-shot setups. Under both few-shot and zero-shot settings, PoT can show an average performance gain over CoT by around 12\\% across all the evaluated datasets. By combining PoT with self-consistency decoding, we can achieve SoTA performance on all math problem datasets and near-SoTA performance on financial datasets. All of our data and code are released in Github https://github.com/wenhuchen/Program-of-Thoughts",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:49,n_refs_in_core:20,degree:35,community:5,deg_w:221,betweenness:.0347,pagerank:.00767,eigenvector:.0141},{id:3,oaid:"3f5e922ce20efe7da64c115e5346481cfc618b79",doi:"10.1016/S1364-6613(02)00029-3",title:"Grounding conceptual knowledge in modality-specific systems.",authors:[{name:"L. Barsalou",institutions:[]},{name:"W. Kyle Simmons",institutions:[]},{name:"A. Barbey",institutions:[]},{name:"Christine D. Wilson",institutions:[]}],authorString:"L. Barsalou; W. Kyle Simmons; A. Barbey; Christine D. Wilson",institutions:[],countries:[],year:2003,journal:"Trends in Cognitive Sciences",citations:1197,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:3,deg_w:4,betweenness:0,pagerank:36e-5,eigenvector:0},{id:4,oaid:"848aa2210061b6bab6f3dbe7df9c190bf1c79c27",doi:"10.1145/3178876.3186175",title:"DKN: Deep Knowledge-Aware Network for News Recommendation",authors:[{name:"Hongwei Wang",institutions:["Stanford University"]},{name:"Fuzheng Zhang",institutions:[]},{name:"Xing Xie",institutions:[]},{name:"M. Guo",institutions:[]}],authorString:"Hongwei Wang; Fuzheng Zhang; Xing Xie; M. Guo",institutions:["Stanford University"],countries:[],year:2018,journal:"The Web Conference",citations:1197,abstract:"Online news recommender systems aim to address the information explosion of news and make personalized recommendation for users. In general, news language is highly condensed, full of knowledge entities and common sense. However, existing methods are unaware of such external knowledge and cannot fully discover latent knowledge-level connections among news. The recommended results for a user are consequently limited to simple patterns and cannot be extended reasonably. To solve the above problem, in this paper, we propose a deep knowledge-aware network (DKN) that incorporates knowledge graph representation into news recommendation. DKN is a content-based deep recommendation framework for click-through rate prediction. The key component of DKN is a multi-channel and word-entity-aligned knowledge-aware convolutional neural network (KCNN) that fuses semantic-level and knowledge-level representations of news. KCNN treats words and entities as multiple channels, and explicitly keeps their alignment relationship during convolution. In addition, to address users» diverse interests, we also design an attention module in DKN to dynamically aggregate a user»s history with respect to current candidate news. Through extensive experiments on a real online news platform, we demonstrate that DKN achieves substantial gains over state-of-the-art deep recommendation models. We also validate the efficacy of the usage of knowledge in DKN.",keywords:[],concepts:[],pdf_url:"http://dl.acm.org/ft_gateway.cfm?id=3186175&type=pdf",is_oa:!0,n_refs:58,n_refs_in_core:1,degree:10,community:0,deg_w:43,betweenness:.02,pagerank:.00147,eigenvector:.0148},{id:5,oaid:"5e2bb96c47ccaa16a4e7192e8fadb3b3e1c3acdc",doi:null,title:"Deep Learning: A Critical Appraisal",authors:[{name:"G. Marcus",institutions:[]}],authorString:"G. Marcus",institutions:[],countries:[],year:2018,journal:"arXiv.org",citations:1190,abstract:`Although deep learning has historical roots going back decades, neither the term "deep learning" nor the approach was popular just over five years ago, when the field was reignited by papers such as Krizhevsky, Sutskever and Hinton's now classic (2012) deep network model of Imagenet. What has the field discovered in the five subsequent years? Against a background of considerable progress in areas such as speech recognition, image recognition, and game playing, and considerable enthusiasm in the popular press, I present ten concerns for deep learning, and suggest that deep learning must be supplemented by other techniques if we are to reach artificial general intelligence.`,keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:73,n_refs_in_core:23,degree:35,community:2,deg_w:163,betweenness:.0528,pagerank:.00909,eigenvector:5e-4},{id:6,oaid:"19f7f38cd8661187fd8ddcec7d30332059102c21",doi:"10.1126/science.283.5398.77",title:"Rule learning by seven-month-old infants.",authors:[{name:"G. Marcus",institutions:[]},{name:"S. Vijayan",institutions:[]},{name:"S. Rao",institutions:[]},{name:"P. Vishton",institutions:[]}],authorString:"G. Marcus; S. Vijayan; S. Rao; P. Vishton",institutions:[],countries:[],year:1999,journal:"Science",citations:1189,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:2,deg_w:12.5,betweenness:2e-4,pagerank:86e-5,eigenvector:0},{id:7,oaid:"0da8af8d81e84381ffe656a0bbf2f3937ffac618",doi:"10.1109/CVPR.2018.00611",title:"Neural Motifs: Scene Graph Parsing with Global Context",authors:[{name:"Rowan Zellers",institutions:["University of Washington"]},{name:"Mark Yatskar",institutions:[]},{name:"Sam Thomson",institutions:[]},{name:"Yejin Choi",institutions:[]}],authorString:"Rowan Zellers; Mark Yatskar; Sam Thomson; Yejin Choi",institutions:["University of Washington"],countries:[],year:2017,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:1184,abstract:"We investigate the problem of producing structured graph representations of visual scenes. Our work analyzes the role of motifs: regularly appearing substructures in scene graphs. We present new quantitative insights on such repeated structures in the Visual Genome dataset. Our analysis shows that object labels are highly predictive of relation labels but not vice-versa. We also find that there are recurring patterns even in larger subgraphs: more than 50% of graphs contain motifs involving at least two relations. Our analysis motivates a new baseline: given object detections, predict the most frequent relation between object pairs with the given labels, as seen in the training set. This baseline improves on the previous state-of-the-art by an average of 3.6% relative improvement across evaluation settings. We then introduce Stacked Motif Networks, a new architecture designed to capture higher order motifs in scene graphs that further improves over our strong baseline by an average 7.1% relative gain. Our code is available at github.com/rowanz/neural-motifs.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1711.06640",is_oa:!0,n_refs:62,n_refs_in_core:5,degree:22,community:3,deg_w:235,betweenness:.0028,pagerank:.00475,eigenvector:.0019},{id:8,oaid:"d9917e59df7184d1f3d35b43c74fe4a28c0bbf76",doi:"10.1016/S0967-5868(96)90015-6",title:"Consciousness",authors:[{name:"R. Newcombe",institutions:[]}],authorString:"R. Newcombe",institutions:[],countries:[],year:1996,journal:"Journal of clinical neuroscience",citations:1183,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:59e-5,eigenvector:0},{id:9,oaid:"7ba9c013988eaff5cd186d73704af329d027872d",doi:"10.1109/ICCV48922.2021.00180",title:"MDETR - Modulated Detection for End-to-End Multi-Modal Understanding",authors:[{name:"Aishwarya Kamath",institutions:[]},{name:"Mannat Singh",institutions:["Facebook AI Research (FAIR)"]},{name:"Yann LeCun",institutions:["Facebook","NYU"]},{name:"Ishan Misra",institutions:[]},{name:"Gabriel Synnaeve",institutions:[]},{name:"Nicolas Carion",institutions:[]}],authorString:"Aishwarya Kamath; Mannat Singh; Yann LeCun; Ishan Misra; Gabriel Synnaeve; Nicolas Carion",institutions:["Facebook","Facebook AI Research (FAIR)","NYU"],countries:[],year:2021,journal:"IEEE International Conference on Computer Vision",citations:1183,abstract:"Multi-modal reasoning systems rely on a pre-trained object detector to extract regions of interest from the image. However, this crucial module is typically used as a black box, trained independently of the downstream task and on a fixed vocabulary of objects and attributes. This makes it challenging for such systems to capture the long tail of visual concepts expressed in free form text. In this paper we propose MDETR, an end-to-end modulated detector that detects objects in an image conditioned on a raw text query, like a caption or a question. We use a transformer-based architecture to reason jointly over text and image by fusing the two modalities at an early stage of the model. We pre-train the network on 1.3M text-image pairs, mined from pre-existing multi-modal datasets having explicit alignment between phrases in text and objects in the image. We then fine-tune on several downstream tasks such as phrase grounding, referring expression comprehension and segmentation, achieving state-of-the-art results on popular benchmarks. We also investigate the utility of our model as an object detector on a given label set when fine-tuned in a few-shot setting. We show that our pre-training approach provides a way to handle the long tail of object categories which have very few labelled instances. Our approach can be easily extended for visual question answering, achieving competitive performance on GQA and CLEVR. The code and models are available at https://github.com/ashkamath/mdetr.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2104.12763",is_oa:!0,n_refs:72,n_refs_in_core:7,degree:25,community:3,deg_w:194.5,betweenness:.0162,pagerank:.00461,eigenvector:.0047},{id:10,oaid:"b85ae9f4367548a7dac7eae1a2a8d5866d27813a",doi:"10.1145/321356.321363",title:"On the Length of Programs for Computing Finite Binary Sequences",authors:[{name:"G. Chaitin",institutions:[]}],authorString:"G. Chaitin",institutions:[],countries:[],year:1966,journal:"JACM",citations:1181,abstract:"",keywords:[],concepts:[],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/321356.321363",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:8,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:11,oaid:"3b24cf031cca18358bc29786c9912104b28cfa2b",doi:null,title:"Noname manuscript No. (will be inserted by the editor) Hyper-heuristics: A Survey of the State of the Art",authors:[],authorString:"",institutions:[],countries:[],year:null,journal:"",citations:1168,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:8,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:12,oaid:"a13fcba4fab4713d5acb2d970eddc6b148d2596d",doi:null,title:"A Survey of Parallel Genetic Algorithms",authors:[{name:"E. Cantú-Paz",institutions:[]}],authorString:"E. Cantú-Paz",institutions:[],countries:[],year:2e3,journal:"",citations:1163,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:8,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:13,oaid:"e9bd6f0b04a0ddf9fcdf3a5fd1cfe87f8ae9cfff",doi:"10.1109/ICCV.2017.563",title:"TALL: Temporal Activity Localization via Language Query",authors:[{name:"J. Gao",institutions:[]},{name:"Chen Sun",institutions:[]},{name:"Zhenheng Yang",institutions:[]},{name:"R. Nevatia",institutions:[]}],authorString:"J. Gao; Chen Sun; Zhenheng Yang; R. Nevatia",institutions:[],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:1162,abstract:"This paper focuses on temporal localization of actions in untrimmed videos. Existing methods typically train classifiers for a pre-defined list of actions and apply them in a sliding window fashion. However, activities in the wild consist of a wide combination of actors, actions and objects; it is difficult to design a proper activity list that meets users’ needs. We propose to localize activities by natural language queries. Temporal Activity Localization via Language (TALL) is challenging as it requires: (1) suitable design of text and video representations to allow cross-modal matching of actions and language queries; (2) ability to locate actions accurately given features from sliding windows of limited granularity. We propose a novel Cross-modal Temporal Regression Localizer (CTRL) to jointly model text query and video clips, output alignment scores and action boundary regression results for candidate clips. Lor evaluation, we adopt TaCoS dataset, and build a new dataset for this task on top of Charades by adding sentence temporal annotations, called Charades-STA. We also build complex sentence queries in Charades-STA for test. Experimental results show that CTRL outperforms previous methods significantly on both datasets.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1705.02101",is_oa:!0,n_refs:36,n_refs_in_core:0,degree:12,community:3,deg_w:79,betweenness:2e-4,pagerank:.00173,eigenvector:7e-4},{id:14,oaid:"d32ba88571141ed0ebe7aeefbaa4ccaf8cda7be3",doi:"10.1038/s41586-023-06924-6",title:"Mathematical discoveries from program search with large language models",authors:[{name:"B. Romera-Paredes",institutions:[]},{name:"M. Barekatain",institutions:[]},{name:"Alexander Novikov",institutions:[]},{name:"Matej Balog",institutions:[]},{name:"M. P. Kumar",institutions:[]},{name:"Emilien Dupont",institutions:[]},{name:"Francisco J. R. Ruiz",institutions:[]},{name:"J. Ellenberg",institutions:[]},{name:"Pengming Wang",institutions:[]},{name:"Omar Fawzi",institutions:[]},{name:"Pushmeet Kohli",institutions:[]},{name:"Alhussein Fawzi",institutions:[]},{name:"Joshua A. Grochow",institutions:[]},{name:"Andrea Lodi",institutions:[]},{name:"Jean-Baptiste Mouret",institutions:[]},{name:"Talia Ringer",institutions:[]},{name:"Tao Yu",institutions:[]}],authorString:"B. Romera-Paredes; M. Barekatain; Alexander Novikov; Matej Balog; M. P. Kumar; Emilien Dupont; Francisco J. R. Ruiz; J. Ellenberg; Pengming Wang; Omar Fawzi; Pushmeet Kohli; Alhussein Fawzi et al.",institutions:[],countries:[],year:2023,journal:"Nature",citations:1159,abstract:"Large language models (LLMs) have demonstrated tremendous capabilities in solving complex tasks, from quantitative reasoning to understanding natural language. However, LLMs sometimes suffer from confabulations (or hallucinations), which can result in them making plausible but incorrect statements1,2. This hinders the use of current large models in scientific discovery. Here we introduce FunSearch (short for searching in the function space), an evolutionary procedure based on pairing a pretrained LLM with a systematic evaluator. We demonstrate the effectiveness of this approach to surpass the best-known results in important problems, pushing the boundary of existing LLM-based approaches3. Applying FunSearch to a central problem in extremal combinatorics—the cap set problem—we discover new constructions of large cap sets going beyond the best-known ones, both in finite dimensional and asymptotic cases. This shows that it is possible to make discoveries for established open problems using LLMs. We showcase the generality of FunSearch by applying it to an algorithmic problem, online bin packing, finding new heuristics that improve on widely used baselines. In contrast to most computer search approaches, FunSearch searches for programs that describe how to solve a problem, rather than what the solution is. Beyond being an effective and scalable strategy, discovered programs tend to be more interpretable than raw solutions, enabling feedback loops between domain experts and FunSearch, and the deployment of such programs in real-world applications. FunSearch makes discoveries in established open problems using large language models by searching for programs describing how to solve a problem, rather than what the solution is.",keywords:[],concepts:[],pdf_url:"https://www.nature.com/articles/s41586-023-06924-6_reference.pdf",is_oa:!0,n_refs:70,n_refs_in_core:28,degree:33,community:8,deg_w:155,betweenness:.0765,pagerank:.01018,eigenvector:.0028},{id:15,oaid:"177f9b0963aca4059791769adcef47edf59dc8a5",doi:null,title:"On the Nature of Expertise.",authors:[{name:"S. Kay",institutions:[]}],authorString:"S. Kay",institutions:[],countries:[],year:1992,journal:"",citations:1158,abstract:"",keywords:["Education"],concepts:["Education"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:16,oaid:"2fe1ac0b09cc0f50eb83eef6c7c6b45ac8b12413",doi:"10.48550/arXiv.2210.07229",title:"Mass-Editing Memory in a Transformer",authors:[{name:"Kevin Meng",institutions:["Massachusetts Institute of Technology"]},{name:"Arnab Sen Sharma",institutions:["Northeastern University"]},{name:"A. Andonian",institutions:[]},{name:"Yonatan Belinkov",institutions:["Technion - Israel Institute of Technology"]},{name:"David Bau",institutions:[]}],authorString:"Kevin Meng; Arnab Sen Sharma; A. Andonian; Yonatan Belinkov; David Bau",institutions:["Massachusetts Institute of Technology","Northeastern University","Technion - Israel Institute of Technology"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:1151,abstract:"Recent work has shown exciting promise in updating large language models with new memories, so as to replace obsolete information or add specialized knowledge. However, this line of work is predominantly limited to updating single associations. We develop MEMIT, a method for directly updating a language model with many memories, demonstrating experimentally that it can scale up to thousands of associations for GPT-J (6B) and GPT-NeoX (20B), exceeding prior work by orders of magnitude. Our code and data are at https://memit.baulab.info.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2210.07229",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:17,oaid:"be9358bdecb7a42b63b87a43900396f2150f79a3",doi:"10.3233/AIC-1988-1306",title:"Scientific Discovery: Computational Explorations of the Creative Processes",authors:[{name:"M. Stacey",institutions:[]}],authorString:"M. Stacey",institutions:[],countries:[],year:1988,journal:"",citations:1150,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:18,oaid:"5dbf93a68b7fda600521f046dea35ea8ba9e884f",doi:"10.48550/arXiv.2308.03688",title:"AgentBench: Evaluating LLMs as Agents",authors:[{name:"Xiao Liu",institutions:["Tsinghua University"]},{name:"Hao Yu",institutions:[]},{name:"Hanchen Zhang",institutions:[]},{name:"Yifan Xu",institutions:[]},{name:"Xuanyu Lei",institutions:["Tsinghua University"]},{name:"Hanyu Lai",institutions:[]},{name:"Yu Gu",institutions:["The Ohio State University"]},{name:"Yuxian Gu",institutions:[]},{name:"Han Ding",institutions:[]},{name:"Kai Men",institutions:[]},{name:"Kejuan Yang",institutions:[]},{name:"Shudan Zhang",institutions:[]},{name:"Xiang Deng",institutions:[]},{name:"Aohan Zeng",institutions:[]},{name:"Zhengxiao Du",institutions:[]},{name:"Chenhui Zhang",institutions:[]},{name:"Shengqi Shen",institutions:[]},{name:"Tianjun Zhang",institutions:[]},{name:"Sheng Shen",institutions:["University of California, Berkeley"]},{name:"Yu Su",institutions:["The Ohio State University","Microsoft"]},{name:"Huan Sun",institutions:[]},{name:"Minlie Huang",institutions:["Tsinghua University"]},{name:"Yuxiao Dong",institutions:[]},{name:"Jie Tang",institutions:[]}],authorString:"Xiao Liu; Hao Yu; Hanchen Zhang; Yifan Xu; Xuanyu Lei; Hanyu Lai; Yu Gu; Yuxian Gu; Han Ding; Kai Men; Kejuan Yang; Shudan Zhang et al.",institutions:["Microsoft","The Ohio State University","Tsinghua University","University of California, Berkeley"],countries:[],year:2023,journal:"International Conference on Learning Representations",citations:1139,abstract:"The potential of Large Language Model (LLM) as agents has been widely acknowledged recently. Thus, there is an urgent need to quantitatively \\textit{evaluate LLMs as agents} on challenging tasks in interactive environments. We present AgentBench, a multi-dimensional benchmark that consists of 8 distinct environments to assess LLM-as-Agent's reasoning and decision-making abilities. Our extensive test over \\num API-based and open-sourced (OSS) LLMs shows that, while top commercial LLMs present a strong ability of acting as agents in complex environments, there is a significant disparity in performance between them and many OSS competitors that are no larger than 70B. We identify the typical reasons of failures in environments and LLMs, showing that poor long-term reasoning, decision-making, and instruction following abilities are the main obstacles for developing usable LLM agents. Improving instruction following and training on high quality multi-round alignment data could improve agent performance. And different from existing assumptions, training on code present ambivalent impacts on different agent tasks. Datasets, environments, and an integrated evaluation package for AgentBench are released at https://github.com/THUDM/AgentBench.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2308.03688",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:19,oaid:"0ba86604228b555475496e200f31878df3aabd6e",doi:"10.1145/3191513",title:"Never-Ending Learning",authors:[{name:"Tom Michael Mitchell",institutions:[]},{name:"William W. Cohen",institutions:["Google"]},{name:"Estevam Hruschka",institutions:["Megagon Labs"]},{name:"Partha P. Talukdar",institutions:[]},{name:"Bo Yang",institutions:[]},{name:"J. Betteridge",institutions:[]},{name:"Andrew Carlson",institutions:[]},{name:"Bhavana Dalvi",institutions:[]},{name:"Matt Gardner",institutions:["Allen Institute for Artificial Intelligence"]},{name:"B. Kisiel",institutions:[]},{name:"Jayant Krishnamurthy",institutions:[]},{name:"N. Lao",institutions:[]},{name:"Kathryn Mazaitis",institutions:[]},{name:"Thahir Mohamed",institutions:[]},{name:"Ndapandula Nakashole",institutions:[]},{name:"Emmanouil Antonios Platanios",institutions:[]},{name:"Alan Ritter",institutions:[]},{name:"M. Samadi",institutions:[]},{name:"Burr Settles",institutions:[]},{name:"Richard C. Wang",institutions:[]},{name:"Derry Tanti Wijaya",institutions:["Boston University","Monash University"]},{name:"A. Gupta",institutions:[]},{name:"Xinlei Chen",institutions:[]},{name:"Abulhair Saparov",institutions:["New York University"]},{name:"Malcolm Greaves",institutions:[]},{name:"Joel Welling",institutions:[]}],authorString:"Tom Michael Mitchell; William W. Cohen; Estevam Hruschka; Partha P. Talukdar; Bo Yang; J. Betteridge; Andrew Carlson; Bhavana Dalvi; Matt Gardner; B. Kisiel; Jayant Krishnamurthy; N. Lao et al.",institutions:["Allen Institute for Artificial Intelligence","Boston University","Google","Megagon Labs","Monash University","New York University"],countries:[],year:2015,journal:"AAAI Conference on Artificial Intelligence",citations:1137,abstract:"Whereas people learn many different types of knowledge from diverse experiences over many years, most current machine learning systems acquire just a single function or data model from just a single data set. We propose a neverending learning paradigm for machine learning, to better reflect the more ambitious and encompassing type of learning performed by humans. As a case study, we describe the Never-Ending Language Learner (NELL), which achieves some of the desired properties of a never-ending learner, and we discuss lessons learned. NELL has been learning to read the web 24 hours/day since January 2010, and so far has acquired a knowledge base with over 80 million confidenceweighted beliefs (e.g., servedWith(tea, biscuits)). NELL has also learned millions of features and parameters that enable it to read these beliefs from the web. Additionally, it has learned to reason over these beliefs to infer new beliefs, and is able to extend its ontology by synthesizing new relational predicates. NELL can be tracked online at http://rtw.ml.cmu.edu, and followed on Twitter at @CMUNELL.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3191513",is_oa:!0,n_refs:39,n_refs_in_core:3,degree:8,community:0,deg_w:37,betweenness:8e-4,pagerank:.00125,eigenvector:.0117},{id:20,oaid:"10bd4160b44803ada6a3d2e366c44b7e2a4ffe90",doi:null,title:"An Explanation of In-context Learning as Implicit Bayesian Inference",authors:[{name:"Sang Michael Xie",institutions:[]},{name:"Aditi Raghunathan",institutions:[]},{name:"Percy Liang",institutions:[]},{name:"Tengyu Ma",institutions:[]}],authorString:"Sang Michael Xie; Aditi Raghunathan; Percy Liang; Tengyu Ma",institutions:[],countries:[],year:2021,journal:"International Conference on Learning Representations",citations:1130,abstract:"Large language models (LMs) such as GPT-3 have the surprising ability to do in-context learning, where the model learns to do a downstream task simply by conditioning on a prompt consisting of input-output examples. The LM learns from these examples without being explicitly pretrained to learn. Thus, it is unclear what enables in-context learning. In this paper, we study how in-context learning can emerge when pretraining documents have long-range coherence. Here, the LM must infer a latent document-level concept to generate coherent next tokens during pretraining. At test time, in-context learning occurs when the LM also infers a shared latent concept between examples in a prompt. We prove when this occurs despite a distribution mismatch between prompts and pretraining data in a setting where the pretraining distribution is a mixture of HMMs. In contrast to messy large-scale datasets used to train LMs capable of in-context learning, we generate a small-scale synthetic dataset (GINC) where Transformers and LSTMs both exhibit in-context learning. Beyond the theory, experiments on GINC exhibit large-scale real-world phenomena including improved in-context performance with model scaling (despite the same pretraining loss), sensitivity to example order, and instances where zero-shot is better than few-shot in-context learning.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:41,n_refs_in_core:0,degree:17,community:1,deg_w:117,betweenness:.0017,pagerank:.00283,eigenvector:.0456},{id:21,oaid:"f3a332ff1b73acda482e5d83696b2c701f487819",doi:null,title:"P-Tuning v2: Prompt Tuning Can Be Comparable to Fine-tuning Universally Across Scales and Tasks",authors:[{name:"Xiao Liu",institutions:["Tsinghua University"]},{name:"Kaixuan Ji",institutions:[]},{name:"Yicheng Fu",institutions:[]},{name:"Zhengxiao Du",institutions:[]},{name:"Zhilin Yang",institutions:[]},{name:"Jie Tang",institutions:[]}],authorString:"Xiao Liu; Kaixuan Ji; Yicheng Fu; Zhengxiao Du; Zhilin Yang; Jie Tang",institutions:["Tsinghua University"],countries:[],year:2021,journal:"arXiv.org",citations:1127,abstract:"Prompt tuning, which only tunes continuous prompts with a frozen language model, substantially reduces per-task storage and memory usage at training. However, in the context of NLU, prior work reveals that prompt tuning does not perform well for normal-sized pretrained models. We also find that existing methods of prompt tuning cannot handle hard sequence labeling tasks, indicating a lack of universality. We present a novel empirical finding that properly optimized prompt tuning can be universally effective across a wide range of model scales and NLU tasks. It matches the performance of finetuning while having only 0.1%-3% tuned parameters. Our method P-Tuning v2 is an implementation of Deep Prompt Tuning \\cite{li2021prefix,qin2021learning} optimized and adapted for NLU. Given the universality and simplicity of P-Tuning v2, we believe it can serve as an alternative to finetuning and a strong baseline for future research.Our code and data are released at https://github.com/THUDM/P-tuning-v2.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:22,oaid:"c84f76770b820d69a6a1f3914a1c84e7c20a8271",doi:"10.7551/mitpress/6161.001.0001",title:"Semantic Cognition: A Parallel Distributed Processing Approach",authors:[{name:"T. Rogers",institutions:[]},{name:"James L. McClelland",institutions:[]}],authorString:"T. Rogers; James L. McClelland",institutions:[],countries:[],year:2004,journal:"",citations:1122,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:3,deg_w:4,betweenness:0,pagerank:36e-5,eigenvector:0},{id:23,oaid:"f110cfdbe9ded7a384bcf5c0d56e536bd275a7eb",doi:null,title:"Unsupervised Learning for Physical Interaction through Video Prediction",authors:[{name:"Chelsea Finn",institutions:[]},{name:"I. Goodfellow",institutions:[]},{name:"S. Levine",institutions:[]}],authorString:"Chelsea Finn; I. Goodfellow; S. Levine",institutions:[],countries:[],year:2016,journal:"Neural Information Processing Systems",citations:1117,abstract:`A core challenge for an agent learning to interact with the world is to predict how its actions affect objects in its environment. Many existing methods for learning the dynamics of physical interactions require labeled object information. However, to scale real-world interaction learning to a variety of scenes and objects, acquiring labeled data becomes increasingly impractical. To learn about physical object motion without labels, we develop an action-conditioned video prediction model that explicitly models pixel motion, by predicting a distribution over pixel motion from previous frames. Because our model explicitly predicts motion, it is partially invariant to object appearance, enabling it to generalize to previously unseen objects. To explore video prediction for real-world interactive agents, we also introduce a dataset of 59,000 robot interactions involving pushing motions, including a test set with novel objects. In this dataset, accurate prediction of videos conditioned on the robot's future actions amounts to learning a "visual imagination" of different futures based on different courses of action. Our experiments show that our proposed method produces more accurate video predictions both quantitatively and qualitatively, when compared to prior methods.`,keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:33,n_refs_in_core:4,degree:12,community:2,deg_w:84,betweenness:5e-4,pagerank:.00281,eigenvector:1e-4},{id:24,oaid:"554f3b32b956035fbfabba730c6f0300d6955dce",doi:"10.1007/BF00117105",title:"Learning logical definitions from relations",authors:[{name:"J. R. Quinlan",institutions:[]}],authorString:"J. R. Quinlan",institutions:[],countries:[],year:1990,journal:"Machine-mediated learning",citations:1114,abstract:"",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007/BF00117105.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:52e-5,eigenvector:3e-4},{id:25,oaid:"7be8c119dbe065c52125ee7716601751f3116844",doi:null,title:"Generalization through Memorization: Nearest Neighbor Language Models",authors:[{name:"Urvashi Khandelwal",institutions:["Google"]},{name:"Omer Levy",institutions:["Meta"]},{name:"Dan Jurafsky",institutions:["Stanford University"]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]},{name:"M. Lewis",institutions:[]}],authorString:"Urvashi Khandelwal; Omer Levy; Dan Jurafsky; Luke Zettlemoyer; M. Lewis",institutions:["Facebook","Google","Meta","Stanford University","University of Washington"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:1109,abstract:"We introduce $k$NN-LMs, which extend a pre-trained neural language model (LM) by linearly interpolating it with a $k$-nearest neighbors ($k$NN) model. The nearest neighbors are computed according to distance in the pre-trained LM embedding space, and can be drawn from any text collection, including the original LM training data. Applying this augmentation to a strong Wikitext-103 LM, with neighbors drawn from the original training set, our $k$NN-LM achieves a new state-of-the-art perplexity of 15.79 - a 2.9 point improvement with no additional training. We also show that this approach has implications for efficiently scaling up to larger training sets and allows for effective domain adaptation, by simply varying the nearest neighbor datastore, again without further training. Qualitatively, the model is particularly helpful in predicting rare patterns, such as factual knowledge. Together, these results strongly suggest that learning similarity between sequences of text is easier than predicting the next word, and that nearest neighbor search is an effective approach for language modeling in the long tail.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:32,n_refs_in_core:0,degree:18,community:1,deg_w:117.5,betweenness:.0032,pagerank:.00257,eigenvector:.0642},{id:26,oaid:"d00735241af700d21762d2f3ca00d920241a15a4",doi:"10.1162/coli.a.16",title:"Siren's Song in the AI Ocean: A Survey on Hallucination in Large Language Models",authors:[{name:"Yue Zhang",institutions:["Soochow University"]},{name:"Yafu Li",institutions:["Westlake University","Zhejiang University"]},{name:"Leyang Cui",institutions:[]},{name:"Deng Cai",institutions:[]},{name:"Lemao Liu",institutions:[]},{name:"Tingchen Fu",institutions:[]},{name:"Xinting Huang",institutions:["University of Melbourne"]},{name:"Enbo Zhao",institutions:[]},{name:"Yu Zhang",institutions:[]},{name:"Yulong Chen",institutions:["University of Cambridge"]},{name:"Longyue Wang",institutions:[]},{name:"A. Luu",institutions:[]},{name:"Wei Bi",institutions:[]},{name:"Freda Shi",institutions:["Toyota Technological Institute at Chicago"]},{name:"Shuming Shi",institutions:[]}],authorString:"Yue Zhang; Yafu Li; Leyang Cui; Deng Cai; Lemao Liu; Tingchen Fu; Xinting Huang; Enbo Zhao; Yu Zhang; Yulong Chen; Longyue Wang; A. Luu et al.",institutions:["Soochow University","Toyota Technological Institute at Chicago","University of Cambridge","University of Melbourne","Westlake University","Zhejiang University"],countries:[],year:2023,journal:"Computational Linguistics",citations:1103,abstract:"While large language models (LLMs) have demonstrated remarkable capabilities across a range of downstream tasks, a significant concern revolves around their propensity to exhibit hallucinations: LLMs occasionally generate content that diverges from the user input, contradicts previously generated context, or misaligns with established world knowledge. This phenomenon poses a substantial challenge to the reliability of LLMs in real-world scenarios. In this paper, we survey recent efforts on the detection, explanation, and mitigation of hallucination, with an emphasis on the unique challenges posed by LLMs. We present taxonomies of the LLM hallucination phenomena and evaluation benchmarks, analyze existing approaches aiming at mitigating LLM hallucination, and discuss potential directions for future research.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://direct.mit.edu/coli/article-pdf/doi/10.1162/coli.a.16/2535477/coli.a.16.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:27,oaid:"5bdfd78fb2285b9306e93bd3a4b534d19bf55f06",doi:"10.1016/j.neunet.2012.02.023",title:"Multi-column deep neural network for traffic sign classification",authors:[{name:"D. Ciresan",institutions:[]},{name:"U. Meier",institutions:[]},{name:"Jonathan Masci",institutions:[]},{name:"J. Schmidhuber",institutions:[]}],authorString:"D. Ciresan; U. Meier; Jonathan Masci; J. Schmidhuber",institutions:[],countries:[],year:2012,journal:"Neural Networks",citations:1102,abstract:"",keywords:[],concepts:[],pdf_url:"http://www.idsia.ch/%7Eciresan/data/nn2012_v3.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:28,oaid:"8e95c5ea7ba5055f03be49c0849de8d4593d43e2",doi:"10.1145/2043174.2043195",title:"Answer set programming at a glance",authors:[{name:"G. Brewka",institutions:[]},{name:"Thomas Eiter",institutions:["Vienna University of Technology (TU Wien)"]},{name:"M. Truszczynski",institutions:[]}],authorString:"G. Brewka; Thomas Eiter; M. Truszczynski",institutions:["Vienna University of Technology (TU Wien)"],countries:[],year:2011,journal:"Communications of the ACM",citations:1098,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8,betweenness:.0016,pagerank:66e-5,eigenvector:1e-4},{id:29,oaid:"131c6f328c11706de2c43cd16e0b7c5d5e610b6a",doi:"10.1145/3649506",title:"Harnessing the Power of LLMs in Practice: A Survey on ChatGPT and Beyond",authors:[{name:"Jingfeng Yang",institutions:["Amazon"]},{name:"Hongye Jin",institutions:[]},{name:"Ruixiang Tang",institutions:[]},{name:"Xiaotian Han",institutions:["Texas A&M University"]},{name:"Qizhang Feng",institutions:[]},{name:"Haoming Jiang",institutions:[]},{name:"Bing Yin",institutions:[]},{name:"X. Hu",institutions:[]}],authorString:"Jingfeng Yang; Hongye Jin; Ruixiang Tang; Xiaotian Han; Qizhang Feng; Haoming Jiang; Bing Yin; X. Hu",institutions:["Amazon","Texas A&M University"],countries:[],year:2023,journal:"ACM Transactions on Knowledge Discovery from Data",citations:1096,abstract:"This article presents a comprehensive and practical guide for practitioners and end-users working with Large Language Models (LLMs) in their downstream Natural Language Processing (NLP) tasks. We provide discussions and insights into the usage of LLMs from the perspectives of models, data, and downstream tasks. First, we offer an introduction and brief summary of current language models. Then, we discuss the influence of pre-training data, training data, and test data. Most importantly, we provide a detailed discussion about the use and non-use cases of large language models for various natural language processing tasks, such as knowledge-intensive tasks, traditional natural language understanding tasks, generation tasks, emergent abilities, and considerations for specific tasks. We present various use cases and non-use cases to illustrate the practical applications and limitations of LLMs in real-world scenarios. We also try to understand the importance of data and the specific challenges associated with each NLP task. Furthermore, we explore the impact of spurious biases on LLMs and delve into other essential considerations, such as efficiency, cost, and latency, to ensure a comprehensive understanding of deploying LLMs in practice. This comprehensive guide aims to provide researchers and practitioners with valuable insights and best practices for working with LLMs, thereby enabling the successful implementation of these models in a wide range of NLP tasks. A curated list of practical guide resources of LLMs, regularly updated, can be found at https://github.com/Mooler0410/LLMsPracticalGuide. An LLMs evolutionary tree, editable yet regularly updated, can be found at llmtree.ai.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3649506",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:30,oaid:"01b6affe3ea4eae1978aec54e87087feb76d9215",doi:null,title:"Generalization and network design strategies",authors:[{name:"Yann LeCun",institutions:["Facebook","NYU"]}],authorString:"Yann LeCun",institutions:["Facebook","NYU"],countries:[],year:1989,journal:"",citations:1095,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:31,oaid:"92173d081b15824d22a9ef070e118744ceee8052",doi:null,title:"Show Your Work: Scratchpads for Intermediate Computation with Language Models",authors:[{name:"Maxwell Nye",institutions:["MIT"]},{name:"Anders Andreassen",institutions:[]},{name:"Guy Gur-Ari",institutions:[]},{name:"H. Michalewski",institutions:[]},{name:"Jacob Austin",institutions:[]},{name:"David Bieber",institutions:["Google"]},{name:"David Dohan",institutions:["Google Brain"]},{name:"Aitor Lewkowycz",institutions:[]},{name:"Maarten Bosma",institutions:["Inflection AI"]},{name:"D. Luan",institutions:[]},{name:"Charles Sutton",institutions:[]},{name:"Augustus Odena",institutions:[]}],authorString:"Maxwell Nye; Anders Andreassen; Guy Gur-Ari; H. Michalewski; Jacob Austin; David Bieber; David Dohan; Aitor Lewkowycz; Maarten Bosma; D. Luan; Charles Sutton; Augustus Odena",institutions:["Google","Google Brain","Inflection AI","MIT"],countries:[],year:2021,journal:"arXiv.org",citations:1088,abstract:'Large pre-trained language models perform remarkably well on tasks that can be done"in one pass", such as generating realistic text or synthesizing computer programs. However, they struggle with tasks that require unbounded multi-step computation, such as adding integers or executing programs. Surprisingly, we find that these same models are able to perform complex multi-step computations -- even in the few-shot regime -- when asked to perform the operation"step by step", showing the results of intermediate computations. In particular, we train transformers to perform multi-step computations by asking them to emit intermediate computation steps into a"scratchpad". On a series of increasingly complex tasks ranging from long addition to the execution of arbitrary programs, we show that scratchpads dramatically improve the ability of language models to perform multi-step computations.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:35,n_refs_in_core:6,degree:26,community:5,deg_w:141.5,betweenness:.0168,pagerank:.0045,eigenvector:.0056},{id:32,oaid:"bba5f2852b1db8a18004eb7328efa5e1d57cc62a",doi:"10.18653/v1/D16-1147",title:"Key-Value Memory Networks for Directly Reading Documents",authors:[{name:"Alexander H. Miller",institutions:[]},{name:"Adam Fisch",institutions:[]},{name:"Jesse Dodge",institutions:["Allen Institute for AI","Carnegie Mellon University","University of Washington"]},{name:"Amir-Hossein Karimi",institutions:["Max Planck Institute for Intelligent Systems","ETH Zurich"]},{name:"Antoine Bordes",institutions:[]},{name:"J. Weston",institutions:[]}],authorString:"Alexander H. Miller; Adam Fisch; Jesse Dodge; Amir-Hossein Karimi; Antoine Bordes; J. Weston",institutions:["Allen Institute for AI","Carnegie Mellon University","ETH Zurich","Max Planck Institute for Intelligent Systems","University of Washington"],countries:[],year:2016,journal:"Conference on Empirical Methods in Natural Language Processing",citations:1087,abstract:"Directly reading documents and being able to answer questions from them is an unsolved challenge. To avoid its inherent difficulty, question answering (QA) has been directed towards using Knowledge Bases (KBs) instead, which has proven effective. Unfortunately KBs often suffer from being too restrictive, as the schema cannot support certain types of answers, and too sparse, e.g. Wikipedia contains much more information than Freebase. In this work we introduce a new method, Key-Value Memory Networks, that makes reading documents more viable by utilizing different encodings in the addressing and output stages of the memory read operation. To compare using KBs, information extraction or Wikipedia documents directly in a single framework we construct an analysis tool, WikiMovies, a QA dataset that contains raw text alongside a preprocessed KB, in the domain of movies. Our method reduces the gap between all three settings. It also achieves state-of-the-art results on the existing WikiQA benchmark.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/D16-1147.pdf",is_oa:!0,n_refs:31,n_refs_in_core:1,degree:10,community:2,deg_w:52.5,betweenness:.0038,pagerank:.00162,eigenvector:.002},{id:33,oaid:"b41e95c8c97846d5ca4c11ef79d7814499cc9663",doi:"10.3115/v1/P15-1142",title:"Compositional Semantic Parsing on Semi-Structured Tables",authors:[{name:"Panupong Pasupat",institutions:[]},{name:"Percy Liang",institutions:[]}],authorString:"Panupong Pasupat; Percy Liang",institutions:[],countries:[],year:2015,journal:"Annual Meeting of the Association for Computational Linguistics",citations:1076,abstract:"Two important aspects of semantic parsing for question answering are the breadth of the knowledge source and the depth of logical compositionality. While existing work trades off one aspect for another, this paper simultaneously makes progress on both fronts through a new task: answering complex questions on semi-structured tables using question-answer pairs as supervision. The central challenge arises from two compounding factors: the broader domain results in an open-ended set of relations, and the deeper compositionality results in a combinatorial explosion in the space of logical forms. We propose a logical-form driven parsing algorithm guided by strong typing constraints and show that it obtains significant improvements over natural baselines. For evaluation, we created a new dataset of 22,033 complex questions on Wikipedia tables, which is made publicly available.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P15-1142.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:5,deg_w:16,betweenness:7e-4,pagerank:77e-5,eigenvector:4e-4},{id:34,oaid:"07b14c24833400b79978b0a5f084803337e30a15",doi:"10.48550/arXiv.2301.12652",title:"REPLUG: Retrieval-Augmented Black-Box Language Models",authors:[{name:"Weijia Shi",institutions:[]},{name:"Sewon Min",institutions:[]},{name:"Michihiro Yasunaga",institutions:[]},{name:"Minjoon Seo",institutions:["KAIST"]},{name:"Rich James",institutions:[]},{name:"M. Lewis",institutions:[]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]},{name:"Wen-tau Yih",institutions:[]}],authorString:"Weijia Shi; Sewon Min; Michihiro Yasunaga; Minjoon Seo; Rich James; M. Lewis; Luke Zettlemoyer; Wen-tau Yih",institutions:["Facebook","KAIST","University of Washington"],countries:[],year:2023,journal:"North American Chapter of the Association for Computational Linguistics",citations:1074,abstract:"We introduce REPLUG, a retrieval-augmented language modeling framework that treats the language model (LM) as a black box and augments it with a tuneable retrieval model. Unlike prior retrieval-augmented LMs that train language models with special cross-attention mechanisms to encode the retrieved text, REPLUG simply prepends retrieved documents to the input for the frozen black-box LM. This simple design can be easily applied to any existing language models. Furthermore, we show that the LM can be used to supervise the retrieval model, which can then find documents that help the LM make better predictions. Our experiments demonstrate that REPLUG with the tuned retriever significantly improves the performance of GPT-3 (175B) on language modeling by 6.3%, as well as the performance of Codex on five-shot MMLU by 5.1%. Code is publicly released at github.com/swj0419/REPLUG.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2301.12652",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:35,oaid:"a5d10341717c0519cf63151b496a6d2ed67aa05f",doi:null,title:"Bilinear Attention Networks",authors:[{name:"Jin-Hwa Kim",institutions:["NAVER AI Lab"]},{name:"Jaehyun Jun",institutions:[]},{name:"Byoung-Tak Zhang",institutions:[]}],authorString:"Jin-Hwa Kim; Jaehyun Jun; Byoung-Tak Zhang",institutions:["NAVER AI Lab"],countries:[],year:2018,journal:"Neural Information Processing Systems",citations:1072,abstract:"Attention networks in multimodal learning provide an efficient way to utilize given visual information selectively. However, the computational cost to learn attention distributions for every pair of multimodal input channels is prohibitively expensive. To solve this problem, co-attention builds two separate attention distributions for each modality neglecting the interaction between multimodal inputs. In this paper, we propose bilinear attention networks (BAN) that find bilinear attention distributions to utilize given vision-language information seamlessly. BAN considers bilinear interactions among two groups of input channels, while low-rank bilinear pooling extracts the joint representations for each pair of channels. Furthermore, we propose a variant of multimodal residual networks to exploit eight-attention maps of the BAN efficiently. We quantitatively and qualitatively evaluate our model on visual question answering (VQA 2.0) and Flickr30k Entities datasets, showing that BAN significantly outperforms previous methods and achieves new state-of-the-arts on both datasets.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:41,n_refs_in_core:2,degree:19,community:3,deg_w:168.5,betweenness:7e-4,pagerank:.00351,eigenvector:.0015},{id:36,oaid:"7ee368e60d0b826e78f965aad8d6c7d406127104",doi:"10.1145/1390156.1390303",title:"Deep learning via semi-supervised embedding",authors:[{name:"J. Weston",institutions:[]},{name:"F. Ratle",institutions:[]},{name:"H. Mobahi",institutions:[]},{name:"R. Collobert",institutions:[]}],authorString:"J. Weston; F. Ratle; H. Mobahi; R. Collobert",institutions:[],countries:[],year:2008,journal:"International Conference on Machine Learning",citations:1070,abstract:"We show how nonlinear embedding algorithms popular for use with shallow semi-supervised learning techniques such as kernel methods can be applied to deep multilayer architectures, either as a regularizer at the output layer, or on each layer of the architecture. This provides a simple alternative to existing approaches to deep learning whilst yielding competitive error rates compared to those methods, and existing shallow semi-supervised techniques.",keywords:[],concepts:[],pdf_url:"http://infoscience.epfl.ch/record/192705",is_oa:!0,n_refs:32,n_refs_in_core:0,degree:2,community:0,deg_w:16,betweenness:1e-4,pagerank:.00103,eigenvector:0},{id:37,oaid:"d91043f0d48b9b2c8ff7ee321abb8fd7efafff7a",doi:"10.1162/tacl_a_00023",title:"The NarrativeQA Reading Comprehension Challenge",authors:[{name:"Tomás Kociský",institutions:[]},{name:"Jonathan Schwarz",institutions:[]},{name:"Phil Blunsom",institutions:[]},{name:"Chris Dyer",institutions:[]},{name:"Karl Moritz Hermann",institutions:[]},{name:"Gábor Melis",institutions:[]},{name:"Edward Grefenstette",institutions:[]}],authorString:"Tomás Kociský; Jonathan Schwarz; Phil Blunsom; Chris Dyer; Karl Moritz Hermann; Gábor Melis; Edward Grefenstette",institutions:[],countries:[],year:2017,journal:"Transactions of the Association for Computational Linguistics",citations:1070,abstract:"Reading comprehension (RC)—in contrast to information retrieval—requires integrating information and reasoning about events, entities, and their relations across a full document. Question answering is conventionally used to assess RC ability, in both artificial agents and children learning to read. However, existing RC datasets and tasks are dominated by questions that can be solved by selecting answers using superficial information (e.g., local context similarity or global term frequency); they thus fail to test for the essential integrative aspect of RC. To encourage progress on deeper comprehension of language, we present a new dataset and set of tasks in which the reader must answer questions about stories by reading entire books or movie scripts. These tasks are designed so that successfully answering their questions requires understanding the underlying narrative rather than relying on shallow pattern matching or salience. We show that although humans solve the tasks easily, standard RC models struggle on the tasks presented here. We provide an analysis of the dataset and the challenges it presents.",keywords:["Linguistics","Education"],concepts:["Linguistics","Education"],pdf_url:"http://www.mitpressjournals.org/doi/pdf/10.1162/tacl_a_00023",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:6e-4,pagerank:55e-5,eigenvector:6e-4},{id:38,oaid:"9d9abd42ababaaa560ea083055632e69f46f0c31",doi:"10.1016/0004-3702(94)90081-7",title:"The Computational Complexity of Propositional STRIPS Planning",authors:[{name:"T. Bylander",institutions:[]}],authorString:"T. Bylander",institutions:[],countries:[],year:1994,journal:"Artificial Intelligence",citations:1064,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:39,oaid:"6dfc2ff03534a4325d06c6f88c3144831996629b",doi:"10.1109/CVPR.2019.00688",title:"From Recognition to Cognition: Visual Commonsense Reasoning",authors:[{name:"Rowan Zellers",institutions:["University of Washington"]},{name:"Yonatan Bisk",institutions:["Carnegie Mellon University"]},{name:"Ali Farhadi",institutions:[]},{name:"Yejin Choi",institutions:[]}],authorString:"Rowan Zellers; Yonatan Bisk; Ali Farhadi; Yejin Choi",institutions:["Carnegie Mellon University","University of Washington"],countries:[],year:2018,journal:"Computer Vision and Pattern Recognition",citations:1062,abstract:"Visual understanding goes well beyond object recognition. With one glance at an image, we can effortlessly imagine the world beyond the pixels: for instance, we can infer people's actions, goals, and mental states. While this task is easy for humans, it is tremendously difficult for today's vision systems, requiring higher-order cognition and commonsense reasoning about the world. We formalize this task as Visual Commonsense Reasoning. Given a challenging question about an image, a machine must answer correctly and then provide a rationale justifying its answer. Next, we introduce a new dataset, VCR, consisting of 290k multiple choice QA problems derived from 110k movie scenes. The key recipe for generating non-trivial and high-quality problems at scale is Adversarial Matching, a new approach to transform rich annotations into multiple choice questions with minimal bias. Experimental results show that while humans find VCR easy (over 90% accuracy), state-of-the-art vision models struggle (~45%). To move towards cognition-level understanding, we present a new reasoning engine, Recognition to Cognition Networks (R2C), that models the necessary layered inferences for grounding, contextualization, and reasoning. R2C helps narrow the gap between humans and machines (~65%); still, the challenge is far from solved, and we provide analysis that suggests avenues for future work.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://arxiv.org/pdf/1811.10830",is_oa:!0,n_refs:91,n_refs_in_core:8,degree:24,community:3,deg_w:215.5,betweenness:.0101,pagerank:.00484,eigenvector:.004},{id:40,oaid:"f48eed915cbb9c6592cdb9df80c1edaeb46959af",doi:null,title:"A measure of intelligence",authors:[{name:"A. Tate",institutions:[]}],authorString:"A. Tate",institutions:[],countries:[],year:2012,journal:"",citations:1060,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:41,oaid:"0f3dc8fda72b596652c2452908a3a141a809f59f",doi:"10.1037/0033-295X.99.4.587",title:"How to build a baby: II. Conceptual primitives.",authors:[{name:"J. Mandler",institutions:[]}],authorString:"J. Mandler",institutions:[],countries:[],year:1992,journal:"Psychology Review",citations:1058,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:42,oaid:"fbc04a1951003ba164303b2898fb7f3c6b4e9083",doi:"10.1016/0004-3702(80)90003-X",title:"Definite Clause Grammars for Language Analysis - A Survey of the Formalism and a Comparison with Augmented Transition Networks",authors:[{name:"Fernando C Pereira",institutions:["Google"]},{name:"D. Warren",institutions:[]}],authorString:"Fernando C Pereira; D. Warren",institutions:["Google"],countries:[],year:1980,journal:"Artificial Intelligence",citations:1053,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:43,oaid:"c03fa01fbb9c77fe3d10609ba5f1dee33a723867",doi:"10.1109/ICRA48891.2023.10161317",title:"ProgPrompt: Generating Situated Robot Task Plans using Large Language Models",authors:[{name:"Ishika Singh",institutions:["University of Southern California"]},{name:"Valts Blukis",institutions:[]},{name:"A. Mousavian",institutions:[]},{name:"Ankit Goyal",institutions:["Nvidia"]},{name:"Danfei Xu",institutions:[]},{name:"Jonathan Tremblay",institutions:[]},{name:"D. Fox",institutions:[]},{name:"Jesse Thomason",institutions:["The University of Washington"]},{name:"Animesh Garg",institutions:["Georgia Institute of Technology","University of Toronto","Nvidia"]}],authorString:"Ishika Singh; Valts Blukis; A. Mousavian; Ankit Goyal; Danfei Xu; Jonathan Tremblay; D. Fox; Jesse Thomason; Animesh Garg",institutions:["Georgia Institute of Technology","Nvidia","The University of Washington","University of Southern California","University of Toronto"],countries:[],year:2022,journal:"IEEE International Conference on Robotics and Automation",citations:1050,abstract:"Task planning can require defining myriad domain knowledge about the world in which a robot needs to act. To ameliorate that effort, large language models (LLMs) can be used to score potential next actions during task planning, and even generate action sequences directly, given an instruction in natural language with no additional domain information. However, such methods either require enumerating all possible next steps for scoring, or generate free-form text that may contain actions not possible on a given robot in its current context. We present a programmatic LLM prompt structure that enables plan generation functional across situated environments, robot capabilities, and tasks. Our key insight is to prompt the LLM with program-like specifications of the available actions and objects in an environment, as well as with example programs that can be executed. We make concrete recommendations about prompt structure and generation constraints through ablation experiments, demonstrate state of the art success rates in VirtualHome household tasks, and deploy our method on a physical robot arm for tabletop tasks. Website at progprompt.github.io",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2209.11302",is_oa:!0,n_refs:39,n_refs_in_core:4,degree:16,community:4,deg_w:91.5,betweenness:.0033,pagerank:.00304,eigenvector:.004},{id:44,oaid:"33a191d483bea906796c5b82582cfa3324bd5c1e",doi:"10.1613/jair.989",title:"A Knowledge Compilation Map",authors:[{name:"Adnan Darwiche",institutions:["UCLA"]},{name:"P. Marquis",institutions:[]}],authorString:"Adnan Darwiche; P. Marquis",institutions:["UCLA"],countries:[],year:2002,journal:"Journal of Artificial Intelligence Research",citations:1049,abstract:"We propose a perspective on knowledge compilation which calls for analyzing different compilation approaches according to two key dimensions: the succinctness of the target compilation language, and the class of queries and transformations that the language supports in polytime. We then provide a knowledge compilation map, which analyzes a large number of existing target compilation languages according to their succinctness and their polytime transformations and queries. We argue that such analysis is necessary for placing new compilation approaches within the context of existing ones. We also go beyond classical, flat target compilation languages based on CNF and DNF, and consider a richer, nested class based on directed acyclic graphs (such as OBDDs), which we show to include a relatively large number of target compilation languages.",keywords:[],concepts:[],pdf_url:"https://jair.org/index.php/jair/article/download/10311/24622",is_oa:!0,n_refs:36,n_refs_in_core:1,degree:3,community:0,deg_w:12.5,betweenness:1e-4,pagerank:85e-5,eigenvector:0},{id:45,oaid:"d08463bd665589d04619f04dbde84183ffcf2e63",doi:null,title:"Towards a Human-like Open-Domain Chatbot",authors:[{name:"Daniel De Freitas",institutions:["Character AI"]},{name:"Minh-Thang Luong",institutions:[]},{name:"David R. So",institutions:[]},{name:"Jamie Hall",institutions:[]},{name:"Noah Fiedel",institutions:[]},{name:"R. Thoppilan",institutions:[]},{name:"Zi Yang",institutions:[]},{name:"Apoorv Kulshreshtha",institutions:[]},{name:"Gaurav Nemade",institutions:[]},{name:"Yifeng Lu",institutions:[]},{name:"Quoc V. Le",institutions:[]}],authorString:"Daniel De Freitas; Minh-Thang Luong; David R. So; Jamie Hall; Noah Fiedel; R. Thoppilan; Zi Yang; Apoorv Kulshreshtha; Gaurav Nemade; Yifeng Lu; Quoc V. Le",institutions:["Character AI"],countries:[],year:2020,journal:"arXiv.org",citations:1036,abstract:"We present Meena, a multi-turn open-domain chatbot trained end-to-end on data mined and filtered from public domain social media conversations. This 2.6B parameter neural network is simply trained to minimize perplexity of the next token. We also propose a human evaluation metric called Sensibleness and Specificity Average (SSA), which captures key elements of a human-like multi-turn conversation. Our experiments show strong correlation between perplexity and SSA. The fact that the best perplexity end-to-end trained Meena scores high on SSA (72% on multi-turn evaluation) suggests that a human-level SSA of 86% is potentially within reach if we can better optimize perplexity. Additionally, the full version of Meena (with a filtering mechanism and tuned decoding) scores 79% SSA, 23% higher in absolute SSA than the existing chatbots we evaluated.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:46,oaid:"5969fdc215def657b8e607aaa03cee3796c10d4a",doi:null,title:"An Introduction to Conditional Random Fields for Relational Learning",authors:[{name:"Charles Sutton",institutions:["Google","University of Edinburgh"]},{name:"A. McCallum",institutions:[]}],authorString:"Charles Sutton; A. McCallum",institutions:["Google","University of Edinburgh"],countries:[],year:2007,journal:"",citations:1031,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:47,oaid:"27113a576148895f1a127f35b5129198b06bf632",doi:"10.1017/S0960129500001560",title:"Comprehending monads",authors:[{name:"P. Wadler",institutions:[]}],authorString:"P. Wadler",institutions:[],countries:[],year:1990,journal:"Mathematical Structures in Computer Science",citations:1026,abstract:"",keywords:[],concepts:[],pdf_url:"https://www.research.ed.ac.uk/files/7944776/Comprehending_monads.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:7,deg_w:4,betweenness:0,pagerank:48e-5,eigenvector:0},{id:48,oaid:"b123a0d46ad917b79c43c5ae981e03ed2458ed11",doi:"10.18653/v1/P17-1015",title:"Program Induction by Rationale Generation: Learning to Solve and Explain Algebraic Word Problems",authors:[{name:"Wang Ling",institutions:[]},{name:"Dani Yogatama",institutions:[]},{name:"Chris Dyer",institutions:[]},{name:"Phil Blunsom",institutions:[]}],authorString:"Wang Ling; Dani Yogatama; Chris Dyer; Phil Blunsom",institutions:[],countries:[],year:2017,journal:"Annual Meeting of the Association for Computational Linguistics",citations:1023,abstract:"Solving algebraic word problems requires executing a series of arithmetic operations—a program—to obtain a final answer. However, since programs can be arbitrarily complicated, inducing them directly from question-answer pairs is a formidable challenge. To make this task more feasible, we solve these problems by generating answer rationales, sequences of natural language and human-readable mathematical expressions that derive the final answer through a series of small steps. Although rationales do not explicitly specify programs, they provide a scaffolding for their structure via intermediate milestones. To evaluate our approach, we have created a new 100,000-sample dataset of questions, answers and rationales. Experimental results show that indirect supervision of program learning via answer rationales is a promising strategy for inducing arithmetic programs.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P17-1015.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:5,community:5,deg_w:22,betweenness:2e-4,pagerank:91e-5,eigenvector:8e-4},{id:49,oaid:"0c5598424cc96d8fb500eb553cb7969f86a0ede0",doi:"10.18653/v1/2020.emnlp-main.750",title:"Evaluating the Factual Consistency of Abstractive Text Summarization",authors:[{name:"Wojciech Kryscinski",institutions:["Salesforce Research"]},{name:"Bryan McCann",institutions:[]},{name:"Caiming Xiong",institutions:["Salesforce Research"]},{name:"R. Socher",institutions:[]}],authorString:"Wojciech Kryscinski; Bryan McCann; Caiming Xiong; R. Socher",institutions:["Salesforce Research"],countries:[],year:2019,journal:"Conference on Empirical Methods in Natural Language Processing",citations:1017,abstract:"Currently used metrics for assessing summarization algorithms do not account for whether summaries are factually consistent with source documents. We propose a weakly-supervised, model-based approach for verifying factual consistency and identifying conflicts between source documents and a generated summary. Training data is generated by applying a series of rule-based transformations to the sentences of source documents. The factual consistency model is then trained jointly for three tasks: 1) identify whether sentences remain factually consistent after transformation, 2) extract a span in the source documents to support the consistency prediction, 3) extract a span in the summary sentence that is inconsistent if one exists. Transferring this model to summaries generated by several state-of-the art models reveals that this highly scalable approach substantially outperforms previous models, including those trained with strong supervision using standard datasets for natural language inference and fact checking. Additionally, human evaluation shows that the auxiliary span extraction tasks provide useful assistance in the process of verifying factual consistency.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2020.emnlp-main.750.pdf",is_oa:!0,n_refs:52,n_refs_in_core:0,degree:14,community:1,deg_w:65,betweenness:.0051,pagerank:.0017,eigenvector:.0287},{id:50,oaid:"e2d3f4ef30652b36145cbecfcd1f50d9f69351f3",doi:"10.1145/1926385.1926423",title:"Automating string processing in spreadsheets using input-output examples",authors:[{name:"Sumit Gulwani",institutions:[]}],authorString:"Sumit Gulwani",institutions:[],countries:[],year:2011,journal:"ACM-SIGACT Symposium on Principles of Programming Languages",citations:1013,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12.5,betweenness:.0014,pagerank:78e-5,eigenvector:5e-4},{id:51,oaid:"def584565d05d6a8ba94de6621adab9e301d375d",doi:"10.1109/CVPR.2016.540",title:"Visual7W: Grounded Question Answering in Images",authors:[{name:"Yuke Zhu",institutions:[]},{name:"O. Groth",institutions:[]},{name:"Michael S. Bernstein",institutions:["Stanford University"]},{name:"Li Fei-Fei",institutions:[]}],authorString:"Yuke Zhu; O. Groth; Michael S. Bernstein; Li Fei-Fei",institutions:["Stanford University"],countries:[],year:2015,journal:"Computer Vision and Pattern Recognition",citations:1009,abstract:"We have seen great progress in basic perceptual tasks such as object recognition and detection. However, AI models still fail to match humans in high-level vision tasks due to the lack of capacities for deeper reasoning. Recently the new task of visual question answering (QA) has been proposed to evaluate a model's capacity for deep image understanding. Previous works have established a loose, global association between QA sentences and images. However, many questions and answers, in practice, relate to local regions in the images. We establish a semantic link between textual descriptions and image regions by object-level grounding. It enables a new type of QA with visual answers, in addition to textual answers used in previous work. We study the visual QA tasks in a grounded setting with a large collection of 7W multiple-choice QA pairs. Furthermore, we evaluate human performance and several baseline models on the QA tasks. Finally, we propose a novel LSTM model with spatial attention to tackle the 7W QA tasks.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/1511.03416",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:10,community:3,deg_w:41.5,betweenness:1e-4,pagerank:.00104,eigenvector:3e-4},{id:52,oaid:"23dd78e424d32f6a48660dcd67ce994b8a7db8be",doi:null,title:"STaR: Bootstrapping Reasoning With Reasoning",authors:[{name:"E. Zelikman",institutions:[]},{name:"Yuhuai Wu",institutions:[]},{name:"Noah D. Goodman",institutions:[]}],authorString:"E. Zelikman; Yuhuai Wu; Noah D. Goodman",institutions:[],countries:[],year:2022,journal:"",citations:1005,abstract:'Generating step-by-step"chain-of-thought"rationales improves language model performance on complex reasoning tasks like mathematics or commonsense question-answering. However, inducing language model rationale generation currently requires either constructing massive rationale datasets or sacrificing accuracy by using only few-shot inference. We propose a technique to iteratively leverage a small number of rationale examples and a large dataset without rationales, to bootstrap the ability to perform successively more complex reasoning. This technique, the"Self-Taught Reasoner"(STaR), relies on a simple loop: generate rationales to answer many questions, prompted with a few rationale examples; if the generated answers are wrong, try again to generate a rationale given the correct answer; fine-tune on all the rationales that ultimately yielded correct answers; repeat. We show that STaR significantly improves performance on multiple datasets compared to a model fine-tuned to directly predict final answers, and performs comparably to fine-tuning a 30$\\times$ larger state-of-the-art language model on CommensenseQA. Thus, STaR lets a model improve itself by learning from its own generated reasoning.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:46,n_refs_in_core:8,degree:22,community:5,deg_w:126.5,betweenness:.0225,pagerank:.00399,eigenvector:.0154},{id:53,oaid:"197e3a315c57c9278876d95b7e522700aa112886",doi:"10.1145/1015330.1015360",title:"Integrating constraints and metric learning in semi-supervised clustering",authors:[{name:"Mikhail Bilenko",institutions:[]},{name:"Sugato Basu",institutions:[]},{name:"R. Mooney",institutions:[]}],authorString:"Mikhail Bilenko; Sugato Basu; R. Mooney",institutions:[],countries:[],year:2004,journal:"International Conference on Machine Learning",citations:987,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:43e-5,eigenvector:0},{id:54,oaid:"5cfbbf3cdff0f905874589bcd21b2646340a5447",doi:null,title:"Choice of Plausible Alternatives: An Evaluation of Commonsense Causal Reasoning",authors:[{name:"A. Gordon",institutions:[]},{name:"Zornitsa Kozareva",institutions:[]},{name:"Melissa Roemmele",institutions:[]}],authorString:"A. Gordon; Zornitsa Kozareva; Melissa Roemmele",institutions:[],countries:[],year:2011,journal:"AAAI Spring Symposium: Logical Formalizations of Commonsense Reasoning",citations:984,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:8e-4,pagerank:51e-5,eigenvector:.0036},{id:55,oaid:"856fe866bcce5e7a540655bea6ecc7406bdcfcba",doi:null,title:"Generalization without Systematicity: On the Compositional Skills of Sequence-to-Sequence Recurrent Networks",authors:[{name:"B. Lake",institutions:[]},{name:"Marco Baroni",institutions:[]}],authorString:"B. Lake; Marco Baroni",institutions:[],countries:[],year:2017,journal:"International Conference on Machine Learning",citations:981,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:2,deg_w:12.5,betweenness:0,pagerank:84e-5,eigenvector:1e-4},{id:56,oaid:"69ee9b3a915951cc84b74599a3a2699a66d4004f",doi:null,title:"CLIPort: What and Where Pathways for Robotic Manipulation",authors:[{name:"Mohit Shridhar",institutions:[]},{name:"Lucas Manuelli",institutions:[]},{name:"D. Fox",institutions:[]}],authorString:"Mohit Shridhar; Lucas Manuelli; D. Fox",institutions:[],countries:[],year:2021,journal:"Conference on Robot Learning",citations:978,abstract:"How can we imbue robots with the ability to manipulate objects precisely but also to reason about them in terms of abstract concepts? Recent works in manipulation have shown that end-to-end networks can learn dexterous skills that require precise spatial reasoning, but these methods often fail to generalize to new goals or quickly learn transferable concepts across tasks. In parallel, there has been great progress in learning generalizable semantic representations for vision and language by training on large-scale internet data, however these representations lack the spatial understanding necessary for fine-grained manipulation. To this end, we propose a framework that combines the best of both worlds: a two-stream architecture with semantic and spatial pathways for vision-based manipulation. Specifically, we present CLIPort, a language-conditioned imitation-learning agent that combines the broad semantic understanding (what) of CLIP [1] with the spatial precision (where) of Transporter [2]. Our end-to-end framework is capable of solving a variety of language-specified tabletop tasks from packing unseen objects to folding cloths, all without any explicit representations of object poses, instance segmentations, memory, symbolic states, or syntactic structures. Experiments in simulated and real-world settings show that our approach is data efficient in few-shot settings and generalizes effectively to seen and unseen semantic concepts. We even learn one multi-task policy for 10 simulated and 9 real-world tasks that is better or comparable to single-task policies.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:67,n_refs_in_core:4,degree:21,community:4,deg_w:140.5,betweenness:.016,pagerank:.00383,eigenvector:.0045},{id:57,oaid:"8c45e059a11b1c6398b45c92610804e1f28336d4",doi:"10.1145/1066100.1066102",title:"Simplify: a theorem prover for program checking",authors:[{name:"David Detlefs",institutions:[]},{name:"Greg Nelson",institutions:[]},{name:"J. Saxe",institutions:[]}],authorString:"David Detlefs; Greg Nelson; J. Saxe",institutions:[],countries:[],year:2005,journal:"JACM",citations:960,abstract:"",keywords:[],concepts:[],pdf_url:"http://www.hpl.hp.com/techreports/2003/HPL-2003-148.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:7,deg_w:4,betweenness:0,pagerank:48e-5,eigenvector:0},{id:58,oaid:"c8c16a56d2a9520197da9a1546f517db5f19b204",doi:null,title:"Adversarial Attacks on Neural Network Policies",authors:[{name:"Sandy H. Huang",institutions:[]},{name:"Nicolas Papernot",institutions:[]},{name:"I. Goodfellow",institutions:[]},{name:"Yan Duan",institutions:[]},{name:"P. Abbeel",institutions:[]}],authorString:"Sandy H. Huang; Nicolas Papernot; I. Goodfellow; Yan Duan; P. Abbeel",institutions:[],countries:[],year:2017,journal:"International Conference on Learning Representations",citations:956,abstract:"Machine learning classifiers are known to be vulnerable to inputs maliciously constructed by adversaries to force misclassification. Such adversarial examples have been extensively studied in the context of computer vision applications. In this work, we show adversarial attacks are also effective when targeting neural network policies in reinforcement learning. Specifically, we show existing adversarial example crafting techniques can be used to significantly degrade test-time performance of trained policies. Our threat model considers adversaries capable of introducing small perturbations to the raw input of the policy. We characterize the degree of vulnerability across tasks and training algorithms, for a subclass of adversarial-example attacks in white-box and black-box settings. Regardless of the learned task or training algorithm, we observe a significant drop in performance, even with small adversarial perturbations that do not interfere with human perception. Videos are available at this http URL.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:74e-5,eigenvector:0},{id:59,oaid:"1fad7fe0a7a90a8470a0688ad26bab6ceb8a85b7",doi:"10.1007/978-3-030-01246-5_41",title:"Graph R-CNN for Scene Graph Generation",authors:[{name:"Jianwei Yang",institutions:[]},{name:"Jiasen Lu",institutions:["Allen Institute of AI"]},{name:"Stefan Lee",institutions:[]},{name:"Dhruv Batra",institutions:[]},{name:"Devi Parikh",institutions:[]}],authorString:"Jianwei Yang; Jiasen Lu; Stefan Lee; Dhruv Batra; Devi Parikh",institutions:["Allen Institute of AI"],countries:[],year:2018,journal:"European Conference on Computer Vision",citations:954,abstract:"We propose a novel scene graph generation model called Graph R-CNN, that is both effective and efficient at detecting objects and their relations in images. Our model contains a Relation Proposal Network (RePN) that efficiently deals with the quadratic number of potential relations between objects in an image. We also propose an attentional Graph Convolutional Network (aGCN) that effectively captures contextual information between objects and relations. Finally, we introduce a new evaluation metric that is more holistic and realistic than existing metrics. We report state-of-the-art performance on scene graph generation as evaluated using both existing and our proposed metrics.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:46,n_refs_in_core:5,degree:20,community:3,deg_w:185.5,betweenness:.001,pagerank:.0039,eigenvector:.0013},{id:60,oaid:"687e80eb70c7bbad6001006d9269b202650a3354",doi:null,title:"Deep Convolutional Inverse Graphics Network",authors:[{name:"Tejas D. Kulkarni",institutions:[]},{name:"William F. Whitney",institutions:["DeepMind"]},{name:"Pushmeet Kohli",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Tejas D. Kulkarni; William F. Whitney; Pushmeet Kohli; J. Tenenbaum",institutions:["DeepMind"],countries:[],year:2015,journal:"Neural Information Processing Systems",citations:951,abstract:"This paper presents the Deep Convolution Inverse Graphics Network (DC-IGN), a model that aims to learn an interpretable representation of images, disentangled with respect to three-dimensional scene structure and viewing transformations such as depth rotations and lighting variations. The DC-IGN model is composed of multiple layers of convolution and de-convolution operators and is trained using the Stochastic Gradient Variational Bayes (SGVB) algorithm [10]. We propose a training procedure to encourage neurons in the graphics code layer to represent a specific transformation (e.g. pose or light). Given a single input image, our model can generate new images of the same object with variations in pose and lighting. We present qualitative and quantitative tests of the model's efficacy at learning a 3D rendering engine for varied object classes including faces and chairs.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:9,community:2,deg_w:38,betweenness:2e-4,pagerank:.0013,eigenvector:1e-4},{id:61,oaid:"4ad2b567d9e1d56efdeea304e605a690a2e6faf6",doi:"10.1016/S1364-6613(00)01819-2",title:"The conscious access hypothesis: origins and recent evidence.",authors:[{name:"B. Baars",institutions:[]}],authorString:"B. Baars",institutions:[],countries:[],year:2002,journal:"Trends in Cognitive Sciences",citations:949,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:59e-5,eigenvector:0},{id:62,oaid:"b7c0e47f8b768258b7d536c21b218e6c46ab8791",doi:null,title:"Learning to Parse Database Queries Using Inductive Logic Programming",authors:[{name:"J. Zelle",institutions:[]},{name:"R. Mooney",institutions:[]}],authorString:"J. Zelle; R. Mooney",institutions:[],countries:[],year:1996,journal:"AAAI/IAAI, Vol. 2",citations:942,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:8,community:5,deg_w:35.5,betweenness:1e-4,pagerank:.00118,eigenvector:.0015},{id:63,oaid:"47570e7f63e296f224a0e7f9a0d08b0de3cbaf40",doi:null,title:"Grammar as a Foreign Language",authors:[{name:"O. Vinyals",institutions:[]},{name:"Lukasz Kaiser",institutions:[]},{name:"Terry Koo",institutions:[]},{name:"Slav Petrov",institutions:["Google"]},{name:"I. Sutskever",institutions:[]},{name:"Geoffrey E. Hinton",institutions:[]}],authorString:"O. Vinyals; Lukasz Kaiser; Terry Koo; Slav Petrov; I. Sutskever; Geoffrey E. Hinton",institutions:["Google"],countries:[],year:2014,journal:"Neural Information Processing Systems",citations:942,abstract:"Syntactic constituency parsing is a fundamental problem in natural language processing and has been the subject of intensive research and engineering for decades. As a result, the most accurate parsers are domain specific, complex, and inefficient. In this paper we show that the domain agnostic attention-enhanced sequence-to-sequence model achieves state-of-the-art results on the most widely used syntactic constituency parsing dataset, when trained on a large synthetic corpus that was annotated using existing parsers. It also matches the performance of standard parsers when trained only on a small human-annotated dataset, which shows that this model is highly data-efficient, in contrast to sequence-to-sequence models without the attention mechanism. Our parser is also fast, processing over a hundred sentences per second with an unoptimized CPU implementation.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:35,n_refs_in_core:0,degree:6,community:5,deg_w:44,betweenness:7e-4,pagerank:.00138,eigenvector:9e-4},{id:64,oaid:"1f4a4769e4d2fb846e59c2f185e0377190739f18",doi:"10.1609/aaai.v25i1.7917",title:"Learning Structured Embeddings of Knowledge Bases",authors:[{name:"Antoine Bordes",institutions:[]},{name:"J. Weston",institutions:[]},{name:"R. Collobert",institutions:[]},{name:"Yoshua Bengio",institutions:[]}],authorString:"Antoine Bordes; J. Weston; R. Collobert; Yoshua Bengio",institutions:[],countries:[],year:2011,journal:"AAAI Conference on Artificial Intelligence",citations:939,abstract:"Many Knowledge Bases (KBs) are now readily available and encompass colossal quantities of information thanks to either a long-term funding effort (e.g. WordNet, OpenCyc) or a collaborative process (e.g. Freebase, DBpedia). However, each of them is based on a different rigorous symbolic framework which makes it hard to use their data in other systems. It is unfortunate because such rich structured knowledge might lead to a huge leap forward in many other areas of AI like nat- ural language processing (word-sense disambiguation, natural language understanding, ...), vision (scene classification, image semantic annotation, ...) or collaborative filtering. In this paper, we present a learning process based on an innovative neural network architecture designed to embed any of these symbolic representations into a more flexible continuous vector space in which the original knowledge is kept and enhanced. These learnt embeddings would allow data from any KB to be easily used in recent machine learning meth- ods for prediction and information retrieval. We illustrate our method on WordNet and Freebase and also present a way to adapt it to knowledge extraction from raw text.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1609/aaai.v25i1.7917",is_oa:!0,n_refs:22,n_refs_in_core:0,degree:5,community:0,deg_w:19,betweenness:4e-4,pagerank:93e-5,eigenvector:4e-4},{id:65,oaid:"06a73ad09664435f8b3cd90293f4e05a047cf375",doi:"10.1609/AAAI.V34I03.5681",title:"K-BERT: Enabling Language Representation with Knowledge Graph",authors:[{name:"Weijie Liu",institutions:["Peking University & Tencent Research"]},{name:"Peng Zhou",institutions:[]},{name:"Zhe Zhao",institutions:[]},{name:"Zhiruo Wang",institutions:[]},{name:"Qi Ju",institutions:[]},{name:"Haotang Deng",institutions:[]},{name:"Ping Wang",institutions:[]}],authorString:"Weijie Liu; Peng Zhou; Zhe Zhao; Zhiruo Wang; Qi Ju; Haotang Deng; Ping Wang",institutions:["Peking University & Tencent Research"],countries:[],year:2019,journal:"AAAI Conference on Artificial Intelligence",citations:938,abstract:"Pre-trained language representation models, such as BERT, capture a general language representation from large-scale corpora, but lack domain-specific knowledge. When reading a domain text, experts make inferences with relevant knowledge. For machines to achieve this capability, we propose a knowledge-enabled language representation model (K-BERT) with knowledge graphs (KGs), in which triples are injected into the sentences as domain knowledge. However, too much knowledge incorporation may divert the sentence from its correct meaning, which is called knowledge noise (KN) issue. To overcome KN, K-BERT introduces soft-position and visible matrix to limit the impact of knowledge. K-BERT can easily inject domain knowledge into the models by being equipped with a KG without pre-training by itself because it is capable of loading model parameters from the pre-trained BERT. Our investigation reveals promising results in twelve NLP tasks. Especially in domain-specific tasks (including finance, law, and medicine), K-BERT significantly outperforms BERT, which demonstrates that K-BERT is an excellent choice for solving the knowledge-driven problems that require experts.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/5681/5537",is_oa:!0,n_refs:24,n_refs_in_core:2,degree:26,community:1,deg_w:239,betweenness:.0019,pagerank:.00481,eigenvector:.1868},{id:66,oaid:"83dfbc785b4fa750a5efe4cadd1e6018094e0a39",doi:"10.1145/2043236.2043240",title:"Communications of the ACM",authors:[{name:"D. Gooch",institutions:[]}],authorString:"D. Gooch",institutions:[],countries:[],year:2011,journal:"XRDS",citations:934,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:2e-4,pagerank:55e-5,eigenvector:2e-4},{id:67,oaid:"46b5d408d950287637dd21ce04772d9b2bacfd14",doi:"10.1109/CVPR.2018.00133",title:"Image Generation from Scene Graphs",authors:[{name:"Justin Johnson",institutions:[]},{name:"Agrim Gupta",institutions:[]},{name:"Li Fei-Fei",institutions:[]}],authorString:"Justin Johnson; Agrim Gupta; Li Fei-Fei",institutions:[],countries:[],year:2018,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:933,abstract:"To truly understand the visual world our models should be able not only to recognize images but also generate them. To this end, there has been exciting recent progress on generating images from natural language descriptions. These methods give stunning results on limited domains such as descriptions of birds or flowers, but struggle to faithfully reproduce complex sentences with many objects and relationships. To overcome this limitation we propose a method for generating images from scene graphs, enabling explicitly reasoning about objects and their relationships. Our model uses graph convolution to process input graphs, computes a scene layout by predicting bounding boxes and segmentation masks for objects, and converts the layout to an image with a cascaded refinement network. The network is trained adversarially against a pair of discriminators to ensure realistic outputs. We validate our approach on Visual Genome and COCO-Stuff, where qualitative results, ablations, and user studies demonstrate our method's ability to generate complex images with multiple objects.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1804.01622",is_oa:!0,n_refs:59,n_refs_in_core:4,degree:19,community:3,deg_w:105.5,betweenness:.0067,pagerank:.0028,eigenvector:5e-4},{id:68,oaid:"7e9ff94476f41041c75e253e84f487db00e9c861",doi:null,title:"Long Range Arena: A Benchmark for Efficient Transformers",authors:[{name:"Yi Tay",institutions:[]},{name:"Mostafa Dehghani",institutions:[]},{name:"Samira Abnar",institutions:[]},{name:"Yikang Shen",institutions:[]},{name:"Dara Bahri",institutions:[]},{name:"Philip Pham",institutions:[]},{name:"J. Rao",institutions:[]},{name:"Liu Yang",institutions:[]},{name:"Sebastian Ruder",institutions:["Cohere"]},{name:"Donald Metzler",institutions:["Google"]}],authorString:"Yi Tay; Mostafa Dehghani; Samira Abnar; Yikang Shen; Dara Bahri; Philip Pham; J. Rao; Liu Yang; Sebastian Ruder; Donald Metzler",institutions:["Cohere","Google"],countries:[],year:2020,journal:"International Conference on Learning Representations",citations:926,abstract:"Transformers do not scale very well to long sequence lengths largely because of quadratic self-attention complexity. In the recent months, a wide spectrum of efficient, fast Transformers have been proposed to tackle this problem, more often than not claiming superior or comparable model quality to vanilla Transformer models. To this date, there is no well-established consensus on how to evaluate this class of models. Moreover, inconsistent benchmarking on a wide spectrum of tasks and datasets makes it difficult to assess relative model quality amongst many models. This paper proposes a systematic and unified benchmark, LRA, specifically focused on evaluating model quality under long-context scenarios. Our benchmark is a suite of tasks consisting of sequences ranging from $1K$ to $16K$ tokens, encompassing a wide range of data types and modalities such as text, natural, synthetic images, and mathematical expressions requiring similarity, structural, and visual-spatial reasoning. We systematically evaluate ten well-established long-range Transformer models (Reformers, Linformers, Linear Transformers, Sinkhorn Transformers, Performers, Synthesizers, Sparse Transformers, and Longformers) on our newly proposed benchmark suite. LRA paves the way towards better understanding this class of efficient Transformer models, facilitates more research in this direction, and presents new challenging tasks to tackle. Our benchmark code will be released at this https URL.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12,betweenness:0,pagerank:62e-5,eigenvector:7e-4},{id:69,oaid:"d586a5b2ba87da716847e0dc773f9b0c5af364f6",doi:"10.2307/1166115",title:"Overregularization in language acquisition.",authors:[{name:"G. Marcus",institutions:[]},{name:"S. Pinker",institutions:[]},{name:"M. Ullman",institutions:[]},{name:"Michelle A. Hollander",institutions:[]},{name:"T. Rosen",institutions:[]},{name:"Fei Xu",institutions:[]},{name:"H. Clahsen",institutions:[]}],authorString:"G. Marcus; S. Pinker; M. Ullman; Michelle A. Hollander; T. Rosen; Fei Xu; H. Clahsen",institutions:[],countries:[],year:1992,journal:"Monographs of the Society for Research in Child Development",citations:923,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:70,oaid:"5288b9f3a9f575543f44c39e1d3b78b3ca4c99da",doi:"10.48550/arXiv.2204.05999",title:"InCoder: A Generative Model for Code Infilling and Synthesis",authors:[{name:"Daniel Fried",institutions:["Carnegie Mellon University"]},{name:"Armen Aghajanyan",institutions:[]},{name:"Jessy Lin",institutions:[]},{name:"Sida I. Wang",institutions:[]},{name:"Eric Wallace",institutions:["UC Berkeley"]},{name:"Freda Shi",institutions:["Toyota Technological Institute at Chicago"]},{name:"Ruiqi Zhong",institutions:[]},{name:"Wen-tau Yih",institutions:[]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]},{name:"M. Lewis",institutions:[]}],authorString:"Daniel Fried; Armen Aghajanyan; Jessy Lin; Sida I. Wang; Eric Wallace; Freda Shi; Ruiqi Zhong; Wen-tau Yih; Luke Zettlemoyer; M. Lewis",institutions:["Carnegie Mellon University","Facebook","Toyota Technological Institute at Chicago","UC Berkeley","University of Washington"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:921,abstract:"Code is seldom written in a single left-to-right pass and is instead repeatedly edited and refined. We introduce InCoder, a unified generative model that can perform program synthesis (via left-to-right generation) as well as editing (via infilling). InCoder is trained to generate code files from a large corpus of permissively licensed code, where regions of code have been randomly masked and moved to the end of each file, allowing code infilling with bidirectional context. Our model is the first generative model that is able to directly perform zero-shot code infilling, which we evaluate on challenging tasks such as type inference, comment generation, and variable re-naming. We find that the ability to condition on bidirectional context substantially improves performance on these tasks, while still performing comparably on standard program synthesis benchmarks in comparison to left-to-right only models pretrained at similar scale. The InCoder models and code are publicly released. https://sites.google.com/view/incoder-code-models",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2204.05999",is_oa:!0,n_refs:75,n_refs_in_core:5,degree:21,community:5,deg_w:169.5,betweenness:.0155,pagerank:.00465,eigenvector:.0307},{id:71,oaid:"784220a5a2ad452282f8af006a6cb5715d54d0ed",doi:"10.1007/978-1-4899-7687-1_100268",title:"Link-Based Classification",authors:[{name:"Qing Lu",institutions:[]},{name:"L. Getoor",institutions:[]}],authorString:"Qing Lu; L. Getoor",institutions:[],countries:[],year:2003,journal:"Encyclopedia of Machine Learning and Data Mining",citations:917,abstract:"",keywords:[],concepts:[],pdf_url:"https://drum.lib.umd.edu/bitstreams/adc0c6ae-f26a-4621-969a-447d92930cc9/download",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:72,oaid:"cd9a204d435b70b5f0e85dbf622d856fb06dbc44",doi:"10.1145/3005777",title:"Integration",authors:[{name:"Ron Wakkary",institutions:[]},{name:"Erik Stolterman",institutions:[]}],authorString:"Ron Wakkary; Erik Stolterman",institutions:[],countries:[],year:2016,journal:"Interactions",citations:916,abstract:"• What Is Wireless Setup, on page 2 • Configuring WLCs in Wireless Network, on page 4 • Active Directory with Wireless Setup, on page 6 • Guest Portals in Wireless Setup, on page 6 • Wireless Network Self-Registration Portal, on page 7 • Wireless Network Sponsored Guest Flow, on page 7 • Wireless Setup BYOD Flow For Native Supplicant and Certificate Provisioning, on page 8 • 802.1X Wireless Flow, on page 9 • Changes to ISE and WLC by Wireless Setup, on page 11 • Enable Your Switch to Support Standard Web Authentication, on page 12 • Local Username and Password Definition for Synthetic RADIUS Transactions, on page 13 • NTP Server Configuration to Ensure Accurate Log and Accounting Timestamps, on page 13 • Command to Enable AAA Functions, on page 13 • RADIUS Server Configuration on the Switch, on page 14 • Command to Enable RADIUS Change of Authorization (CoA), on page 14 • Command to Enable Device Tracking and DHCP Snooping, on page 15 • Command to Enable 802.1X Port-Based Authentication, on page 15 • Command to Enable EAP for Critical Authentications, on page 15 • Command to Throttle AAA Requests Using Recovery Delay, on page 16 • VLAN Definitions Based on Enforcement States, on page 16 • Local (Default) ACLs Definition on the Switch, on page 17 • Enable Switch Ports for 802.1X and MAB, on page 18 • Command to Enable 802.1X based on Identity-Based Networking Services, on page 20 • Command to Enable EPM Logging, on page 21 • Command to Enable SNMP Traps, on page 22 • Command to Enable SNMP v3 Query for Profiling, on page 22 • Command to Enable MAC Notification Traps for Profiler to Collect, on page 22 • RADIUS Idle-Timeout Configuration on the Switch, on page 23 • Wireless LAN Controller Configuration for iOS Supplicant Provisioning, on page 23 • Configuring ACLs on the Wireless LAN Controller for MDM Interoperability, on page 23",keywords:[],concepts:[],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3005777?download=true",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:44e-5,eigenvector:0},{id:73,oaid:"eef7cfe8267954adbb4675576072a1d80ca7a3a8",doi:"10.18653/v1/N19-1245",title:"MathQA: Towards Interpretable Math Word Problem Solving with Operation-Based Formalisms",authors:[{name:"Aida Amini",institutions:["University of Washington"]},{name:"Saadia Gabriel",institutions:[]},{name:"Shanchuan Lin",institutions:[]},{name:"Rik Koncel-Kedziorski",institutions:[]},{name:"Yejin Choi",institutions:[]},{name:"Hannaneh Hajishirzi",institutions:[]}],authorString:"Aida Amini; Saadia Gabriel; Shanchuan Lin; Rik Koncel-Kedziorski; Yejin Choi; Hannaneh Hajishirzi",institutions:["University of Washington"],countries:[],year:2019,journal:"North American Chapter of the Association for Computational Linguistics",citations:899,abstract:"We introduce a large-scale dataset of math word problems and an interpretable neural math problem solver by learning to map problems to their operation programs. Due to annotation challenges, current datasets in this domain have been either relatively small in scale or did not offer precise operational annotations over diverse problem types. We introduce a new representation language to model operation programs corresponding to each math problem that aim to improve both the performance and the interpretability of the learned models. Using this representation language, we significantly enhance the AQUA-RAT dataset with fully-specified operational programs. We additionally introduce a neural sequence-to-program model with automatic problem categorization. Our experiments show improvements over competitive baselines in our dataset as well as the AQUA-RAT dataset. The results are still lower than human performance indicating that the dataset poses new challenges for future research. Our dataset is available at https://math-qa.github.io/math-QA/",keywords:[],concepts:[],pdf_url:"https://doi.org/10.18653/v1/n19-1245",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:7,community:5,deg_w:29,betweenness:2e-4,pagerank:.00108,eigenvector:.0019},{id:74,oaid:"9caf5445e47af0fc0782bec1f26e4de840a0b5a9",doi:"10.1016/0004-3702(94)90105-8",title:"Knowledge-Based Artificial Neural Networks",authors:[{name:"G. Towell",institutions:[]},{name:"J. Shavlik",institutions:[]}],authorString:"G. Towell; J. Shavlik",institutions:[],countries:[],year:1994,journal:"Artificial Intelligence",citations:891,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:4e-4,eigenvector:1e-4},{id:75,oaid:"b32a6f6ef7dd775e0f876b4713ceccebc56e651e",doi:"10.1145/3520312.3534862",title:"A systematic evaluation of large language models of code",authors:[{name:"Frank F. Xu",institutions:[]},{name:"Uri Alon",institutions:["Carnegie Mellon University"]},{name:"Graham Neubig",institutions:[]},{name:"Vincent J. Hellendoorn",institutions:[]}],authorString:"Frank F. Xu; Uri Alon; Graham Neubig; Vincent J. Hellendoorn",institutions:["Carnegie Mellon University"],countries:[],year:2022,journal:"MAPS@PLDI",citations:890,abstract:"Large language models (LMs) of code have recently shown tremendous promise in completing code and synthesizing code from natural language descriptions. However, the current state-of-the-art code LMs (e.g., Codex) are not publicly available, leaving many questions about their model and data design decisions. We aim to fill in some of these blanks through a systematic evaluation of the largest existing models: Codex, GPT-J, GPT-Neo, GPT-NeoX-20B, and CodeParrot, across various programming languages. Although Codex itself is not open-source, we find that existing opensource models do achieve close results in some programming languages, although targeted mainly for natural language modeling. We further identify an important missing piece in the form of a large open-source model trained exclusively on a multi-lingual corpus of code. We release a new model, PolyCoder, with 2.7B parameters based on the GPT-2 architecture, that was trained on 249GB of code across 12 programming languages on a single machine. In the C programming language, PolyCoder outperforms all models including Codex. Our trained models are open-source and publicly available at https://github.com/VHellendoorn/Code-LMs, which enables future research and application in this area. We have an online appendix at https://arxiv.org/abs/2202.13169.",keywords:[],concepts:[],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3520312.3534862",is_oa:!0,n_refs:34,n_refs_in_core:0,degree:17,community:5,deg_w:107.5,betweenness:.0028,pagerank:.00285,eigenvector:.0113},{id:76,oaid:"7ff03b371acc40f5ca38c19876ebec499a7959d9",doi:"10.1007/978-3-662-04726-2",title:"Foundations of Genetic Programming",authors:[{name:"William B. Langdon",institutions:[]},{name:"Riccardo Poli",institutions:[]}],authorString:"William B. Langdon; Riccardo Poli",institutions:[],countries:[],year:2002,journal:"Springer Berlin Heidelberg",citations:884,abstract:"",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1007/978-3-662-04726-2",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:83e-5,eigenvector:0},{id:77,oaid:"476ba2a1c5204d46e420506afacb4b0da6abb868",doi:null,title:"Shakey the Robot",authors:[{name:"N. Nilsson",institutions:[]}],authorString:"N. Nilsson",institutions:[],countries:[],year:1984,journal:"",citations:883,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8,betweenness:0,pagerank:69e-5,eigenvector:1e-4},{id:78,oaid:"a389456fdc46e458d0a813a608b71b44b2ff8e62",doi:"10.1609/aaai.v25i1.7979",title:"Understanding Natural Language Commands for Robotic Navigation and Mobile Manipulation",authors:[{name:"Stefanie Tellex",institutions:[]},{name:"T. Kollar",institutions:[]},{name:"Steven Dickerson",institutions:[]},{name:"Matthew R. Walter",institutions:[]},{name:"A. Banerjee",institutions:[]},{name:"S. Teller",institutions:[]},{name:"N. Roy",institutions:[]}],authorString:"Stefanie Tellex; T. Kollar; Steven Dickerson; Matthew R. Walter; A. Banerjee; S. Teller; N. Roy",institutions:[],countries:[],year:2011,journal:"AAAI Conference on Artificial Intelligence",citations:875,abstract:`This paper describes a new model for understanding natural language commands given to autonomous systems that perform navigation and mobile manipulation in semi-structured environments. Previous approaches have used models with fixed structure to infer the likelihood of a sequence of actions given the environment and the command. In contrast, our framework, called Generalized Grounding Graphs, dynamically instantiates a probabilistic graphical model for a particular natural language command according to the command's hierarchical and compositional semantic structure. Our system performs inference in the model to successfully find and execute plans corresponding to natural language commands such as "Put the tire pallet on the truck." The model is trained using a corpus of commands collected using crowdsourcing. We pair each command with robot actions and use the corpus to learn the parameters of the model. We evaluate the robot's performance by inferring plans from natural language commands, executing each plan in a realistic robot simulator, and asking users to evaluate the system's performance. We demonstrate that our system can successfully follow many natural language commands from the corpus.`,keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/7979/7838",is_oa:!0,n_refs:22,n_refs_in_core:5,degree:15,community:4,deg_w:86,betweenness:.0011,pagerank:.00259,eigenvector:.001},{id:79,oaid:"3950df97ea527009a32569cb7016bc3df1383dca",doi:"10.18653/V1/2021.NAACL-MAIN.45",title:"QA-GNN: Reasoning with Language Models and Knowledge Graphs for Question Answering",authors:[{name:"Michihiro Yasunaga",institutions:[]},{name:"Hongyu Ren",institutions:[]},{name:"Antoine Bosselut",institutions:["EPFL"]},{name:"Percy Liang",institutions:[]},{name:"J. Leskovec",institutions:[]}],authorString:"Michihiro Yasunaga; Hongyu Ren; Antoine Bosselut; Percy Liang; J. Leskovec",institutions:["EPFL"],countries:[],year:2021,journal:"North American Chapter of the Association for Computational Linguistics",citations:872,abstract:"The problem of answering questions using knowledge from pre-trained language models (LMs) and knowledge graphs (KGs) presents two challenges: given a QA context (question and answer choice), methods need to (i) identify relevant knowledge from large KGs, and (ii) perform joint reasoning over the QA context and KG. Here we propose a new model, QA-GNN, which addresses the above challenges through two key innovations: (i) relevance scoring, where we use LMs to estimate the importance of KG nodes relative to the given QA context, and (ii) joint reasoning, where we connect the QA context and KG to form a joint graph, and mutually update their representations through graph-based message passing. We evaluate QA-GNN on the CommonsenseQA and OpenBookQA datasets, and show its improvement over existing LM and LM+KG models, as well as its capability to perform interpretable and structured reasoning, e.g., correctly handling negation in questions.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.naacl-main.45.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:1,deg_w:13,betweenness:0,pagerank:58e-5,eigenvector:.0076},{id:80,oaid:"4af09143735210777281b66997ec12994dbb43d4",doi:"10.18653/v1/P19-1279",title:"Matching the Blanks: Distributional Similarity for Relation Learning",authors:[{name:"Livio Baldini Soares",institutions:["Google Deepmind"]},{name:"Nicholas FitzGerald",institutions:["Google Research"]},{name:"Jeffrey Ling",institutions:[]},{name:"T. Kwiatkowski",institutions:[]}],authorString:"Livio Baldini Soares; Nicholas FitzGerald; Jeffrey Ling; T. Kwiatkowski",institutions:["Google Deepmind","Google Research"],countries:[],year:2019,journal:"Annual Meeting of the Association for Computational Linguistics",citations:869,abstract:"General purpose relation extractors, which can model arbitrary relations, are a core aspiration in information extraction. Efforts have been made to build general purpose extractors that represent relations with their surface forms, or which jointly embed surface forms with relations from an existing knowledge graph. However, both of these approaches are limited in their ability to generalize. In this paper, we build on extensions of Harris’ distributional hypothesis to relations, as well as recent advances in learning text representations (specifically, BERT), to build task agnostic relation representations solely from entity-linked text. We show that these representations significantly outperform previous work on exemplar based relation extraction (FewRel) even without using any of that task’s training data. We also show that models initialized with our task agnostic representations, and then tuned on supervised relation extraction datasets, significantly outperform the previous methods on SemEval 2010 Task 8, KBP37, and TACRED",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P19-1279.pdf",is_oa:!0,n_refs:32,n_refs_in_core:2,degree:20,community:1,deg_w:129,betweenness:.0098,pagerank:.00298,eigenvector:.0802},{id:81,oaid:"50f76736c3090c6effac25400e5e40cc0b7b5ad9",doi:null,title:"The Neuro-Symbolic Concept Learner: Interpreting Scenes, Words, and Sentences From Natural Supervision",authors:[{name:"Jiayuan Mao",institutions:[]},{name:"Chuang Gan",institutions:[]},{name:"Pushmeet Kohli",institutions:[]},{name:"J. Tenenbaum",institutions:[]},{name:"Jiajun Wu",institutions:["Stanford University"]}],authorString:"Jiayuan Mao; Chuang Gan; Pushmeet Kohli; J. Tenenbaum; Jiajun Wu",institutions:["Stanford University"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:867,abstract:"We propose the Neuro-Symbolic Concept Learner (NS-CL), a model that learns visual concepts, words, and semantic parsing of sentences without explicit supervision on any of them; instead, our model learns by simply looking at images and reading paired questions and answers. Our model builds an object-based scene representation and translates sentences into executable, symbolic programs. To bridge the learning of two modules, we use a neuro-symbolic reasoning module that executes these programs on the latent scene representation. Analogical to human concept learning, the perception module learns visual concepts based on the language description of the object being referred to. Meanwhile, the learned visual concepts facilitate learning new words and parsing new sentences. We use curriculum learning to guide the searching over the large compositional space of images and language. Extensive experiments demonstrate the accuracy and efficiency of our model on learning visual concepts, word representations, and semantic parsing of sentences. Further, our method allows easy generalization to new object attributes, compositions, language concepts, scenes and questions, and even new program domains. It also empowers applications including visual question answering and bidirectional image-text retrieval.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:50,n_refs_in_core:23,degree:46,community:3,deg_w:335.5,betweenness:.0448,pagerank:.0086,eigenvector:.0025},{id:82,oaid:"7cbc2a7843411a1768ab762930707af0a3c33a19",doi:null,title:"Using DeepSpeed and Megatron to Train Megatron-Turing NLG 530B, A Large-Scale Generative Language Model",authors:[{name:"Shaden Smith",institutions:[]},{name:"M. Patwary",institutions:[]},{name:"Brandon Norick",institutions:[]},{name:"P. LeGresley",institutions:[]},{name:"Samyam Rajbhandari",institutions:[]},{name:"J. Casper",institutions:[]},{name:"Zhun Liu",institutions:[]},{name:"Shrimai Prabhumoye",institutions:[]},{name:"George Zerveas",institutions:["Microsoft","Brown University"]},{name:"V. Korthikanti",institutions:[]},{name:"Elton Zhang",institutions:[]},{name:"R. Child",institutions:[]},{name:"Reza Yazdani Aminabadi",institutions:[]},{name:"J. Bernauer",institutions:[]},{name:"Xia Song",institutions:[]},{name:"M. Shoeybi",institutions:[]},{name:"Yuxiong He",institutions:[]},{name:"Michael Houston",institutions:[]},{name:"Saurabh Tiwary",institutions:[]},{name:"Bryan Catanzaro",institutions:[]}],authorString:"Shaden Smith; M. Patwary; Brandon Norick; P. LeGresley; Samyam Rajbhandari; J. Casper; Zhun Liu; Shrimai Prabhumoye; George Zerveas; V. Korthikanti; Elton Zhang; R. Child et al.",institutions:["Brown University","Microsoft"],countries:[],year:2022,journal:"arXiv.org",citations:862,abstract:"Pretrained general-purpose language models can achieve state-of-the-art accuracies in various natural language processing domains by adapting to downstream tasks via zero-shot, few-shot and fine-tuning techniques. Because of their success, the size of these models has increased rapidly, requiring high-performance hardware, software, and algorithmic techniques to enable training such large models. As the result of a joint effort between Microsoft and NVIDIA, we present details on the training of the largest monolithic transformer based language model, Megatron-Turing NLG 530B (MT-NLG), with 530 billion parameters. In this paper, we first focus on the infrastructure as well as the 3D parallelism methodology used to train this model using DeepSpeed and Megatron. Next, we detail the training process, the design of our training corpus, and our data curation techniques, which we believe is a key ingredient to the success of the model. Finally, we discuss various evaluation results, as well as other interesting observations and new properties exhibited by MT-NLG. We demonstrate that MT-NLG achieves superior zero-, one-, and few-shot learning accuracies on several NLP benchmarks and establishes new state-of-the-art results. We believe that our contributions will help further the development of large-scale training infrastructures, large-scale language models, and natural language generations.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:69,n_refs_in_core:0,degree:16,community:1,deg_w:134.5,betweenness:.0014,pagerank:.00312,eigenvector:.0623},{id:83,oaid:"29ade9f04f11dd8d434f051563f03928ed62c21b",doi:"10.1073/pnas.1306572110",title:"Simulation as an engine of physical scene understanding",authors:[{name:"P. Battaglia",institutions:[]},{name:"Jessica B. Hamrick",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"P. Battaglia; Jessica B. Hamrick; J. Tenenbaum",institutions:[],countries:[],year:2013,journal:"Proceedings of the National Academy of Sciences of the United States of America",citations:861,abstract:"",keywords:[],concepts:[],pdf_url:"https://europepmc.org/articles/pmc3831455?pdf=render",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:6,community:2,deg_w:22.5,betweenness:0,pagerank:9e-4,eigenvector:1e-4},{id:84,oaid:"56cafbac34f2bb3f6a9828cd228ff281b810d6bb",doi:"10.1162/tacl_a_00360",title:"KEPLER: A Unified Model for Knowledge Embedding and Pre-trained Language Representation",authors:[{name:"Xiaozhi Wang",institutions:["Tsinghua University"]},{name:"Tianyu Gao",institutions:["Princeton University"]},{name:"Zhaocheng Zhu",institutions:[]},{name:"Zhiyuan Liu",institutions:["Tsinghua University"]},{name:"Juan-Zi Li",institutions:[]},{name:"Jian Tang",institutions:[]}],authorString:"Xiaozhi Wang; Tianyu Gao; Zhaocheng Zhu; Zhiyuan Liu; Juan-Zi Li; Jian Tang",institutions:["Princeton University","Tsinghua University"],countries:[],year:2019,journal:"Transactions of the Association for Computational Linguistics",citations:851,abstract:"Abstract Pre-trained language representation models (PLMs) cannot well capture factual knowledge from text. In contrast, knowledge embedding (KE) methods can effectively represent the relational facts in knowledge graphs (KGs) with informative entity embeddings, but conventional KE models cannot take full advantage of the abundant textual information. In this paper, we propose a unified model for Knowledge Embedding and Pre-trained LanguagERepresentation (KEPLER), which can not only better integrate factual knowledge into PLMs but also produce effective text-enhanced KE with the strong PLMs. In KEPLER, we encode textual entity descriptions with a PLM as their embeddings, and then jointly optimize the KE and language modeling objectives. Experimental results show that KEPLER achieves state-of-the-art performances on various NLP tasks, and also works remarkably well as an inductive KE model on KG link prediction. Furthermore, for pre-training and evaluating KEPLER, we construct Wikidata5M1 , a large-scale KG dataset with aligned entity descriptions, and benchmark state-of-the-art KE methods on it. It shall serve as a new KE benchmark and facilitate the research on large KG, inductive KE, and KG with text. The source code can be obtained from https://github.com/THU-KEG/KEPLER.",keywords:[],concepts:[],pdf_url:"https://direct.mit.edu/tacl/article-pdf/doi/10.1162/tacl_a_00360/1923927/tacl_a_00360.pdf",is_oa:!0,n_refs:72,n_refs_in_core:7,degree:31,community:1,deg_w:412.5,betweenness:.0051,pagerank:.00811,eigenvector:.307},{id:85,oaid:"5f0625c30014c12f333eb518268647673d18f9f1",doi:"10.1017/S0140525X17000140",title:"What can the brain teach us about building artificial intelligence?",authors:[{name:"B. Lake",institutions:[]},{name:"T. Ullman",institutions:[]},{name:"J. Tenenbaum",institutions:[]},{name:"S. Gershman",institutions:[]}],authorString:"B. Lake; T. Ullman; J. Tenenbaum; S. Gershman",institutions:[],countries:[],year:2016,journal:"Behavioral and Brain Sciences",citations:848,abstract:"Abstract Lake et al. offer a timely critique on the recent accomplishments in artificial intelligence from the vantage point of human intelligence and provide insightful suggestions about research directions for building more human-like intelligence. Because we agree with most of the points they raised, here we offer a few points that are complementary.",keywords:["Sociology"],concepts:["Sociology"],pdf_url:"https://arxiv.org/pdf/1712.01626",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12,betweenness:3e-4,pagerank:92e-5,eigenvector:0},{id:86,oaid:"bcdaf6c98ddbd6809cf6241aa77200d7394db163",doi:"10.48550/arXiv.2305.11738",title:"CRITIC: Large Language Models Can Self-Correct with Tool-Interactive Critiquing",authors:[{name:"Zhibin Gou",institutions:["Tsinghua University"]},{name:"Zhihong Shao",institutions:[]},{name:"Yeyun Gong",institutions:[]},{name:"Yelong Shen",institutions:[]},{name:"Yujiu Yang",institutions:[]},{name:"Nan Duan",institutions:[]},{name:"Weizhu Chen",institutions:[]}],authorString:"Zhibin Gou; Zhihong Shao; Yeyun Gong; Yelong Shen; Yujiu Yang; Nan Duan; Weizhu Chen",institutions:["Tsinghua University"],countries:[],year:2023,journal:"International Conference on Learning Representations",citations:841,abstract:'Recent developments in large language models (LLMs) have been impressive. However, these models sometimes show inconsistencies and problematic behavior, such as hallucinating facts, generating flawed code, or creating offensive and toxic content. Unlike these models, humans typically utilize external tools to cross-check and refine their initial content, like using a search engine for fact-checking, or a code interpreter for debugging. Inspired by this observation, we introduce a framework called CRITIC that allows LLMs, which are essentially"black boxes"to validate and progressively amend their own outputs in a manner similar to human interaction with tools. More specifically, starting with an initial output, CRITIC interacts with appropriate tools to evaluate certain aspects of the text, and then revises the output based on the feedback obtained during this validation process. Comprehensive evaluations involving free-form question answering, mathematical program synthesis, and toxicity reduction demonstrate that CRITIC consistently enhances the performance of LLMs. Meanwhile, our research highlights the crucial importance of external feedback in promoting the ongoing self-improvement of LLMs.',keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2305.11738",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:5,deg_w:4,betweenness:0,pagerank:39e-5,eigenvector:2e-4},{id:87,oaid:"1bdd75a37f7c601f01e9d31c2551fa9f2067ffd7",doi:"10.1109/CVPR.2016.501",title:"MovieQA: Understanding Stories in Movies through Question-Answering",authors:[{name:"Makarand Tapaswi",institutions:["Wadhwani AI","IIIT Hyderabad"]},{name:"Yukun Zhu",institutions:[]},{name:"R. Stiefelhagen",institutions:[]},{name:"A. Torralba",institutions:[]},{name:"R. Urtasun",institutions:[]},{name:"S. Fidler",institutions:[]}],authorString:"Makarand Tapaswi; Yukun Zhu; R. Stiefelhagen; A. Torralba; R. Urtasun; S. Fidler",institutions:["IIIT Hyderabad","Wadhwani AI"],countries:[],year:2015,journal:"Computer Vision and Pattern Recognition",citations:832,abstract:'We introduce the MovieQA dataset which aims to evaluate automatic story comprehension from both video and text. The dataset consists of 14,944 questions about 408 movies with high semantic diversity. The questions range from simpler "Who" did "What" to "Whom", to "Why" and "How" certain events occurred. Each question comes with a set of five possible answers, a correct one and four deceiving answers provided by human annotators. Our dataset is unique in that it contains multiple sources of information - video clips, plots, subtitles, scripts, and DVS. We analyze our data through various statistics and methods. We further extend existing QA techniques to show that question-answering with such open-ended semantics is hard. We make this data set public along with an evaluation benchmark to encourage inspiring work in this challenging domain.',keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1512.02902",is_oa:!0,n_refs:51,n_refs_in_core:2,degree:20,community:3,deg_w:162,betweenness:.0024,pagerank:.00339,eigenvector:.0014},{id:88,oaid:"9b093787f9be3d480cd11f8ec6ca5b0e44050d6d",doi:"10.1038/s41586-023-06747-5",title:"Solving olympiad geometry without human demonstrations",authors:[{name:"Trieu H. Trinh",institutions:[]},{name:"Yuhuai Wu",institutions:[]},{name:"Quoc V. Le",institutions:[]},{name:"He He",institutions:[]},{name:"Thang Luong",institutions:[]}],authorString:"Trieu H. Trinh; Yuhuai Wu; Quoc V. Le; He He; Thang Luong",institutions:[],countries:[],year:2024,journal:"Nature",citations:829,abstract:"Proving mathematical theorems at the olympiad level represents a notable milestone in human-level automated reasoning1–4, owing to their reputed difficulty among the world’s best talents in pre-university mathematics. Current machine-learning approaches, however, are not applicable to most mathematical domains owing to the high cost of translating human proofs into machine-verifiable format. The problem is even worse for geometry because of its unique translation challenges1,5, resulting in severe scarcity of training data. We propose AlphaGeometry, a theorem prover for Euclidean plane geometry that sidesteps the need for human demonstrations by synthesizing millions of theorems and proofs across different levels of complexity. AlphaGeometry is a neuro-symbolic system that uses a neural language model, trained from scratch on our large-scale synthetic data, to guide a symbolic deduction engine through infinite branching points in challenging problems. On a test set of 30 latest olympiad-level problems, AlphaGeometry solves 25, outperforming the previous best method that only solves ten problems and approaching the performance of an average International Mathematical Olympiad (IMO) gold medallist. Notably, AlphaGeometry produces human-readable proofs, solves all geometry problems in the IMO 2000 and 2015 under human expert evaluation and discovers a generalized version of a translated IMO theorem in 2004. A new neuro-symbolic theorem prover for Euclidean plane geometry trained from scratch on millions of synthesized theorems and proofs outperforms the previous best method and reaches the performance of an olympiad gold medallist.",keywords:[],concepts:[],pdf_url:"https://www.nature.com/articles/s41586-023-06747-5.pdf",is_oa:!0,n_refs:42,n_refs_in_core:10,degree:17,community:6,deg_w:76,betweenness:.0093,pagerank:.00265,eigenvector:.0031},{id:89,oaid:"31184789ef4c3084af930b1e0dede3215b4a9240",doi:null,title:"KG-BERT: BERT for Knowledge Graph Completion",authors:[{name:"Liang Yao",institutions:["Sun Yat-sen University"]},{name:"Chengsheng Mao",institutions:["Northwestern University"]},{name:"Yuan Luo",institutions:[]}],authorString:"Liang Yao; Chengsheng Mao; Yuan Luo",institutions:["Northwestern University","Sun Yat-sen University"],countries:[],year:2019,journal:"arXiv.org",citations:827,abstract:"Knowledge graphs are important resources for many artificial intelligence tasks but often suffer from incompleteness. In this work, we propose to use pre-trained language models for knowledge graph completion. We treat triples in knowledge graphs as textual sequences and propose a novel framework named Knowledge Graph Bidirectional Encoder Representations from Transformer (KG-BERT) to model these triples. Our method takes entity and relation descriptions of a triple as input and computes scoring function of the triple with the KG-BERT language model. Experimental results on multiple benchmark knowledge graphs show that our method can achieve state-of-the-art performance in triple classification, link prediction and relation prediction tasks.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:44,n_refs_in_core:0,degree:18,community:1,deg_w:180,betweenness:8e-4,pagerank:.00375,eigenvector:.1394},{id:90,oaid:"b9b7686b465e4c9a080781ed32d11e5112766f48",doi:null,title:"Research Group ( CIS ) Department of Computer & Information Science June 2007 Provenance Semirings",authors:[{name:"Todd J. Green",institutions:[]}],authorString:"Todd J. Green",institutions:[],countries:[],year:2015,journal:"",citations:826,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:42e-5,eigenvector:0},{id:91,oaid:"7e928ef936c2815d7522c5176163d6ab7309a8b7",doi:"10.18653/v1/D15-1174",title:"Representing Text for Joint Embedding of Text and Knowledge Bases",authors:[{name:"Kristina Toutanova",institutions:[]},{name:"Danqi Chen",institutions:["Princeton University"]},{name:"Patrick Pantel",institutions:[]},{name:"Hoifung Poon",institutions:[]},{name:"Pallavi Choudhury",institutions:[]},{name:"Michael Gamon",institutions:[]}],authorString:"Kristina Toutanova; Danqi Chen; Patrick Pantel; Hoifung Poon; Pallavi Choudhury; Michael Gamon",institutions:["Princeton University"],countries:[],year:2015,journal:"Conference on Empirical Methods in Natural Language Processing",citations:825,abstract:"Models that learn to represent textual and knowledge base relations in the same continuous latent space are able to perform joint inferences among the two kinds of relations and obtain high accuracy on knowledge base completion (Riedel et al., 2013). In this paper we propose a model that captures the compositional structure of textual relations, and jointly optimizes entity, knowledge base, and textual relation representations. The proposed model significantly improves performance over a model that does not share parameters among textual relations with common sub-structure.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D15-1174.pdf",is_oa:!0,n_refs:30,n_refs_in_core:6,degree:22,community:0,deg_w:170,betweenness:.0072,pagerank:.00455,eigenvector:.042},{id:92,oaid:"1d803f07e4591bd67c358eef715bcd443e821894",doi:null,title:"BC-Z: Zero-Shot Task Generalization with Robotic Imitation Learning",authors:[{name:"Eric Jang",institutions:[]},{name:"A. Irpan",institutions:[]},{name:"Mohi Khansari",institutions:[]},{name:"Daniel Kappler",institutions:[]},{name:"F. Ebert",institutions:[]},{name:"Corey Lynch",institutions:[]},{name:"S. Levine",institutions:[]},{name:"Chelsea Finn",institutions:[]}],authorString:"Eric Jang; A. Irpan; Mohi Khansari; Daniel Kappler; F. Ebert; Corey Lynch; S. Levine; Chelsea Finn",institutions:[],countries:[],year:2022,journal:"Conference on Robot Learning",citations:823,abstract:"In this paper, we study the problem of enabling a vision-based robotic manipulation system to generalize to novel tasks, a long-standing challenge in robot learning. We approach the challenge from an imitation learning perspective, aiming to study how scaling and broadening the data collected can facilitate such generalization. To that end, we develop an interactive and flexible imitation learning system that can learn from both demonstrations and interventions and can be conditioned on different forms of information that convey the task, including pre-trained embeddings of natural language or videos of humans performing the task. When scaling data collection on a real robot to more than 100 distinct tasks, we find that this system can perform 24 unseen manipulation tasks with an average success rate of 44%, without any robot demonstrations for those tasks.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:54,n_refs_in_core:1,degree:9,community:4,deg_w:59,betweenness:1e-4,pagerank:.00178,eigenvector:6e-4},{id:93,oaid:"7845f1d3e796b5704d4bd37a945e0cf3fb8bbf1f",doi:"10.1093/acrefore/9780190264086.013.79",title:"VISUAL ATTENTION",authors:[{name:"Jimmy Ba",institutions:[]},{name:"Volodymyr Mnih",institutions:[]},{name:"K. Kavukcuoglu",institutions:[]}],authorString:"Jimmy Ba; Volodymyr Mnih; K. Kavukcuoglu",institutions:[],countries:[],year:2014,journal:"",citations:823,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:49e-5,eigenvector:0},{id:94,oaid:"62176de125738e3b95850d1227bac81fd646b78e",doi:"10.48550/arXiv.2305.04091",title:"Plan-and-Solve Prompting: Improving Zero-Shot Chain-of-Thought Reasoning by Large Language Models",authors:[{name:"Lei Wang",institutions:["University of Electronic Science and Technology of China","Singapore Management University"]},{name:"Wanyu Xu",institutions:[]},{name:"Yihuai Lan",institutions:[]},{name:"Zhiqiang Hu",institutions:[]},{name:"Yunshi Lan",institutions:[]},{name:"Roy Ka-Wei Lee",institutions:["Singapore University of Technology and Design"]},{name:"Ee-Peng Lim",institutions:[]}],authorString:"Lei Wang; Wanyu Xu; Yihuai Lan; Zhiqiang Hu; Yunshi Lan; Roy Ka-Wei Lee; Ee-Peng Lim",institutions:["Singapore Management University","Singapore University of Technology and Design","University of Electronic Science and Technology of China"],countries:[],year:2023,journal:"Annual Meeting of the Association for Computational Linguistics",citations:802,abstract:"Large language models (LLMs) have recently been shown to deliver impressive performance in various NLP tasks. To tackle multi-step reasoning tasks, Few-shot chain-of-thought (CoT) prompting includes a few manually crafted step-by-step reasoning demonstrations which enable LLMs to explicitly generate reasoning steps and improve their reasoning task accuracy. To eliminate the manual efforts, Zero-shot-CoT concatenates the target problem statement with “Let’s think step by step” as an input prompt to LLMs. Despite the success of Zero-shot-CoT, it still suffers from three pitfalls: calculation errors, missing-step errors, and semantic misunderstanding errors. To address the missing-step errors, we propose Plan-and-Solve (PS) Prompting. It consists of two components: first, devising a plan to divide the entire task into smaller subtasks, and then carrying out the subtasks according to the plan. To address the calculation errors and improve the quality of generated reasoning steps, we extend PS prompting with more detailed instructions and derive PS+ prompting. We evaluate our proposed prompting strategy on ten datasets across three reasoning problems. The experimental results over GPT-3 show that our proposed zero-shot prompting consistently outperforms Zero-shot-CoT across all datasets by a large margin, is comparable to or exceeds Zero-shot-Program-of-Thought Prompting, and has comparable performance with 8-shot CoT prompting on the math reasoning problem. The code can be found at https://github.com/AGI-Edgerunners/Plan-and-Solve-Prompting.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2305.04091",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:5,deg_w:4,betweenness:0,pagerank:39e-5,eigenvector:2e-4},{id:95,oaid:"5776b2e8475a0e927ac7e13b897cdd2bc5e4f929",doi:null,title:"Automating Inequality: How High-Tech Tools Profile, Police, and Punish the Poor",authors:[{name:"Virginia E. Eubanks",institutions:[]}],authorString:"Virginia E. Eubanks",institutions:[],countries:[],year:2018,journal:"",citations:799,abstract:"",keywords:["Sociology","Law"],concepts:["Sociology","Law"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:44e-5,eigenvector:0},{id:96,oaid:"e7e1313061b0d56364bd2c41f017deb954bb05db",doi:"10.18653/v1/D18-1167",title:"TVQA: Localized, Compositional Video Question Answering",authors:[{name:"Jie Lei",institutions:[]},{name:"Licheng Yu",institutions:["Microsoft","University of North Carolina at Chapel Hill"]},{name:"Mohit Bansal",institutions:["UNC Chapel Hill"]},{name:"Tamara L. Berg",institutions:[]}],authorString:"Jie Lei; Licheng Yu; Mohit Bansal; Tamara L. Berg",institutions:["Microsoft","UNC Chapel Hill","University of North Carolina at Chapel Hill"],countries:[],year:2018,journal:"Conference on Empirical Methods in Natural Language Processing",citations:796,abstract:"Recent years have witnessed an increasing interest in image-based question-answering (QA) tasks. However, due to data limitations, there has been much less work on video-based QA. In this paper, we present TVQA, a large-scale video QA dataset based on 6 popular TV shows. TVQA consists of 152,545 QA pairs from 21,793 clips, spanning over 460 hours of video. Questions are designed to be compositional in nature, requiring systems to jointly localize relevant moments within a clip, comprehend subtitle-based dialogue, and recognize relevant visual concepts. We provide analyses of this new dataset as well as several baselines and a multi-stream end-to-end trainable neural network framework for the TVQA task. The dataset is publicly available at http://tvqa.cs.unc.edu.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D18-1167.pdf",is_oa:!0,n_refs:46,n_refs_in_core:7,degree:23,community:3,deg_w:190,betweenness:.0025,pagerank:.00413,eigenvector:.0016},{id:97,oaid:"6c1e1cc1e0e1f8fd026fe517607b2d4535565fa7",doi:"10.48550/arXiv.2211.10435",title:"PAL: Program-aided Language Models",authors:[{name:"Luyu Gao",institutions:[]},{name:"Aman Madaan",institutions:["Carnegie Mellon University"]},{name:"Shuyan Zhou",institutions:["Carnegie Mellon University"]},{name:"Uri Alon",institutions:["Carnegie Mellon University"]},{name:"Pengfei Liu",institutions:[]},{name:"Yiming Yang",institutions:[]},{name:"Jamie Callan",institutions:["Carnegie Mellon University"]},{name:"Graham Neubig",institutions:[]}],authorString:"Luyu Gao; Aman Madaan; Shuyan Zhou; Uri Alon; Pengfei Liu; Yiming Yang; Jamie Callan; Graham Neubig",institutions:["Carnegie Mellon University"],countries:[],year:2022,journal:"International Conference on Machine Learning",citations:793,abstract:`Large language models (LLMs) have recently demonstrated an impressive ability to perform arithmetic and symbolic reasoning tasks, when provided with a few examples at test time ("few-shot prompting"). Much of this success can be attributed to prompting methods such as"chain-of-thought'', which employ LLMs for both understanding the problem description by decomposing it into steps, as well as solving each step of the problem. While LLMs seem to be adept at this sort of step-by-step decomposition, LLMs often make logical and arithmetic mistakes in the solution part, even when the problem is decomposed correctly. In this paper, we present Program-Aided Language models (PAL): a novel approach that uses the LLM to read natural language problems and generate programs as the intermediate reasoning steps, but offloads the solution step to a runtime such as a Python interpreter. With PAL, decomposing the natural language problem into runnable steps remains the only learning task for the LLM, while solving is delegated to the interpreter. We demonstrate this synergy between a neural LLM and a symbolic interpreter across 13 mathematical, symbolic, and algorithmic reasoning tasks from BIG-Bench Hard and other benchmarks. In all these natural language reasoning tasks, generating code using an LLM and reasoning using a Python interpreter leads to more accurate results than much larger models. For example, PAL using Codex achieves state-of-the-art few-shot accuracy on the GSM8K benchmark of math word problems, surpassing PaLM-540B which uses chain-of-thought by absolute 15% top-1. Our code and data are publicly available at http://reasonwithpal.com/ .`,keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2211.10435",is_oa:!0,n_refs:56,n_refs_in_core:27,degree:39,community:5,deg_w:251.5,betweenness:.0906,pagerank:.00806,eigenvector:.0125},{id:98,oaid:"aa567981b204bbef0209f337c8394590e2fa441e",doi:null,title:"ON TYPES AND PROGRAMMING LANGUAGES",authors:[{name:"Neal Parikh",institutions:[]}],authorString:"Neal Parikh",institutions:[],countries:[],year:2004,journal:"",citations:792,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:7,deg_w:4,betweenness:0,pagerank:48e-5,eigenvector:0},{id:99,oaid:"558ac446dc26bee9789d660a251b75728cb6eeb2",doi:"10.18653/v1/P16-1004",title:"Language to Logical Form with Neural Attention",authors:[{name:"Li Dong",institutions:["Microsoft Research"]},{name:"Mirella Lapata",institutions:["University of Edinburgh"]}],authorString:"Li Dong; Mirella Lapata",institutions:["Microsoft Research","University of Edinburgh"],countries:[],year:2016,journal:"Annual Meeting of the Association for Computational Linguistics",citations:790,abstract:"Semantic parsing aims at mapping natural language to machine interpretable meaning representations. Traditional approaches rely on high-quality lexicons, manually-built templates, and linguistic features which are either domain- or representation-specific. In this paper we present a general method based on an attention-enhanced encoder-decoder model. We encode input utterances into vector representations, and generate their logical forms by conditioning the output sequences or trees on the encoding vectors. Experimental results on four datasets show that our approach performs competitively without using hand-engineered features and is easy to adapt across domains and meaning representations.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.aclweb.org/anthology/P16-1004.pdf",is_oa:!0,n_refs:53,n_refs_in_core:4,degree:22,community:5,deg_w:121.5,betweenness:.0132,pagerank:.00332,eigenvector:.0017},{id:100,oaid:"1cf6bc0866226c1f8e282463adc8b75d92fba9bb",doi:"10.1007/978-3-319-46478-7_28",title:"Ask, Attend and Answer: Exploring Question-Guided Spatial Attention for Visual Question Answering",authors:[{name:"Huijuan Xu",institutions:["Pennsylvania State University--University Park"]},{name:"Kate Saenko",institutions:[]}],authorString:"Huijuan Xu; Kate Saenko",institutions:["Pennsylvania State University--University Park"],countries:[],year:2015,journal:"European Conference on Computer Vision",citations:786,abstract:'We address the problem of Visual Question Answering (VQA), which requires joint image and language understanding to answer a question about a given photograph. Recent approaches have applied deep image captioning methods based on convolutional-recurrent networks to this problem, but have failed to model spatial inference. To remedy this, we propose a model we call the Spatial Memory Network and apply it to the VQA task. Memory networks are recurrent neural networks with an explicit attention mechanism that selects certain parts of the information stored in memory. Our Spatial Memory Network stores neuron activations from different spatial regions of the image in its memory, and uses the question to choose relevant regions for computing the answer, a process of which constitutes a single "hop" in the network. We propose a novel spatial attention architecture that aligns words with image patches in the first hop, and obtain improved results by adding a second attention hop which considers the whole question to choose visual evidence based on the results of the first hop. To better understand the inference process learned by the network, we design synthetic questions that specifically require spatial inference and visualize the attention weights. We evaluate our model on two published visual question answering datasets, DAQUAR [1] and VQA [2], and obtain improved results compared to a strong deep baseline model (iBOWIMG) which concatenates image and question features to predict the answer [3].',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:42,n_refs_in_core:3,degree:23,community:3,deg_w:199.5,betweenness:.0023,pagerank:.00403,eigenvector:.0015},{id:101,oaid:"ef2bc452812d6005ab0a66af6c3f97b6b0ba837e",doi:null,title:"Quantifying Generalization in Reinforcement Learning",authors:[{name:"K. Cobbe",institutions:[]},{name:"Oleg Klimov",institutions:[]},{name:"Christopher Hesse",institutions:[]},{name:"Taehoon Kim",institutions:[]},{name:"John Schulman",institutions:[]}],authorString:"K. Cobbe; Oleg Klimov; Christopher Hesse; Taehoon Kim; John Schulman",institutions:[],countries:[],year:2018,journal:"International Conference on Machine Learning",citations:785,abstract:"In this paper, we investigate the problem of overfitting in deep reinforcement learning. Among the most common benchmarks in RL, it is customary to use the same environments for both training and testing. This practice offers relatively little insight into an agent's ability to generalize. We address this issue by using procedurally generated environments to construct distinct training and test sets. Most notably, we introduce a new environment called CoinRun, designed as a benchmark for generalization in RL. Using CoinRun, we find that agents overfit to surprisingly large training sets. We then show that deeper convolutional architectures improve generalization, as do methods traditionally found in supervised learning, including L2 regularization, dropout, data augmentation and batch normalization.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:20,n_refs_in_core:0,degree:1,community:0,deg_w:5,betweenness:0,pagerank:46e-5,eigenvector:1e-4},{id:102,oaid:"f6e6fba61b654c5b799a9efe3b5849ce1197aab3",doi:null,title:"DeepProbLog: Neural Probabilistic Logic Programming",authors:[{name:"Robin Manhaeve",institutions:[]},{name:"Sebastijan Dumancic",institutions:[]},{name:"A. Kimmig",institutions:[]},{name:"T. Demeester",institutions:[]},{name:"L. D. Raedt",institutions:[]}],authorString:"Robin Manhaeve; Sebastijan Dumancic; A. Kimmig; T. Demeester; L. D. Raedt",institutions:[],countries:[],year:2018,journal:"BNAIC/BENELEARN",citations:782,abstract:"We introduce DeepProbLog, a probabilistic logic programming language that incorporates deep learning by means of neural predicates. We show how existing inference and learning techniques can be adapted for the new language. Our experiments demonstrate that DeepProbLog supports both symbolic and subsymbolic representations and inference, 1) program induction, 2) probabilistic (logic) programming, and 3) (deep) learning from examples. To the best of our knowledge, this work is the first to propose a framework where general-purpose neural networks and expressive probabilistic-logical modeling and reasoning are integrated in a way that exploits the full expressiveness and strengths of both worlds and can be trained end-to-end based on examples.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:58,n_refs_in_core:29,degree:42,community:0,deg_w:240.5,betweenness:.0584,pagerank:.01101,eigenvector:.0014},{id:103,oaid:"6859336c7098c8474fc413b221a723d66a4fb8bb",doi:"10.1145/2593882.2593900",title:"Probabilistic programming",authors:[{name:"A. Gordon",institutions:[]},{name:"T. Henzinger",institutions:[]},{name:"Aditya V. Nori",institutions:[]},{name:"S. Rajamani",institutions:[]}],authorString:"A. Gordon; T. Henzinger; Aditya V. Nori; S. Rajamani",institutions:[],countries:[],year:2014,journal:"FOSE",citations:777,abstract:"",keywords:[],concepts:[],pdf_url:"https://www.pure.ed.ac.uk/ws/files/19355513/Gordon_Henzinger_ET_AL_2014_Probabilistic_Programming.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12,betweenness:0,pagerank:74e-5,eigenvector:0},{id:104,oaid:"99053e3a708fc27709c9dab33110dc98b187c158",doi:"10.18653/v1/2021.emnlp-main.300",title:"FinQA: A Dataset of Numerical Reasoning over Financial Data",authors:[{name:"Zhiyu Chen",institutions:[]},{name:"Wenhu Chen",institutions:[]},{name:"Charese Smiley",institutions:[]},{name:"Sameena Shah",institutions:[]},{name:"Iana Borova",institutions:[]},{name:"Dylan Langdon",institutions:[]},{name:"Reema Moussa",institutions:[]},{name:"Matthew I. Beane",institutions:[]},{name:"Ting-Hao 'Kenneth' Huang",institutions:["Pennsylvania State University"]},{name:"Bryan R. Routledge",institutions:["Carnegie Mellon University"]},{name:"W. Wang",institutions:[]}],authorString:"Zhiyu Chen; Wenhu Chen; Charese Smiley; Sameena Shah; Iana Borova; Dylan Langdon; Reema Moussa; Matthew I. Beane; Ting-Hao 'Kenneth' Huang; Bryan R. Routledge; W. Wang",institutions:["Carnegie Mellon University","Pennsylvania State University"],countries:[],year:2021,journal:"Conference on Empirical Methods in Natural Language Processing",citations:772,abstract:"The sheer volume of financial statements makes it difficult for humans to access and analyze a business’s financials. Robust numerical reasoning likewise faces unique challenges in this domain. In this work, we focus on answering deep questions over financial data, aiming to automate the analysis of a large corpus of financial documents. In contrast to existing tasks on general domain, the finance domain includes complex numerical reasoning and understanding of heterogeneous representations. To facilitate analytical progress, we propose a new large-scale dataset, FinQA, with Question-Answering pairs over Financial reports, written by financial experts. We also annotate the gold reasoning programs to ensure full explainability. We further introduce baselines and conduct comprehensive experiments in our dataset. The results demonstrate that popular, large, pre-trained models fall far short of expert humans in acquiring finance knowledge and in complex multi-step numerical reasoning on that knowledge. Our dataset – the first of its kind – should therefore enable significant, new community research into complex application domains. The dataset and code are publicly available at https://github.com/czyssrs/FinQA.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.emnlp-main.300.pdf",is_oa:!0,n_refs:33,n_refs_in_core:4,degree:11,community:5,deg_w:64,betweenness:7e-4,pagerank:.00202,eigenvector:.0042},{id:105,oaid:"f96898d15a1bf1fa8925b1280d0e07a7a8e72194",doi:null,title:"Dynamic Memory Networks for Visual and Textual Question Answering",authors:[{name:"Caiming Xiong",institutions:["Salesforce Research"]},{name:"Stephen Merity",institutions:["Salesforce Research"]},{name:"R. Socher",institutions:[]}],authorString:"Caiming Xiong; Stephen Merity; R. Socher",institutions:["Salesforce Research"],countries:[],year:2016,journal:"International Conference on Machine Learning",citations:770,abstract:"Neural network architectures with memory and attention mechanisms exhibit certain reasoning capabilities required for question answering. One such architecture, the dynamic memory network (DMN), obtained high accuracy on a variety of language tasks. However, it was not shown whether the architecture achieves strong results for question answering when supporting facts are not marked during training or whether it could be applied to other modalities such as images. Based on an analysis of the DMN, we propose several improvements to its memory and input modules. Together with these changes we introduce a novel input module for images in order to be able to answer visual questions. Our new DMN+ model improves the state of the art on both the Visual Question Answering dataset and the \\babi-10k text question-answering dataset without supporting fact supervision.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:13,community:3,deg_w:52,betweenness:3e-4,pagerank:.00134,eigenvector:3e-4},{id:106,oaid:"23e42bc79f10234bdceef31441be39a2d9d2a9a0",doi:null,title:"Differentiable Learning of Logical Rules for Knowledge Base Reasoning",authors:[{name:"Fan Yang",institutions:[]},{name:"Zhilin Yang",institutions:[]},{name:"William W. Cohen",institutions:["Google"]}],authorString:"Fan Yang; Zhilin Yang; William W. Cohen",institutions:["Google"],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:769,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:0,deg_w:17.5,betweenness:4e-4,pagerank:93e-5,eigenvector:3e-4},{id:107,oaid:"9ada8fa11b1cdece31f253acae50b62df8d5f823",doi:"10.48550/arXiv.2305.07922",title:"CodeT5+: Open Code Large Language Models for Code Understanding and Generation",authors:[{name:"Yue Wang",institutions:["The Chinese University of Hong Kong"]},{name:"Hung Le",institutions:[]},{name:"Akhilesh Deepak Gotmare",institutions:["Salesforce Research"]},{name:"Nghi D. Q. Bui",institutions:[]},{name:"Junnan Li",institutions:[]},{name:"Steven C. H. Hoi",institutions:[]}],authorString:"Yue Wang; Hung Le; Akhilesh Deepak Gotmare; Nghi D. Q. Bui; Junnan Li; Steven C. H. Hoi",institutions:["Salesforce Research","The Chinese University of Hong Kong"],countries:[],year:2023,journal:"Conference on Empirical Methods in Natural Language Processing",citations:756,abstract:"Large language models (LLMs) pretrained on vast source code have achieved prominent progress in code intelligence. However, existing code LLMs have two main limitations in terms of architecture and pretraining tasks. First, they often adopt a specific architecture (encoder-only or decoder-only) or rely on a unified encoder-decoder network for different downstream tasks. The former paradigm is limited by inflexibility in applications while in the latter, the model is treated as a single system for all tasks, leading to suboptimal performance on a subset of tasks. Secondly, they often employ a limited set of pretraining objectives which might not be relevant to some downstream tasks and hence result in substantial performance degrade. To address these limitations, we propose ``CodeT5+'', a family of encoder-decoder LLMs for code in which component modules can be flexibly combined to suit a wide range of downstream code tasks. Such flexibility is enabled by our proposed mixture of pretraining objectives to mitigate the pretrain-finetune discrepancy. These objectives cover span denoising, contrastive learning, text-code matching, and causal LM pretraining tasks, on both unimodal and bimodal multilingual code corpora. Furthermore, we propose to initialize CodeT5+ with frozen off-the-shelf LLMs without training from scratch to efficiently scale up our models, and explore instruction-tuning to align with natural language instructions. We extensively evaluate CodeT5+ on over 20 code-related benchmarks in different settings, including zero-shot, finetuning, and instruction-tuning. We observe state-of-the-art (SoTA) model performance on various code-related tasks, such as code generation and completion, math programming, and text-to-code retrieval tasks. Particularly, our instruction-tuned CodeT5+ 16B achieves new SoTA results on HumanEval code generation task against other open code LLMs.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2305.07922",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:5,deg_w:4,betweenness:0,pagerank:39e-5,eigenvector:2e-4},{id:108,oaid:"cdf54c147434c83a4a380916b6c1279b0ca19fc2",doi:"10.48550/arXiv.2207.04429",title:"LM-Nav: Robotic Navigation with Large Pre-Trained Models of Language, Vision, and Action",authors:[{name:"Dhruv Shah",institutions:[]},{name:"B. Osinski",institutions:[]},{name:"Brian Ichter",institutions:[]},{name:"S. Levine",institutions:[]}],authorString:"Dhruv Shah; B. Osinski; Brian Ichter; S. Levine",institutions:[],countries:[],year:2022,journal:"Conference on Robot Learning",citations:751,abstract:"Goal-conditioned policies for robotic navigation can be trained on large, unannotated datasets, providing for good generalization to real-world settings. However, particularly in vision-based settings where specifying goals requires an image, this makes for an unnatural interface. Language provides a more convenient modality for communication with robots, but contemporary methods typically require expensive supervision, in the form of trajectories annotated with language descriptions. We present a system, LM-Nav, for robotic navigation that enjoys the benefits of training on unannotated large datasets of trajectories, while still providing a high-level interface to the user. Instead of utilizing a labeled instruction following dataset, we show that such a system can be constructed entirely out of pre-trained models for navigation (ViNG), image-language association (CLIP), and language modeling (GPT-3), without requiring any fine-tuning or language-annotated robot data. We instantiate LM-Nav on a real-world mobile robot and demonstrate long-horizon navigation through complex, outdoor environments from natural language instructions. For videos of our experiments, code release, and an interactive Colab notebook that runs in your browser, please check out our project page https://sites.google.com/view/lmnav",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2207.04429",is_oa:!0,n_refs:72,n_refs_in_core:5,degree:20,community:4,deg_w:133,betweenness:.0056,pagerank:.00358,eigenvector:.006},{id:109,oaid:"b18e4272a7b9fa2e1c970d258ab5ea99ed5e2284",doi:null,title:"Towards a Definition of Knowledge Graphs",authors:[{name:"Lisa Ehrlinger",institutions:[]},{name:"Wolfram Wöß",institutions:[]}],authorString:"Lisa Ehrlinger; Wolfram Wöß",institutions:[],countries:[],year:2016,journal:"International Conference on Semantic Systems",citations:750,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:59e-5,eigenvector:0},{id:110,oaid:"ac64fb7e6d2ddf236332ec9f371fe85d308c114d",doi:null,title:"A Multi-World Approach to Question Answering about Real-World Scenes based on Uncertain Input",authors:[{name:"Mateusz Malinowski",institutions:[]},{name:"Mario Fritz",institutions:[]}],authorString:"Mateusz Malinowski; Mario Fritz",institutions:[],countries:[],year:2014,journal:"Neural Information Processing Systems",citations:750,abstract:"We propose a method for automatically answering questions about images by bringing together recent advances from natural language processing and computer vision. We combine discrete reasoning with uncertain predictions by a multi-world approach that represents uncertainty about the perceived world in a bayesian framework. Our approach can handle human questions of high complexity about realistic scenes and replies with range of answer like counts, object classes, instances and lists of them. The system is directly trained from question-answer pairs. We establish a first benchmark for this task that can be seen as a modern attempt at a visual turing test.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:17,community:3,deg_w:74.5,betweenness:2e-4,pagerank:.00168,eigenvector:5e-4},{id:111,oaid:"ada81a4de88a6ce474df2e2446ad11fea480616e",doi:null,title:"Socratic Models: Composing Zero-Shot Multimodal Reasoning with Language",authors:[{name:"Andy Zeng",institutions:[]},{name:"Adrian S. Wong",institutions:[]},{name:"Stefan Welker",institutions:[]},{name:"K. Choromanski",institutions:[]},{name:"Federico Tombari",institutions:[]},{name:"Aveek Purohit",institutions:[]},{name:"M. Ryoo",institutions:[]},{name:"Vikas Sindhwani",institutions:[]},{name:"Johnny Lee",institutions:[]},{name:"Vincent Vanhoucke",institutions:["Google"]},{name:"Peter R. Florence",institutions:[]}],authorString:"Andy Zeng; Adrian S. Wong; Stefan Welker; K. Choromanski; Federico Tombari; Aveek Purohit; M. Ryoo; Vikas Sindhwani; Johnny Lee; Vincent Vanhoucke; Peter R. Florence",institutions:["Google"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:747,abstract:'Large pretrained (e.g.,"foundation") models exhibit distinct capabilities depending on the domain of data they are trained on. While these domains are generic, they may only barely overlap. For example, visual-language models (VLMs) are trained on Internet-scale image captions, but large language models (LMs) are further trained on Internet-scale text with no images (e.g., spreadsheets, SAT questions, code). As a result, these models store different forms of commonsense knowledge across different domains. In this work, we show that this diversity is symbiotic, and can be leveraged through Socratic Models (SMs): a modular framework in which multiple pretrained models may be composed zero-shot i.e., via multimodal-informed prompting, to exchange information with each other and capture new multimodal capabilities, without requiring finetuning. With minimal engineering, SMs are not only competitive with state-of-the-art zero-shot image captioning and video-to-text retrieval, but also enable new applications such as (i) answering free-form questions about egocentric video, (ii) engaging in multimodal assistive dialogue with people (e.g., for cooking recipes) by interfacing with external APIs and databases (e.g., web search), and (iii) robot perception and planning.',keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:154,n_refs_in_core:6,degree:24,community:4,deg_w:207.5,betweenness:.0314,pagerank:.00534,eigenvector:.0337},{id:112,oaid:"6e565308c8081e807709cb4a917443b737e6cdb4",doi:null,title:"Large-scale Simple Question Answering with Memory Networks",authors:[{name:"Antoine Bordes",institutions:[]},{name:"Nicolas Usunier",institutions:[]},{name:"S. Chopra",institutions:[]},{name:"J. Weston",institutions:[]}],authorString:"Antoine Bordes; Nicolas Usunier; S. Chopra; J. Weston",institutions:[],countries:[],year:2015,journal:"arXiv.org",citations:747,abstract:"Training large-scale question answering systems is complicated because training sources usually cover a small portion of the range of possible questions. This paper studies the impact of multitask and transfer learning for simple question answering; a setting for which the reasoning required to answer is quite easy, as long as one can retrieve the correct evidence given a question, which can be difficult in large-scale conditions. To this end, we introduce a new dataset of 100k questions that we use in conjunction with existing benchmarks. We conduct our study within the framework of Memory Networks (Weston et al., 2015) because this perspective allows us to eventually scale up to more complex reasoning, and show that Memory Networks can be successfully trained to achieve excellent performance.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:2,deg_w:12.5,betweenness:6e-4,pagerank:67e-5,eigenvector:8e-4},{id:113,oaid:"2a441a46e228ed0ea2251a4e61be6c7025b45766",doi:"10.1007/978-3-319-21401-6_26",title:"The Lean Theorem Prover (System Description)",authors:[{name:"L. D. Moura",institutions:[]},{name:"Soonho Kong",institutions:[]},{name:"J. Avigad",institutions:[]},{name:"Floris van Doorn",institutions:[]},{name:"Jakob von Raumer",institutions:[]}],authorString:"L. D. Moura; Soonho Kong; J. Avigad; Floris van Doorn; Jakob von Raumer",institutions:[],countries:[],year:2015,journal:"CADE",citations:744,abstract:"Lean is a new open source theorem prover being developed at Microsoft Research and Carnegie Mellon University, with a small trusted kernel based on dependent type theory. It aims to bridge the gap between interactive and automated theorem proving, by situating automated tools and methods in a framework that supports user interaction and the construction of fully specified axiomatic proofs. Lean is an ongoing and long-term effort, but it already provides many useful components, integrated development environments, and a rich API which can be used to embed it into other systems. It is currently being used to formalize category theory, homotopy type theory, and abstract algebra. We describe the project goals, system architecture, and main features, and we discuss applications and continuing work.",keywords:[],concepts:[],pdf_url:"https://figshare.com/articles/journal_contribution/The_Lean_Theorem_Prover_system_description_/6492815",is_oa:!0,n_refs:27,n_refs_in_core:0,degree:12,community:6,deg_w:58,betweenness:4e-4,pagerank:.0018,eigenvector:.0025},{id:114,oaid:"44ef6cf919250001836ed73c0d58b20ea1e2d308",doi:"10.1162/tacl_a_00461",title:"ByT5: Towards a Token-Free Future with Pre-trained Byte-to-Byte Models",authors:[{name:"Linting Xue",institutions:[]},{name:"Aditya Barua",institutions:[]},{name:"Noah Constant",institutions:[]},{name:"Rami Al-Rfou",institutions:["Waymo","Google"]},{name:"Sharan Narang",institutions:[]},{name:"Mihir Kale",institutions:[]},{name:"Adam Roberts",institutions:[]},{name:"Colin Raffel",institutions:[]}],authorString:"Linting Xue; Aditya Barua; Noah Constant; Rami Al-Rfou; Sharan Narang; Mihir Kale; Adam Roberts; Colin Raffel",institutions:["Google","Waymo"],countries:[],year:2021,journal:"Transactions of the Association for Computational Linguistics",citations:737,abstract:"Most widely used pre-trained language models operate on sequences of tokens corresponding to word or subword units. By comparison, token-free models that operate directly on raw text (bytes or characters) have many benefits: They can process text in any language out of the box, they are more robust to noise, and they minimize technical debt by removing complex and error-prone text preprocessing pipelines. Because byte or character sequences are longer than token sequences, past work on token-free models has often introduced new model architectures designed to amortize the cost of operating directly on raw text. In this paper, we show that a standard Transformer architecture can be used with minimal modifications to process byte sequences. We characterize the trade-offs in terms of parameter count, training FLOPs, and inference speed, and show that byte-level models are competitive with their token-level counterparts. We also demonstrate that byte-level models are significantly more robust to noise and perform better on tasks that are sensitive to spelling and pronunciation. As part of our contribution, we release a new set of pre-trained byte-level Transformer models based on the T5 architecture, as well as all code and data used in our experiments.1",keywords:[],concepts:[],pdf_url:"https://direct.mit.edu/tacl/article-pdf/doi/10.1162/tacl_a_00461/2004058/tacl_a_00461.pdf",is_oa:!0,n_refs:66,n_refs_in_core:1,degree:9,community:1,deg_w:51.5,betweenness:6e-4,pagerank:.00134,eigenvector:.0172},{id:115,oaid:"2c871df72c52b58f05447fcb3afc838168d94505",doi:"10.18653/v1/2022.acl-long.581",title:"Knowledge Neurons in Pretrained Transformers",authors:[{name:"Damai Dai",institutions:[]},{name:"Li Dong",institutions:["Microsoft Research"]},{name:"Y. Hao",institutions:[]},{name:"Zhifang Sui",institutions:[]},{name:"Furu Wei",institutions:["Microsoft Research"]}],authorString:"Damai Dai; Li Dong; Y. Hao; Zhifang Sui; Furu Wei",institutions:["Microsoft Research"],countries:[],year:2021,journal:"Annual Meeting of the Association for Computational Linguistics",citations:736,abstract:"Large-scale pretrained language models are surprisingly good at recalling factual knowledge presented in the training corpus. In this paper, we present preliminary studies on how factual knowledge is stored in pretrained Transformers by introducing the concept of knowledge neurons. Specifically, we examine the fill-in-the-blank cloze task for BERT. Given a relational fact, we propose a knowledge attribution method to identify the neurons that express the fact. We find that the activation of such knowledge neurons is positively correlated to the expression of their corresponding facts. In our case studies, we attempt to leverage knowledge neurons to edit (such as update, and erase) specific factual knowledge without fine-tuning. Our results shed light on understanding the storage of knowledge within pretrained Transformers.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2022.acl-long.581.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:47e-5,eigenvector:.0065},{id:116,oaid:"90873a97aa9a43775e5aeea01b03aea54b28bfbd",doi:"10.1109/CVPR.2018.00522",title:"Don't Just Assume; Look and Answer: Overcoming Priors for Visual Question Answering",authors:[{name:"Aishwarya Agrawal",institutions:[]},{name:"Dhruv Batra",institutions:[]},{name:"Devi Parikh",institutions:[]},{name:"Aniruddha Kembhavi",institutions:["Allen Institute for Artificial Intelligence"]}],authorString:"Aishwarya Agrawal; Dhruv Batra; Devi Parikh; Aniruddha Kembhavi",institutions:["Allen Institute for Artificial Intelligence"],countries:[],year:2017,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:730,abstract:"A number of studies have found that today's Visual Question Answering (VQA) models are heavily driven by superficial correlations in the training data and lack sufficient image grounding. To encourage development of models geared towards the latter, we propose a new setting for VQA where for every question type, train and test sets have different prior distributions of answers. Specifically, we present new splits of the VQA v1 and VQA v2 datasets, which we call Visual Question Answering under Changing Priors (VQA-CP v1 and VQA-CP v2 respectively). First, we evaluate several existing VQA models under this new setting and show that their performance degrades significantly compared to the original VQA setting. Second, we propose a novel Grounded Visual Question Answering model (GVQA) that contains inductive biases and restrictions in the architecture specifically designed to prevent the model from 'cheating' by primarily relying on priors in the training data. Specifically, GVQA explicitly disentangles the recognition of visual concepts present in the image from the identification of plausible answer space for a given question, enabling the model to more robustly generalize across different distributions of answers. GVQA is built off an existing VQA model - Stacked Attention Networks (SAN). Our experiments demonstrate that GVQA significantly outperforms SAN on both VQA-CP v1 and VQA-CP v2 datasets. Interestingly, it also outperforms more powerful VQA models such as Multimodal Compact Bilinear Pooling (MCB) in several cases. GVQA offers strengths complementary to SAN when trained and evaluated on the original VQA v1 and VQA v2 datasets. Finally, GVQA is more transparent and interpretable than existing VQA models.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1712.00377",is_oa:!0,n_refs:41,n_refs_in_core:8,degree:24,community:3,deg_w:197,betweenness:.0011,pagerank:.00418,eigenvector:.0012},{id:117,oaid:"442ab95eb9cfbc03bb17a27b52313b5d25eaa738",doi:"10.1038/s41586-022-05172-4",title:"Discovering faster matrix multiplication algorithms with reinforcement learning",authors:[{name:"Alhussein Fawzi",institutions:[]},{name:"M. Balog",institutions:[]},{name:"Aja Huang",institutions:[]},{name:"T. Hubert",institutions:[]},{name:"B. Romera-Paredes",institutions:[]},{name:"M. Barekatain",institutions:[]},{name:"Alexander Novikov",institutions:[]},{name:"Francisco J. R. Ruiz",institutions:[]},{name:"Julian Schrittwieser",institutions:[]},{name:"Grzegorz Swirszcz",institutions:[]},{name:"David Silver",institutions:[]},{name:"D. Hassabis",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"Alhussein Fawzi; M. Balog; Aja Huang; T. Hubert; B. Romera-Paredes; M. Barekatain; Alexander Novikov; Francisco J. R. Ruiz; Julian Schrittwieser; Grzegorz Swirszcz; David Silver; D. Hassabis et al.",institutions:[],countries:[],year:2022,journal:"Nature",citations:726,abstract:"Improving the efficiency of algorithms for fundamental computations can have a widespread impact, as it can affect the overall speed of a large amount of computations. Matrix multiplication is one such primitive task, occurring in many systems—from neural networks to scientific computing routines. The automatic discovery of algorithms using machine learning offers the prospect of reaching beyond human intuition and outperforming the current best human-designed algorithms. However, automating the algorithm discovery procedure is intricate, as the space of possible algorithms is enormous. Here we report a deep reinforcement learning approach based on AlphaZero1 for discovering efficient and provably correct algorithms for the multiplication of arbitrary matrices. Our agent, AlphaTensor, is trained to play a single-player game where the objective is finding tensor decompositions within a finite factor space. AlphaTensor discovered algorithms that outperform the state-of-the-art complexity for many matrix sizes. Particularly relevant is the case of 4 × 4 matrices in a finite field, where AlphaTensor’s algorithm improves on Strassen’s two-level algorithm for the first time, to our knowledge, since its discovery 50 years ago2. We further showcase the flexibility of AlphaTensor through different use-cases: algorithms with state-of-the-art complexity for structured matrix multiplication and improved practical efficiency by optimizing matrix multiplication for runtime on specific hardware. Our results highlight AlphaTensor’s ability to accelerate the process of algorithmic discovery on a range of problems, and to optimize for different criteria. A reinforcement learning approach based on AlphaZero is used to discover efficient and provably correct algorithms for matrix multiplication, finding faster algorithms for a variety of matrix sizes.",keywords:[],concepts:[],pdf_url:"https://www.nature.com/articles/s41586-022-05172-4.pdf",is_oa:!0,n_refs:68,n_refs_in_core:1,degree:5,community:6,deg_w:17,betweenness:.0022,pagerank:88e-5,eigenvector:5e-4},{id:118,oaid:"481bd9ed53700ca2a1f1361fc18abc108639d78b",doi:"10.1007/978-3-662-44923-3",title:"Inductive Logic Programming",authors:[{name:"Gerson Zaverucha",institutions:[]},{name:"V. S. Costa",institutions:[]},{name:"Aline Paes",institutions:["Universidade Federal Fluminense"]}],authorString:"Gerson Zaverucha; V. S. Costa; Aline Paes",institutions:["Universidade Federal Fluminense"],countries:[],year:2014,journal:"Lecture Notes in Computer Science",citations:721,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12.5,betweenness:1e-4,pagerank:73e-5,eigenvector:2e-4},{id:119,oaid:"9d15ebe3f5aaf32a9f835f88703241461324c35b",doi:null,title:"Neural-Symbolic VQA: Disentangling Reasoning from Vision and Language Understanding",authors:[{name:"Kexin Yi",institutions:[]},{name:"Jiajun Wu",institutions:["Stanford University"]},{name:"Chuang Gan",institutions:[]},{name:"A. Torralba",institutions:[]},{name:"Pushmeet Kohli",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Kexin Yi; Jiajun Wu; Chuang Gan; A. Torralba; Pushmeet Kohli; J. Tenenbaum",institutions:["Stanford University"],countries:[],year:2018,journal:"Neural Information Processing Systems",citations:720,abstract:"We marry two powerful ideas: deep representation learning for visual recognition and language understanding, and symbolic program execution for reasoning. Our neural-symbolic visual question answering (NS-VQA) system first recovers a structural scene representation from the image and a program trace from the question. It then executes the program on the scene representation to obtain an answer. Incorporating symbolic structure as prior knowledge offers three unique advantages. First, executing programs on a symbolic space is more robust to long program traces; our model can solve complex reasoning tasks better, achieving an accuracy of 99.8% on the CLEVR dataset. Second, the model is more data- and memory-efficient: it performs well after learning on a small number of training data; it can also encode an image into a compact representation, requiring less storage than existing methods for offline question answering. Third, symbolic program execution offers full transparency to the reasoning process; we are thus able to interpret and diagnose each execution step.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:48,n_refs_in_core:27,degree:49,community:3,deg_w:355.5,betweenness:.0333,pagerank:.00954,eigenvector:.0021},{id:120,oaid:"0ba581718f294db1d7b3dbc159cc3d3380f74606",doi:"10.1109/ACCESS.2024.3387941",title:"ChatGPT for Robotics: Design Principles and Model Abilities",authors:[{name:"Sai H. Vemprala",institutions:[]},{name:"Rogerio Bonatti",institutions:[]},{name:"A. Bucker",institutions:[]},{name:"Ashish Kapoor",institutions:[]}],authorString:"Sai H. Vemprala; Rogerio Bonatti; A. Bucker; Ashish Kapoor",institutions:[],countries:[],year:2023,journal:"IEEE Access",citations:720,abstract:"This paper presents an experimental study regarding the use of OpenAI’s ChatGPT for robotics applications. We outline a strategy that combines design principles for prompt engineering and the creation of a high-level function library which allows ChatGPT to adapt to different robotics tasks, simulators, and form factors. We focus our evaluations on the effectiveness of different prompt engineering techniques and dialog strategies towards the execution of various types of robotics tasks. We explore ChatGPT’s ability to use free-form dialog, parse XML tags, and to synthesize code, in addition to the use of task-specific prompting functions and closed-loop reasoning through dialogues. Our study encompasses a range of tasks within the robotics domain, from basic logical, geometrical, and mathematical reasoning all the way to complex domains such as aerial navigation, manipulation, and embodied agents. We show that ChatGPT can be effective at solving several of such tasks, while allowing users to interact with it primarily via natural language instructions. In addition to these studies, we introduce an open-sourced research tool called PromptCraft, which contains a platform where researchers can collaboratively upload and vote on examples of good prompting schemes for robotics applications, as well as a sample robotics simulator with ChatGPT integration, making it easier for users to get started with using ChatGPT for robotics. Videos and blog: aka.ms/ChatGPT-Robotics PromptCraft, AirSim-ChatGPT code: https://github.com/microsoft/PromptCraft-Robotics",keywords:[],concepts:[],pdf_url:"https://ieeexplore.ieee.org/ielx7/6287639/6514899/10500490.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:121,oaid:"a00db2526f5f05f5855893b525f79cfe2624925b",doi:null,title:"Language and Experience: Evidence from the Blind Child",authors:[{name:"B. Landau",institutions:[]},{name:"L. Gleitman",institutions:[]}],authorString:"B. Landau; L. Gleitman",institutions:[],countries:[],year:1988,journal:"",citations:705,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:122,oaid:"b2f521c02c6ed3080c5fe123e938cdf4555e6fd2",doi:"10.1109/CVPR.2017.149",title:"TGIF-QA: Toward Spatio-Temporal Reasoning in Visual Question Answering",authors:[{name:"Y. Jang",institutions:[]},{name:"Yale Song",institutions:[]},{name:"Youngjae Yu",institutions:[]},{name:"Youngjin Kim",institutions:[]},{name:"Gunhee Kim",institutions:["Seoul National University","rippleAI"]}],authorString:"Y. Jang; Yale Song; Youngjae Yu; Youngjin Kim; Gunhee Kim",institutions:["Seoul National University","rippleAI"],countries:[],year:2017,journal:"Computer Vision and Pattern Recognition",citations:704,abstract:"Vision and language understanding has emerged as a subject undergoing intense study in Artificial Intelligence. Among many tasks in this line of research, visual question answering (VQA) has been one of the most successful ones, where the goal is to learn a model that understands visual content at region-level details and finds their associations with pairs of questions and answers in the natural language form. Despite the rapid progress in the past few years, most existing work in VQA have focused primarily on images. In this paper, we focus on extending VQA to the video domain and contribute to the literature in three important ways. First, we propose three new tasks designed specifically for video VQA, which require spatio-temporal reasoning from videos to answer questions correctly. Next, we introduce a new large-scale dataset for video VQA named TGIF-QA that extends existing VQA work with our new tasks. Finally, we propose a dual-LSTM based approach with both spatial and temporal attention, and show its effectiveness over conventional VQA techniques through empirical evaluations.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/1704.04497",is_oa:!0,n_refs:44,n_refs_in_core:4,degree:22,community:3,deg_w:209,betweenness:4e-4,pagerank:.00425,eigenvector:.0017},{id:123,oaid:"f0a79cb16c3e53e9c536b65ec7b2157db1d352f1",doi:"10.3233/978-1-61499-385-8-43",title:"Program Synthesis",authors:[{name:"Sumit Gulwani",institutions:[]},{name:"Oleksandr Polozov",institutions:["Google"]},{name:"Rishabh Singh",institutions:[]}],authorString:"Sumit Gulwani; Oleksandr Polozov; Rishabh Singh",institutions:["Google"],countries:[],year:2017,journal:"Software Systems Safety",citations:702,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:2,deg_w:17,betweenness:5e-4,pagerank:78e-5,eigenvector:9e-4},{id:124,oaid:"5c74b1021aebd0575c339ce4dfd47e183009a9c5",doi:null,title:"Implicit Behavioral Cloning",authors:[{name:"Peter R. Florence",institutions:[]},{name:"Corey Lynch",institutions:[]},{name:"Andy Zeng",institutions:[]},{name:"Oscar Ramirez",institutions:[]},{name:"Ayzaan Wahid",institutions:[]},{name:"Laura Downs",institutions:[]},{name:"Adrian S. Wong",institutions:[]},{name:"Johnny Lee",institutions:[]},{name:"Igor Mordatch",institutions:[]},{name:"Jonathan Tompson",institutions:[]}],authorString:"Peter R. Florence; Corey Lynch; Andy Zeng; Oscar Ramirez; Ayzaan Wahid; Laura Downs; Adrian S. Wong; Johnny Lee; Igor Mordatch; Jonathan Tompson",institutions:[],countries:[],year:2021,journal:"Conference on Robot Learning",citations:698,abstract:"We find that across a wide range of robot policy learning scenarios, treating supervised policy learning with an implicit model generally performs better, on average, than commonly used explicit models. We present extensive experiments on this finding, and we provide both intuitive insight and theoretical arguments distinguishing the properties of implicit models compared to their explicit counterparts, particularly with respect to approximating complex, potentially discontinuous and multi-valued (set-valued) functions. On robotic policy learning tasks we show that implicit behavioral cloning policies with energy-based models (EBM) often outperform common explicit (Mean Square Error, or Mixture Density) behavioral cloning policies, including on tasks with high-dimensional action spaces and visual image inputs. We find these policies provide competitive results or outperform state-of-the-art offline reinforcement learning methods on the challenging human-expert tasks from the D4RL benchmark suite, despite using no reward information. In the real world, robots with implicit policies can learn complex and remarkably subtle behaviors on contact-rich tasks from human demonstrations, including tasks with high combinatorial complexity and tasks requiring 1mm precision.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:73,n_refs_in_core:1,degree:7,community:4,deg_w:37.5,betweenness:5e-4,pagerank:.00134,eigenvector:5e-4},{id:125,oaid:"eaa518ad767dae7875f7f8fbc9eca6e05f9d11d0",doi:"10.3389/frobt.2016.00040",title:"Quality Diversity: A New Frontier for Evolutionary Computation",authors:[{name:"Justin K. Pugh",institutions:[]},{name:"L. Soros",institutions:[]},{name:"Kenneth O. Stanley",institutions:[]}],authorString:"Justin K. Pugh; L. Soros; Kenneth O. Stanley",institutions:[],countries:[],year:2016,journal:"Frontiers in Robotics and AI",citations:694,abstract:"While evolutionary computation and evolutionary robotics take inspiration from nature, they have long focused mainly on problems of performance optimization. Yet evolution in nature can be interpreted as more nuanced than a process of simple optimization. In particular, natural evolution is a divergent search that optimizes locally within each niche as it simultaneously diversifies. This tendency to discover both quality and diversity at the same time differs from many of the conventional algorithms of machine learning, and also thereby suggests a different foundation for inferring the approach of greatest potential for evolutionary algorithms. In fact, several recent evolutionary algorithms called quality diversity (QD) algorithms(e.g. novelty search with local competition and MAP-Elites) have drawn inspiration from this more nuanced view, aiming to fill a space of possibilities with the best possible example of each type of achievable behavior. The result is a new class of algorithms that return an archive of diverse, high-quality behaviors in a single run. The aim in this paper is to study the application of QD algorithms in challenging environments (in particular complex mazes) to establish their best practices for ambitious domains in the future. In addition to providing insight into cases when QD succeeds and fails, a new approach is investigated that hybridizes multiple views of behaviors (called behavior characterizations) in the same run, which succeeds in overcoming some of the challenges associated with searching for QD with respect to a behavior characterization that is not necessarily sufficient for generating both quality and diversity at the same time.",keywords:[],concepts:[],pdf_url:"https://www.frontiersin.org/articles/10.3389/frobt.2016.00040/pdf",is_oa:!0,n_refs:61,n_refs_in_core:1,degree:2,community:8,deg_w:10.5,betweenness:0,pagerank:99e-5,eigenvector:1e-4},{id:126,oaid:"10f7507b8408bf35125b8e04254ad890c8d45e1d",doi:null,title:"Procedures As A Representation For Data In A Computer Program For Understanding Natural Language",authors:[{name:"T. Winograd",institutions:[]}],authorString:"T. Winograd",institutions:[],countries:[],year:1971,journal:"",citations:692,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:4,deg_w:16.5,betweenness:.0011,pagerank:79e-5,eigenvector:2e-4},{id:127,oaid:"9bf6a8197a5f8e51b52fa599d1dddd18f36b0d4d",doi:null,title:"Relation Extraction with Matrix Factorization and Universal Schemas",authors:[{name:"Sebastian Riedel",institutions:[]},{name:"Limin Yao",institutions:[]},{name:"A. McCallum",institutions:[]},{name:"Benjamin M Marlin",institutions:["University of Massachusetts Amherst"]}],authorString:"Sebastian Riedel; Limin Yao; A. McCallum; Benjamin M Marlin",institutions:["University of Massachusetts Amherst"],countries:[],year:2013,journal:"North American Chapter of the Association for Computational Linguistics",citations:692,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:14,community:0,deg_w:61,betweenness:3e-4,pagerank:.00193,eigenvector:.0036},{id:128,oaid:"72b048f4aa34f0e46457efcad2a22c5874ef3202",doi:"10.1007/978-1-4684-3384-5",title:"Logic and Data Bases",authors:[{name:"H. Gallaire",institutions:[]},{name:"J. Minker",institutions:[]}],authorString:"H. Gallaire; J. Minker",institutions:[],countries:[],year:1978,journal:"Springer US",citations:692,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:4e-4,eigenvector:1e-4},{id:129,oaid:"a7f59b2162ae0ea2520753b1b9b17277490a9458",doi:"10.48550/arXiv.2302.06675",title:"Symbolic Discovery of Optimization Algorithms",authors:[{name:"Xiangning Chen",institutions:[]},{name:"Chen Liang",institutions:["Google Brain"]},{name:"Da Huang",institutions:[]},{name:"Esteban Real",institutions:[]},{name:"Kaiyuan Wang",institutions:[]},{name:"Yao Liu",institutions:[]},{name:"Hieu Pham",institutions:["Google Brain, Carnegie Mellon University"]},{name:"Xuanyi Dong",institutions:[]},{name:"Thang Luong",institutions:[]},{name:"Cho-Jui Hsieh",institutions:[]},{name:"Yifeng Lu",institutions:[]},{name:"Quoc V. Le",institutions:[]}],authorString:"Xiangning Chen; Chen Liang; Da Huang; Esteban Real; Kaiyuan Wang; Yao Liu; Hieu Pham; Xuanyi Dong; Thang Luong; Cho-Jui Hsieh; Yifeng Lu; Quoc V. Le",institutions:["Google Brain","Google Brain, Carnegie Mellon University"],countries:[],year:2023,journal:"Neural Information Processing Systems",citations:688,abstract:"We present a method to formulate algorithm discovery as program search, and apply it to discover optimization algorithms for deep neural network training. We leverage efficient search techniques to explore an infinite and sparse program space. To bridge the large generalization gap between proxy and target tasks, we also introduce program selection and simplification strategies. Our method discovers a simple and effective optimization algorithm, $\\textbf{Lion}$ ($\\textit{Evo$\\textbf{L}$ved S$\\textbf{i}$gn M$\\textbf{o}$me$\\textbf{n}$tum}$). It is more memory-efficient than Adam as it only keeps track of the momentum. Different from adaptive optimizers, its update has the same magnitude for each parameter calculated through the sign operation. We compare Lion with widely used optimizers, such as Adam and Adafactor, for training a variety of models on different tasks. On image classification, Lion boosts the accuracy of ViT by up to 2% on ImageNet and saves up to 5x the pre-training compute on JFT. On vision-language contrastive learning, we achieve 88.3% $\\textit{zero-shot}$ and 91.1% $\\textit{fine-tuning}$ accuracy on ImageNet, surpassing the previous best results by 2% and 0.1%, respectively. On diffusion models, Lion outperforms Adam by achieving a better FID score and reducing the training compute by up to 2.3x. For autoregressive, masked language modeling, and fine-tuning, Lion exhibits a similar or better performance compared to Adam. Our analysis of Lion reveals that its performance gain grows with the training batch size. It also requires a smaller learning rate than Adam due to the larger norm of the update produced by the sign function. Additionally, we examine the limitations of Lion and identify scenarios where its improvements are small or not statistically significant. Lion is also successfully deployed in production systems such as Google search ads CTR model.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2302.06675",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:8,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:130,oaid:"e5822c78e94e53fb56094fc443bb1c650168d014",doi:"10.1016/j.inffus.2020.01.011",title:"Emotion recognition using multi-modal data and machine learning techniques: A tutorial and review",authors:[{name:"Jianhua Zhang",institutions:[]},{name:"Z. Yin",institutions:[]},{name:"Peng Chen",institutions:[]},{name:"S. Nichele",institutions:[]}],authorString:"Jianhua Zhang; Z. Yin; Peng Chen; S. Nichele",institutions:[],countries:[],year:2020,journal:"Information Fusion",citations:684,abstract:"Abstract In recent years, the rapid advances in machine learning (ML) and information fusion has made it possible to endow machines/computers with the ability of emotion understanding, recognition, and analysis. Emotion recognition has attracted increasingly intense interest from researchers from diverse fields. Human emotions can be recognized from facial expressions, speech, behavior (gesture/posture) or physiological signals. However, the first three methods can be ineffective since humans may involuntarily or deliberately conceal their real emotions (so-called social masking). The use of physiological signals can lead to more objective and reliable emotion recognition. Compared with peripheral neurophysiological signals, electroencephalogram (EEG) signals respond to fluctuations of affective states more sensitively and in real time and thus can provide useful features of emotional states. Therefore, various EEG-based emotion recognition techniques have been developed recently. In this paper, the emotion recognition methods based on multi-channel EEG signals as well as multi-modal physiological signals are reviewed. According to the standard pipeline for emotion recognition, we review different feature extraction (e.g., wavelet transform and nonlinear dynamics), feature reduction, and ML classifier design methods (e.g., k-nearest neighbor (KNN), naive Bayesian (NB), support vector machine (SVM) and random forest (RF)). Furthermore, the EEG rhythms that are highly correlated with emotions are analyzed and the correlation between different brain areas and emotions is discussed. Finally, we compare different ML and deep learning algorithms for emotion recognition and suggest several open problems and future research directions in this exciting and fast-growing area of AI.",keywords:[],concepts:[],pdf_url:"https://hdl.handle.net/11250/2838485",is_oa:!0,n_refs:205,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:131,oaid:"4be02694125b71876552900a53c85c47a2a83614",doi:"10.1109/lra.2022.3180108",title:"CALVIN: A Benchmark for Language-Conditioned Policy Learning for Long-Horizon Robot Manipulation Tasks",authors:[{name:"Oier Mees",institutions:[]},{name:"Lukás Hermann",institutions:[]},{name:"Erick Rosete-Beas",institutions:[]},{name:"Wolfram Burgard",institutions:["University of Technology Nuremberg"]}],authorString:"Oier Mees; Lukás Hermann; Erick Rosete-Beas; Wolfram Burgard",institutions:["University of Technology Nuremberg"],countries:[],year:2021,journal:"IEEE Robotics and Automation Letters",citations:683,abstract:"General-purpose robots coexisting with humans in their environment must learn to relate human language to their perceptions and actions to be useful in a range of daily tasks. Moreover, they need to acquire a diverse repertoire of general-purpose skills that allow composing long-horizon tasks by following unconstrained language instructions. In this letter, we present Composing Actions from Language and Vision (CALVIN) (Composing Actions from Language and Vision), an open-source simulated benchmark to learn long-horizon language-conditioned tasks. Our aim is to make it possible to develop agents that can solve many robotic manipulation tasks over a long horizon, from onboard sensors, and specified only via human language. CALVIN tasks are more complex in terms of sequence length, action space, and language than existing vision-and-language task datasets and supports flexible specification of sensor suites. We evaluate the agents in zero-shot to novel language instructions and to novel environments. We show that a baseline model based on multi-context imitation learning performs poorly on CALVIN, suggesting that there is significant room for developing innovative agents that learn to relate human language to their world models with this benchmark.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:39,n_refs_in_core:7,degree:12,community:4,deg_w:90,betweenness:5e-4,pagerank:.00247,eigenvector:.0018},{id:132,oaid:"237175d9a7864dcf396751593605ea022c31421b",doi:null,title:"Supplementary materials for: Plug & Play Generative Networks: Conditional Iterative Generation of Images in Latent Space",authors:[],authorString:"",institutions:[],countries:[],year:2017,journal:"",citations:674,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:0,pagerank:68e-5,eigenvector:0},{id:133,oaid:"2aea6cc6c42101b2615753c2933a33e57dd665f2",doi:null,title:"Random Walk Inference and Learning in A Large Scale Knowledge Base",authors:[{name:"N. Lao",institutions:[]},{name:"Tom Michael Mitchell",institutions:[]},{name:"William W. Cohen",institutions:["Google"]}],authorString:"N. Lao; Tom Michael Mitchell; William W. Cohen",institutions:["Google"],countries:[],year:2011,journal:"Conference on Empirical Methods in Natural Language Processing",citations:668,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:11,community:0,deg_w:41.5,betweenness:2e-4,pagerank:.00141,eigenvector:.0022},{id:134,oaid:"df1b7ec5e3feca2174fbd301e4915909c2fcae04",doi:"10.1109/TIT.1956.1056797",title:"The logic theory machine-A complex information processing system",authors:[{name:"A. Newell",institutions:[]},{name:"H. Simon",institutions:[]}],authorString:"A. Newell; H. Simon",institutions:[],countries:[],year:1956,journal:"IRE Transactions on Information Theory",citations:665,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:6,deg_w:4,betweenness:0,pagerank:38e-5,eigenvector:5e-4},{id:135,oaid:"4c6fe6179c408e1fbb3871af13d1a8e64f766e54",doi:"10.18653/v1/D15-1202",title:"Solving General Arithmetic Word Problems",authors:[{name:"Subhro Roy",institutions:[]},{name:"Dan Roth",institutions:["University of Pennsylvania, Oracle"]}],authorString:"Subhro Roy; Dan Roth",institutions:["University of Pennsylvania, Oracle"],countries:[],year:2016,journal:"Conference on Empirical Methods in Natural Language Processing",citations:664,abstract:"This paper presents a novel approach to automatically solving arithmetic word problems. This is the first algorithmic approach that can handle arithmetic problems with multiple steps and operations, without depending on additional annotations or predefined templates. We develop a theory for expression trees that can be used to represent and evaluate the target arithmetic expressions; we use it to uniquely decompose the target arithmetic problem to multiple classification problems; we then compose an expression tree, combining these with world knowledge through a constrained inference framework. Our classifiers gain from the use of quantity schemas that supports better extraction of features. Experimental results show that our method outperforms existing systems, achieving state of the art performance on benchmark datasets of arithmetic word problems.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D15-1202.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:6,community:5,deg_w:25.5,betweenness:.0047,pagerank:.00116,eigenvector:.0011},{id:136,oaid:"003ef1cd670d01af05afa0d3c72d72228f494432",doi:"10.48550/arXiv.2304.11477",title:"LLM+P: Empowering Large Language Models with Optimal Planning Proficiency",authors:[{name:"B. Liu",institutions:[]},{name:"Yuqian Jiang",institutions:[]},{name:"Xiaohan Zhang",institutions:["SUNY Binghamton"]},{name:"Qian Liu",institutions:[]},{name:"Shiqi Zhang",institutions:[]},{name:"Joydeep Biswas",institutions:["The University of Texas at Austin"]},{name:"Peter Stone",institutions:[]}],authorString:"B. Liu; Yuqian Jiang; Xiaohan Zhang; Qian Liu; Shiqi Zhang; Joydeep Biswas; Peter Stone",institutions:["SUNY Binghamton","The University of Texas at Austin"],countries:[],year:2023,journal:"arXiv.org",citations:662,abstract:"Large language models (LLMs) have demonstrated remarkable zero-shot generalization abilities: state-of-the-art chatbots can provide plausible answers to many common questions that arise in daily life. However, so far, LLMs cannot reliably solve long-horizon planning problems. By contrast, classical planners, once a problem is given in a formatted way, can use efficient search algorithms to quickly identify correct, or even optimal, plans. In an effort to get the best of both worlds, this paper introduces LLM+P, the first framework that incorporates the strengths of classical planners into LLMs. LLM+P takes in a natural language description of a planning problem, then returns a correct (or optimal) plan for solving that problem in natural language. LLM+P does so by first converting the language description into a file written in the planning domain definition language (PDDL), then leveraging classical planners to quickly find a solution, and then translating the found solution back into natural language. Along with LLM+P, we define a diverse set of different benchmark problems taken from common planning scenarios. Via a comprehensive set of experiments on these benchmark problems, we find that LLM+P is able to provide optimal solutions for most problems, while LLMs fail to provide even feasible plans for most problems.\\footnote{The code and results are publicly available at https://github.com/Cranial-XIX/llm-pddl.git.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2304.11477",is_oa:!0,n_refs:69,n_refs_in_core:22,degree:32,community:4,deg_w:154,betweenness:.0606,pagerank:.00898,eigenvector:.0053},{id:137,oaid:"26ee8223907bf0fe00ab3760f1d7bc1ae1a89a73",doi:"10.1145/3241036",title:"The seven tools of causal inference, with reflections on machine learning",authors:[{name:"J. Pearl",institutions:[]}],authorString:"J. Pearl",institutions:[],countries:[],year:2019,journal:"Communications of the ACM",citations:662,abstract:'The kind of causal inference seen in natural human thought can be "algorithmitized" to help produce human-level machine intelligence.',keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3241036",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:44e-5,eigenvector:0},{id:138,oaid:"2da7c1872f2a18ae7187fe1b53ef62e727e3cf22",doi:"10.1145/765568.765570",title:"A differential approach to inference in Bayesian networks",authors:[{name:"Adnan Darwiche",institutions:["UCLA"]}],authorString:"Adnan Darwiche",institutions:["UCLA"],countries:[],year:2e3,journal:"JACM",citations:659,abstract:"We present a new approach to inference in Bayesian networks, which is based on representing the network using a polynomial and then retrieving answers to probabilistic queries by evaluating and differentiating the polynomial. The network polynomial itself is exponential in size, but we show how it can be computed efficiently using an arithmetic circuit that can be evaluated and differentiated in time and space linear in the circuit size. The proposed framework for inference subsumes one of the most influential methods for inference in Bayesian networks, known as the tree-clustering or jointree method, which provides a deeper understanding of this classical method and lifts its desirable characteristics to a much more general setting. We discuss some theoretical and practical implications of this subsumption.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1301.3847",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:43e-5,eigenvector:0},{id:139,oaid:"24cee2bfa372e01f8276111c41b82ad06de07500",doi:"10.1016/0010-0277(94)90039-6",title:"Initial knowledge: six suggestions.",authors:[{name:"E. Spelke",institutions:[]}],authorString:"E. Spelke",institutions:[],countries:[],year:1994,journal:"Cognition",citations:653,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:140,oaid:"d88d69a64f236309e95c611cacd2dfdd35496758",doi:null,title:"CLEVRER: CoLlision Events for Video REpresentation and Reasoning",authors:[{name:"Kexin Yi",institutions:[]},{name:"Chuang Gan",institutions:[]},{name:"Yunzhu Li",institutions:["MIT"]},{name:"Pushmeet Kohli",institutions:[]},{name:"Jiajun Wu",institutions:["Stanford University"]},{name:"A. Torralba",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Kexin Yi; Chuang Gan; Yunzhu Li; Pushmeet Kohli; Jiajun Wu; A. Torralba; J. Tenenbaum",institutions:["MIT","Stanford University"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:653,abstract:'The ability to reason about temporal and causal events from videos lies at the core of human intelligence. Most video reasoning benchmarks, however, focus on pattern recognition from complex visual and language input, instead of on causal structure. We study the complementary problem, exploring the temporal and causal structures behind videos of objects with simple visual appearance. To this end, we introduce the CoLlision Events for Video REpresentation and Reasoning (CLEVRER), a diagnostic video dataset for systematic evaluation of computational models on a wide range of reasoning tasks. Motivated by the theory of human casual judgment, CLEVRER includes four types of questions: descriptive (e.g., "what color"), explanatory ("what is responsible for"), predictive ("what will happen next"), and counterfactual ("what if"). We evaluate various state-of-the-art models for visual reasoning on our benchmark. While these models thrive on the perception-based task (descriptive), they perform poorly on the causal tasks (explanatory, predictive and counterfactual), suggesting that a principled approach for causal reasoning should incorporate the capability of both perceiving complex visual and language inputs, and understanding the underlying dynamics and causal relations. We also study an oracle model that explicitly combines these components via symbolic representations.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:64,n_refs_in_core:34,degree:50,community:3,deg_w:367.5,betweenness:.0424,pagerank:.00972,eigenvector:.0022},{id:141,oaid:"792bf014f202938b798656c61a6fce2adc74403f",doi:"10.1109/ICCV.2015.209",title:"Constrained Convolutional Neural Networks for Weakly Supervised Segmentation",authors:[{name:"Deepak Pathak",institutions:["Carnegie Mellon University"]},{name:"Philipp Krähenbühl",institutions:[]},{name:"Trevor Darrell",institutions:[]}],authorString:"Deepak Pathak; Philipp Krähenbühl; Trevor Darrell",institutions:["Carnegie Mellon University"],countries:[],year:2015,journal:"IEEE International Conference on Computer Vision",citations:651,abstract:"We present an approach to learn a dense pixel-wise labeling from image-level tags. Each image-level tag imposes constraints on the output labeling of a Convolutional Neural Network (CNN) classifier. We propose Constrained CNN (CCNN), a method which uses a novel loss function to optimize for any set of linear constraints on the output space (i.e. predicted label distribution) of a CNN. Our loss formulation is easy to optimize and can be incorporated directly into standard stochastic gradient descent optimization. The key idea is to phrase the training objective as a biconvex optimization for linear models, which we then relax to nonlinear deep networks. Extensive experiments demonstrate the generality of our new learning framework. The constrained loss yields state-of-the-art results on weakly supervised semantic image segmentation. We further demonstrate that adding slightly more supervision can greatly improve the performance of the learning algorithm.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:39,n_refs_in_core:1,degree:5,community:3,deg_w:26.5,betweenness:6e-4,pagerank:.00122,eigenvector:2e-4},{id:142,oaid:"0c06bd20403a204bcd95dae1f176c10894fe7139",doi:"10.18653/v1/2020.acl-main.412",title:"Improving Multi-hop Question Answering over Knowledge Graphs using Knowledge Base Embeddings",authors:[{name:"Apoorv Saxena",institutions:[]},{name:"Aditay Tripathi",institutions:["Indian Institute of Science, Bengaluru","Indraprastha Institute of Information Technology, New Delhi"]},{name:"P. Talukdar",institutions:[]}],authorString:"Apoorv Saxena; Aditay Tripathi; P. Talukdar",institutions:["Indian Institute of Science, Bengaluru","Indraprastha Institute of Information Technology, New Delhi"],countries:[],year:2020,journal:"Annual Meeting of the Association for Computational Linguistics",citations:650,abstract:"Knowledge Graphs (KG) are multi-relational graphs consisting of entities as nodes and relations among them as typed edges. Goal of the Question Answering over KG (KGQA) task is to answer natural language queries posed over the KG. Multi-hop KGQA requires reasoning over multiple edges of the KG to arrive at the right answer. KGs are often incomplete with many missing links, posing additional challenges for KGQA, especially for multi-hop KGQA. Recent research on multi-hop KGQA has attempted to handle KG sparsity using relevant external text, which isn’t always readily available. In a separate line of research, KG embedding methods have been proposed to reduce KG sparsity by performing missing link prediction. Such KG embedding methods, even though highly relevant, have not been explored for multi-hop KGQA so far. We fill this gap in this paper and propose EmbedKGQA. EmbedKGQA is particularly effective in performing multi-hop KGQA over sparse KGs. EmbedKGQA also relaxes the requirement of answer selection from a pre-specified neighborhood, a sub-optimal constraint enforced by previous multi-hop KGQA methods. Through extensive experiments on multiple benchmark datasets, we demonstrate EmbedKGQA’s effectiveness over other state-of-the-art baselines.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.412.pdf",is_oa:!0,n_refs:35,n_refs_in_core:4,degree:19,community:1,deg_w:109,betweenness:.0107,pagerank:.00299,eigenvector:.0494},{id:143,oaid:"af66165c454a0e94afbab36271fe3deaae0b421a",doi:null,title:"An Efficient Recognition and Syntax-Analysis Algorithm for Context-Free Languages",authors:[{name:"T. Kasami",institutions:[]}],authorString:"T. Kasami",institutions:[],countries:[],year:1965,journal:"",citations:648,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:144,oaid:"a9de2fc7ae3230652f27fd95e7175da8cf44f075",doi:"10.18653/v1/P16-1228",title:"Harnessing Deep Neural Networks with Logic Rules",authors:[{name:"Zhiting Hu",institutions:[]},{name:"Xuezhe Ma",institutions:["University of Southern California;Carnegie Mellon University"]},{name:"Zhengzhong Liu",institutions:[]},{name:"E. Hovy",institutions:[]},{name:"E. Xing",institutions:[]}],authorString:"Zhiting Hu; Xuezhe Ma; Zhengzhong Liu; E. Hovy; E. Xing",institutions:["University of Southern California;Carnegie Mellon University"],countries:[],year:2016,journal:"Annual Meeting of the Association for Computational Linguistics",citations:643,abstract:"Combining deep neural networks with structured logic rules is desirable to harness flexibility and reduce uninterpretability of the neural models. We propose a general framework capable of enhancing various types of neural networks (e.g., CNNs and RNNs) with declarative first-order logic rules. Specifically, we develop an iterative distillation method that transfers the structured information of logic rules into the weights of neural networks. We deploy the framework on a CNN for sentiment analysis, and an RNN for named entity recognition. With a few highly intuitive rules, we obtain substantial improvements and achieve state-of-the-art or comparable results to previous best-performing systems.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P16-1228.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:0,deg_w:18,betweenness:0,pagerank:91e-5,eigenvector:3e-4},{id:145,oaid:"a6383f155fa9d3e9b15092bfefbf613f982eb263",doi:null,title:"The Algebraic Mind: Integrating Connectionism and Cognitive Science",authors:[{name:"G. Marcus",institutions:[]}],authorString:"G. Marcus",institutions:[],countries:[],year:2001,journal:"",citations:642,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:2,deg_w:17,betweenness:1e-4,pagerank:92e-5,eigenvector:1e-4},{id:146,oaid:"7572aefcd241ec76341addcb2e2e417587cb2e4c",doi:"10.1145/3289600.3290956",title:"Knowledge Graph Embedding Based Question Answering",authors:[{name:"Xiao Huang",institutions:["The Hong Kong Polytechnic University"]},{name:"Jingyuan Zhang",institutions:[]},{name:"Dingcheng Li",institutions:[]},{name:"Ping Li",institutions:[]}],authorString:"Xiao Huang; Jingyuan Zhang; Dingcheng Li; Ping Li",institutions:["The Hong Kong Polytechnic University"],countries:[],year:2019,journal:"Web Search and Data Mining",citations:640,abstract:"Question answering over knowledge graph (QA-KG) aims to use facts in the knowledge graph (KG) to answer natural language questions. It helps end users more efficiently and more easily access the substantial and valuable knowledge in the KG, without knowing its data structures. QA-KG is a nontrivial problem since capturing the semantic meaning of natural language is difficult for a machine. Meanwhile, many knowledge graph embedding methods have been proposed. The key idea is to represent each predicate/entity as a low-dimensional vector, such that the relation information in the KG could be preserved. The learned vectors could benefit various applications such as KG completion and recommender systems. In this paper, we explore to use them to handle the QA-KG problem. However, this remains a challenging task since a predicate could be expressed in different ways in natural language questions. Also, the ambiguity of entity names and partial names makes the number of possible answers large. To bridge the gap, we propose an effective Knowledge Embedding based Question Answering (KEQA) framework. We focus on answering the most common types of questions, i.e., simple questions, in which each question could be answered by the machine straightforwardly if its single head entity and single predicate are correctly identified. To answer a simple question, instead of inferring its head entity and predicate directly, KEQA targets at jointly recovering the question's head entity, predicate, and tail entity representations in the KG embedding spaces. Based on a carefully-designed joint distance metric, the three learned vectors' closest fact in the KG is returned as the answer. Experiments on a widely-adopted benchmark demonstrate that the proposed KEQA outperforms the state-of-the-art QA-KG methods.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:147,oaid:"c334c8ddfa0c1d16be63ed8cd2f19c4bf6bb35a9",doi:null,title:"The Art of Prolog: Advanced Programming Techniques",authors:[{name:"L. Sterling",institutions:[]},{name:"E. Shapiro",institutions:[]}],authorString:"L. Sterling; E. Shapiro",institutions:[],countries:[],year:1994,journal:"",citations:637,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:148,oaid:"4f03e69963b9649950ba29ae864a0de8c14f1f86",doi:"10.18653/v1/2021.findings-acl.121",title:"K-Adapter: Infusing Knowledge into Pre-Trained Models with Adapters",authors:[{name:"Ruize Wang",institutions:[]},{name:"Duyu Tang",institutions:[]},{name:"Nan Duan",institutions:[]},{name:"Zhongyu Wei",institutions:[]},{name:"Xuanjing Huang",institutions:["Fudan University"]},{name:"Jianshu Ji",institutions:[]},{name:"Guihong Cao",institutions:[]},{name:"Daxin Jiang",institutions:[]},{name:"Ming Zhou",institutions:[]}],authorString:"Ruize Wang; Duyu Tang; Nan Duan; Zhongyu Wei; Xuanjing Huang; Jianshu Ji; Guihong Cao; Daxin Jiang; Ming Zhou",institutions:["Fudan University"],countries:[],year:2020,journal:"Findings",citations:634,abstract:"We study the problem of injecting knowledge into large pre-trained models like BERT and RoBERTa. Existing methods typically update the original parameters of pre-trained models when injecting knowledge. However, when multiple kinds of knowledge are injected, they may suffer from catastrophic forgetting. To address this, we propose K-Adapter, which remains the original parameters of the pre-trained model fixed and supports continual knowledge infusion. Taking RoBERTa as the pre-trained model, K-Adapter has a neural adapter for each kind of infused knowledge, like a plug-in connected to RoBERTa. There is no information flow between different adapters, thus different adapters are efficiently trained in a distributed way. We inject two kinds of knowledge, including factual knowledge obtained from automatically aligned text-triplets on Wikipedia and Wikidata, and linguistic knowledge obtained from dependency parsing. Results on three knowledge-driven tasks (total six datasets) including relation classification, entity typing and question answering demonstrate that each adapter improves the performance, and the combination of both adapters brings further improvements. Probing experiments further indicate that K-Adapter captures richer factual and commonsense knowledge than RoBERTa.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.findings-acl.121.pdf",is_oa:!0,n_refs:49,n_refs_in_core:3,degree:24,community:1,deg_w:308,betweenness:.0013,pagerank:.00591,eigenvector:.2557},{id:149,oaid:"8a25c9403d8a0e2fb8ca362a1b26262afd57417f",doi:null,title:"DeepCoder: Learning to Write Programs",authors:[{name:"M. Balog",institutions:[]},{name:"Alexander L. Gaunt",institutions:[]},{name:"Marc Brockschmidt",institutions:[]},{name:"Sebastian Nowozin",institutions:[]},{name:"Daniel Tarlow",institutions:[]}],authorString:"M. Balog; Alexander L. Gaunt; Marc Brockschmidt; Sebastian Nowozin; Daniel Tarlow",institutions:[],countries:[],year:2016,journal:"International Conference on Learning Representations",citations:627,abstract:"We develop a first line of attack for solving programming competition-style problems from input-output examples using deep learning. The approach is to train a neural network to predict properties of the program that generated the outputs from the inputs. We use the neural network’s predictions to augment search techniques from the programming languages community, including enumerative search and an SMT-based solver. Empirically, we show that our approach leads to an order of magnitude speedup over the strong non-augmented baselines and a Recurrent Neural Network approach, and that we are able to solve problems of difficulty comparable to the simplest problems on programming competition websites.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:7,deg_w:21,betweenness:.0029,pagerank:.00103,eigenvector:6e-4},{id:150,oaid:"7f6acbbeabcbd585ef52105749705ca9cc3854bc",doi:"10.1126/science.aan8871",title:"What is consciousness, and could machines have it?",authors:[{name:"S. Dehaene",institutions:[]},{name:"Hakwan C. Lau",institutions:[]},{name:"S. Kouider",institutions:[]}],authorString:"S. Dehaene; Hakwan C. Lau; S. Kouider",institutions:[],countries:[],year:2017,journal:"Science",citations:626,abstract:"The controversial question of whether machines may ever be conscious must be based on a careful consideration of how consciousness arises in the only physical system that undoubtedly possesses it: the human brain. We suggest that the word “consciousness” conflates two different types of information-processing computations in the brain: the selection of information for global broadcasting, thus making it flexibly available for computation and report (C1, consciousness in the first sense), and the self-monitoring of those computations, leading to a subjective sense of certainty or error (C2, consciousness in the second sense). We argue that despite their recent successes, current machines are still mostly implementing computations that reflect unconscious processing (C0) in the human brain. We review the psychological and neural science of unconscious (C0) and conscious computations (C1 and C2) and outline how they may inspire novel machine architectures.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://escholarship.org/content/qt56b2q8h9/qt56b2q8h9.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:59e-5,eigenvector:0},{id:151,oaid:"289fb3709475f5c87df8d97f129af54029d27fee",doi:null,title:"Compositional Attention Networks for Machine Reasoning",authors:[{name:"Drew A. Hudson",institutions:[]},{name:"Christopher D. Manning",institutions:["Stanford University"]}],authorString:"Drew A. Hudson; Christopher D. Manning",institutions:["Stanford University"],countries:[],year:2018,journal:"International Conference on Learning Representations",citations:625,abstract:"We present the MAC network, a novel fully differentiable neural network architecture, designed to facilitate explicit and expressive reasoning. MAC moves away from monolithic black-box neural architectures towards a design that encourages both transparency and versatility. The model approaches problems by decomposing them into a series of attention-based reasoning steps, each performed by a novel recurrent Memory, Attention, and Composition (MAC) cell that maintains a separation between control and memory. By stringing the cells together and imposing structural constraints that regulate their interaction, MAC effectively learns to perform iterative reasoning processes that are directly inferred from the data in an end-to-end approach. We demonstrate the model's strength, robustness and interpretability on the challenging CLEVR dataset for visual reasoning, achieving a new state-of-the-art 98.9% accuracy, halving the error rate of the previous best model. More importantly, we show that the model is computationally-efficient and data-efficient, in particular requiring 5x less data than existing models to achieve strong results.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:35,n_refs_in_core:9,degree:29,community:3,deg_w:247.5,betweenness:.0064,pagerank:.00602,eigenvector:.0018},{id:152,oaid:"d295a620fc10a7a656dc693e1b1bf668d1508a8e",doi:null,title:"Robust Physical-World Attacks on Deep Learning Models",authors:[{name:"I. Evtimov",institutions:[]},{name:"Kevin Eykholt",institutions:[]},{name:"Earlence Fernandes",institutions:[]},{name:"T. Kohno",institutions:[]},{name:"Bo Li",institutions:[]},{name:"Atul Prakash",institutions:["University of Michigan"]},{name:"Amir Rahmati",institutions:["Stony Brook University"]},{name:"D. Song",institutions:[]}],authorString:"I. Evtimov; Kevin Eykholt; Earlence Fernandes; T. Kohno; Bo Li; Atul Prakash; Amir Rahmati; D. Song",institutions:["Stony Brook University","University of Michigan"],countries:[],year:2017,journal:"",citations:623,abstract:"Recent studies show that the state-of-the-art deep neural networks (DNNs) are vulnerable to adversarial examples, resulting from small-magnitude perturbations added to the input. Given that that emerging physical systems are using DNNs in safety-critical situations, adversarial examples could mislead these systems and cause dangerous situations.Therefore, understanding adversarial examples in the physical world is an important step towards developing resilient learning algorithms. We propose a general attack algorithm,Robust Physical Perturbations (RP2), to generate robust visual adversarial perturbations under different physical conditions. Using the real-world case of road sign classification, we show that adversarial examples generated using RP2 achieve high targeted misclassification rates against standard-architecture road sign classifiers in the physical world under various environmental conditions, including viewpoints. Due to the current lack of a standardized testing method, we propose a two-stage evaluation methodology for robust physical adversarial examples consisting of lab and field tests. Using this methodology, we evaluate the efficacy of physical adversarial manipulations on real objects. Witha perturbation in the form of only black and white stickers,we attack a real stop sign, causing targeted misclassification in 100% of the images obtained in lab settings, and in 84.8%of the captured video frames obtained on a moving vehicle(field test) for the target classifier.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:45,n_refs_in_core:1,degree:3,community:2,deg_w:17.5,betweenness:0,pagerank:.00127,eigenvector:0},{id:153,oaid:"573e0d000c21d66f74454655c942337b3a12171e",doi:"10.1007/978-3-642-40627-0_2",title:"Answer Set Programming",authors:[{name:"Wolfgang Faber",institutions:[]}],authorString:"Wolfgang Faber",institutions:[],countries:[],year:2012,journal:"Formal Methods in Computer-Aided Design",citations:619,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:154,oaid:"d25b1edda507cba944938ec8784d8b124c2381a5",doi:null,title:"MONet: Unsupervised Scene Decomposition and Representation",authors:[{name:"Christopher P. Burgess",institutions:[]},{name:"L. Matthey",institutions:[]},{name:"Nicholas Watters",institutions:[]},{name:"Rishabh Kabra",institutions:[]},{name:"I. Higgins",institutions:[]},{name:"M. Botvinick",institutions:[]},{name:"Alexander Lerchner",institutions:["DeepMind"]}],authorString:"Christopher P. Burgess; L. Matthey; Nicholas Watters; Rishabh Kabra; I. Higgins; M. Botvinick; Alexander Lerchner",institutions:["DeepMind"],countries:[],year:2019,journal:"arXiv.org",citations:619,abstract:"The ability to decompose scenes in terms of abstract building blocks is crucial for general intelligence. Where those basic building blocks share meaningful properties, interactions and other regularities across scenes, such decompositions can simplify reasoning and facilitate imagination of novel scenarios. In particular, representing perceptual observations in terms of entities should improve data efficiency and transfer performance on a wide range of tasks. Thus we need models capable of discovering useful decompositions of scenes by identifying units with such regularities and representing them in a common format. To address this problem, we have developed the Multi-Object Network (MONet). In this model, a VAE is trained end-to-end together with a recurrent attention network -- in a purely unsupervised manner -- to provide attention masks around, and reconstructions of, regions of images. We show that this model is capable of learning to decompose and represent challenging 3D scenes into semantically meaningful components, such as objects and background elements.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:37,n_refs_in_core:3,degree:12,community:2,deg_w:73,betweenness:.0017,pagerank:.00241,eigenvector:2e-4},{id:155,oaid:"3ecd3e00bbbfd94446c3adc9c6878de27e250f7c",doi:"10.1162/COLI_a_00127",title:"Learning Dependency-Based Compositional Semantics",authors:[{name:"P. Liang",institutions:[]},{name:"Michael I. Jordan",institutions:[]},{name:"D. Klein",institutions:[]}],authorString:"P. Liang; Michael I. Jordan; D. Klein",institutions:[],countries:[],year:2011,journal:"International Conference on Computational Logic",citations:618,abstract:"Suppose we want to build a system that answers a natural language question by representing its semantics as a logical forxm and computing the answer given a structured database of facts. The core part of such a system is the semantic parser that maps questions to logical forms. Semantic parsers are typically trained from examples of questions annotated with their target logical forms, but this type of annotation is expensive.Our goal is to instead learn a semantic parser from question–answer pairs, where the logical form is modeled as a latent variable. We develop a new semantic formalism, dependency-based compositional semantics (DCS) and define a log-linear distribution over DCS logical forms. The model parameters are estimated using a simple procedure that alternates between beam search and numerical optimization. On two standard semantic parsing benchmarks, we show that our system obtains comparable accuracies to even state-of-the-art systems that do require annotated logical forms.",keywords:[],concepts:[],pdf_url:"https://direct.mit.edu/coli/article-pdf/39/2/389/1812365/coli_a_00127.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:7,community:5,deg_w:29,betweenness:.0017,pagerank:.00101,eigenvector:2e-4},{id:156,oaid:"8cf83c619423a1504f26495d5f6a495054c46462",doi:null,title:"Learning to Poke by Poking: Experiential Learning of Intuitive Physics",authors:[{name:"Pulkit Agrawal",institutions:[]},{name:"Ashvin Nair",institutions:[]},{name:"P. Abbeel",institutions:[]},{name:"Jitendra Malik",institutions:["UC Berkeley","Facebook"]},{name:"S. Levine",institutions:[]}],authorString:"Pulkit Agrawal; Ashvin Nair; P. Abbeel; Jitendra Malik; S. Levine",institutions:["Facebook","UC Berkeley"],countries:[],year:2016,journal:"Neural Information Processing Systems",citations:616,abstract:"We investigate an experiential learning paradigm for acquiring an internal model of intuitive physics. Our model is evaluated on a real-world robotic manipulation task that requires displacing objects to target locations by poking. The robot gathered over 400 hours of experience by executing more than 100K pokes on different objects. We propose a novel approach based on deep neural networks for modeling the dynamics of robot's interactions directly from images, by jointly estimating forward and inverse models of dynamics. The inverse model objective provides supervision to construct informative visual features, which the forward model can then predict and in turn regularize the feature space for the inverse model. The interplay between these two objectives creates useful, accurate models that can then be used for multi-step decision making. This formulation has the additional benefit that it is possible to learn forward models in an abstract feature space and thus alleviate the need of predicting pixels. Our experiments show that this joint modeling approach outperforms alternative methods.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:2,deg_w:18,betweenness:0,pagerank:78e-5,eigenvector:0},{id:157,oaid:"319b84be7a843250bc81d7086f79a4126d550277",doi:null,title:"ERNIE 3.0: Large-scale Knowledge Enhanced Pre-training for Language Understanding and Generation",authors:[{name:"Yu Sun",institutions:[]},{name:"Shuohuan Wang",institutions:[]},{name:"Shikun Feng",institutions:[]},{name:"Siyu Ding",institutions:[]},{name:"Chao Pang",institutions:[]},{name:"Junyuan Shang",institutions:[]},{name:"Jiaxiang Liu",institutions:[]},{name:"Xuyi Chen",institutions:[]},{name:"Yanbin Zhao",institutions:[]},{name:"Yuxiang Lu",institutions:[]},{name:"Weixin Liu",institutions:[]},{name:"Zhihua Wu",institutions:[]},{name:"Weibao Gong",institutions:[]},{name:"Jianzhong Liang",institutions:[]},{name:"Zhizhou Shang",institutions:[]},{name:"Peng Sun",institutions:[]},{name:"Wei Liu",institutions:[]},{name:"Ouyang Xuan",institutions:[]},{name:"Dianhai Yu",institutions:[]},{name:"Hao Tian",institutions:[]},{name:"Hua Wu",institutions:[]},{name:"Haifeng Wang",institutions:[]}],authorString:"Yu Sun; Shuohuan Wang; Shikun Feng; Siyu Ding; Chao Pang; Junyuan Shang; Jiaxiang Liu; Xuyi Chen; Yanbin Zhao; Yuxiang Lu; Weixin Liu; Zhihua Wu et al.",institutions:[],countries:[],year:2021,journal:"arXiv.org",citations:615,abstract:"Pre-trained models have achieved state-of-the-art results in various Natural Language Processing (NLP) tasks. Recent works such as T5 and GPT-3 have shown that scaling up pre-trained language models can improve their generalization abilities. Particularly, the GPT-3 model with 175 billion parameters shows its strong task-agnostic zero-shot/few-shot learning capabilities. Despite their success, these large-scale models are trained on plain texts without introducing knowledge such as linguistic knowledge and world knowledge. In addition, most large-scale models are trained in an auto-regressive way. As a result, this kind of traditional fine-tuning approach demonstrates relatively weak performance when solving downstream language understanding tasks. In order to solve the above problems, we propose a unified framework named ERNIE 3.0 for pre-training large-scale knowledge enhanced models. It fuses auto-regressive network and auto-encoding network, so that the trained model can be easily tailored for both natural language understanding and generation tasks with zero-shot learning, few-shot learning or fine-tuning. We trained the model with 10 billion parameters on a 4TB corpus consisting of plain texts and a large-scale knowledge graph. Empirical results show that the model outperforms the state-of-the-art models on 54 Chinese NLP tasks, and its English version achieves the first place on the SuperGLUE benchmark (July 3, 2021), surpassing the human performance by +0.8% (90.6% vs. 89.8%).",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:97,n_refs_in_core:6,degree:22,community:1,deg_w:277,betweenness:.0026,pagerank:.00555,eigenvector:.225},{id:158,oaid:"856d5dcba4772328b8fb784494e3d41d39669b0d",doi:null,title:"Machine Theory of Mind",authors:[{name:"Neil C. Rabinowitz",institutions:[]},{name:"Frank Perbet",institutions:[]},{name:"H. F. Song",institutions:[]},{name:"Chiyuan Zhang",institutions:[]},{name:"S. Eslami",institutions:[]},{name:"M. Botvinick",institutions:[]}],authorString:"Neil C. Rabinowitz; Frank Perbet; H. F. Song; Chiyuan Zhang; S. Eslami; M. Botvinick",institutions:[],countries:[],year:2018,journal:"International Conference on Machine Learning",citations:615,abstract:`Theory of mind (ToM; Premack & Woodruff, 1978) broadly refers to humans' ability to represent the mental states of others, including their desires, beliefs, and intentions. We propose to train a machine to build such models too. We design a Theory of Mind neural network -- a ToMnet -- which uses meta-learning to build models of the agents it encounters, from observations of their behaviour alone. Through this process, it acquires a strong prior model for agents' behaviour, as well as the ability to bootstrap to richer predictions about agents' characteristics and mental states using only a small number of behavioural observations. We apply the ToMnet to agents behaving in simple gridworld environments, showing that it learns to model random, algorithmic, and deep reinforcement learning agents from varied populations, and that it passes classic ToM tasks such as the "Sally-Anne" test (Wimmer & Perner, 1983; Baron-Cohen et al., 1985) of recognising that others can hold false beliefs about the world. We argue that this system -- which autonomously learns how to model other agents in its world -- is an important step forward for developing multi-agent AI systems, for building intermediating technology for machine-human interaction, and for advancing the progress on interpretable AI.`,keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:76,n_refs_in_core:1,degree:2,community:2,deg_w:9,betweenness:1e-4,pagerank:77e-5,eigenvector:0},{id:159,oaid:"a396a6febdacb84340d139096455e67049ac1e22",doi:"10.1109/ICCV.2017.93",title:"Learning to Reason: End-to-End Module Networks for Visual Question Answering",authors:[{name:"Ronghang Hu",institutions:[]},{name:"Jacob Andreas",institutions:["MIT","Microsoft"]},{name:"Marcus Rohrbach",institutions:["TU Darmstadt"]},{name:"Trevor Darrell",institutions:[]},{name:"Kate Saenko",institutions:[]}],authorString:"Ronghang Hu; Jacob Andreas; Marcus Rohrbach; Trevor Darrell; Kate Saenko",institutions:["MIT","Microsoft","TU Darmstadt"],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:608,abstract:"Natural language questions are inherently compositional, and many are most easily answered by reasoning about their decomposition into modular sub-problems. For example, to answer “is there an equal number of balls and boxes?” we can look for balls, look for boxes, count them, and compare the results. The recently proposed Neural Module Network (NMN) architecture [3, 2] implements this approach to question answering by parsing questions into linguistic substructures and assembling question-specific deep networks from smaller modules that each solve one subtask. However, existing NMN implementations rely on brittle off-the-shelf parsers, and are restricted to the module configurations proposed by these parsers rather than learning them from data. In this paper, we propose End-to-End Module Networks (N2NMNs), which learn to reason by directly predicting instance-specific network layouts without the aid of a parser. Our model learns to generate network structures (by imitating expert demonstrations) while simultaneously learning network parameters (using the downstream task loss). Experimental results on the new CLEVR dataset targeted at compositional question answering show that N2NMNs achieve an error reduction of nearly 50% relative to state-of-theart attentional approaches, while discovering interpretable network architectures specialized for each question.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1704.05526",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:10,community:3,deg_w:42.5,betweenness:.0016,pagerank:.0012,eigenvector:6e-4},{id:160,oaid:"526e22c130b18924976553d29ba11bc9d898d58b",doi:"10.1007/s10994-009-5106-x",title:"Search-based structured prediction",authors:[{name:"Hal Daumé",institutions:[]},{name:"John Langford",institutions:[]},{name:"D. Marcu",institutions:[]}],authorString:"Hal Daumé; John Langford; D. Marcu",institutions:[],countries:[],year:2009,journal:"Machine-mediated learning",citations:602,abstract:"We present Searn, an algorithm for integrating search and learning to solve complex structured prediction problems such as those that occur in natural language, speech, computational biology, and vision. Searn is a meta-algorithm that transforms these complex problems into simple classification problems to which any binary classifier may be applied. Unlike current algorithms for structured learning that require decomposition of both the loss function and the feature functions over the predicted structure, Searn is able to learn prediction functions for any loss function and any class of features. Moreover, Searn comes with a strong, natural theoretical guarantee: good performance on the derived classification problems implies good performance on the structured prediction problem.",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10994-009-5106-x.pdf",is_oa:!0,n_refs:67,n_refs_in_core:0,degree:2,community:0,deg_w:13,betweenness:0,pagerank:81e-5,eigenvector:0},{id:161,oaid:"46b8cbcdff87b842c2c1d4a003c831f845096ba7",doi:null,title:"Order-Embeddings of Images and Language",authors:[{name:"Ivan Vendrov",institutions:[]},{name:"Ryan Kiros",institutions:[]},{name:"S. Fidler",institutions:[]},{name:"R. Urtasun",institutions:[]}],authorString:"Ivan Vendrov; Ryan Kiros; S. Fidler; R. Urtasun",institutions:[],countries:[],year:2015,journal:"International Conference on Learning Representations",citations:602,abstract:"Hypernymy, textual entailment, and image captioning can be seen as special cases of a single visual-semantic hierarchy over words, sentences, and images. In this paper we advocate for explicitly modeling the partial order structure of this hierarchy. Towards this goal, we introduce a general method for learning ordered representations, and show how it can be applied to a variety of tasks involving images and language. We show that the resulting representations improve performance over current approaches for hypernym prediction and image-caption retrieval.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12.5,betweenness:2e-4,pagerank:62e-5,eigenvector:3e-4},{id:162,oaid:"e70e6c254a57e361047de5030b1502b8ccbe341b",doi:"10.3233/AIC-2011-0491",title:"Potassco: The Potsdam Answer Set Solving Collection",authors:[{name:"M. Gebser",institutions:[]},{name:"B. Kaufmann",institutions:[]},{name:"Roland Kaminski",institutions:[]},{name:"Max Ostrowski",institutions:[]},{name:"Torsten Schaub",institutions:["University of Potsdam"]},{name:"M. Lindauer",institutions:[]}],authorString:"M. Gebser; B. Kaufmann; Roland Kaminski; Max Ostrowski; Torsten Schaub; M. Lindauer",institutions:["University of Potsdam"],countries:[],year:2011,journal:"AI Communications",citations:595,abstract:"This paper gives an overview of the open source project Potassco, the Potsdam Answer Set Solving Collection, bundling tools for Answer Set Programming developed at the University of Potsdam.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:163,oaid:"9286ac6e9b1aacd7d93496eb4615ae7678876d2a",doi:null,title:"Fast Model Editing at Scale",authors:[{name:"E. Mitchell",institutions:[]},{name:"Charles Lin",institutions:[]},{name:"Antoine Bosselut",institutions:["EPFL"]},{name:"Chelsea Finn",institutions:[]},{name:"Christopher D. Manning",institutions:["Stanford University"]}],authorString:"E. Mitchell; Charles Lin; Antoine Bosselut; Chelsea Finn; Christopher D. Manning",institutions:["EPFL","Stanford University"],countries:[],year:2021,journal:"International Conference on Learning Representations",citations:592,abstract:"While large pre-trained models have enabled impressive results on a variety of downstream tasks, the largest existing models still make errors, and even accurate predictions may become outdated over time. Because detecting all such failures at training time is impossible, enabling both developers and end users of such models to correct inaccurate outputs while leaving the model otherwise intact is desirable. However, the distributed, black-box nature of the representations learned by large neural networks makes producing such targeted edits difficult. If presented with only a single problematic input and new desired output, fine-tuning approaches tend to overfit; other editing algorithms are either computationally infeasible or simply ineffective when applied to very large models. To enable easy post-hoc editing at scale, we propose Model Editor Networks using Gradient Decomposition (MEND), a collection of small auxiliary editing networks that use a single desired input-output pair to make fast, local edits to a pre-trained model's behavior. MEND learns to transform the gradient obtained by standard fine-tuning, using a low-rank decomposition of the gradient to make the parameterization of this transformation tractable. MEND can be trained on a single GPU in less than a day even for 10 billion+ parameter models; once trained MEND enables rapid application of new edits to the pre-trained model. Our experiments with T5, GPT, BERT, and BART models show that MEND is the only approach to model editing that effectively edits the behavior of models with more than 10 billion parameters. Code and data available at https://sites.google.com/view/mend-editing.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:47,n_refs_in_core:2,degree:17,community:1,deg_w:105.5,betweenness:.0046,pagerank:.00252,eigenvector:.0593},{id:164,oaid:"e0f27336698c84709bd60b6b7f4ce588cbae66bf",doi:"10.48550/arXiv.2305.09645",title:"StructGPT: A General Framework for Large Language Model to Reason over Structured Data",authors:[{name:"Jinhao Jiang",institutions:[]},{name:"Kun Zhou",institutions:[]},{name:"Zican Dong",institutions:[]},{name:"Keming Ye",institutions:[]},{name:"Wayne Xin Zhao",institutions:[]},{name:"Ji-rong Wen",institutions:[]}],authorString:"Jinhao Jiang; Kun Zhou; Zican Dong; Keming Ye; Wayne Xin Zhao; Ji-rong Wen",institutions:[],countries:[],year:2023,journal:"Conference on Empirical Methods in Natural Language Processing",citations:592,abstract:"In this paper, we study how to improve the zero-shot reasoning ability of large language models~(LLMs) over structured data in a unified way. Inspired by the study on tool augmentation for LLMs, we develop an \\emph{Iterative Reading-then-Reasoning~(IRR)} approach for solving question answering tasks based on structured data, called \\textbf{StructGPT}. In our approach, we construct the specialized function to collect relevant evidence from structured data (\\ie \\emph{reading}), and let LLMs concentrate the reasoning task based on the collected information (\\ie \\emph{reasoning}). Specially, we propose an \\emph{invoking-linearization-generation} procedure to support LLMs in reasoning on the structured data with the help of the external interfaces. By iterating this procedures with provided interfaces, our approach can gradually approach the target answer to a given query. Extensive experiments conducted on three types of structured data demonstrate the effectiveness of our approach, which can significantly boost the performance of ChatGPT and achieve comparable performance against the full-data supervised-tuning baselines. Our codes and data are publicly available at~\\url{https://github.com/RUCAIBox/StructGPT}.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2305.09645",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:165,oaid:"d5901f15a0214b50e6a0085337e49a9b966775a7",doi:"10.1007/s10462-023-10448-w",title:"Neurosymbolic AI: the 3rd wave",authors:[{name:"A. Garcez",institutions:[]},{name:"L. Lamb",institutions:[]}],authorString:"A. Garcez; L. Lamb",institutions:[],countries:[],year:2020,journal:"Artificial Intelligence Review",citations:592,abstract:"Current advances in Artificial Intelligence (AI) and Machine Learning have achieved unprecedented impact across research communities and industry. Nevertheless, concerns around trust, safety, interpretability and accountability of AI were raised by influential thinkers. Many identified the need for well-founded knowledge representation and reasoning to be integrated with deep learning and for sound explainability. Neurosymbolic computing has been an active area of research for many years seeking to bring together robust learning in neural networks with reasoning and explainability by offering symbolic representations for neural models. In this paper, we relate recent and early research in neurosymbolic AI with the objective of identifying the most important ingredients of neurosymbolic AI systems. We focus on research that integrates in a principled way neural network-based learning with symbolic knowledge representation and logical reasoning. Finally, this review identifies promising directions and challenges for the next decade of AI research from the perspective of neurosymbolic computing, commonsense reasoning and causal explanation.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:121,n_refs_in_core:44,degree:57,community:0,deg_w:289.5,betweenness:.0999,pagerank:.01455,eigenvector:.0018},{id:166,oaid:"9010d8c1850605bbfed06f60be208b6639c95aff",doi:"10.21236/ad0785031",title:"Situations, Actions, and Causal Laws",authors:[{name:"J. McCarthy",institutions:[]}],authorString:"J. McCarthy",institutions:[],countries:[],year:1963,journal:"",citations:591,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:167,oaid:"c89c71dbe5617bea44383585b58cd0cbc37bf79a",doi:"10.1609/aimag.v26i2.1813",title:"General Game Playing: Overview of the AAAI Competition",authors:[{name:"M. Genesereth",institutions:[]},{name:"Nathaniel Love",institutions:[]},{name:"B. Pell",institutions:[]}],authorString:"M. Genesereth; Nathaniel Love; B. Pell",institutions:[],countries:[],year:2005,journal:"The AI Magazine",citations:588,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:168,oaid:"2e17cf6a339fd071ad222062f868e882ef4120a4",doi:"10.1109/ICCV.2017.325",title:"Inferring and Executing Programs for Visual Reasoning",authors:[{name:"Justin Johnson",institutions:[]},{name:"B. Hariharan",institutions:[]},{name:"L. Maaten",institutions:[]},{name:"Judy Hoffman",institutions:[]},{name:"Li Fei-Fei",institutions:[]},{name:"C. L. Zitnick",institutions:[]},{name:"Ross B. Girshick",institutions:[]}],authorString:"Justin Johnson; B. Hariharan; L. Maaten; Judy Hoffman; Li Fei-Fei; C. L. Zitnick; Ross B. Girshick",institutions:[],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:586,abstract:"Existing methods for visual reasoning attempt to directly map inputs to outputs using black-box architectures without explicitly modeling the underlying reasoning processes. As a result, these black-box models often learn to exploit biases in the data rather than learning to perform visual reasoning. Inspired by module networks, this paper proposes a model for visual reasoning that consists of a program generator that constructs an explicit representation of the reasoning process to be performed, and an execution engine that executes the resulting program to produce an answer. Both the program generator and the execution engine are implemented by neural networks, and are trained using a combination of backpropagation and REINFORCE. Using the CLEVR benchmark for visual reasoning, we show that our model significantly outperforms strong baselines and generalizes better in a variety of settings.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1705.03633",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:8,community:3,deg_w:33.5,betweenness:0,pagerank:.001,eigenvector:3e-4},{id:169,oaid:"bafe023fb072045dc0cd50316382a61c8dcb9fae",doi:"10.1145/3580305.3599790",title:"CodeGeeX: A Pre-Trained Model for Code Generation with Multilingual Benchmarking on HumanEval-X",authors:[{name:"Qinkai Zheng",institutions:[]},{name:"Xiao Xia",institutions:[]},{name:"Xu Zou",institutions:[]},{name:"Yuxiao Dong",institutions:[]},{name:"Shanshan Wang",institutions:[]},{name:"Yufei Xue",institutions:[]},{name:"Zihan Wang",institutions:[]},{name:"Lei Shen",institutions:[]},{name:"Andi Wang",institutions:[]},{name:"Yang Li",institutions:[]},{name:"Teng Su",institutions:[]},{name:"Zhilin Yang",institutions:[]},{name:"Jie Tang",institutions:[]}],authorString:"Qinkai Zheng; Xiao Xia; Xu Zou; Yuxiao Dong; Shanshan Wang; Yufei Xue; Zihan Wang; Lei Shen; Andi Wang; Yang Li; Teng Su; Zhilin Yang et al.",institutions:[],countries:[],year:2023,journal:"Knowledge Discovery and Data Mining",citations:585,abstract:"Large pre-trained code generation models, such as OpenAI Codex, can generate syntax-and function-correct code, making the coding of programmers more productive. In this paper, we introduce CodeGeeX, a multilingual model with 13 billion parameters for code generation. CodeGeeX is pre-trained on 850 billion tokens of 23 programming languages as of June 2022. Our extensive experiments suggest that CodeGeeX outperforms multilingual code models of similar scale for both the tasks of code generation and translation on HumanEval-X. Building upon HumanEval (Python only), we develop the HumanEval-X benchmark for evaluating multilingual models by hand-writing the solutions in C++, Java, JavaScript, and Go. In addition, we build CodeGeeX-based extensions on Visual Studio Code, JetBrains, and Cloud Studio, generating 8 billion tokens for tens of thousands of active users per week. Our user study demonstrates that CodeGeeX can help to increase coding efficiency for 83.4% of its users. Finally, CodeGeeX is publicly accessible since Sep. 2022, we open-sourced its code, model weights, API, extensions, and HumanEval-X at https://github.com/THUDM/CodeGeeX.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3580305.3599790",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:6,deg_w:4,betweenness:0,pagerank:38e-5,eigenvector:5e-4},{id:170,oaid:"b3213c84a6ff7a2f11099de783c93166e4fc02a4",doi:"10.18653/v1/2021.acl-long.254",title:"TAT-QA: A Question Answering Benchmark on a Hybrid of Tabular and Textual Content in Finance",authors:[{name:"Fengbin Zhu",institutions:["National University of Singapore","6Estates PTE. LTD."]},{name:"Wenqiang Lei",institutions:["National University of Singapore"]},{name:"Youcheng Huang",institutions:[]},{name:"Chao Wang",institutions:["6Estates"]},{name:"Shuo Zhang",institutions:[]},{name:"Jiancheng Lv",institutions:[]},{name:"Fuli Feng",institutions:[]},{name:"Tat-seng Chua",institutions:[]}],authorString:"Fengbin Zhu; Wenqiang Lei; Youcheng Huang; Chao Wang; Shuo Zhang; Jiancheng Lv; Fuli Feng; Tat-seng Chua",institutions:["6Estates","6Estates PTE. LTD.","National University of Singapore"],countries:[],year:2021,journal:"Annual Meeting of the Association for Computational Linguistics",citations:584,abstract:"Hybrid data combining both tabular and textual content (e.g., financial reports) are quite pervasive in the real world. However, Question Answering (QA) over such hybrid data is largely neglected in existing research. In this work, we extract samples from real financial reports to build a new large-scale QA dataset containing both Tabular And Textual data, named TAT-QA, where numerical reasoning is usually required to infer the answer, such as addition, subtraction, multiplication, division, counting, comparison/sorting, and the compositions. We further propose a novel QA model termed TAGOP, which is capable of reasoning over both tables and text. It adopts sequence tagging to extract relevant cells from the table along with relevant spans from the text to infer their semantics, and then applies symbolic reasoning over them with a set of aggregation operators to arrive at the final answer. TAGOP achieves 58.0% inF1, which is an 11.1% absolute increase over the previous best baseline model, according to our experiments on TAT-QA. But this result still lags far behind performance of expert human, i.e.90.8% in F1. It is demonstrated that our TAT-QA is very challenging and can serve as a benchmark for training and testing powerful QA models that address hybrid form data.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.acl-long.254.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:5,deg_w:12.5,betweenness:0,pagerank:59e-5,eigenvector:.0017},{id:171,oaid:"98ea4abc9bf0e30eb020db2075c9c8a039a848a3",doi:"10.18653/v1/N16-1181",title:"Learning to Compose Neural Networks for Question Answering",authors:[{name:"Jacob Andreas",institutions:["MIT","Microsoft"]},{name:"Marcus Rohrbach",institutions:["TU Darmstadt"]},{name:"Trevor Darrell",institutions:[]},{name:"D. Klein",institutions:[]}],authorString:"Jacob Andreas; Marcus Rohrbach; Trevor Darrell; D. Klein",institutions:["MIT","Microsoft","TU Darmstadt"],countries:[],year:2016,journal:"North American Chapter of the Association for Computational Linguistics",citations:584,abstract:"We describe a question answering model that applies to both images and structured knowledge bases. The model uses natural language strings to automatically assemble neural networks from a collection of composable modules. Parameters for these modules are learned jointly with network-assembly parameters via reinforcement learning, with only (world, question, answer) triples as supervision. Our approach, which we term a dynamic neural model network, achieves state-of-the-art results on benchmark datasets in both visual and structured domains.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/N16-1181.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:13,community:3,deg_w:51.5,betweenness:.0028,pagerank:.00158,eigenvector:4e-4},{id:172,oaid:"2b5f51588f1c4cdca0865de20c1e2e1ff3570fd1",doi:null,title:"Attend, Infer, Repeat: Fast Scene Understanding with Generative Models",authors:[{name:"S. Eslami",institutions:[]},{name:"N. Heess",institutions:[]},{name:"T. Weber",institutions:[]},{name:"Yuval Tassa",institutions:[]},{name:"David Szepesvari",institutions:[]},{name:"K. Kavukcuoglu",institutions:[]},{name:"Geoffrey E. Hinton",institutions:[]}],authorString:"S. Eslami; N. Heess; T. Weber; Yuval Tassa; David Szepesvari; K. Kavukcuoglu; Geoffrey E. Hinton",institutions:[],countries:[],year:2016,journal:"Neural Information Processing Systems",citations:583,abstract:"We present a framework for efficient inference in structured image models that explicitly reason about objects. We achieve this by performing probabilistic inference using a recurrent neural network that attends to scene elements and processes them one at a time. Crucially, the model itself learns to choose the appropriate number of inference steps. We use this scheme to learn to perform inference in partially specified 2D models (variable-sized variational auto-encoders) and fully specified 3D models (probabilistic renderers). We show that such models learn to identify multiple objects - counting, locating and classifying the elements of a scene - without any supervision, e.g., decomposing 3D images with various numbers of objects in a single forward pass of a neural network. We further show that the networks produce accurate inferences when compared to supervised counterparts, and that their structure leads to improved generalization.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:42,n_refs_in_core:2,degree:15,community:2,deg_w:91,betweenness:.0039,pagerank:.00307,eigenvector:2e-4},{id:173,oaid:"f14c2534c41899a3044f9c19c3c1acd6254e9bb8",doi:"10.1016/b978-0-12-814885-3.00013-0",title:"Extraction",authors:[{name:"S. Ray",institutions:[]},{name:"G. Das",institutions:[]}],authorString:"S. Ray; G. Das",institutions:[],countries:[],year:2020,journal:"Process Equipment and Plant Design",citations:577,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:174,oaid:"73e46a1a4d6c16f4165b8b9e806829e64bbc4738",doi:"10.1111/J.2044-8295.1984.TB01915.X",title:"Heuristic and analytic processes in reasoning",authors:[{name:"Jonathan Evans",institutions:[]}],authorString:"Jonathan Evans",institutions:[],countries:[],year:1984,journal:"",citations:576,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:175,oaid:"e4f5c9d0ab8ea3a91b0f9ffa698fa79c43463115",doi:"10.5555/1756006.1859918",title:"Posterior Regularization for Structured Latent Variable Models",authors:[{name:"Kuzman Ganchev",institutions:[]},{name:"João Graça",institutions:[]},{name:"Jennifer Gillenwater",institutions:[]},{name:"B. Taskar",institutions:[]}],authorString:"Kuzman Ganchev; João Graça; Jennifer Gillenwater; B. Taskar",institutions:[],countries:[],year:2010,journal:"Journal of machine learning research",citations:575,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:61e-5,eigenvector:0},{id:176,oaid:"7cabc21f57b5df93534151df4cc5d09e64db2ad6",doi:"10.3233/EAI-2002-260",title:"E – a brainiac theorem prover",authors:[{name:"S. Schulz",institutions:[]}],authorString:"S. Schulz",institutions:[],countries:[],year:2002,journal:"AI Communications",citations:568,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:6,deg_w:8,betweenness:0,pagerank:52e-5,eigenvector:1e-4},{id:177,oaid:"4df7bbe3ca7806f39a490c99f17867a0ac299bc3",doi:"10.24963/ijcai.2018/792",title:"Learning Explanatory Rules from Noisy Data",authors:[{name:"Richard Evans",institutions:[]},{name:"Edward Grefenstette",institutions:[]}],authorString:"Richard Evans; Edward Grefenstette",institutions:[],countries:[],year:2017,journal:"Journal of Artificial Intelligence Research",citations:562,abstract:"Artificial Neural Networks are powerful function approximators capable of modelling solutions to a wide variety of problems, both supervised and unsupervised. As their size and expressivity increases, so too does the variance of the model, yielding a nearly ubiquitous overfitting problem. Although mitigated by a variety of model regularisation methods, the common cure is to seek large amounts of training data—which is not necessarily easily obtained—that sufficiently approximates the data distribution of the domain we wish to test on. In contrast, logic programming methods such as Inductive Logic Programming offer an extremely data-efficient process by which models can be trained to reason on symbolic domains. However, these methods are unable to deal with the variety of domains neural networks can be applied to: they are not robust to noise in or mislabelling of inputs, and perhaps more importantly, cannot be applied to non-symbolic domains where the data is ambiguous, such as operating on raw pixels. In this paper, we propose a Differentiable Inductive Logic framework (∂ILP), which can not only solve tasks which traditional ILP systems are suited for, but shows a robustness to noise and error in the training data which ILP cannot cope with. Furthermore, as it is trained by backpropagation against a likelihood objective, it can be hybridised by connecting it with neural networks over ambiguous data in order to be applied to domains which ILP cannot address, while providing data efficiency and generalisation beyond what neural networks on their own can achieve.",keywords:[],concepts:[],pdf_url:"https://jair.org/index.php/jair/article/download/11172/26376",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:0,deg_w:18,betweenness:0,pagerank:98e-5,eigenvector:2e-4},{id:178,oaid:"572c12e81319ccd47cc0c637c82efadd03fd05ab",doi:null,title:"Autoregressive Entity Retrieval",authors:[{name:"Nicola De Cao",institutions:["The University of Edinburgh","University of Amsterdam"]},{name:"Gautier Izacard",institutions:[]},{name:"Sebastian Riedel",institutions:[]},{name:"F. Petroni",institutions:[]}],authorString:"Nicola De Cao; Gautier Izacard; Sebastian Riedel; F. Petroni",institutions:["The University of Edinburgh","University of Amsterdam"],countries:[],year:2020,journal:"International Conference on Learning Representations",citations:561,abstract:"Entities are at the center of how we represent and aggregate knowledge. For instance, Encyclopedias such as Wikipedia are structured by entities (e.g., one per article). The ability to retrieve such entities given a query is fundamental for knowledge-intensive tasks such as entity linking and open-domain question answering. One way to understand current approaches is as classifiers among atomic labels, one for each entity. Their weight vectors are dense entity representations produced by encoding entity information such as descriptions. This approach leads to several shortcomings: i) context and entity affinity is mainly captured through a vector dot product, potentially missing fine-grained interactions between the two; ii) a large memory footprint is needed to store dense representations when considering large entity sets; iii) an appropriately hard set of negative data has to be subsampled at training time. We propose GENRE, the first system that retrieves entities by generating their unique names, left to right, token-by-token in an autoregressive fashion, and conditioned on the context. This enables to mitigate the aforementioned technical issues: i) the autoregressive formulation allows us to directly capture relations between context and entity name, effectively cross encoding both; ii) the memory footprint is greatly reduced because the parameters of our encoder-decoder architecture scale with vocabulary size, not entity count; iii) the exact softmax loss can be efficiently computed without the need to subsample negative data. We show the efficacy of the approach with more than 20 datasets on entity disambiguation, end-to-end entity linking and document retrieval tasks, achieving new SOTA, or very competitive results while using a tiny fraction of the memory of competing systems. Finally, we demonstrate that new entities can be added by simply specifying their unambiguous name.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:78,n_refs_in_core:1,degree:19,community:1,deg_w:140,betweenness:.0034,pagerank:.00325,eigenvector:.0561},{id:179,oaid:"2ed575c344e23aa14989b270977b98cec9b39407",doi:null,title:"A Semantic Loss Function for Deep Learning with Symbolic Knowledge",authors:[{name:"Jingyi Xu",institutions:[]},{name:"Zilu Zhang",institutions:[]},{name:"Tal Friedman",institutions:[]},{name:"Yitao Liang",institutions:[]},{name:"Guy Van den Broeck",institutions:["University of California, Los Angeles"]}],authorString:"Jingyi Xu; Zilu Zhang; Tal Friedman; Yitao Liang; Guy Van den Broeck",institutions:["University of California, Los Angeles"],countries:[],year:2017,journal:"International Conference on Machine Learning",citations:556,abstract:"This paper develops a novel methodology for using symbolic knowledge in deep learning. From first principles, we derive a semantic loss function that bridges between neural output vectors and logical constraints. This loss function captures how close the neural network is to satisfying the constraints on its output. An experimental evaluation shows that it effectively guides the learner to achieve (near-)state-of-the-art results on semi-supervised multi-class classification. Moreover, it significantly increases the ability of the neural network to predict structured objects, such as rankings and paths. These discrete concepts are tremendously difficult to learn, and benefit from a tight integration of deep learning and symbolic reasoning methods.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:56,n_refs_in_core:21,degree:36,community:0,deg_w:172.5,betweenness:.0463,pagerank:.00813,eigenvector:.0013},{id:180,oaid:"cf36c0c47e1f1a9bb5285c638bdd77244113bbae",doi:"10.1016/j.tics.2024.01.011",title:"Dissociating language and thought in large language models",authors:[{name:"Kyle Mahowald",institutions:[]},{name:"Anna A. Ivanova",institutions:[]},{name:"I. Blank",institutions:[]},{name:"Nancy Kanwisher",institutions:[]},{name:"Joshua B. Tenenbaum",institutions:[]},{name:"Evelina Fedorenko",institutions:[]}],authorString:"Kyle Mahowald; Anna A. Ivanova; I. Blank; Nancy Kanwisher; Joshua B. Tenenbaum; Evelina Fedorenko",institutions:[],countries:[],year:2024,journal:"Trends in Cognitive Sciences",citations:554,abstract:"Large Language Models (LLMs) have come closest among all models to date to mastering human language, yet opinions about their linguistic and cognitive capabilities remain split. Here, we evaluate LLMs using a distinction between formal linguistic competence—knowledge of linguistic rules and patterns—and functional linguistic competence—understanding and using language in the world. We ground this distinction in human neuroscience, which has shown that formal and functional competence rely on different neural mechanisms. Although LLMs are surprisingly good at formal competence, their performance on functional competence tasks remains spotty and often requires specialized fine-tuning and/or coupling with external modules. We posit that models that use language in humanlike ways would need to master both of these competence types, which, in turn, could require the emergence of mechanisms specialized for formal linguistic competence, distinct from functional competence.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://arxiv.org/pdf/2301.06627",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:181,oaid:"9ac3ab347f66cd3b9bac65c44b6edab924565f4e",doi:"10.1177/1350507615602981",title:"Sapiens: A Brief History of Humankind - A Review",authors:[{name:"Dirk Lindebaum",institutions:[]}],authorString:"Dirk Lindebaum",institutions:[],countries:[],year:2015,journal:"",citations:553,abstract:"",keywords:["History"],concepts:["History"],pdf_url:"https://orca.cardiff.ac.uk/id/eprint/88512/1/Management%20Learning-2015-Lindebaum-636-8.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:57e-5,eigenvector:0},{id:182,oaid:"cf2de559e5a6235783e0762862f6e42192f142a8",doi:"10.1109/ICCV.2017.142",title:"Scene Graph Generation from Objects, Phrases and Region Captions",authors:[{name:"Yikang Li",institutions:[]},{name:"Wanli Ouyang",institutions:["The University of Sydney"]},{name:"Bolei Zhou",institutions:[]},{name:"Kun Wang",institutions:["SenseTime","CUHK"]},{name:"Xiaogang Wang",institutions:[]}],authorString:"Yikang Li; Wanli Ouyang; Bolei Zhou; Kun Wang; Xiaogang Wang",institutions:["CUHK","SenseTime","The University of Sydney"],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:552,abstract:"Object detection, scene graph generation and region captioning, which are three scene understanding tasks at different semantic levels, are tied together: scene graphs are generated on top of objects detected in an image with their pairwise relationship predicted, while region captioning gives a language description of the objects, their attributes, relations and other context information. In this work, to leverage the mutual connections across semantic levels, we propose a novel neural network model, termed as Multi-level Scene Description Network (denoted as MSDN), to solve the three vision tasks jointly in an end-to-end manner. Object, phrase, and caption regions are first aligned with a dynamic graph based on their spatial and semantic connections. Then a feature refining structure is used to pass messages across the three levels of semantic tasks through the graph. We benchmark the learned model on three tasks, and show the joint learning across three tasks with our proposed method can bring mutual improvements over previous models. Particularly, on the scene graph generation task, our proposed method outperforms the stateof- art method with more than 3% margin. Code has been made publicly available.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1707.09700",is_oa:!0,n_refs:51,n_refs_in_core:0,degree:14,community:3,deg_w:142,betweenness:2e-4,pagerank:.00289,eigenvector:.0011},{id:183,oaid:"7345843e87c81e24e42264859b214d26042f8d51",doi:"10.18653/v1/N16-1024",title:"Recurrent Neural Network Grammars",authors:[{name:"Chris Dyer",institutions:[]},{name:"Adhiguna Kuncoro",institutions:[]},{name:"Miguel Ballesteros",institutions:["Oracle"]},{name:"Noah A. Smith",institutions:["University of Washington","Allen Institute for AI"]}],authorString:"Chris Dyer; Adhiguna Kuncoro; Miguel Ballesteros; Noah A. Smith",institutions:["Allen Institute for AI","Oracle","University of Washington"],countries:[],year:2016,journal:"North American Chapter of the Association for Computational Linguistics",citations:551,abstract:"We introduce recurrent neural network grammars, probabilistic models of sentences with explicit phrase structure. We explain efficient inference procedures that allow application to both parsing and language modeling. Experiments show that they provide better parsing in English than any single previously published supervised generative model and better language modeling than state-of-the-art sequential RNNs in English and Chinese.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.aclweb.org/anthology/N16-1024.pdf",is_oa:!0,n_refs:55,n_refs_in_core:1,degree:5,community:5,deg_w:28,betweenness:.0014,pagerank:.00107,eigenvector:4e-4},{id:184,oaid:"4c609f5e6696642996705d07b1f0cd9cc012a49a",doi:"10.1111/J.1468-0149.1988.TB01254.X",title:"Change in View: Principles of Reasoning",authors:[{name:"H. Price",institutions:[]}],authorString:"H. Price",institutions:[],countries:[],year:1988,journal:"",citations:551,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:3,deg_w:4,betweenness:0,pagerank:36e-5,eigenvector:0},{id:185,oaid:"af5c7848417882012203ac21399977ebda695a2b",doi:"10.48550/arXiv.2303.12570",title:"RepoCoder: Repository-Level Code Completion Through Iterative Retrieval and Generation",authors:[{name:"Fengji Zhang",institutions:[]},{name:"B. Chen",institutions:[]},{name:"Yue Zhang",institutions:[]},{name:"Jin Liu",institutions:[]},{name:"Daoguang Zan",institutions:[]},{name:"Yi Mao",institutions:[]},{name:"Jian-Guang Lou",institutions:[]},{name:"Weizhu Chen",institutions:[]}],authorString:"Fengji Zhang; B. Chen; Yue Zhang; Jin Liu; Daoguang Zan; Yi Mao; Jian-Guang Lou; Weizhu Chen",institutions:[],countries:[],year:2023,journal:"Conference on Empirical Methods in Natural Language Processing",citations:543,abstract:"The task of repository-level code completion is to continue writing the unfinished code based on a broader context of the repository. While for automated code completion tools, it is difficult to utilize the useful information scattered in different files. We propose RepoCoder, a simple, generic, and effective framework to address the challenge. It streamlines the repository-level code completion process by incorporating a similarity-based retriever and a pre-trained code language model in an iterative retrieval-generation pipeline. RepoCoder makes effective utilization of repository-level information for code completion and has the ability to generate code at various levels of granularity. Moreover, we propose a new benchmark RepoEval, which consists of the latest and high-quality real-world repositories covering line, API invocation, and function body completion scenarios. Experimental results indicate that RepoCoder significantly improves the In-File completion baseline by over 10% in all settings and consistently outperforms the vanilla retrieval-augmented code completion approach. Furthermore, we validate the effectiveness of RepoCoder through comprehensive analysis, providing valuable insights for future research. Our source code and benchmark are publicly available: https://github.com/microsoft/CodeT/tree/main/RepoCoder",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2303.12570",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:6,deg_w:4,betweenness:0,pagerank:38e-5,eigenvector:5e-4},{id:186,oaid:"b47e96762351b2dbf7e863ece4640df6194bcc0c",doi:"10.48550/arXiv.2310.01061",title:"Reasoning on Graphs: Faithful and Interpretable Large Language Model Reasoning",authors:[{name:"Linhao Luo",institutions:[]},{name:"Yuan-Fang Li",institutions:[]},{name:"Gholamreza Haffari",institutions:[]},{name:"Shirui Pan",institutions:[]}],authorString:"Linhao Luo; Yuan-Fang Li; Gholamreza Haffari; Shirui Pan",institutions:[],countries:[],year:2023,journal:"International Conference on Learning Representations",citations:541,abstract:"Large language models (LLMs) have demonstrated impressive reasoning abilities in complex tasks. However, they lack up-to-date knowledge and experience hallucinations during reasoning, which can lead to incorrect reasoning processes and diminish their performance and trustworthiness. Knowledge graphs (KGs), which capture vast amounts of facts in a structured format, offer a reliable source of knowledge for reasoning. Nevertheless, existing KG-based LLM reasoning methods only treat KGs as factual knowledge bases and overlook the importance of their structural information for reasoning. In this paper, we propose a novel method called reasoning on graphs (RoG) that synergizes LLMs with KGs to enable faithful and interpretable reasoning. Specifically, we present a planning-retrieval-reasoning framework, where RoG first generates relation paths grounded by KGs as faithful plans. These plans are then used to retrieve valid reasoning paths from the KGs for LLMs to conduct faithful reasoning. Furthermore, RoG not only distills knowledge from KGs to improve the reasoning ability of LLMs through training but also allows seamless integration with any arbitrary LLMs during inference. Extensive experiments on two benchmark KGQA datasets demonstrate that RoG achieves state-of-the-art performance on KG reasoning tasks and generates faithful and interpretable reasoning results.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2310.01061",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:187,oaid:"87875a07976c26f82705de1fc70041169e5d652b",doi:"10.48550/arXiv.2306.15626",title:"LeanDojo: Theorem Proving with Retrieval-Augmented Language Models",authors:[{name:"Kaiyu Yang",institutions:[]},{name:"Aidan M. Swope",institutions:[]},{name:"Alex Gu",institutions:[]},{name:"Rahul Chalamala",institutions:[]},{name:"Peiyang Song",institutions:[]},{name:"Shixing Yu",institutions:[]},{name:"Saad Godil",institutions:[]},{name:"R. Prenger",institutions:[]},{name:"Anima Anandkumar",institutions:[]}],authorString:"Kaiyu Yang; Aidan M. Swope; Alex Gu; Rahul Chalamala; Peiyang Song; Shixing Yu; Saad Godil; R. Prenger; Anima Anandkumar",institutions:[],countries:[],year:2023,journal:"Neural Information Processing Systems",citations:540,abstract:"Large language models (LLMs) have shown promise in proving formal theorems using proof assistants such as Lean. However, existing methods are difficult to reproduce or build on, due to private code, data, and large compute requirements. This has created substantial barriers to research on machine learning methods for theorem proving. This paper removes these barriers by introducing LeanDojo: an open-source Lean playground consisting of toolkits, data, models, and benchmarks. LeanDojo extracts data from Lean and enables interaction with the proof environment programmatically. It contains fine-grained annotations of premises in proofs, providing valuable data for premise selection: a key bottleneck in theorem proving. Using this data, we develop ReProver (Retrieval-Augmented Prover): an LLM-based prover augmented with retrieval for selecting premises from a vast math library. It is inexpensive and needs only one GPU week of training. Our retriever leverages LeanDojo's program analysis capability to identify accessible premises and hard negative examples, which makes retrieval much more effective. Furthermore, we construct a new benchmark consisting of 98,734 theorems and proofs extracted from Lean's math library. It features challenging data split requiring the prover to generalize to theorems relying on novel premises that are never used in training. We use this benchmark for training and evaluation, and experimental results demonstrate the effectiveness of ReProver over non-retrieval baselines and GPT-4. We thus provide the first set of open-source LLM-based theorem provers without any proprietary datasets and release it under a permissive MIT license to facilitate further research.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2306.15626",is_oa:!0,n_refs:102,n_refs_in_core:44,degree:54,community:6,deg_w:349,betweenness:.0629,pagerank:.01116,eigenvector:.0316},{id:188,oaid:"d0e7319b3a06468995d193c0276ec89dbc032388",doi:"10.1017/CBO9780511623714.011",title:"Designs, graphs, codes, and their links",authors:[{name:"P. Cameron",institutions:[]},{name:"J. H. Lint",institutions:[]}],authorString:"P. Cameron; J. H. Lint",institutions:[],countries:[],year:1991,journal:"",citations:534,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:8,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:189,oaid:"710d183174844da5b7f392667f3cc25d2b098dde",doi:"10.18653/v1/D19-1282",title:"KagNet: Knowledge-Aware Graph Networks for Commonsense Reasoning",authors:[{name:"Bill Yuchen Lin",institutions:["Allen Institute for AI (AI2)"]},{name:"Xinyue Chen",institutions:["Carnegie Mellon University"]},{name:"Jamin Chen",institutions:[]},{name:"Xiang Ren",institutions:["University of Southern California"]}],authorString:"Bill Yuchen Lin; Xinyue Chen; Jamin Chen; Xiang Ren",institutions:["Allen Institute for AI (AI2)","Carnegie Mellon University","University of Southern California"],countries:[],year:2019,journal:"Conference on Empirical Methods in Natural Language Processing",citations:530,abstract:"Commonsense reasoning aims to empower machines with the human ability to make presumptions about ordinary situations in our daily life. In this paper, we propose a textual inference framework for answering commonsense questions, which effectively utilizes external, structured commonsense knowledge graphs to perform explainable inferences. The framework first grounds a question-answer pair from the semantic space to the knowledge-based symbolic space as a schema graph, a related sub-graph of external knowledge graphs. It represents schema graphs with a novel knowledge-aware graph network module named KagNet, and finally scores answers with graph representations. Our model is based on graph convolutional networks and LSTMs, with a hierarchical path-based attention mechanism. The intermediate attention scores make it transparent and interpretable, which thus produce trustworthy inferences. Using ConceptNet as the only external resource for Bert-based models, we achieved state-of-the-art performance on the CommonsenseQA, a large-scale dataset for commonsense reasoning.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D19-1282.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:8,community:1,deg_w:36,betweenness:.0053,pagerank:.00112,eigenvector:.0204},{id:190,oaid:"2bdbb07bc12b8d8c332b7a84aa05e76218c07cd9",doi:"10.18653/v1/N16-1136",title:"MAWPS: A Math Word Problem Repository",authors:[{name:"Rik Koncel-Kedziorski",institutions:[]},{name:"Subhro Roy",institutions:[]},{name:"Aida Amini",institutions:["University of Washington"]},{name:"Nate Kushman",institutions:[]},{name:"Hannaneh Hajishirzi",institutions:[]}],authorString:"Rik Koncel-Kedziorski; Subhro Roy; Aida Amini; Nate Kushman; Hannaneh Hajishirzi",institutions:["University of Washington"],countries:[],year:2016,journal:"North American Chapter of the Association for Computational Linguistics",citations:528,abstract:"Recent work across several AI subdisciplines has focused on automatically solving math word problems. In this paper we introduce MAWPS, an online repository of Math Word Problems, to provide a unified testbed to evaluate different algorithms. MAWPS allows for the automatic construction of datasets with particular characteristics, providing tools for tuning the lexical and template overlap of a dataset as well as for filtering ungrammatical problems from web-sourced corpora. The online nature of this repository facilitates easy community contribution. At present, we have amassed 3,320 problems, including the full datasets used in several prominent works.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/N16-1136.pdf",is_oa:!0,n_refs:16,n_refs_in_core:3,degree:9,community:5,deg_w:42,betweenness:5e-4,pagerank:.00157,eigenvector:.0025},{id:191,oaid:"2bf2c3598f1ee3a2fa22185cb2aaeb425de004ad",doi:"10.1145/2701413",title:"Commonsense reasoning and commonsense knowledge in artificial intelligence",authors:[{name:"E. Davis",institutions:[]},{name:"G. Marcus",institutions:[]}],authorString:"E. Davis; G. Marcus",institutions:[],countries:[],year:2015,journal:"Communications of the ACM",citations:525,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:2,deg_w:12,betweenness:.0019,pagerank:62e-5,eigenvector:.0015},{id:192,oaid:"05cf65bea06b26d11a6324113bb4d6219e495a7b",doi:"10.24963/ijcai.2018/643",title:"Commonsense Knowledge Aware Conversation Generation with Graph Attention",authors:[{name:"Hao Zhou",institutions:["Tsinghua University"]},{name:"Tom Young",institutions:[]},{name:"Minlie Huang",institutions:["Tsinghua University"]},{name:"Haizhou Zhao",institutions:[]},{name:"Jingfang Xu",institutions:[]},{name:"Xiaoyan Zhu",institutions:[]}],authorString:"Hao Zhou; Tom Young; Minlie Huang; Haizhou Zhao; Jingfang Xu; Xiaoyan Zhu",institutions:["Tsinghua University"],countries:[],year:2018,journal:"International Joint Conference on Artificial Intelligence",citations:524,abstract:"Commonsense knowledge is vital to many natural language processing tasks. In this paper, we present a novel open-domain conversation generation model to demonstrate how large-scale commonsense knowledge can facilitate language understanding and generation. Given a user post, the model retrieves relevant knowledge graphs from a knowledge base and then encodes the graphs with a static graph attention mechanism, which augments the semantic information of the post and thus supports better understanding of the post. Then, during word generation, the model attentively reads the retrieved knowledge graphs and the knowledge triples within each graph to facilitate better generation through a dynamic graph attention mechanism. This is the first attempt that uses large-scale commonsense knowledge in conversation generation. Furthermore, unlike existing models that use knowledge triples (entities) separately and independently, our model treats each knowledge graph as a whole, which encodes more structured, connected semantic information in the graphs. Experiments show that the proposed model can generate more appropriate and informative responses than state-of-the-art baselines.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2018/0643.pdf",is_oa:!0,n_refs:27,n_refs_in_core:0,degree:5,community:1,deg_w:27,betweenness:8e-4,pagerank:85e-5,eigenvector:.0133},{id:193,oaid:"afed6dc6900d3b37e528b9086661bba583d60bf6",doi:null,title:"Analysing Mathematical Reasoning Abilities of Neural Models",authors:[{name:"D. Saxton",institutions:[]},{name:"Edward Grefenstette",institutions:[]},{name:"Felix Hill",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"D. Saxton; Edward Grefenstette; Felix Hill; Pushmeet Kohli",institutions:[],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:524,abstract:"Mathematical reasoning---a core ability within human intelligence---presents some unique challenges as a domain: we do not come to understand and solve mathematical problems primarily on the back of experience and evidence, but on the basis of inferring, learning, and exploiting laws, axioms, and symbol manipulation rules. In this paper, we present a new challenge for the evaluation (and eventually the design) of neural architectures and similar system, developing a task suite of mathematics problems involving sequential questions and answers in a free-form textual input/output format. The structured nature of the mathematics domain, covering arithmetic, algebra, probability and calculus, enables the construction of training and test splits designed to clearly illuminate the capabilities and failure-modes of different architectures, as well as evaluate their ability to compose and relate knowledge and learned processes. Having described the data generation process and its potential future expansions, we conduct a comprehensive analysis of models from two broad classes of the most powerful sequence-to-sequence architectures and find notable differences in their ability to resolve mathematical problems and generalize their knowledge.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:29,n_refs_in_core:5,degree:26,community:2,deg_w:135,betweenness:.0406,pagerank:.00433,eigenvector:.0041},{id:194,oaid:"3896d833f428bb483e15de1a584da4f2348797e6",doi:"10.1016/S0004-3702(02)00186-8",title:"Answer set programming and plan generation",authors:[{name:"V. Lifschitz",institutions:[]}],authorString:"V. Lifschitz",institutions:[],countries:[],year:2002,journal:"Artificial Intelligence",citations:519,abstract:"",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1016/s0004-3702(02)00186-8",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:195,oaid:"fe257027193ea4a74fdab99d7509ce4002ad7de6",doi:null,title:"Learning a SAT Solver from Single-Bit Supervision",authors:[{name:"Daniel Selsam",institutions:[]},{name:"Matthew Lamm",institutions:[]},{name:"Benedikt Bünz",institutions:[]},{name:"Percy Liang",institutions:[]},{name:"L. D. Moura",institutions:[]},{name:"D. Dill",institutions:[]}],authorString:"Daniel Selsam; Matthew Lamm; Benedikt Bünz; Percy Liang; L. D. Moura; D. Dill",institutions:[],countries:[],year:2018,journal:"International Conference on Learning Representations",citations:518,abstract:"We present NeuroSAT, a message passing neural network that learns to solve SAT problems after only being trained as a classifier to predict satisfiability. Although it is not competitive with state-of-the-art SAT solvers, NeuroSAT can solve problems that are substantially larger and more difficult than it ever saw during training by simply running for more iterations. Moreover, NeuroSAT generalizes to novel distributions; after training only on random SAT problems, at test time it can solve SAT problems encoding graph coloring, clique detection, dominating set, and vertex cover problems, all on a range of distributions over small random graphs.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:29,n_refs_in_core:0,degree:10,community:6,deg_w:46.5,betweenness:.0033,pagerank:.00149,eigenvector:.002},{id:196,oaid:"f40d7336f4c42fbb93cea65317a8ce6c6a3762a5",doi:"10.7551/mitpress/4298.003.0069",title:"A Statistical Learning Method for Logic Programs with Distribution Semantics",authors:[{name:"Taisuke Sato",institutions:[]}],authorString:"Taisuke Sato",institutions:[],countries:[],year:1995,journal:"International Conference on Logic Programming",citations:514,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:197,oaid:"de8cee69a45fca54b5efcecdab91c883c632a82e",doi:"10.1126/science.aax6239",title:"Dendritic action potentials and computation in human layer 2/3 cortical neurons",authors:[{name:"A. Gidon",institutions:[]},{name:"T. Zolnik",institutions:[]},{name:"Pawel Fidzinski",institutions:[]},{name:"Felix Bolduan",institutions:[]},{name:"Athanasia Papoutsi",institutions:[]},{name:"Panayiota Poirazi",institutions:["Foundation for Research and Technology-Hellas"]},{name:"M. Holtkamp",institutions:[]},{name:"I. Vida",institutions:[]},{name:"M. Larkum",institutions:[]}],authorString:"A. Gidon; T. Zolnik; Pawel Fidzinski; Felix Bolduan; Athanasia Papoutsi; Panayiota Poirazi; M. Holtkamp; I. Vida; M. Larkum",institutions:["Foundation for Research and Technology-Hellas"],countries:[],year:2020,journal:"Science",citations:510,abstract:"Human dendrites are special A special developmental program in the human brain drives the disproportionate thickening of cortical layer 2/3. This suggests that the expansion of layer 2/3, along with its numerous neurons and their large dendrites, may contribute to what makes us human. Gidon et al. thus investigated the dendritic physiology of layer 2/3 pyramidal neurons in slices taken from surgically resected brain tissue in epilepsy patients. Dual somatodendritic recordings revealed previously unknown classes of action potentials in the dendrites of these neurons, which make their activity far more complex than has been previously thought. These action potentials allow single neurons to solve two long-standing computational problems in neuroscience that were considered to require multilayer neural networks. Science, this issue p. 83 Dendritic action potentials extend the repertoire of computations available to human neurons. The active electrical properties of dendrites shape neuronal input and output and are fundamental to brain function. However, our knowledge of active dendrites has been almost entirely acquired from studies of rodents. In this work, we investigated the dendrites of layer 2 and 3 (L2/3) pyramidal neurons of the human cerebral cortex ex vivo. In these neurons, we discovered a class of calcium-mediated dendritic action potentials (dCaAPs) whose waveform and effects on neuronal output have not been previously described. In contrast to typical all-or-none action potentials, dCaAPs were graded; their amplitudes were maximal for threshold-level stimuli but dampened for stronger stimuli. These dCaAPs enabled the dendrites of individual human neocortical pyramidal neurons to classify linearly nonseparable inputs—a computation conventionally thought to require multilayered networks.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:65e-5,eigenvector:0},{id:198,oaid:"ccb1ccc4deacc4fb18000f0e1ce24329548963ae",doi:"10.48550/arXiv.2302.01560",title:"Describe, Explain, Plan and Select: Interactive Planning with Large Language Models Enables Open-World Multi-Task Agents",authors:[{name:"Zihao Wang",institutions:["Peking University"]},{name:"Shaofei Cai",institutions:["Peking University"]},{name:"Anji Liu",institutions:["National University of Singapore"]},{name:"Xiaojian Ma",institutions:[]},{name:"Yitao Liang",institutions:["University of California, Los Angeles"]}],authorString:"Zihao Wang; Shaofei Cai; Anji Liu; Xiaojian Ma; Yitao Liang",institutions:["National University of Singapore","Peking University","University of California, Los Angeles"],countries:[],year:2023,journal:"arXiv.org",citations:508,abstract:`We investigate the challenge of task planning for multi-task embodied agents in open-world environments. Two main difficulties are identified: 1) executing plans in an open-world environment (e.g., Minecraft) necessitates accurate and multi-step reasoning due to the long-term nature of tasks, and 2) as vanilla planners do not consider how easy the current agent can achieve a given sub-task when ordering parallel sub-goals within a complicated plan, the resulting plan could be inefficient or even infeasible. To this end, we propose"$\\underline{D}$escribe, $\\underline{E}$xplain, $\\underline{P}$lan and $\\underline{S}$elect"($\\textbf{DEPS}$), an interactive planning approach based on Large Language Models (LLMs). DEPS facilitates better error correction on initial LLM-generated $\\textit{plan}$ by integrating $\\textit{description}$ of the plan execution process and providing self-$\\textit{explanation}$ of feedback when encountering failures during the extended planning phases. Furthermore, it includes a goal $\\textit{selector}$, which is a trainable module that ranks parallel candidate sub-goals based on the estimated steps of completion, consequently refining the initial plan. Our experiments mark the milestone of the first zero-shot multi-task agent that can robustly accomplish 70+ Minecraft tasks and nearly double the overall performances. Further testing reveals our method's general effectiveness in popularly adopted non-open-ended domains as well (i.e., ALFWorld and tabletop manipulation). The ablation and exploratory studies detail how our design beats the counterparts and provide a promising update on the $\\texttt{ObtainDiamond}$ grand challenge with our approach. The code is released at https://github.com/CraftJarvis/MC-Planner.`,keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2302.01560",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:199,oaid:"d6a7a563640bf53953c4fda0997e4db176488510",doi:"10.1109/ICCV.2013.337",title:"YouTube2Text: Recognizing and Describing Arbitrary Activities Using Semantic Hierarchies and Zero-Shot Recognition",authors:[{name:"S. Guadarrama",institutions:[]},{name:"N. Krishnamoorthy",institutions:[]},{name:"Girish Malkarnenkar",institutions:[]},{name:"Subhashini Venugopalan",institutions:["UT Austin, Google"]},{name:"R. Mooney",institutions:[]},{name:"Trevor Darrell",institutions:[]},{name:"Kate Saenko",institutions:[]}],authorString:"S. Guadarrama; N. Krishnamoorthy; Girish Malkarnenkar; Subhashini Venugopalan; R. Mooney; Trevor Darrell; Kate Saenko",institutions:["UT Austin, Google"],countries:[],year:2013,journal:"IEEE International Conference on Computer Vision",citations:506,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:12.5,betweenness:0,pagerank:52e-5,eigenvector:1e-4},{id:200,oaid:"119601712acbe6ee133a1744f0970190c4195519",doi:"10.48550/arXiv.2307.07697",title:"Think-on-Graph: Deep and Responsible Reasoning of Large Language Model with Knowledge Graph",authors:[{name:"Jiashuo Sun",institutions:["DAMO Academy, Alibaba Group"]},{name:"Chengjin Xu",institutions:[]},{name:"Lumingyuan Tang",institutions:[]},{name:"Sai Wang",institutions:[]},{name:"Chen Lin",institutions:[]},{name:"Yeyun Gong",institutions:[]},{name:"H. Shum",institutions:[]},{name:"Jian Guo",institutions:[]}],authorString:"Jiashuo Sun; Chengjin Xu; Lumingyuan Tang; Sai Wang; Chen Lin; Yeyun Gong; H. Shum; Jian Guo",institutions:["DAMO Academy, Alibaba Group"],countries:[],year:2023,journal:"arXiv.org",citations:503,abstract:"",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2307.07697",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:201,oaid:"fe5bec4083e00764146df9f0191790cc72d972b9",doi:"10.18653/v1/2020.acl-main.577",title:"Named Entity Recognition as Dependency Parsing",authors:[{name:"Juntao Yu",institutions:["Queen Mary Univerity of London"]},{name:"Bernd Bohnet",institutions:["Google Research"]},{name:"Massimo Poesio",institutions:[]}],authorString:"Juntao Yu; Bernd Bohnet; Massimo Poesio",institutions:["Google Research","Queen Mary Univerity of London"],countries:[],year:2020,journal:"Annual Meeting of the Association for Computational Linguistics",citations:503,abstract:"Named Entity Recognition (NER) is a fundamental task in Natural Language Processing, concerned with identifying spans of text expressing references to entities. NER research is often focused on flat entities only (flat NER), ignoring the fact that entity references can be nested, as in [Bank of [China]] (Finkel and Manning, 2009). In this paper, we use ideas from graph-based dependency parsing to provide our model a global view on the input via a biaffine model (Dozat and Manning, 2017). The biaffine model scores pairs of start and end tokens in a sentence which we use to explore all spans, so that the model is able to predict named entities accurately. We show that the model works well for both nested and flat NER through evaluation on 8 corpora and achieving SoTA performance on all of them, with accuracy gains of up to 2.2 percentage points.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.577.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:202,oaid:"97d69e7e8c04714bf58dcbe5ae7454db69b657a7",doi:null,title:"The Next Decade in AI: Four Steps Towards Robust Artificial Intelligence",authors:[{name:"G. Marcus",institutions:[]}],authorString:"G. Marcus",institutions:[],countries:[],year:2020,journal:"arXiv.org",citations:503,abstract:"Recent research in artificial intelligence and machine learning has largely emphasized general-purpose learning and ever-larger training sets and more and more compute. In contrast, I propose a hybrid, knowledge-driven, reasoning-based approach, centered around cognitive models, that could provide the substrate for a richer, more robust AI than is currently possible.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:105,n_refs_in_core:43,degree:53,community:2,deg_w:257.5,betweenness:.0857,pagerank:.01418,eigenvector:.001},{id:203,oaid:"58cb0c24c936b8a14ca7b2d56ba80de733c545b3",doi:"10.18653/v1/D16-1092",title:"Human Attention in Visual Question Answering: Do Humans and Deep Networks look at the same regions?",authors:[{name:"Abhishek Das",institutions:["FAIR, Meta AI"]},{name:"Harsh Agrawal",institutions:["Apple","Georgia Institute of Technology"]},{name:"C. L. Zitnick",institutions:[]},{name:"Devi Parikh",institutions:[]},{name:"Dhruv Batra",institutions:[]}],authorString:"Abhishek Das; Harsh Agrawal; C. L. Zitnick; Devi Parikh; Dhruv Batra",institutions:["Apple","FAIR, Meta AI","Georgia Institute of Technology"],countries:[],year:2016,journal:"Conference on Empirical Methods in Natural Language Processing",citations:502,abstract:"We conduct large-scale studies on `human attention' in Visual Question Answering (VQA) to understand where humans choose to look to answer questions about images. We design and test multiple game-inspired novel attention-annotation interfaces that require the subject to sharpen regions of a blurred image to answer a question. Thus, we introduce the VQA-HAT (Human ATtention) dataset. We evaluate attention maps generated by state-of-the-art VQA models against human attention both qualitatively (via visualizations) and quantitatively (via rank-order correlation). Overall, our experiments show that current attention models in VQA do not seem to be looking at the same regions as humans.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D16-1092.pdf",is_oa:!0,n_refs:40,n_refs_in_core:4,degree:21,community:3,deg_w:154.5,betweenness:5e-4,pagerank:.00321,eigenvector:.0013},{id:204,oaid:"b39eed03d345f5c244eac12fd1315d26eba77d62",doi:null,title:"Deep Learning for Symbolic Mathematics",authors:[{name:"Guillaume Lample",institutions:[]},{name:"François Charton",institutions:[]}],authorString:"Guillaume Lample; François Charton",institutions:[],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:500,abstract:"Neural networks have a reputation for being better at solving statistical or approximate problems than at performing calculations or working with symbolic data. In this paper, we show that they can be surprisingly good at more elaborated tasks in mathematics, such as symbolic integration and solving differential equations. We propose a syntax for representing these mathematical problems, and methods for generating large datasets that can be used to train sequence-to-sequence models. We achieve results that outperform commercial Computer Algebra Systems such as Matlab or Mathematica.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:6,deg_w:20.5,betweenness:.0024,pagerank:96e-5,eigenvector:.0016},{id:205,oaid:"e6566ece21f6637c515fe9969f9d1ec6cca6d36c",doi:"10.18653/v1/N18-2108",title:"Higher-Order Coreference Resolution with Coarse-to-Fine Inference",authors:[{name:"Kenton Lee",institutions:[]},{name:"Luheng He",institutions:[]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]}],authorString:"Kenton Lee; Luheng He; Luke Zettlemoyer",institutions:["Facebook","University of Washington"],countries:[],year:2018,journal:"North American Chapter of the Association for Computational Linguistics",citations:498,abstract:"We introduce a fully-differentiable approximation to higher-order inference for coreference resolution. Our approach uses the antecedent distribution from a span-ranking architecture as an attention mechanism to iteratively refine span representations. This enables the model to softly consider multiple hops in the predicted clusters. To alleviate the computational cost of this iterative process, we introduce a coarse-to-fine approach that incorporates a less accurate but more efficient bilinear factor, enabling more aggressive pruning without hurting accuracy. Compared to the existing state-of-the-art span-ranking approach, our model significantly improves accuracy on the English OntoNotes benchmark, while being far more computationally efficient.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/N18-2108.pdf",is_oa:!0,n_refs:17,n_refs_in_core:0,degree:3,community:1,deg_w:37.5,betweenness:0,pagerank:.0012,eigenvector:.0095},{id:206,oaid:"53e4ab9730e983242a3409c7bf1af945041a6563",doi:"10.1109/ICCV.2013.178",title:"NEIL: Extracting Visual Knowledge from Web Data",authors:[{name:"Xinlei Chen",institutions:[]},{name:"Abhinav Shrivastava",institutions:["University of Maryland, College Park"]},{name:"A. Gupta",institutions:[]}],authorString:"Xinlei Chen; Abhinav Shrivastava; A. Gupta",institutions:["University of Maryland, College Park"],countries:[],year:2013,journal:"IEEE International Conference on Computer Vision",citations:497,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:3,deg_w:16.5,betweenness:.0045,pagerank:64e-5,eigenvector:.0057},{id:207,oaid:"f13e41d24e5d0a68ca662c1b49de398a6fb68251",doi:"10.18653/v1/2020.acl-main.92",title:"A Diverse Corpus for Evaluating and Developing English Math Word Problem Solvers",authors:[{name:"Shen-Yun Miao",institutions:[]},{name:"Chao-Chun Liang",institutions:["Institute of Information Science, Academia Sinica"]},{name:"Keh-Yih Su",institutions:[]}],authorString:"Shen-Yun Miao; Chao-Chun Liang; Keh-Yih Su",institutions:["Institute of Information Science, Academia Sinica"],countries:[],year:2020,journal:"Annual Meeting of the Association for Computational Linguistics",citations:493,abstract:"We present ASDiv (Academia Sinica Diverse MWP Dataset), a diverse (in terms of both language patterns and problem types) English math word problem (MWP) corpus for evaluating the capability of various MWP solvers. Existing MWP corpora for studying AI progress remain limited either in language usage patterns or in problem types. We thus present a new English MWP corpus with 2,305 MWPs that cover more text patterns and most problem types taught in elementary school. Each MWP is annotated with its problem type and grade level (for indicating the level of difficulty). Furthermore, we propose a metric to measure the lexicon usage diversity of a given MWP corpus, and demonstrate that ASDiv is more diverse than existing corpora. Experiments show that our proposed corpus reflects the true capability of MWP solvers more faithfully.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.92.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:5,deg_w:9,betweenness:0,pagerank:53e-5,eigenvector:5e-4},{id:208,oaid:"03de0b6cb973fc6d7f32a0a38de5deb2db3420c3",doi:"10.1386/padm.2.2.139_1",title:"Thinking movement and the creation of dance through numbers",authors:[{name:"S. Portanova",institutions:[]}],authorString:"S. Portanova",institutions:[],countries:[],year:2006,journal:"",citations:487,abstract:"",keywords:["Sociology","Philosophy"],concepts:["Sociology","Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:62e-5,eigenvector:1e-4},{id:209,oaid:"a7862e14b4c20cefd6dc4f611f8aa866fabf130b",doi:"10.3115/v1/D14-1058",title:"Learning to Solve Arithmetic Word Problems with Verb Categorization",authors:[{name:"Mohammad Javad Hosseini",institutions:["University of Edinburgh"]},{name:"Hannaneh Hajishirzi",institutions:[]},{name:"Oren Etzioni",institutions:[]},{name:"Nate Kushman",institutions:[]}],authorString:"Mohammad Javad Hosseini; Hannaneh Hajishirzi; Oren Etzioni; Nate Kushman",institutions:["University of Edinburgh"],countries:[],year:2014,journal:"Conference on Empirical Methods in Natural Language Processing",citations:486,abstract:"This paper presents a novel approach to learning to solve simple arithmetic word problems. Our system, ARIS, analyzes each of the sentences in the problem statement to identify the relevant variables and their values. ARIS then maps this information into an equation that represents the problem, and enables its (trivial) solution as shown in Figure 1. The paper analyzes the arithmetic-word problems “genre”, identifying seven categories of verbs used in such problems. ARIS learns to categorize verbs with 81.2% accuracy, and is able to solve 77.7% of the problems in a corpus of standard primary school test questions. We report the first learning results on this task without reliance on predefined templates and make our data publicly available. 1",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/D14-1058.pdf",is_oa:!0,n_refs:35,n_refs_in_core:0,degree:4,community:5,deg_w:17.5,betweenness:1e-4,pagerank:76e-5,eigenvector:.001},{id:210,oaid:"49f58b64635446badc73ef8e665aa74e0f6f158a",doi:"10.1016/j.artint.2007.11.002",title:"On probabilistic inference by weighted model counting",authors:[{name:"M. Chavira",institutions:[]},{name:"Adnan Darwiche",institutions:["UCLA"]}],authorString:"M. Chavira; Adnan Darwiche",institutions:["UCLA"],countries:[],year:2008,journal:"Artificial Intelligence",citations:486,abstract:"",keywords:[],concepts:[],pdf_url:"https://www.sciencedirect.com/science/article/pii/S0004370207001889/pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:43e-5,eigenvector:0},{id:211,oaid:"cde902f11b0870c695428d865a35eb819b1d24b7",doi:"10.1162/tacl_a_00209",title:"Weakly Supervised Learning of Semantic Parsers for Mapping Instructions to Actions",authors:[{name:"Yoav Artzi",institutions:["Cornell University"]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]}],authorString:"Yoav Artzi; Luke Zettlemoyer",institutions:["Cornell University","Facebook","University of Washington"],countries:[],year:2013,journal:"Transactions of the Association for Computational Linguistics",citations:485,abstract:"The context in which language is used provides a strong signal for learning to recover its meaning. In this paper, we show it can be used within a grounded CCG semantic parsing approach that learns a joint model of meaning and context for interpreting and executing natural language instructions, using various types of weak supervision. The joint nature provides crucial benefits by allowing situated cues, such as the set of visible objects, to directly influence learning. It also enables algorithms that learn while executing instructions, for example by trying to replicate human actions. Experiments on a benchmark navigational dataset demonstrate strong performance under differing forms of supervision, including correctly executing 60% more instruction sets relative to the previous state of the art.",keywords:[],concepts:[],pdf_url:"http://www.mitpressjournals.org/doi/pdf/10.1162/tacl_a_00209",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:9,community:4,deg_w:36,betweenness:7e-4,pagerank:.00113,eigenvector:5e-4},{id:212,oaid:"5fe0a4af3bd1479d5e39fbda2215c86bce54722b",doi:null,title:"Generative Language Modeling for Automated Theorem Proving",authors:[{name:"Stanislas Polu",institutions:[]},{name:"I. Sutskever",institutions:[]}],authorString:"Stanislas Polu; I. Sutskever",institutions:[],countries:[],year:2020,journal:"arXiv.org",citations:484,abstract:"We explore the application of transformer-based language models to automated theorem proving. This work is motivated by the possibility that a major limitation of automated theorem provers compared to humans -- the generation of original mathematical terms -- might be addressable via generation from language models. We present an automated prover and proof assistant, GPT-f, for the Metamath formalization language, and analyze its performance. GPT-f found new short proofs that were accepted into the main Metamath library, which is to our knowledge, the first time a deep-learning based system has contributed proofs that were adopted by a formal mathematics community.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:10,community:6,deg_w:36.5,betweenness:7e-4,pagerank:.00135,eigenvector:.0026},{id:213,oaid:"924a0f0b1cfcb0d1f8f4ac232e91fe19307861cb",doi:"10.1007/978-3-319-10590-1_4",title:"Large-Scale Object Classification Using Label Relation Graphs",authors:[{name:"Jia Deng",institutions:[]},{name:"Nan Ding",institutions:[]},{name:"Yangqing Jia",institutions:[]},{name:"Andrea Frome",institutions:[]},{name:"K. Murphy",institutions:[]},{name:"Samy Bengio",institutions:["Apple"]},{name:"Yuan Li",institutions:[]},{name:"H. Neven",institutions:[]},{name:"Hartwig Adam",institutions:["Google DeepMind"]}],authorString:"Jia Deng; Nan Ding; Yangqing Jia; Andrea Frome; K. Murphy; Samy Bengio; Yuan Li; H. Neven; Hartwig Adam",institutions:["Apple","Google DeepMind"],countries:[],year:2014,journal:"European Conference on Computer Vision",citations:482,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8,betweenness:1e-4,pagerank:51e-5,eigenvector:0},{id:214,oaid:"f5c73d9e6641b018b633690102121f5605d34fb0",doi:"10.48550/arXiv.2305.13172",title:"Editing Large Language Models: Problems, Methods, and Opportunities",authors:[{name:"Yunzhi Yao",institutions:["Zhejiang University;Shandong University"]},{name:"Peng Wang",institutions:[]},{name:"Bo Tian",institutions:[]},{name:"Siyuan Cheng",institutions:[]},{name:"Zhoubo Li",institutions:[]},{name:"Shumin Deng",institutions:[]},{name:"Huajun Chen",institutions:[]},{name:"Ningyu Zhang",institutions:["Zhejiang University"]}],authorString:"Yunzhi Yao; Peng Wang; Bo Tian; Siyuan Cheng; Zhoubo Li; Shumin Deng; Huajun Chen; Ningyu Zhang",institutions:["Zhejiang University","Zhejiang University;Shandong University"],countries:[],year:2023,journal:"Conference on Empirical Methods in Natural Language Processing",citations:482,abstract:"Despite the ability to train capable LLMs, the methodology for maintaining their relevancy and rectifying errors remains elusive. To this end, the past few years have witnessed a surge in techniques for editing LLMs, the objective of which is to efficiently alter the behavior of LLMs within a specific domain without negatively impacting performance across other inputs. This paper embarks on a deep exploration of the problems, methods, and opportunities related to model editing for LLMs. In particular, we provide an exhaustive overview of the task definition and challenges associated with model editing, along with an in-depth empirical analysis of the most progressive methods currently at our disposal. We also build a new benchmark dataset to facilitate a more robust evaluation and pinpoint enduring issues intrinsic to existing techniques. Our objective is to provide valuable insights into the effectiveness and feasibility of each editing technique, thereby assisting the community in making informed decisions on the selection of the most appropriate method for a specific task or context. Code and datasets are available at https://github.com/zjunlp/EasyEdit.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://arxiv.org/pdf/2305.13172",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:215,oaid:"fddbcabe0fc9be0684855ae3dd059fb525a69e5b",doi:null,title:"Simple BERT Models for Relation Extraction and Semantic Role Labeling",authors:[{name:"Peng Shi",institutions:["University of Waterloo"]},{name:"Jimmy J. Lin",institutions:[]}],authorString:"Peng Shi; Jimmy J. Lin",institutions:["University of Waterloo"],countries:[],year:2019,journal:"arXiv.org",citations:482,abstract:"We present simple BERT-based models for relation extraction and semantic role labeling. In recent years, state-of-the-art performance has been achieved using neural models by incorporating lexical and syntactic features such as part-of-speech tags and dependency trees. In this paper, extensive experiments on datasets for these two tasks show that without using any external features, a simple BERT-based model can achieve state-of-the-art performance. To our knowledge, we are the first to successfully apply BERT in this manner. Our models provide strong baselines for future research.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:23,n_refs_in_core:1,degree:6,community:1,deg_w:30.5,betweenness:1e-4,pagerank:.001,eigenvector:.0266},{id:216,oaid:"829e36b23f7b42e109f84b5b761052498b291962",doi:"10.18653/v1/2020.aacl-main.46",title:"A Survey of the State of Explainable AI for Natural Language Processing",authors:[{name:"Marina Danilevsky",institutions:["IBM Research"]},{name:"Kun Qian",institutions:[]},{name:"R. Aharonov",institutions:[]},{name:"Yannis Katsis",institutions:[]},{name:"B. Kawas",institutions:[]},{name:"Prithviraj Sen",institutions:[]}],authorString:"Marina Danilevsky; Kun Qian; R. Aharonov; Yannis Katsis; B. Kawas; Prithviraj Sen",institutions:["IBM Research"],countries:[],year:2020,journal:"AACL",citations:475,abstract:"Recent years have seen important advances in the quality of state-of-the-art models, but this has come at the expense of models becoming less interpretable. This survey presents an overview of the current state of Explainable AI (XAI), considered within the domain of Natural Language Processing (NLP). We discuss the main categorization of explanations, as well as the various ways explanations can be arrived at and visualized. We detail the operations and explainability techniques currently available for generating explanations for NLP model predictions, to serve as a resource for model developers in the community. Finally, we point out the current gaps and encourage directions for future work in this important research area.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://aclanthology.org/2020.aacl-main.46.pdf",is_oa:!0,n_refs:78,n_refs_in_core:2,degree:5,community:2,deg_w:21,betweenness:.0037,pagerank:9e-4,eigenvector:.0069},{id:217,oaid:"3843469976bd895851bfa08c8208350745bf649f",doi:"10.48550/arXiv.2307.06135",title:"SayPlan: Grounding Large Language Models using 3D Scene Graphs for Scalable Task Planning",authors:[{name:"Krishan Rana",institutions:[]},{name:"Jesse Haviland",institutions:["Queensland University of Technology","CSIRO"]},{name:"Sourav Garg",institutions:["Queensland University of Technology, Brisbane, Australia"]},{name:"Jad Abou-Chakra",institutions:[]},{name:"I. Reid",institutions:[]},{name:"Niko Sünderhauf",institutions:[]}],authorString:"Krishan Rana; Jesse Haviland; Sourav Garg; Jad Abou-Chakra; I. Reid; Niko Sünderhauf",institutions:["CSIRO","Queensland University of Technology","Queensland University of Technology, Brisbane, Australia"],countries:[],year:2023,journal:"Conference on Robot Learning",citations:475,abstract:"Large language models (LLMs) have demonstrated impressive results in developing generalist planning agents for diverse tasks. However, grounding these plans in expansive, multi-floor, and multi-room environments presents a significant challenge for robotics. We introduce SayPlan, a scalable approach to LLM-based, large-scale task planning for robotics using 3D scene graph (3DSG) representations. To ensure the scalability of our approach, we: (1) exploit the hierarchical nature of 3DSGs to allow LLMs to conduct a 'semantic search' for task-relevant subgraphs from a smaller, collapsed representation of the full graph; (2) reduce the planning horizon for the LLM by integrating a classical path planner and (3) introduce an 'iterative replanning' pipeline that refines the initial plan using feedback from a scene graph simulator, correcting infeasible actions and avoiding planning failures. We evaluate our approach on two large-scale environments spanning up to 3 floors and 36 rooms with 140 assets and objects and show that our approach is capable of grounding large-scale, long-horizon task plans from abstract, and natural language instruction for a mobile manipulator robot to execute. We provide real robot video demonstrations on our project page https://sayplan.github.io.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2307.06135",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:218,oaid:"f8a22859230e0ccafefc020dccc66b5a646fe0ac",doi:"10.1609/aaai.v35i7.16792",title:"COMET-ATOMIC 2020: On Symbolic and Neural Commonsense Knowledge Graphs",authors:[{name:"Jena D. Hwang",institutions:[]},{name:"Chandra Bhagavatula",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Ronan Le Bras",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Jeff Da",institutions:[]},{name:"Keisuke Sakaguchi",institutions:["Tohoku University"]},{name:"Antoine Bosselut",institutions:["EPFL"]},{name:"Yejin Choi",institutions:[]}],authorString:"Jena D. Hwang; Chandra Bhagavatula; Ronan Le Bras; Jeff Da; Keisuke Sakaguchi; Antoine Bosselut; Yejin Choi",institutions:["Allen Institute for Artificial Intelligence","EPFL","Tohoku University"],countries:[],year:2020,journal:"AAAI Conference on Artificial Intelligence",citations:472,abstract:"Recent years have brought about a renewed interest in commonsense representation and reasoning in the field of natural language understanding. The development of new commonsense knowledge graphs (CSKG) has been central to these advances as their diverse facts can be used and referenced by machine learning models for tackling new and challenging tasks. At the same time, there remain questions about the quality and coverage of these resources due to the massive scale required to comprehensively encompass general commonsense knowledge. In this work, we posit that manually constructed CSKGs will never achieve the coverage necessary to be applicable in all situations encountered by NLP agents. Therefore, we propose a new evaluation framework for testing the utility of KGs based on how effectively implicit knowledge representations can be learned from them. With this new goal, we propose Atomic 2020, a new CSKG of general-purpose commonsense knowledge containing knowledge that is not readily available in pretrained language models. We evaluate its properties in comparison with other leading CSKGs, performing the first large-scale pairwise study of commonsense knowledge resources. Next, we show that Atomic 2020 is better suited for training knowledge models that can generate accurate, representative knowledge for new, unseen entities and events. Finally, through human evaluation, we show that the few-shot performance of GPT-3 (175B parameters), while impressive, remains ~12 absolute points lower than a BART-based knowledge model trained on Atomic 2020 despite using over 430x fewer parameters.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/16792/16599",is_oa:!0,n_refs:42,n_refs_in_core:4,degree:19,community:1,deg_w:150.5,betweenness:.0035,pagerank:.00357,eigenvector:.0919},{id:219,oaid:"a1786540a4e15f0757e1b84a02f98ed436a969e0",doi:null,title:"A Compositional Object-Based Approach to Learning Physical Dynamics",authors:[{name:"Michael Chang",institutions:[]},{name:"T. Ullman",institutions:[]},{name:"A. Torralba",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Michael Chang; T. Ullman; A. Torralba; J. Tenenbaum",institutions:[],countries:[],year:2016,journal:"International Conference on Learning Representations",citations:470,abstract:"We present the Neural Physics Engine (NPE), a framework for learning simulators of intuitive physics that naturally generalize across variable object count and different scene configurations. We propose a factorization of a physical scene into composable object-based representations and a neural network architecture whose compositional structure factorizes object dynamics into pairwise interactions. Like a symbolic physics engine, the NPE is endowed with generic notions of objects and their interactions; realized as a neural network, it can be trained via stochastic gradient descent to adapt to specific object properties and dynamics of different worlds. We evaluate the efficacy of our approach on simple rigid body dynamics in two-dimensional worlds. By comparing to less structured architectures, we show that the NPE's compositional representation of the structure in physical interactions improves its ability to predict movement, generalize across variable object count and different scene configurations, and infer latent properties of objects such as mass.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:51,n_refs_in_core:10,degree:27,community:2,deg_w:159,betweenness:.0134,pagerank:.00507,eigenvector:4e-4},{id:220,oaid:"dedfe929d182cc3537a9ed765d589b4735ce062a",doi:"10.48550/arXiv.2305.15771",title:"On the Planning Abilities of Large Language Models - A Critical Investigation",authors:[{name:"Karthik Valmeekam",institutions:["Arizona State University"]},{name:"Matthew Marquez",institutions:[]},{name:"S. Sreedharan",institutions:[]},{name:"Subbarao Kambhampati",institutions:[]}],authorString:"Karthik Valmeekam; Matthew Marquez; S. Sreedharan; Subbarao Kambhampati",institutions:["Arizona State University"],countries:[],year:2023,journal:"Neural Information Processing Systems",citations:469,abstract:"Intrigued by the claims of emergent reasoning capabilities in LLMs trained on general web corpora, in this paper, we set out to investigate their planning capabilities. We aim to evaluate (1) the effectiveness of LLMs in generating plans autonomously in commonsense planning tasks and (2) the potential of LLMs as a source of heuristic guidance for other agents (AI planners) in their planning tasks. We conduct a systematic study by generating a suite of instances on domains similar to the ones employed in the International Planning Competition and evaluate LLMs in two distinct modes: autonomous and heuristic. Our findings reveal that LLMs' ability to generate executable plans autonomously is rather limited, with the best model (GPT-4) having an average success rate of ~12% across the domains. However, the results in the heuristic mode show more promise. In the heuristic mode, we demonstrate that LLM-generated plans can improve the search process for underlying sound planners and additionally show that external verifiers can help provide feedback on the generated plans and back-prompt the LLM for better plan generation.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"http://arxiv.org/pdf/2305.15771",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:221,oaid:"d450b0f12ae0437048e4047a630c31d902002d0c",doi:null,title:"Distributional Smoothing with Virtual Adversarial Training",authors:[{name:"Takeru Miyato",institutions:["Preferred Networks, Inc."]},{name:"S. Maeda",institutions:[]},{name:"Masanori Koyama",institutions:[]},{name:"Ken Nakae",institutions:[]},{name:"S. Ishii",institutions:[]}],authorString:"Takeru Miyato; S. Maeda; Masanori Koyama; Ken Nakae; S. Ishii",institutions:["Preferred Networks, Inc."],countries:[],year:2015,journal:"International Conference on Learning Representations",citations:467,abstract:"We propose local distributional smoothness (LDS), a new notion of smoothness for statistical model that can be used as a regularization term to promote the smoothness of the model distribution. We named the LDS based regularization as virtual adversarial training (VAT). The LDS of a model at an input datapoint is defined as the KL-divergence based robustness of the model distribution against local perturbation around the datapoint. VAT resembles adversarial training, but distinguishes itself in that it determines the adversarial direction from the model distribution alone without using the label information, making it applicable to semi-supervised learning. The computational cost for VAT is relatively low. For neural network, the approximated gradient of the LDS can be computed with no more than three pairs of forward and back propagations. When we applied our technique to supervised and semi-supervised learning for the MNIST dataset, it outperformed all the training methods other than the current state of the art method, which is based on a highly advanced generative model. We also applied our method to SVHN and NORB, and confirmed our method's superior performance over the current state of the art semi-supervised method applied to these datasets.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:43e-5,eigenvector:0},{id:222,oaid:"5889e9afbcc3935867f9ae16fe46c71b9f2b071f",doi:null,title:"End-to-end Differentiable Proving",authors:[{name:"Tim Rocktäschel",institutions:[]},{name:"Sebastian Riedel",institutions:[]}],authorString:"Tim Rocktäschel; Sebastian Riedel",institutions:[],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:465,abstract:"We introduce neural networks for end-to-end differentiable proving of queries to knowledge bases by operating on dense vector representations of symbols. These neural networks are constructed recursively by taking inspiration from the backward chaining algorithm as used in Prolog. Specifically, we replace symbolic unification with a differentiable computation on vector representations of symbols using a radial basis function kernel, thereby combining symbolic reasoning with learning subsymbolic vector representations. By using gradient descent, the resulting neural network can be trained to infer facts from a given incomplete knowledge base. It learns to (i) place representations of similar symbols in close proximity in a vector space, (ii) make use of such similarities to prove queries, (iii) induce logical rules, and (iv) use provided and induced logical rules for multi-hop reasoning. We demonstrate that this architecture outperforms ComplEx, a state-of-the-art neural link prediction model, on three out of four benchmark knowledge bases while at the same time inducing interpretable function-free first-order logic rules.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:66,n_refs_in_core:37,degree:57,community:0,deg_w:346.5,betweenness:.0783,pagerank:.0127,eigenvector:.009},{id:223,oaid:"3bf09b2e2639add154a9fe6ff98cc373d3e90e4e",doi:"10.1109/CVPR.2018.00754",title:"Neural Baby Talk",authors:[{name:"Jiasen Lu",institutions:["Allen Institute of AI"]},{name:"Jianwei Yang",institutions:[]},{name:"Dhruv Batra",institutions:[]},{name:"Devi Parikh",institutions:[]}],authorString:"Jiasen Lu; Jianwei Yang; Dhruv Batra; Devi Parikh",institutions:["Allen Institute of AI"],countries:[],year:2018,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:464,abstract:"We introduce a novel framework for image captioning that can produce natural language explicitly grounded in entities that object detectors find in the image. Our approach reconciles classical slot filling approaches (that are generally better grounded in images) with modern neural captioning approaches (that are generally more natural sounding and accurate). Our approach first generates a sentence 'template' with slot locations explicitly tied to specific image regions. These slots are then filled in by visual concepts identified in the regions by object detectors. The entire architecture (sentence template generation and slot filling with object detectors) is end-to-end differentiable. We verify the effectiveness of our proposed model on different image captioning tasks. On standard image captioning and novel object captioning, our model reaches state-of-the-art on both COCO and Flickr30k datasets. We also demonstrate that our model has unique advantages when the train and test distributions of scene compositions - and hence language priors of associated captions - are different. Code has been made available at: https://github.com/jiasenlu/NeuralBabyTalk.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:50,n_refs_in_core:1,degree:18,community:3,deg_w:207,betweenness:.0053,pagerank:.00404,eigenvector:.0071},{id:224,oaid:"9d40837175577bb0009b138269b422f6d5820d00",doi:"10.52202/068431-1587",title:"Transformer Memory as a Differentiable Search Index",authors:[{name:"Yi Tay",institutions:[]},{name:"Vinh Q. Tran",institutions:["Google"]},{name:"Mostafa Dehghani",institutions:[]},{name:"Jianmo Ni",institutions:["Google"]},{name:"Dara Bahri",institutions:[]},{name:"Harsh Mehta",institutions:[]},{name:"Zhen Qin",institutions:[]},{name:"Kai Hui",institutions:["Google Research"]},{name:"Zhe Zhao",institutions:[]},{name:"Jai Gupta",institutions:["Google Inc"]},{name:"Tal Schuster",institutions:["MIT"]},{name:"William W. Cohen",institutions:["Google"]},{name:"Donald Metzler",institutions:["Google"]}],authorString:"Yi Tay; Vinh Q. Tran; Mostafa Dehghani; Jianmo Ni; Dara Bahri; Harsh Mehta; Zhen Qin; Kai Hui; Zhe Zhao; Jai Gupta; Tal Schuster; William W. Cohen et al.",institutions:["Google","Google Inc","Google Research","MIT"],countries:[],year:2022,journal:"Neural Information Processing Systems",citations:463,abstract:"In this paper, we demonstrate that information retrieval can be accomplished with a single Transformer, in which all information about the corpus is encoded in the parameters of the model. To this end, we introduce the Differentiable Search Index (DSI), a new paradigm that learns a text-to-text model that maps string queries directly to relevant docids; in other words, a DSI model answers queries directly using only its parameters, dramatically simplifying the whole retrieval process. We study variations in how documents and their identifiers are represented, variations in training procedures, and the interplay between models and corpus sizes. Experiments demonstrate that given appropriate design choices, DSI significantly outperforms strong baselines such as dual encoder models. Moreover, DSI demonstrates strong generalization capabilities, outperforming a BM25 baseline in a zero-shot setup.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:36,n_refs_in_core:1,degree:17,community:1,deg_w:125.5,betweenness:.0032,pagerank:.00293,eigenvector:.0475},{id:225,oaid:"00fe3d95d0fd5f1433d81405bee772c4fe9af9c6",doi:"10.1109/CVPR.2016.29",title:"What Value Do Explicit High Level Concepts Have in Vision to Language Problems?",authors:[{name:"Qi Wu",institutions:[]},{name:"Chunhua Shen",institutions:[]},{name:"Lingqiao Liu",institutions:[]},{name:"A. Dick",institutions:[]},{name:"Anton van den Hengel",institutions:["University of Adelaide, Commonwealth Bank of Australia"]}],authorString:"Qi Wu; Chunhua Shen; Lingqiao Liu; A. Dick; Anton van den Hengel",institutions:["University of Adelaide, Commonwealth Bank of Australia"],countries:[],year:2015,journal:"Computer Vision and Pattern Recognition",citations:463,abstract:"Much recent progress in Vision-to-Language (V2L) problems has been achieved through a combination of Convolutional Neural Networks (CNNs) and Recurrent Neural Networks (RNNs). This approach does not explicitly represent high-level semantic concepts, but rather seeks to progress directly from image features to text. In this paper we investigate whether this direct approach succeeds due to, or despite, the fact that it avoids the explicit representation of high-level information. We propose a method of incorporating high-level concepts into the successful CNN-RNN approach, and show that it achieves a significant improvement on the state-of-the-art in both image captioning and visual question answering. We also show that the same mechanism can be used to introduce external semantic information and that doing so further improves performance. We achieve the best reported results on both image captioning and VQA on several benchmark datasets, and provide an analysis of the value of explicit high-level concepts in V2L problems.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"http://arxiv.org/pdf/1506.01144",is_oa:!0,n_refs:73,n_refs_in_core:2,degree:21,community:3,deg_w:241.5,betweenness:.0054,pagerank:.00488,eigenvector:.0029},{id:226,oaid:"3e565c544a8639cc9c7568833e484d7610f5e5d4",doi:"10.48550/arXiv.2209.14610",title:"Dynamic Prompt Learning via Policy Gradient for Semi-structured Mathematical Reasoning",authors:[{name:"Pan Lu",institutions:["Stanford University"]},{name:"Liang Qiu",institutions:["Amazon Alexa AI"]},{name:"Kai-Wei Chang",institutions:["UCLA"]},{name:"Y. Wu",institutions:[]},{name:"Song-Chun Zhu",institutions:[]},{name:"Tanmay Rajpurohit",institutions:[]},{name:"Peter Clark",institutions:["Allen Institute for AI"]},{name:"A. Kalyan",institutions:[]}],authorString:"Pan Lu; Liang Qiu; Kai-Wei Chang; Y. Wu; Song-Chun Zhu; Tanmay Rajpurohit; Peter Clark; A. Kalyan",institutions:["Allen Institute for AI","Amazon Alexa AI","Stanford University","UCLA"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:463,abstract:"Mathematical reasoning, a core ability of human intelligence, presents unique challenges for machines in abstract thinking and logical reasoning. Recent large pre-trained language models such as GPT-3 have achieved remarkable progress on mathematical reasoning tasks written in text form, such as math word problems (MWP). However, it is unknown if the models can handle more complex problems that involve math reasoning over heterogeneous information, such as tabular data. To fill the gap, we present Tabular Math Word Problems (TabMWP), a new dataset containing 38,431 open-domain grade-level problems that require mathematical reasoning on both textual and tabular data. Each question in TabMWP is aligned with a tabular context, which is presented as an image, semi-structured text, and a structured table. There are two types of questions: free-text and multi-choice, and each problem is annotated with gold solutions to reveal the multi-step reasoning process. We evaluate different pre-trained models on TabMWP, including the GPT-3 model in a few-shot setting. As earlier studies suggest, since few-shot GPT-3 relies on the selection of in-context examples, its performance is unstable and can degrade to near chance. The unstable issue is more severe when handling complex problems like TabMWP. To mitigate this, we further propose a novel approach, PromptPG, which utilizes policy gradient to learn to select in-context examples from a small amount of training data and then constructs the corresponding prompt for the test example. Experimental results show that our method outperforms the best baseline by 5.31% on the accuracy metric and reduces the prediction variance significantly compared to random selection, which verifies its effectiveness in selecting in-context examples.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2209.14610",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:5,deg_w:4,betweenness:0,pagerank:39e-5,eigenvector:2e-4},{id:227,oaid:"a5b1bf6584f24fe3ccc8d67e5bba369783f817f0",doi:"10.1145/1734454.1734553",title:"Toward understanding natural language directions",authors:[{name:"T. Kollar",institutions:[]},{name:"Stefanie Tellex",institutions:[]},{name:"D. Roy",institutions:[]},{name:"N. Roy",institutions:[]}],authorString:"T. Kollar; Stefanie Tellex; D. Roy; N. Roy",institutions:[],countries:[],year:2010,journal:"IEEE/ACM International Conference on Human-Robot Interaction",citations:459,abstract:"Speaking using unconstrained natural language is an intuitive and flexible way for humans to interact with robots. Understanding this kind of linguistic input is challenging because diverse words and phrases must be mapped into structures that the robot can understand, and elements in those structures must be grounded in an uncertain environment. We present a system that follows natural language directions by extracting a sequence of spatial description clauses from the linguistic input and then infers the most probable path through the environment given only information about the environmental geometry and detected visible objects. We use a probabilistic graphical model that factors into three key components. The first component grounds landmark phrases such as “the computers” in the perceptual frame of the robot by exploiting co-occurrence statistics from a database of tagged images such as Flickr. Second, a spatial reasoning component judges how well spatial relations such as “past the computers” describe a path. Finally, verb phrases such as “turn right” are modeled according to the amount of change in orientation in the path. Our system follows 60% of the directions in our corpus to within 15 meters of the true destination, significantly outperforming other approaches.",keywords:[],concepts:[],pdf_url:"https://dspace.mit.edu/bitstream/1721.1/67029/1/Roy_Toward%20Understanding.pdf",is_oa:!0,n_refs:19,n_refs_in_core:2,degree:7,community:4,deg_w:44,betweenness:1e-4,pagerank:.00145,eigenvector:6e-4},{id:228,oaid:"c7d007ba376faddf0046930ea7375ed59600cee9",doi:"10.1109/CVPR.2017.344",title:"Graph-Structured Representations for Visual Question Answering",authors:[{name:"Damien Teney",institutions:["Idiap Research Institute","University of Adelaide"]},{name:"Lingqiao Liu",institutions:[]},{name:"Anton van den Hengel",institutions:["University of Adelaide, Commonwealth Bank of Australia"]}],authorString:"Damien Teney; Lingqiao Liu; Anton van den Hengel",institutions:["Idiap Research Institute","University of Adelaide","University of Adelaide, Commonwealth Bank of Australia"],countries:[],year:2016,journal:"Computer Vision and Pattern Recognition",citations:455,abstract:"This paper proposes to improve visual question answering (VQA) with structured representations of both scene contents and questions. A key challenge in VQA is to require joint reasoning over the visual and text domains. The predominant CNN/LSTM-based approach to VQA is limited by monolithic vector representations that largely ignore structure in the scene and in the question. CNN feature vectors cannot effectively capture situations as simple as multiple object instances, and LSTMs process questions as series of words, which do not reflect the true complexity of language structure. We instead propose to build graphs over the scene objects and over the question words, and we describe a deep neural network that exploits the structure in these representations. We show that this approach achieves significant improvements over the state-of-the-art, increasing accuracy from 71.2% to 74.4% in accuracy on the abstract scenes multiple-choice benchmark, and from 34.7% to 39.1% in accuracy over pairs of balanced scenes, i.e. images with fine-grained differences and opposite yes/no answers to a same question.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1609.05600",is_oa:!0,n_refs:30,n_refs_in_core:6,degree:24,community:3,deg_w:178.5,betweenness:.0018,pagerank:.00382,eigenvector:.001},{id:229,oaid:"a4c40532e68728fbeab5d9415f6ad8e9530db360",doi:"10.18653/v1/W17-3518",title:"The WebNLG Challenge: Generating Text from RDF Data",authors:[{name:"Claire Gardent",institutions:[]},{name:"Anastasia Shimorina",institutions:[]},{name:"Shashi Narayan",institutions:[]},{name:"Laura Perez-Beltrachini",institutions:[]}],authorString:"Claire Gardent; Anastasia Shimorina; Shashi Narayan; Laura Perez-Beltrachini",institutions:[],countries:[],year:2017,journal:"International Conference on Natural Language Generation",citations:454,abstract:"The WebNLG challenge consists in mapping sets of RDF triples to text. It provides a common benchmark on which to train, evaluate and compare “microplanners”, i.e. generation systems that verbalise a given content by making a range of complex interacting choices including referring expression generation, aggregation, lexicalisation, surface realisation and sentence segmentation. In this paper, we introduce the microplanning task, describe data preparation, introduce our evaluation methodology, analyse participant results and provide a brief description of the participating systems.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.aclweb.org/anthology/W17-3518.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:1,deg_w:17.5,betweenness:0,pagerank:66e-5,eigenvector:.0091},{id:230,oaid:"e850d4c0dad3aee3b8b40be5e5d5e5c31354d8cc",doi:"10.52202/075280-1693",title:"PlanBench: An Extensible Benchmark for Evaluating Large Language Models on Planning and Reasoning about Change",authors:[{name:"Karthik Valmeekam",institutions:["Arizona State University"]},{name:"Alberto Olmo",institutions:[]},{name:"S. Sreedharan",institutions:[]},{name:"Subbarao Kambhampati",institutions:[]}],authorString:"Karthik Valmeekam; Alberto Olmo; S. Sreedharan; Subbarao Kambhampati",institutions:["Arizona State University"],countries:[],year:2022,journal:"Neural Information Processing Systems",citations:452,abstract:"Generating plans of action, and reasoning about change have long been considered a core competence of intelligent agents. It is thus no surprise that evaluating the planning and reasoning capabilities of large language models (LLMs) has become a hot topic of research. Most claims about LLM planning capabilities are however based on common sense tasks-where it becomes hard to tell whether LLMs are planning or merely retrieving from their vast world knowledge. There is a strong need for systematic and extensible planning benchmarks with sufficient diversity to evaluate whether LLMs have innate planning capabilities. Motivated by this, we propose PlanBench, an extensible benchmark suite based on the kinds of domains used in the automated planning community, especially in the International Planning Competition, to test the capabilities of LLMs in planning or reasoning about actions and change. PlanBench provides sufficient diversity in both the task domains and the specific planning capabilities. Our studies also show that on many critical capabilities-including plan generation-LLM performance falls quite short, even with the SOTA models. PlanBench can thus function as a useful marker of progress of LLMs in planning and reasoning.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:231,oaid:"778ce81457383bd5e3fdb11b145ded202ebb4970",doi:"10.1109/CVPR.2017.127",title:"Semantic Compositional Networks for Visual Captioning",authors:[{name:"Zhe Gan",institutions:["Microsoft"]},{name:"Chuang Gan",institutions:[]},{name:"Xiaodong He",institutions:[]},{name:"Yunchen Pu",institutions:[]},{name:"Kenneth Tran",institutions:[]},{name:"Jianfeng Gao",institutions:[]},{name:"L. Carin",institutions:[]},{name:"L. Deng",institutions:[]}],authorString:"Zhe Gan; Chuang Gan; Xiaodong He; Yunchen Pu; Kenneth Tran; Jianfeng Gao; L. Carin; L. Deng",institutions:["Microsoft"],countries:[],year:2016,journal:"Computer Vision and Pattern Recognition",citations:451,abstract:"A Semantic Compositional Network (SCN) is developed for image captioning, in which semantic concepts (i.e., tags) are detected from the image, and the probability of each tag is used to compose the parameters in a long short-term memory (LSTM) network. The SCN extends each weight matrix of the LSTM to an ensemble of tag-dependent weight matrices. The degree to which each member of the ensemble is used to generate an image caption is tied to the image-dependent probability of the corresponding tag. In addition to captioning images, we also extend the SCN to generate captions for video clips. We qualitatively analyze semantic composition in SCNs, and quantitatively evaluate the algorithm on three benchmark datasets: COCO, Flickr30k, and Youtube2Text. Experimental results show that the proposed method significantly outperforms prior state-of-the-art approaches, across multiple evaluation metrics.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1611.08002",is_oa:!0,n_refs:60,n_refs_in_core:1,degree:18,community:3,deg_w:182.5,betweenness:.0037,pagerank:.00374,eigenvector:.0027},{id:232,oaid:"27cd5a3eb55d2df2a4c06e96247b79f215516a67",doi:null,title:"Algorithmic Fairness",authors:[{name:"Dana Pessach",institutions:[]},{name:"E. Shmueli",institutions:[]}],authorString:"Dana Pessach; E. Shmueli",institutions:[],countries:[],year:2020,journal:"arXiv.org",citations:450,abstract:"An increasing number of decisions regarding the daily lives of human beings are being controlled by artificial intelligence (AI) algorithms in spheres ranging from healthcare, transportation, and education to college admissions, recruitment, provision of loans and many more realms. Since they now touch on many aspects of our lives, it is crucial to develop AI algorithms that are not only accurate but also objective and fair. Recent studies have shown that algorithmic decision-making may be inherently prone to unfairness, even when there is no intention for it. This paper presents an overview of the main concepts of identifying, measuring and improving algorithmic fairness when using AI algorithms. The paper begins by discussing the causes of algorithmic bias and unfairness and the common definitions and measures for fairness. Fairness-enhancing mechanisms are then reviewed and divided into pre-process, in-process and post-process mechanisms. A comprehensive comparison of the mechanisms is then conducted, towards a better understanding of which mechanisms should be used in different scenarios. The paper then describes the most commonly used fairness-related datasets in this field. Finally, the paper ends by reviewing several emerging research sub-fields of algorithmic fairness.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:44e-5,eigenvector:0},{id:233,oaid:"1046b1d5ad67940beb01a2ef13fbe6fd6d4ec4ec",doi:null,title:"Weapons of Math Destruction: How Big Data Increases Inequality and Threatens Democracy",authors:[{name:"Alexandra Carter",institutions:[]}],authorString:"Alexandra Carter",institutions:[],countries:[],year:2018,journal:"",citations:450,abstract:"",keywords:["Sociology"],concepts:["Sociology"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:234,oaid:"448dc7666ea457dc1de66b1384c06ba7f3e4650f",doi:"10.1177/0278364913484072",title:"Integrated task and motion planning in belief space",authors:[{name:"L. Kaelbling",institutions:[]},{name:"Tomas Lozano-Perez",institutions:["Massachusetts Institute of Technology"]}],authorString:"L. Kaelbling; Tomas Lozano-Perez",institutions:["Massachusetts Institute of Technology"],countries:[],year:2013,journal:"Int. J. Robotics Res.",citations:446,abstract:"We describe an integrated strategy for planning, perception, state estimation and action in complex mobile manipulation domains based on planning in the belief space of probability distributions over states using hierarchical goal regression (pre-image back-chaining). We develop a vocabulary of logical expressions that describe sets of belief states, which are goals and subgoals in the planning process. We show that a relatively small set of symbolic operators can give rise to task-oriented perception in support of the manipulation goals. An implementation of this method is demonstrated in simulation and on a real PR2 robot, showing robust, flexible solution of mobile manipulation problems with multiple objects and substantial uncertainty.",keywords:[],concepts:[],pdf_url:"http://hdl.handle.net/1721.1/87038",is_oa:!0,n_refs:78,n_refs_in_core:1,degree:3,community:4,deg_w:15,betweenness:8e-4,pagerank:.00115,eigenvector:1e-4},{id:235,oaid:"498ca0a1f8c980586408addf7ab2919ecdb7dd3d",doi:"10.1145/2187836.2187874",title:"Factorizing YAGO: scalable machine learning for linked data",authors:[{name:"Maximilian Nickel",institutions:[]},{name:"Volker Tresp",institutions:[]},{name:"H. Kriegel",institutions:[]}],authorString:"Maximilian Nickel; Volker Tresp; H. Kriegel",institutions:[],countries:[],year:2012,journal:"The Web Conference",citations:441,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:0,deg_w:20.5,betweenness:0,pagerank:87e-5,eigenvector:4e-4},{id:236,oaid:"b115c1e1e9e51f8ad7d47b745bc04e29a654b84d",doi:"10.48550/arXiv.2301.13379",title:"Faithful Chain-of-Thought Reasoning",authors:[{name:"Qing Lyu",institutions:["University of Pennsylvania"]},{name:"Shreya Havaldar",institutions:[]},{name:"Adam Stein",institutions:[]},{name:"Li Zhang",institutions:["University of Pennsylvania"]},{name:"D. Rao",institutions:[]},{name:"Eric Wong",institutions:[]},{name:"Marianna Apidianaki",institutions:[]},{name:"Chris Callison-Burch",institutions:["University of Pennsylvania"]}],authorString:"Qing Lyu; Shreya Havaldar; Adam Stein; Li Zhang; D. Rao; Eric Wong; Marianna Apidianaki; Chris Callison-Burch",institutions:["University of Pennsylvania"],countries:[],year:2023,journal:"International Joint Conference on Natural Language Processing",citations:439,abstract:"While Chain-of-Thought (CoT) prompting boosts Language Models' (LM) performance on a gamut of complex reasoning tasks, the generated reasoning chain does not necessarily reflect how the model arrives at the answer (aka. faithfulness). We propose Faithful CoT, a reasoning framework involving two stages: Translation (Natural Language query $\\rightarrow$ symbolic reasoning chain) and Problem Solving (reasoning chain $\\rightarrow$ answer), using an LM and a deterministic solver respectively. This guarantees that the reasoning chain provides a faithful explanation of the final answer. Aside from interpretability, Faithful CoT also improves empirical performance: it outperforms standard CoT on 9 of 10 benchmarks from 4 diverse domains, with a relative accuracy gain of 6.3% on Math Word Problems (MWP), 3.4% on Planning, 5.5% on Multi-hop Question Answering (QA), and 21.4% on Relational Inference. Furthermore, with GPT-4 and Codex, it sets the new state-of-the-art few-shot performance on 7 datasets (with 95.0+ accuracy on 6 of them), showing a strong synergy between faithfulness and accuracy.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://arxiv.org/pdf/2301.13379",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:237,oaid:"76ad9a7e9a9a047adb533a150c98c2a0c5fe9cc9",doi:"10.1007/978-3-642-39799-8_1",title:"First-Order Theorem Proving and Vampire",authors:[{name:"Laura Kovács",institutions:[]},{name:"Andrei Voronkov",institutions:[]}],authorString:"Laura Kovács; Andrei Voronkov",institutions:[],countries:[],year:2013,journal:"International Conference on Computer Aided Verification",citations:439,abstract:"",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007/978-3-642-39799-8_1.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:6,deg_w:13.5,betweenness:0,pagerank:63e-5,eigenvector:6e-4},{id:238,oaid:"23752fcbd66f3e8da6d169a16db17515ed7b916e",doi:"10.1093/acprof:oso/9780195102659.001.1",title:"In the Theater of Consciousness",authors:[{name:"B. Baars",institutions:[]}],authorString:"B. Baars",institutions:[],countries:[],year:1997,journal:"",citations:436,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:59e-5,eigenvector:0},{id:239,oaid:"b59d91e0699d4e1896a15bae13fd180bdaf77ea5",doi:null,title:"Neural Programmer-Interpreters",authors:[{name:"Scott E. Reed",institutions:[]},{name:"Nando de Freitas",institutions:[]}],authorString:"Scott E. Reed; Nando de Freitas",institutions:[],countries:[],year:2015,journal:"International Conference on Learning Representations",citations:435,abstract:"We propose the neural programmer-interpreter (NPI): a recurrent and compositional neural network that learns to represent and execute programs. NPI has three learnable components: a task-agnostic recurrent core, a persistent key-value program memory, and domain-specific encoders that enable a single NPI to operate in multiple perceptually diverse environments with distinct affordances. By learning to compose lower-level programs to express higher-level programs, NPI reduces sample complexity and increases generalization ability compared to sequence-to-sequence LSTMs. The program memory allows efficient learning of additional tasks by building on existing programs. NPI can also harness the environment (e.g. a scratch pad with read-write pointers) to cache intermediate results of computation, lessening the long-term memory burden on recurrent hidden units. In this work we train the NPI with fully-supervised execution traces; each program has example sequences of calls to the immediate subprograms conditioned on the input. Rather than training on a huge number of relatively weak labels, NPI learns from a small number of rich examples. We demonstrate the capability of our model to learn several types of compositional programs: addition, sorting, and canonicalizing 3D models. Furthermore, a single NPI learns to execute these programs and all 21 associated subprograms.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:7,community:0,deg_w:27,betweenness:.0019,pagerank:.00118,eigenvector:3e-4},{id:240,oaid:"7ba98b00a224094c09676090f5d6d69498f5b299",doi:null,title:"MiniF2F: a cross-system benchmark for formal Olympiad-level mathematics",authors:[{name:"Kunhao Zheng",institutions:[]},{name:"Jesse Michael Han",institutions:[]},{name:"Stanislas Polu",institutions:[]}],authorString:"Kunhao Zheng; Jesse Michael Han; Stanislas Polu",institutions:[],countries:[],year:2021,journal:"International Conference on Learning Representations",citations:433,abstract:"We present miniF2F, a dataset of formal Olympiad-level mathematics problems statements intended to provide a unified cross-system benchmark for neural theorem proving. The miniF2F benchmark currently targets Metamath, Lean, Isabelle (partially) and HOL Light (partially) and consists of 488 problem statements drawn from the AIME, AMC, and the International Mathematical Olympiad (IMO), as well as material from high-school and undergraduate mathematics courses. We report baseline results using GPT-f, a neural theorem prover based on GPT-3 and provide an analysis of its performance. We intend for miniF2F to be a community-driven effort and hope that our benchmark will help spur advances in neural theorem proving.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:6,deg_w:8.5,betweenness:0,pagerank:5e-4,eigenvector:7e-4},{id:241,oaid:"851f27df3a1ec8daa693f6642194562e3fe9769a",doi:null,title:"Walk the Talk: Connecting Language, Knowledge, and Action in Route Instructions",authors:[{name:"M. MacMahon",institutions:[]},{name:"B. Stankiewicz",institutions:[]},{name:"B. Kuipers",institutions:[]}],authorString:"M. MacMahon; B. Stankiewicz; B. Kuipers",institutions:[],countries:[],year:2006,journal:"AAAI Conference on Artificial Intelligence",citations:432,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:7,community:4,deg_w:33,betweenness:0,pagerank:.0011,eigenvector:5e-4},{id:242,oaid:"1bc9865ebf52b59abac7f5ee4456ff2ac37fcff3",doi:null,title:"ST-MoE: Designing Stable and Transferable Sparse Expert Models",authors:[{name:"Barret Zoph",institutions:[]},{name:"Irwan Bello",institutions:[]},{name:"Sameer Kumar",institutions:[]},{name:"Nan Du",institutions:[]},{name:"Yanping Huang",institutions:[]},{name:"J. Dean",institutions:[]},{name:"Noam Shazeer",institutions:["Google"]},{name:"W. Fedus",institutions:[]}],authorString:"Barret Zoph; Irwan Bello; Sameer Kumar; Nan Du; Yanping Huang; J. Dean; Noam Shazeer; W. Fedus",institutions:["Google"],countries:[],year:2022,journal:"",citations:432,abstract:"Scale has opened new frontiers in natural language processing -- but at a high cost. In response, Mixture-of-Experts (MoE) and Switch Transformers have been proposed as an energy efficient path to even larger and more capable language models. But advancing the state-of-the-art across a broad set of natural language tasks has been hindered by training instabilities and uncertain quality during fine-tuning. Our work focuses on these issues and acts as a design guide. We conclude by scaling a sparse model to 269B parameters, with a computational cost comparable to a 32B dense encoder-decoder Transformer (Stable and Transferable Mixture-of-Experts or ST-MoE-32B). For the first time, a sparse model achieves state-of-the-art performance in transfer learning, across a diverse set of tasks including reasoning (SuperGLUE, ARC Easy, ARC Challenge), summarization (XSum, CNN-DM), closed book question answering (WebQA, Natural Questions), and adversarially constructed tasks (Winogrande, ANLI R3).",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:243,oaid:"d38e8631bba0720becdaf7b89f79d9f9dca45d82",doi:null,title:"Inferring Algorithmic Patterns with Stack-Augmented Recurrent Nets",authors:[{name:"Armand Joulin",institutions:[]},{name:"Tomas Mikolov",institutions:[]}],authorString:"Armand Joulin; Tomas Mikolov",institutions:[],countries:[],year:2015,journal:"Neural Information Processing Systems",citations:428,abstract:"Despite the recent achievements in machine learning, we are still very far from achieving real artificial intelligence. In this paper, we discuss the limitations of standard deep learning approaches and show that some of these limitations can be overcome by learning how to grow the complexity of a model in a structured way. Specifically, we study the simplest sequence prediction problems that are beyond the scope of what is learnable with standard recurrent networks, algorithmically generated sequences which can only be learned by models which have the capacity to count and to memorize sequences. We show that some basic algorithms can be learned from sequential data using a recurrent network associated with a trainable memory.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:40,n_refs_in_core:0,degree:8,community:2,deg_w:48,betweenness:8e-4,pagerank:.00173,eigenvector:6e-4},{id:244,oaid:"beb335e43da1f518ed7df3a851784925254a6a94",doi:"10.1109/CVPR.2019.00632",title:"Knowledge-Embedded Routing Network for Scene Graph Generation",authors:[{name:"Tianshui Chen",institutions:[]},{name:"Weihao Yu",institutions:[]},{name:"Riquan Chen",institutions:[]},{name:"Liang Lin",institutions:[]}],authorString:"Tianshui Chen; Weihao Yu; Riquan Chen; Liang Lin",institutions:[],countries:[],year:2019,journal:"Computer Vision and Pattern Recognition",citations:426,abstract:"To understand a scene in depth not only involves locating/recognizing individual objects, but also requires to infer the relationships and interactions among them. However, since the distribution of real-world relationships is seriously unbalanced, existing methods perform quite poorly for the less frequent relationships. In this work, we find that the statistical correlations between object pairs and their relationships can effectively regularize semantic space and make prediction less ambiguous, and thus well address the unbalanced distribution issue. To achieve this, we incorporate these statistical correlations into deep neural networks to facilitate scene graph generation by developing a Knowledge-Embedded Routing Network. More specifically, we show that the statistical correlations between objects appearing in images and their relationships, can be explicitly represented by a structured knowledge graph, and a routing mechanism is learned to propagate messages through the graph to explore their interactions. Extensive experiments on the large-scale Visual Genome dataset demonstrate the superiority of the proposed method over current state-of-the-art competitors.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1903.03326",is_oa:!0,n_refs:35,n_refs_in_core:3,degree:14,community:3,deg_w:101,betweenness:.0019,pagerank:.00241,eigenvector:5e-4},{id:245,oaid:"3954a3f80cf1b1f76430d80e924d85f2f1ba6799",doi:"10.1007/978-3-319-00065-7_28",title:"Learning to Parse Natural Language Commands to a Robot Control System",authors:[{name:"Cynthia Matuszek",institutions:[]},{name:"E. Herbst",institutions:[]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]},{name:"D. Fox",institutions:[]}],authorString:"Cynthia Matuszek; E. Herbst; Luke Zettlemoyer; D. Fox",institutions:["Facebook","University of Washington"],countries:[],year:2012,journal:"International Symposium on Experimental Robotics",citations:424,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:4,deg_w:19.5,betweenness:0,pagerank:74e-5,eigenvector:3e-4},{id:246,oaid:"3ff0af64279929a952ee340e645256b7e0580f65",doi:null,title:"RobustFill: Neural Program Learning under Noisy I/O",authors:[{name:"Jacob Devlin",institutions:[]},{name:"Jonathan Uesato",institutions:[]},{name:"Surya Bhupatiraju",institutions:[]},{name:"Rishabh Singh",institutions:[]},{name:"Abdel-rahman Mohamed",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"Jacob Devlin; Jonathan Uesato; Surya Bhupatiraju; Rishabh Singh; Abdel-rahman Mohamed; Pushmeet Kohli",institutions:[],countries:[],year:2017,journal:"International Conference on Machine Learning",citations:423,abstract:"The problem of automatically generating a computer program from some specification has been studied since the early days of AI. Recently, two competing approaches for automatic program learning have received significant attention: (1) neural program synthesis, where a neural network is conditioned on input/output (I/O) examples and learns to generate a program, and (2) neural program induction, where a neural network generates new outputs directly using a latent program representation. Here, for the first time, we directly compare both approaches on a large-scale, real-world learning task and we additionally contrast to rule-based program synthesis, which uses hand-crafted semantics to guide the program generation. Our neural models use a modified attention RNN to allow encoding of variable-sized sets of I/O pairs, which achieve 92% accuracy on a real-world test set, compared to the 34% accuracy of the previous best neural synthesis approach. The synthesis model also outperforms a comparable induction model on this task, but we more importantly demonstrate that the strength of each approach is highly dependent on the evaluation metric and end-user application. Finally, we show that we can train our neural models to remain very robust to the type of noise expected in real-world data (e.g., typos), while a highly-engineered rule-based system fails entirely.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:7,deg_w:21.5,betweenness:6e-4,pagerank:.00111,eigenvector:1e-4},{id:247,oaid:"bd6b6291c3c14551cf9f2aa0e04e2e33c86b800e",doi:null,title:"The Malmo Platform for Artificial Intelligence Experimentation",authors:[{name:"Matthew Johnson",institutions:[]},{name:"Katja Hofmann",institutions:[]},{name:"Tim Hutton",institutions:[]},{name:"David Bignell",institutions:[]}],authorString:"Matthew Johnson; Katja Hofmann; Tim Hutton; David Bignell",institutions:[],countries:[],year:2016,journal:"International Joint Conference on Artificial Intelligence",citations:423,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8,betweenness:0,pagerank:46e-5,eigenvector:2e-4},{id:248,oaid:"550f7dba7757f22afd87786749509574609d6180",doi:null,title:"Hinge-Loss Markov Random Fields and Probabilistic Soft Logic",authors:[{name:"Stephen H. Bach",institutions:[]},{name:"Matthias Broecheler",institutions:[]},{name:"Bert Huang",institutions:[]},{name:"Lise Getoor",institutions:[]}],authorString:"Stephen H. Bach; Matthias Broecheler; Bert Huang; Lise Getoor",institutions:[],countries:[],year:2015,journal:"Journal of machine learning research",citations:422,abstract:"A fundamental challenge in developing high-impact machine learning technologies is balancing the need to model rich, structured domains with the ability to scale to big data. Many important problem areas are both richly structured and large scale, from social and biological networks, to knowledge graphs and the Web, to images, video, and natural language. In this paper, we introduce two new formalisms for modeling structured data, and show that they can both capture rich structure and scale to big data. The first, hinge-loss Markov random fields (HL-MRFs), is a new kind of probabilistic graphical model that generalizes different approaches to convex inference. We unite three approaches from the randomized algorithms, probabilistic graphical models, and fuzzy logic communities, showing that all three lead to the same inference objective. We then define HL-MRFs by generalizing this unified objective. The second new formalism, probabilistic soft logic (PSL), is a probabilistic programming language that makes HL-MRFs easy to define using a syntax based on first-order logic. We introduce an algorithm for inferring most-probable variable assignments (MAP inference) that is much more scalable than general-purpose convex optimization methods, because it uses message passing to take advantage of sparse dependency structures. We then show how to learn the parameters of HL-MRFs. The learned HL-MRFs are as accurate as analogous discrete models, but much more scalable. Together, these algorithms enable HL-MRFs and PSL to model rich, structured data at scales not previously possible.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:146,n_refs_in_core:3,degree:9,community:0,deg_w:45.5,betweenness:.0012,pagerank:.00226,eigenvector:1e-4},{id:249,oaid:"e264e1e55433f158bf8aa8b260bf430d76d5fa28",doi:null,title:"International Journal of Computer Vision manuscript No. (will be inserted by the editor) Semantic Modeling of Natural Scenes for Content-Based Image Retrieval",authors:[],authorString:"",institutions:[],countries:[],year:null,journal:"",citations:417,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:44e-5,eigenvector:1e-4},{id:250,oaid:"ca7bd64d372e3bcb3f4633ca4a20291ff57de3c3",doi:"10.48550/arXiv.2304.10149",title:"Is ChatGPT a Good Recommender? A Preliminary Study",authors:[{name:"Junling Liu",institutions:[]},{name:"Chaoyong Liu",institutions:[]},{name:"Renjie Lv",institutions:[]},{name:"Kangdi Zhou",institutions:[]},{name:"Y. Zhang",institutions:[]}],authorString:"Junling Liu; Chaoyong Liu; Renjie Lv; Kangdi Zhou; Y. Zhang",institutions:[],countries:[],year:2023,journal:"arXiv.org",citations:415,abstract:"Recommendation systems have witnessed significant advancements and have been widely used over the past decades. However, most traditional recommendation methods are task-specific and therefore lack efficient generalization ability. Recently, the emergence of ChatGPT has significantly advanced NLP tasks by enhancing the capabilities of conversational models. Nonetheless, the application of ChatGPT in the recommendation domain has not been thoroughly investigated. In this paper, we employ ChatGPT as a general-purpose recommendation model to explore its potential for transferring extensive linguistic and world knowledge acquired from large-scale corpora to recommendation scenarios. Specifically, we design a set of prompts and evaluate ChatGPT's performance on five recommendation scenarios. Unlike traditional recommendation methods, we do not fine-tune ChatGPT during the entire evaluation process, relying only on the prompts themselves to convert recommendation tasks into natural language tasks. Further, we explore the use of few-shot prompting to inject interaction information that contains user potential interest to help ChatGPT better understand user needs and interests. Comprehensive experimental results on Amazon Beauty dataset show that ChatGPT has achieved promising results in certain tasks and is capable of reaching the baseline level in others. We conduct human evaluations on two explainability-oriented tasks to more accurately evaluate the quality of contents generated by different models. And the human evaluations show ChatGPT can truly understand the provided information and generate clearer and more reasonable results. We hope that our study can inspire researchers to further explore the potential of language models like ChatGPT to improve recommendation performance and contribute to the advancement of the recommendation systems field.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"http://arxiv.org/pdf/2304.10149",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:251,oaid:"f3fbcfbb396f6c0391674c8637a373b729e5e531",doi:"10.1613/jair.1.11674",title:"Compositionality Decomposed: How do Neural Networks Generalise?",authors:[{name:"Dieuwke Hupkes",institutions:[]},{name:"Verna Dankers",institutions:["University of Edinburgh"]},{name:"Mathijs Mul",institutions:[]},{name:"Elia Bruni",institutions:[]}],authorString:"Dieuwke Hupkes; Verna Dankers; Mathijs Mul; Elia Bruni",institutions:["University of Edinburgh"],countries:[],year:2019,journal:"Journal of Artificial Intelligence Research",citations:414,abstract:"Despite a multitude of empirical studies, little consensus exists on whether neural networks are able to generalise compositionally, a controversy that, in part, stems from a lack of agreement about what it means for a neural model to be compositional. As a response to this controversy, we present a set of tests that provide a bridge between, on the one hand, the vast amount of linguistic and philosophical theory about compositionality of language and, on the other, the successful neural models of language. We collect different interpretations of compositionality and translate them into five theoretically grounded tests for models that are formulated on a task-independent level. In particular, we provide tests to investigate (i) if models systematically recombine known parts and rules (ii) if models can extend their predictions beyond the length they have seen in the training data (iii) if models’ composition operations are local or global (iv) if models’ predictions are robust to synonym substitutions and (v) if models favour rules or exceptions during training. To demonstrate the usefulness of this evaluation paradigm, we instantiate these five tests on a highly compositional data set which we dub PCFG SET and apply the resulting tests to three popular sequence-to-sequence models: a recurrent, a convolution-based and a transformer model. We provide an in-depth analysis of the results, which uncover the strengths and weaknesses of these three architectures and point to potential areas of improvement.",keywords:["Philosophy","Linguistics"],concepts:["Philosophy","Linguistics"],pdf_url:"https://jair.org/index.php/jair/article/download/11674/26576",is_oa:!0,n_refs:97,n_refs_in_core:4,degree:15,community:2,deg_w:69,betweenness:.0188,pagerank:.00256,eigenvector:.0022},{id:252,oaid:"8f2d4758e6d525509ae36bb30224dc9259027e6b",doi:"10.1007/s10514-023-10131-7",title:"Text2Motion: from natural language instructions to feasible plans",authors:[{name:"Kevin Lin",institutions:["Microsoft","University of Washington"]},{name:"Christopher Agia",institutions:["Stanford University"]},{name:"Toki Migimatsu",institutions:[]},{name:"M. Pavone",institutions:[]},{name:"Jeannette Bohg",institutions:[]}],authorString:"Kevin Lin; Christopher Agia; Toki Migimatsu; M. Pavone; Jeannette Bohg",institutions:["Microsoft","Stanford University","University of Washington"],countries:[],year:2023,journal:"Autonomous Robots",citations:411,abstract:"We propose Text2Motion, a language-based planning framework enabling robots to solve sequential manipulation tasks that require long-horizon reasoning. Given a natural language instruction, our framework constructs both a task- and motion-level plan that is verified to reach inferred symbolic goals. Text2Motion uses feasibility heuristics encoded in Q-functions of a library of skills to guide task planning with Large Language Models. Whereas previous language-based planners only consider the feasibility of individual skills, Text2Motion actively resolves geometric dependencies spanning skill sequences by performing geometric feasibility planning during its search. We evaluate our method on a suite of problems that require long-horizon reasoning, interpretation of abstract goals, and handling of partial affordance perception. Our experiments show that Text2Motion can solve these challenging problems with a success rate of 82%, while prior state-of-the-art language-based planning methods only achieve 13%. Text2Motion thus provides promising generalization characteristics to semantically diverse sequential manipulation tasks with geometric dependencies between skills. Qualitative results are made available at https://sites.google.com/stanford.edu/text2motion.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2303.12153",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:253,oaid:"12a763cb52f650710900790ca0bc43e5d5b88be6",doi:"10.18653/v1/2022.acl-long.225",title:"Generated Knowledge Prompting for Commonsense Reasoning",authors:[{name:"Jiacheng Liu",institutions:["University of Washington"]},{name:"Alisa Liu",institutions:["University of Washington","Northwestern University"]},{name:"Ximing Lu",institutions:["University of Washington"]},{name:"S. Welleck",institutions:[]},{name:"Peter West",institutions:["Allen Institute for AI","University of Washington"]},{name:"Ronan Le Bras",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Yejin Choi",institutions:[]},{name:"Hannaneh Hajishirzi",institutions:[]}],authorString:"Jiacheng Liu; Alisa Liu; Ximing Lu; S. Welleck; Peter West; Ronan Le Bras; Yejin Choi; Hannaneh Hajishirzi",institutions:["Allen Institute for AI","Allen Institute for Artificial Intelligence","Northwestern University","University of Washington"],countries:[],year:2021,journal:"Annual Meeting of the Association for Computational Linguistics",citations:411,abstract:"It remains an open question whether incorporating external knowledge benefits commonsense reasoning while maintaining the flexibility of pretrained sequence models. To investigate this question, we develop generated knowledge prompting, which consists of generating knowledge from a language model, then providing the knowledge as additional input when answering a question. Our method does not require task-specific supervision for knowledge integration, or access to a structured knowledge base, yet it improves performance of large-scale, state-of-the-art models on four commonsense reasoning tasks, achieving state-of-the-art results on numerical commonsense (NumerSense), general commonsense (CommonsenseQA 2.0), and scientific commonsense (QASC) benchmarks. Generated knowledge prompting highlights large-scale language models as flexible sources of external knowledge for improving commonsense reasoning.Our code is available at github.com/liujch1998/GKP",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2022.acl-long.225.pdf",is_oa:!0,n_refs:39,n_refs_in_core:2,degree:18,community:1,deg_w:115.5,betweenness:.002,pagerank:.00282,eigenvector:.0589},{id:254,oaid:"acc43abe319bca7652a91f7d4ca6187049fb82e4",doi:null,title:"Measuring abstract reasoning in neural networks",authors:[{name:"Adam Santoro",institutions:[]},{name:"Felix Hill",institutions:[]},{name:"D. Barrett",institutions:[]},{name:"Ari S. Morcos",institutions:[]},{name:"T. Lillicrap",institutions:[]}],authorString:"Adam Santoro; Felix Hill; D. Barrett; Ari S. Morcos; T. Lillicrap",institutions:[],countries:[],year:2018,journal:"International Conference on Machine Learning",citations:408,abstract:"Whether neural networks can learn abstract reasoning or whether they merely rely on superficial statistics is a topic of recent debate. Here, we propose a dataset and challenge designed to probe abstract reasoning, inspired by a well-known human IQ test. To succeed at this challenge, models must cope with various generalisation `regimes' in which the training and test data differ in clearly-defined ways. We show that popular models such as ResNets perform poorly, even when the training and test sets differ only minimally, and we present a novel architecture, with a structure designed to encourage reasoning, that does significantly better. When we vary the way in which the test questions and training data differ, we find that our model is notably proficient at certain forms of generalisation, but notably weak at others. We further show that the model's ability to generalise improves markedly if it is trained to predict symbolic explanations for its answers. Altogether, we introduce and explore ways to both measure and induce stronger abstract reasoning in neural networks. Our freely-available dataset should motivate further progress in this direction.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:3,deg_w:16.5,betweenness:1e-4,pagerank:66e-5,eigenvector:2e-4},{id:255,oaid:"d1500f1dbd62e26ef0753f31e845078f58479968",doi:"10.48550/arXiv.2307.01928",title:"Robots That Ask For Help: Uncertainty Alignment for Large Language Model Planners",authors:[{name:"Allen Z. Ren",institutions:[]},{name:"Anushri Dixit",institutions:[]},{name:"Alexandra Bodrova",institutions:[]},{name:"Sumeet Singh",institutions:[]},{name:"Stephen Tu",institutions:[]},{name:"Noah Brown",institutions:[]},{name:"Peng Xu",institutions:[]},{name:"L. Takayama",institutions:[]},{name:"F. Xia",institutions:[]},{name:"Jacob Varley",institutions:[]},{name:"Zhenjia Xu",institutions:[]},{name:"Dorsa Sadigh",institutions:[]},{name:"Andy Zeng",institutions:[]},{name:"Anirudha Majumdar",institutions:[]}],authorString:"Allen Z. Ren; Anushri Dixit; Alexandra Bodrova; Sumeet Singh; Stephen Tu; Noah Brown; Peng Xu; L. Takayama; F. Xia; Jacob Varley; Zhenjia Xu; Dorsa Sadigh et al.",institutions:[],countries:[],year:2023,journal:"Conference on Robot Learning",citations:404,abstract:"Large language models (LLMs) exhibit a wide range of promising capabilities -- from step-by-step planning to commonsense reasoning -- that may provide utility for robots, but remain prone to confidently hallucinated predictions. In this work, we present KnowNo, which is a framework for measuring and aligning the uncertainty of LLM-based planners such that they know when they don't know and ask for help when needed. KnowNo builds on the theory of conformal prediction to provide statistical guarantees on task completion while minimizing human help in complex multi-step planning settings. Experiments across a variety of simulated and real robot setups that involve tasks with different modes of ambiguity (e.g., from spatial to numeric uncertainties, from human preferences to Winograd schemas) show that KnowNo performs favorably over modern baselines (which may involve ensembles or extensive prompt tuning) in terms of improving efficiency and autonomy, while providing formal assurances. KnowNo can be used with LLMs out of the box without model-finetuning, and suggests a promising lightweight approach to modeling uncertainty that can complement and scale with the growing capabilities of foundation models. Website: https://robot-help.github.io",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2307.01928",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:4,deg_w:4,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:256,oaid:"833c4ac0599f4b8c5f1ee6ea948ec675fbe56b15",doi:null,title:"Neural-Symbolic Computing: An Effective Methodology for Principled Integration of Machine Learning and Reasoning",authors:[{name:"A. Garcez",institutions:[]},{name:"M. Gori",institutions:[]},{name:"L. Lamb",institutions:[]},{name:"L. Serafini",institutions:[]},{name:"Michael Spranger",institutions:["Sony AI Inc.","Sony Computer Science Laboratories Inc.","Sony Corporation"]},{name:"S. Tran",institutions:[]}],authorString:"A. Garcez; M. Gori; L. Lamb; L. Serafini; Michael Spranger; S. Tran",institutions:["Sony AI Inc.","Sony Computer Science Laboratories Inc.","Sony Corporation"],countries:[],year:2019,journal:"FLAP",citations:401,abstract:"Current advances in Artificial Intelligence and machine learning in general, and deep learning in particular have reached unprecedented impact not only across research communities, but also over popular media channels. However, concerns about interpretability and accountability of AI have been raised by influential thinkers. In spite of the recent impact of AI, several works have identified the need for principled knowledge representation and reasoning mechanisms integrated with deep learning-based systems to provide sound and explainable models for such systems. Neural-symbolic computing aims at integrating, as foreseen by Valiant, two most fundamental cognitive abilities: the ability to learn from the environment, and the ability to reason from what has been learned. Neural-symbolic computing has been an active topic of research for many years, reconciling the advantages of robust learning in neural networks and reasoning and interpretability of symbolic representation. In this paper, we survey recent accomplishments of neural-symbolic computing as a principled methodology for integrated machine learning and reasoning. We illustrate the effectiveness of the approach by outlining the main characteristics of the methodology: principled integration of neural learning with symbolic knowledge representation and reasoning allowing for the construction of explainable AI systems. The insights provided by neural-symbolic computing shed new light on the increasingly prominent need for interpretable and accountable AI systems.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:44e-5,eigenvector:0},{id:257,oaid:"6c6c822a6bde514140648c32ee6a5acba5a225d7",doi:null,title:"Tabled Evaluation with Delaying for General Logic Programs",authors:[{name:"M. Van Emden",institutions:[]},{name:"D. Kemp",institutions:[]},{name:"Peter J. Stuckey",institutions:[]},{name:"D. Srivastava",institutions:[]},{name:"D. Kemp",institutions:[]},{name:"R. Topor",institutions:[]}],authorString:"M. Van Emden; D. Kemp; Peter J. Stuckey; D. Srivastava; D. Kemp; R. Topor",institutions:[],countries:[],year:1996,journal:"",citations:400,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:258,oaid:"9df88155d6b65e14e06f8dcd851d31b7753659b1",doi:"10.1145/3372885.3373824",title:"The lean mathematical library",authors:[{name:"The mathlib Community",institutions:[]}],authorString:"The mathlib Community",institutions:[],countries:[],year:2019,journal:"Certified Programs and Proofs",citations:399,abstract:"This paper describes mathlib, a community-driven effort to build a unified library of mathematics formalized in the Lean proof assistant. Among proof assistant libraries, it is distinguished by its dependently typed foundations, focus on classical mathematics, extensive hierarchy of structures, use of large- and small-scale automation, and distributed organization. We explain the architecture and design decisions of the library and the social organization that has led to its development.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1910.09336",is_oa:!0,n_refs:60,n_refs_in_core:3,degree:8,community:6,deg_w:59.5,betweenness:7e-4,pagerank:.00201,eigenvector:.0026},{id:259,oaid:"394bb8f1d599a3608c4d79eb30432f7e533bbfed",doi:null,title:"Foundations of Databases: The Logical Level",authors:[{name:"S. Abiteboul",institutions:[]},{name:"R. Hull",institutions:[]},{name:"V. Vianu",institutions:[]}],authorString:"S. Abiteboul; R. Hull; V. Vianu",institutions:[],countries:[],year:1995,journal:"",citations:399,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:42e-5,eigenvector:0},{id:260,oaid:"b21670e8061a06ab97e7d6052c9345a326e84ff8",doi:null,title:"UL2: Unifying Language Learning Paradigms",authors:[{name:"Yi Tay",institutions:[]},{name:"Mostafa Dehghani",institutions:[]},{name:"Vinh Q. Tran",institutions:["Google"]},{name:"Xavier García",institutions:[]},{name:"Jason Wei",institutions:[]},{name:"Xuezhi Wang",institutions:[]},{name:"Hyung Won Chung",institutions:[]},{name:"Dara Bahri",institutions:[]},{name:"Tal Schuster",institutions:["MIT"]},{name:"H. Zheng",institutions:[]},{name:"Denny Zhou",institutions:[]},{name:"N. Houlsby",institutions:[]},{name:"Donald Metzler",institutions:["Google"]}],authorString:"Yi Tay; Mostafa Dehghani; Vinh Q. Tran; Xavier García; Jason Wei; Xuezhi Wang; Hyung Won Chung; Dara Bahri; Tal Schuster; H. Zheng; Denny Zhou; N. Houlsby et al.",institutions:["Google","MIT"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:397,abstract:"Existing pre-trained models are generally geared towards a particular class of problems. To date, there seems to be still no consensus on what the right architecture and pre-training setup should be. This paper presents a unified framework for pre-training models that are universally effective across datasets and setups. We begin by disentangling architectural archetypes with pre-training objectives -- two concepts that are commonly conflated. Next, we present a generalized&unified perspective for self-supervision in NLP and show how different pre-training objectives can be cast as one another and how interpolating between different objectives can be effective. We then propose Mixture-of-Denoisers (MoD), a pre-training objective that combines diverse pre-training paradigms together. We furthermore introduce a notion of mode switching, wherein downstream fine-tuning is associated with specific pre-training schemes. We conduct extensive ablative experiments to compare multiple pre-training objectives and find that our method pushes the Pareto-frontier by outperforming T5&GPT-like models across multiple diverse setups. By scaling our model up to 20B parameters, we achieve SOTA performance on 50 well-established supervised finetuning based NLP tasks. Our model also achieve strong results at in-context learning, outperforming 175B GPT-3 on zero-shot SuperGLUE and tripling the performance of T5-XXL on one-shot summarization. On 0-shot MMLU, UL2 20B outperforms T0 and T5 models. UL2 20B also works well with chain-of-thought prompting and reasoning, making it an appealing choice for research into reasoning at a small to medium scale of 20B parameters. Finally, we apply FLAN instruction tuning to the UL2 20B model, achieving MMLU and Big-Bench scores competitive to FLAN-PaLM 62B. We release Flax-based T5X checkpoints for the UL2 20B&Flan-UL2 20B.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:261,oaid:"d756c70a3cb6df2fdf52f0027942f10712ebde56",doi:"10.1609/AIMAG.V6I4.510",title:"CYC: Using Common Sense Knowledge to Overcome Brittleness and Knowledge Acquisition Bottlenecks",authors:[{name:"D. Lenat",institutions:[]},{name:"M. Prakash",institutions:[]},{name:"M. Shepherd",institutions:[]}],authorString:"D. Lenat; M. Prakash; M. Shepherd",institutions:[],countries:[],year:1986,journal:"The AI Magazine",citations:397,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:262,oaid:"d379ba96b8f400b23b2cd72c428af67e578959ea",doi:"10.1109/ICCV.2019.01041",title:"Relation-Aware Graph Attention Network for Visual Question Answering",authors:[{name:"Linjie Li",institutions:["Microsoft"]},{name:"Zhe Gan",institutions:["Microsoft"]},{name:"Yu Cheng",institutions:["The Chinese University of Hong Kong"]},{name:"Jingjing Liu",institutions:[]}],authorString:"Linjie Li; Zhe Gan; Yu Cheng; Jingjing Liu",institutions:["Microsoft","The Chinese University of Hong Kong"],countries:[],year:2019,journal:"IEEE International Conference on Computer Vision",citations:396,abstract:"In order to answer semantically-complicated questions about an image, a Visual Question Answering (VQA) model needs to fully understand the visual scene in the image, especially the interactive dynamics between different objects. We propose a Relation-aware Graph Attention Network (ReGAT), which encodes each image into a graph and models multi-type inter-object relations via a graph attention mechanism, to learn question-adaptive relation representations. Two types of visual object relations are explored: (i) Explicit Relations that represent geometric positions and semantic interactions between objects; and (ii) Implicit Relations that capture the hidden dynamics between image regions. Experiments demonstrate that ReGAT outperforms prior state-of-the-art approaches on both VQA 2.0 and VQA-CP v2 datasets. We further show that ReGAT is compatible to existing VQA architectures, and can be used as a generic relation encoder to boost the model performance for VQA.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/1903.12314",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:3,deg_w:4,betweenness:0,pagerank:36e-5,eigenvector:0},{id:263,oaid:"0d21adbba3a679c95d52544a05cfc40a510da129",doi:"10.1111/1467-8624.00224",title:"Detecting blickets: how young children use information about novel causal powers in categorization and induction.",authors:[{name:"A. Gopnik",institutions:[]},{name:"David M. Sobel",institutions:[]}],authorString:"A. Gopnik; David M. Sobel",institutions:[],countries:[],year:2e3,journal:"Child Development",citations:396,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:264,oaid:"935b064c82edfd83993fef8aec29d3ed8ad0a378",doi:"10.1145/3828.3833",title:"A simple on-line bin-packing algorithm",authors:[{name:"Chung-Chieh Lee",institutions:[]},{name:"Der-Tsai Lee",institutions:[]}],authorString:"Chung-Chieh Lee; Der-Tsai Lee",institutions:[],countries:[],year:1985,journal:"JACM",citations:394,abstract:"",keywords:[],concepts:[],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3828.3833",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:8,deg_w:13.5,betweenness:0,pagerank:.00112,eigenvector:0},{id:265,oaid:"521ccc898395a2818fced22b4cf371b0e5121f94",doi:"10.18653/v1/2022.naacl-main.341",title:"Symbolic Knowledge Distillation: from General Language Models to Commonsense Models",authors:[{name:"Peter West",institutions:["Allen Institute for AI","University of Washington"]},{name:"Chandrasekhar Bhagavatula",institutions:[]},{name:"Jack Hessel",institutions:["AI2"]},{name:"Jena D. Hwang",institutions:[]},{name:"Liwei Jiang",institutions:[]},{name:"Ronan Le Bras",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Ximing Lu",institutions:["University of Washington"]},{name:"S. Welleck",institutions:[]},{name:"Yejin Choi",institutions:[]}],authorString:"Peter West; Chandrasekhar Bhagavatula; Jack Hessel; Jena D. Hwang; Liwei Jiang; Ronan Le Bras; Ximing Lu; S. Welleck; Yejin Choi",institutions:["AI2","Allen Institute for AI","Allen Institute for Artificial Intelligence","University of Washington"],countries:[],year:2021,journal:"North American Chapter of the Association for Computational Linguistics",citations:393,abstract:"The common practice for training commonsense models has gone from–human–to–corpus–to–machine: humans author commonsense knowledge graphs in order to train commonsense models. In this work, we investigate an alternative, from–machine–to–corpus–to–machine: general language models author these commonsense knowledge graphs to train commonsense models. Our study leads to a new framework, Symbolic Knowledge Distillation. As with prior art in Knowledge Distillation (Hinton et al. 2015), our approach uses larger models to teach smaller models. A key difference is that we distill knowledge symbolically–as text–in addition to the neural model. We distill only one aspect–the commonsense of a general language model teacher, allowing the student to be a different type, a commonsense model. Altogether, we show that careful prompt engineering and a separately trained critic model allow us to selectively distill high-quality causal commonsense from GPT-3, a general language model. Empirical results demonstrate that, for the first time, a human-authored commonsense knowledge graph is surpassed by our automatically distilled variant in all three criteria: quantity, quality, and diversity. In addition, it results in a neural commonsense model that surpasses the teacher model’s commonsense capabilities despite its 100x smaller size. We apply this to the ATOMIC resource, and will share our new symbolic knowledge graph and commonsense models.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://aclanthology.org/2022.naacl-main.341.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:266,oaid:"a222764ed0176fc1d32ab5cab6588f6e9e426b45",doi:"10.1007/978-3-030-11298-1",title:"An Introduction to Kolmogorov Complexity and Its Applications",authors:[{name:"Ming Li",institutions:[]},{name:"P. Vitányi",institutions:[]}],authorString:"Ming Li; P. Vitányi",institutions:[],countries:[],year:2019,journal:"Texts in Computer Science",citations:387,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:8,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:267,oaid:"308388616c12158423fbf8bd8c441d11d1f432a2",doi:"10.1145/2451116.2451150",title:"Stochastic superoptimization",authors:[{name:"Eric Schkufza",institutions:[]},{name:"Rahul Sharma",institutions:[]},{name:"A. Aiken",institutions:[]}],authorString:"Eric Schkufza; Rahul Sharma; A. Aiken",institutions:[],countries:[],year:2012,journal:"International Conference on Architectural Support for Programming Languages and Operating Systems",citations:386,abstract:"We formulate the loop-free binary superoptimization task as a stochastic search problem. The competing constraints of transformation correctness and performance improvement are encoded as terms in a cost function, and a Markov Chain Monte Carlo sampler is used to rapidly explore the space of all possible programs to find one that is an optimization of a given target program. Although our method sacrifices completeness, the scope of programs we are able to consider, and the resulting quality of the programs that we produce, far exceed those of existing superoptimizers. Beginning from binaries compiled by llvm -O0 for 64-bit x86, our prototype implementation, STOKE, is able to produce programs which either match or outperform the code produced by gcc -O3, icc -O3, and in some cases, expert handwritten assembly.",keywords:[],concepts:[],pdf_url:"http://theory.stanford.edu/~aiken/publications/papers/asplos13.pdf",is_oa:!0,n_refs:18,n_refs_in_core:2,degree:3,community:7,deg_w:12,betweenness:.001,pagerank:99e-5,eigenvector:0},{id:268,oaid:"27be68e7adee09e7c02b1873b3c318298fe87032",doi:null,title:"Causality: Models",authors:[],authorString:"",institutions:[],countries:[],year:2e3,journal:"",citations:384,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:269,oaid:"492ba3ad3f0cb85f0636bc275fecd7e7960709da",doi:null,title:"A Meta-Transfer Objective for Learning to Disentangle Causal Mechanisms",authors:[{name:"Yoshua Bengio",institutions:[]},{name:"T. Deleu",institutions:[]},{name:"Nasim Rahaman",institutions:[]},{name:"Nan Rosemary Ke",institutions:[]},{name:"Sébastien Lachapelle",institutions:[]},{name:"O. Bilaniuk",institutions:[]},{name:"Anirudh Goyal",institutions:["Mila, University of Montreal"]},{name:"C. Pal",institutions:[]}],authorString:"Yoshua Bengio; T. Deleu; Nasim Rahaman; Nan Rosemary Ke; Sébastien Lachapelle; O. Bilaniuk; Anirudh Goyal; C. Pal",institutions:["Mila, University of Montreal"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:382,abstract:"We propose to meta-learn causal structures based on how fast a learner adapts to new distributions arising from sparse distributional changes, e.g. due to interventions, actions of agents and other sources of non-stationarities. We show that under this assumption, the correct causal structural choices lead to faster adaptation to modified distributions because the changes are concentrated in one or just a few mechanisms when the learned knowledge is modularized appropriately. This leads to sparse expected gradients and a lower effective number of degrees of freedom needing to be relearned while adapting to the change. It motivates using the speed of adaptation to a modified distribution as a meta-learning objective. We demonstrate how this can be used to determine the cause-effect relationship between two observed variables. The distributional changes do not need to correspond to standard interventions (clamping a variable), and the learner has no direct knowledge of these interventions. We show that causal structures can be parameterized via continuous variables and learned end-to-end. We then explore how these ideas could be used to also learn an encoder that would map low-level observed variables to unobserved causal variables leading to faster adaptation out-of-distribution, learning a representation space where one can satisfy the assumptions of independent mechanisms and of small and sparse changes in these mechanisms due to actions and non-stationarities.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:65e-5,eigenvector:0},{id:270,oaid:"b2e0f559cc6e1398830f6feafa846a26ab4c234e",doi:"10.1016/J.JNCA.2021.103076",title:"Domain-specific Knowledge Graphs: A survey",authors:[{name:"Bilal Abu-Salih",institutions:[]}],authorString:"Bilal Abu-Salih",institutions:[],countries:[],year:2020,journal:"Journal of Network and Computer Applications",citations:382,abstract:"Knowledge Graphs (KGs) have made a qualitative leap and effected a real revolution in knowledge representation. This is leveraged by the underlying structure of the KG which underpins a better comprehension, reasoning and interpreting of knowledge for both human and machine. Therefore, KGs continue to be used as a main driver to tackle a plethora of real-life problems in dissimilar domains. However, there is no consensus on a plausible and definition to domain KG. Further, in conjunction with several limitations and deficiencies, various domain KG construction approaches are far from perfection. This survey is the first to provide an inclusive definition to the notion of domain KG. Also, a comprehensive review of the state-of-the-art approaches drawn from academic works relevant to seven dissimilar domains of knowledge is provided. The scrutiny of the current approaches reveals a correlated array of limitations and deficiencies. The set of improvements made to address the limitations of the current approaches are introduced followed by recommendations and opportunities for future research directions.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2011.00235",is_oa:!0,n_refs:139,n_refs_in_core:1,degree:2,community:1,deg_w:11.5,betweenness:0,pagerank:73e-5,eigenvector:.0096},{id:271,oaid:"3ac08d8c8210252cef12787539a81b0c8280ee3d",doi:"10.1609/aaai.v35i16.17717",title:"Document-Level Relation Extraction with Adaptive Thresholding and Localized Context Pooling",authors:[{name:"Wenxuan Zhou",institutions:[]},{name:"Kevin Huang",institutions:[]},{name:"Tengyu Ma",institutions:["Stanford University"]},{name:"Jing Huang",institutions:[]}],authorString:"Wenxuan Zhou; Kevin Huang; Tengyu Ma; Jing Huang",institutions:["Stanford University"],countries:[],year:2020,journal:"AAAI Conference on Artificial Intelligence",citations:382,abstract:"Document-level relation extraction (RE) poses new challenges compared to its sentence-level counterpart. One document commonly contains multiple entity pairs, and one entity pair occurs multiple times in the document associated with multiple possible relations. In this paper, we propose two novel techniques, adaptive thresholding and localized context pooling, to solve the multi-label and multi-entity problems. The adaptive thresholding replaces the global threshold for multi-label classification in the prior work with a learnable entities-dependent threshold. The localized context pooling directly transfers attention from pre-trained language models to locate relevant context that is useful to decide the relation. We experiment on three document-level RE benchmark datasets: DocRED, a recently released large-scale RE dataset, and two datasets CDRand GDA in the biomedical domain. Our ATLOP (Adaptive Thresholding and Localized cOntext Pooling) model achieves an F1 score of 63.4, and also significantly outperforms existing models on both CDR and GDA. We have released our code at https://github.com/wzhouad/ATLOP.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/17717/17524",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:272,oaid:"412250739a306210863f55f22fb486bc4f05203e",doi:null,title:"Proceedings of the Twenty-Second International Joint Conference on Artificial Intelligence SDD: A New Canonical Representation of Propositional Knowledge Bases",authors:[],authorString:"",institutions:[],countries:[],year:null,journal:"",citations:381,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:13,betweenness:0,pagerank:78e-5,eigenvector:1e-4},{id:273,oaid:"097889e0b93591d75de08f9da661ff882a1532f6",doi:"10.17863/CAM.42159",title:"Learning Disentangled Representations with Semi-Supervised Deep Generative Models",authors:[{name:"Siddharth Narayanaswamy",institutions:[]},{name:"Brooks Paige",institutions:[]},{name:"Jan-Willem van de Meent",institutions:[]},{name:"Alban Desmaison",institutions:[]},{name:"Noah D. Goodman",institutions:[]},{name:"Pushmeet Kohli",institutions:[]},{name:"Frank D. Wood",institutions:[]},{name:"Philip H. S. Torr",institutions:[]}],authorString:"Siddharth Narayanaswamy; Brooks Paige; Jan-Willem van de Meent; Alban Desmaison; Noah D. Goodman; Pushmeet Kohli; Frank D. Wood; Philip H. S. Torr",institutions:[],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:378,abstract:"Variational autoencoders (VAEs) learn representations of data by jointly training a probabilistic encoder and decoder network. Typically these models encode all features of the data into a single variable. Here we are interested in learning disentangled representations that encode distinct aspects of the data into separate variables. We propose to learn such representations using model architectures that generalise from standard VAEs, employing a general graphical model structure in the encoder and decoder. This allows us to train partially-specified models that make relatively strong assumptions about a subset of interpretable variables and rely on the flexibility of neural networks to learn representations for the remaining variables. We further define a general objective for semi-supervised learning in this model class, which can be approximated using an importance sampling procedure. We evaluate our framework's ability to learn disentangled representations, both by qualitative exploration of its generative capacity, and quantitative evaluation of its discriminative ability on a variety of models and datasets.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:36,n_refs_in_core:2,degree:13,community:2,deg_w:77.5,betweenness:.0018,pagerank:.00256,eigenvector:2e-4},{id:274,oaid:"8161b5b6cd925fff18a836987ce140d633031439",doi:"10.1037/0003-066X.44.2.134",title:"A perspective on thinking.",authors:[{name:"J. Greeno",institutions:[]}],authorString:"J. Greeno",institutions:[],countries:[],year:1989,journal:"",citations:375,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:3,deg_w:4,betweenness:0,pagerank:36e-5,eigenvector:0},{id:275,oaid:"c09ff6965322ece56bce383266c75159234f59c4",doi:"10.18653/v1/2021.acl-long.451",title:"A Unified Generative Framework for Various NER Subtasks",authors:[{name:"Hang Yan",institutions:[]},{name:"Tao Gui",institutions:[]},{name:"Junqi Dai",institutions:[]},{name:"Qipeng Guo",institutions:["Fudan University"]},{name:"Zheng Zhang",institutions:[]},{name:"Xipeng Qiu",institutions:["Fudan University"]}],authorString:"Hang Yan; Tao Gui; Junqi Dai; Qipeng Guo; Zheng Zhang; Xipeng Qiu",institutions:["Fudan University"],countries:[],year:2021,journal:"Annual Meeting of the Association for Computational Linguistics",citations:374,abstract:"Named Entity Recognition (NER) is the task of identifying spans that represent entities in sentences. Whether the entity spans are nested or discontinuous, the NER task can be categorized into the flat NER, nested NER, and discontinuous NER subtasks. These subtasks have been mainly solved by the token-level sequence labelling or span-level classification. However, these solutions can hardly tackle the three kinds of NER subtasks concurrently. To that end, we propose to formulate the NER subtasks as an entity span sequence generation task, which can be solved by a unified sequence-to-sequence (Seq2Seq) framework. Based on our unified framework, we can leverage the pre-trained Seq2Seq model to solve all three kinds of NER subtasks without the special design of the tagging schema or ways to enumerate spans. We exploit three types of entity representations to linearize entities into a sequence. Our proposed framework is easy-to-implement and achieves state-of-the-art (SoTA) or near SoTA performance on eight English NER datasets, including two flat NER datasets, three nested NER datasets, and three discontinuous NER datasets.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.acl-long.451.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:1,community:1,deg_w:4,betweenness:0,pagerank:37e-5,eigenvector:.0054},{id:276,oaid:"a6fdb277d0a4b09899f802bda3359f5c2021a156",doi:null,title:"Recursively Summarizing Books with Human Feedback",authors:[{name:"Jeff Wu",institutions:[]},{name:"Long Ouyang",institutions:[]},{name:"Daniel M. Ziegler",institutions:[]},{name:"Nissan Stiennon",institutions:[]},{name:"Ryan Lowe",institutions:[]},{name:"Jan Leike",institutions:[]},{name:"P. Christiano",institutions:[]}],authorString:"Jeff Wu; Long Ouyang; Daniel M. Ziegler; Nissan Stiennon; Ryan Lowe; Jan Leike; P. Christiano",institutions:[],countries:[],year:2021,journal:"arXiv.org",citations:373,abstract:"A major challenge for scaling machine learning is training models to perform tasks that are very difficult or time-consuming for humans to evaluate. We present progress on this problem on the task of abstractive summarization of entire fiction novels. Our method combines learning from human feedback with recursive task decomposition: we use models trained on smaller parts of the task to assist humans in giving feedback on the broader task. We collect a large volume of demonstrations and comparisons from human labelers, and fine-tune GPT-3 using behavioral cloning and reward modeling to do summarization recursively. At inference time, the model first summarizes small sections of the book and then recursively summarizes these summaries to produce a summary of the entire book. Our human labelers are able to supervise and evaluate the models quickly, despite not having read the entire books themselves. Our resulting model generates sensible summaries of entire books, even matching the quality of human-written summaries in a few cases ($\\sim5\\%$ of books). We achieve state-of-the-art results on the recent BookSum dataset for book-length summarization. A zero-shot question-answering model using these summaries achieves state-of-the-art results on the challenging NarrativeQA benchmark for answering questions about books and movie scripts. We release datasets of samples from our model.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:4,deg_w:17,betweenness:3e-4,pagerank:82e-5,eigenvector:9e-4},{id:277,oaid:"2606e6a5759c030e259ebf3f4261b9c04a36a609",doi:"10.18653/v1/W15-2812",title:"Generating Semantically Precise Scene Graphs from Textual Descriptions for Improved Image Retrieval",authors:[{name:"Sebastian Schuster",institutions:["University College London","University of Vienna"]},{name:"Ranjay Krishna",institutions:["University of Washington"]},{name:"Angel X. Chang",institutions:[]},{name:"Li Fei-Fei",institutions:[]},{name:"Christopher D. Manning",institutions:["Stanford University"]}],authorString:"Sebastian Schuster; Ranjay Krishna; Angel X. Chang; Li Fei-Fei; Christopher D. Manning",institutions:["Stanford University","University College London","University of Vienna","University of Washington"],countries:[],year:2015,journal:"VL@EMNLP",citations:371,abstract:"Semantically complex queries which include attributes of objects and relations between objects still pose a major challenge to image retrieval systems. Recent work in computer vision has shown that a graph-based semantic representation called a scene graph is an effective representation for very detailed image descriptions and for complex queries for retrieval. In this paper, we show that scene graphs can be effectively created automatically from a natural language scene description. We present a rule-based and a classifierbased scene graph parser whose output can be used for image retrieval. We show that including relations and attributes in the query graph outperforms a model that only considers objects and that using the output of our parsers is almost as effective as using human-constructed scene graphs (Recall@10 of 27.1% vs. 33.4%). Additionally, we demonstrate the general usefulness of parsing to scene graphs by showing that the output can also be used to generate 3D scenes.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/W15-2812.pdf",is_oa:!0,n_refs:32,n_refs_in_core:1,degree:6,community:3,deg_w:35.5,betweenness:1e-4,pagerank:99e-5,eigenvector:2e-4},{id:278,oaid:"17230f5b3956188055a48c5f4f61d131cce0662f",doi:"10.1162/tacl_a_00160",title:"Parsing Algebraic Word Problems into Equations",authors:[{name:"Rik Koncel-Kedziorski",institutions:[]},{name:"Hannaneh Hajishirzi",institutions:[]},{name:"Ashish Sabharwal",institutions:[]},{name:"Oren Etzioni",institutions:[]},{name:"S. Ang",institutions:[]}],authorString:"Rik Koncel-Kedziorski; Hannaneh Hajishirzi; Ashish Sabharwal; Oren Etzioni; S. Ang",institutions:[],countries:[],year:2015,journal:"Transactions of the Association for Computational Linguistics",citations:369,abstract:"This paper formalizes the problem of solving multi-sentence algebraic word problems as that of generating and scoring equation trees. We use integer linear programming to generate equation trees and score their likelihood by learning local and global discriminative models. These models are trained on a small set of word problems and their answers, without any manual annotation, in order to choose the equation that best matches the problem text. We refer to the overall system as Alges. We compare Alges with previous work and show that it covers the full gamut of arithmetic operations whereas Hosseini et al. (2014) only handle addition and subtraction. In addition, Alges overcomes the brittleness of the Kushman et al. (2014) approach on single-equation problems, yielding a 15% to 50% reduction in error.",keywords:[],concepts:[],pdf_url:"http://www.mitpressjournals.org/doi/pdf/10.1162/tacl_a_00160",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:5,deg_w:12.5,betweenness:0,pagerank:63e-5,eigenvector:.001},{id:279,oaid:"67a9dde04f367efc903b6d06097df9bdd9887ae7",doi:null,title:"Recurrent Independent Mechanisms",authors:[{name:"Anirudh Goyal",institutions:["Mila, University of Montreal"]},{name:"Alex Lamb",institutions:["Montreal Institute for Learning Algorithms (MILA)"]},{name:"Jordan Hoffmann",institutions:[]},{name:"Shagun Sodhani",institutions:[]},{name:"S. Levine",institutions:[]},{name:"Yoshua Bengio",institutions:[]},{name:"B. Scholkopf",institutions:[]}],authorString:"Anirudh Goyal; Alex Lamb; Jordan Hoffmann; Shagun Sodhani; S. Levine; Yoshua Bengio; B. Scholkopf",institutions:["Mila, University of Montreal","Montreal Institute for Learning Algorithms (MILA)"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:369,abstract:"Learning modular structures which reflect the dynamics of the environment can lead to better generalization and robustness to changes which only affect a few of the underlying causes. We propose Recurrent Independent Mechanisms (RIMs), a new recurrent architecture in which multiple groups of recurrent cells operate with nearly independent transition dynamics, communicate only sparingly through the bottleneck of attention, and are only updated at time steps where they are most relevant. We show that this leads to specialization amongst the RIMs, which in turn allows for dramatically improved generalization on tasks where some factors of variation differ systematically between training and evaluation.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:46e-5,eigenvector:0},{id:280,oaid:"92e5e019f6723e6a2dae19cb0c9fe41adda2ca35",doi:"10.1145/2737924.2737977",title:"Synthesizing data structure transformations from input-output examples",authors:[{name:"John K. Feser",institutions:[]},{name:"Swarat Chaudhuri",institutions:[]},{name:"Işıl Dillig",institutions:[]}],authorString:"John K. Feser; Swarat Chaudhuri; Işıl Dillig",institutions:[],countries:[],year:2015,journal:"ACM-SIGPLAN Symposium on Programming Language Design and Implementation",citations:366,abstract:"",keywords:[],concepts:[],pdf_url:"http://www.cs.utexas.edu/%7Eisil/pldi15b.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:281,oaid:"2ee629820b95f311927d24570d7719bd2843f66d",doi:"10.1609/aaai.v31i1.10934",title:"Label-Free Supervision of Neural Networks with Physics and Domain Knowledge",authors:[{name:"Russell Stewart",institutions:[]},{name:"S. Ermon",institutions:[]}],authorString:"Russell Stewart; S. Ermon",institutions:[],countries:[],year:2016,journal:"AAAI Conference on Artificial Intelligence",citations:363,abstract:"In many machine learning applications, labeled data is scarce and obtaining more labels is expensive. We introduce a new approach to supervising neural networks by specifying constraints that should hold over the output space, rather than direct examples of input-output pairs. These constraints are derived from prior domain knowledge, e.g., from known laws of physics. We demonstrate the effectiveness of this approach on real world and simulated computer vision tasks. We are able to train a convolutional neural network to detect and track objects without any labeled examples. Our approach can significantly reduce the need for labeled training data, but introduces new challenges for encoding prior knowledge into appropriate loss functions.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1609/aaai.v31i1.10934",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:1e-4,pagerank:55e-5,eigenvector:0},{id:282,oaid:"adfc4a14e319bd4a49b88452c74b03d7ae4400eb",doi:"10.1613/jair.5575",title:"From Skills to Symbols: Learning Symbolic Representations for Abstract High-Level Planning",authors:[{name:"G. Konidaris",institutions:[]},{name:"L. Kaelbling",institutions:[]},{name:"Tomas Lozano-Perez",institutions:["Massachusetts Institute of Technology"]}],authorString:"G. Konidaris; L. Kaelbling; Tomas Lozano-Perez",institutions:["Massachusetts Institute of Technology"],countries:[],year:2018,journal:"Journal of Artificial Intelligence Research",citations:363,abstract:"We consider the problem of constructing abstract representations for planning in high-dimensional, continuous environments. We assume an agent equipped with a collection of high-level actions, and construct representations provably capable of evaluating plans composed of sequences of those actions. We first consider the deterministic planning case, and show that the relevant computation involves set operations performed over sets of states. We define the specific collection of sets that is necessary and sufficient for planning, and use them to construct a grounded abstract symbolic representation that is provably suitable for deterministic planning. The resulting representation can be expressed in PDDL, a canonical high-level planning domain language; we construct such a representation for the Playroom domain and solve it in milliseconds using an off-the-shelf planner. We then consider probabilistic planning, which we show requires generalizing from sets of states to distributions over states. We identify the specific distributions required for planning, and use them to construct a grounded abstract symbolic representation that correctly estimates the expected reward and probability of success of any plan. In addition, we show that learning the relevant probability distributions corresponds to specific instances of probabilistic density estimation and probabilistic classification. We construct an agent that autonomously learns the correct abstract representation of a computer game domain, and rapidly solves it. Finally, we apply these techniques to create a physical robot system that autonomously learns its own symbolic representation of a mobile manipulation task directly from sensorimotor data---point clouds, map locations, and joint angles---and then plans using that representation. Together, these results establish a principled link between high-level actions and abstract representations, a concrete theoretical foundation for constructing abstract representations with provable properties, and a practical mechanism for autonomously learning abstract high-level representations.",keywords:[],concepts:[],pdf_url:"https://jair.org/index.php/jair/article/download/11175/26380",is_oa:!0,n_refs:76,n_refs_in_core:1,degree:5,community:4,deg_w:21,betweenness:.0039,pagerank:.00133,eigenvector:1e-4},{id:283,oaid:"cf18287e79b1fd73cd333fc914bb24c00a537f4c",doi:null,title:"Self-Supervised Visual Planning with Temporal Skip Connections",authors:[{name:"F. Ebert",institutions:[]},{name:"Chelsea Finn",institutions:[]},{name:"Alex X. Lee",institutions:[]},{name:"S. Levine",institutions:[]}],authorString:"F. Ebert; Chelsea Finn; Alex X. Lee; S. Levine",institutions:[],countries:[],year:2017,journal:"Conference on Robot Learning",citations:363,abstract:"In order to autonomously learn wide repertoires of complex skills, robots must be able to learn from their own autonomously collected data, without human supervision. One learning signal that is always available for autonomously collected data is prediction: if a robot can learn to predict the future, it can use this predictive model to take actions to produce desired outcomes, such as moving an object to a particular location. However, in complex open-world scenarios, designing a representation for prediction is difficult. In this work, we instead aim to enable self-supervised robotic learning through direct video prediction: instead of attempting to design a good representation, we directly predict what the robot will see next, and then use this model to achieve desired goals. A key challenge in video prediction for robotic manipulation is handling complex spatial arrangements such as occlusions. To that end, we introduce a video prediction model that can keep track of objects through occlusion by incorporating temporal skip-connections. Together with a novel planning criterion and action space formulation, we demonstrate that this model substantially outperforms prior work on video prediction-based control. Our results show manipulation of objects not seen during training, handling multiple objects, and pushing objects around obstructions. These results represent a significant advance in the range and complexity of skills that can be performed entirely with self-supervised robotic learning.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:26,n_refs_in_core:2,degree:4,community:2,deg_w:30,betweenness:1e-4,pagerank:.00114,eigenvector:1e-4},{id:284,oaid:"87aa2524ac337cdccebf5cebfeeb84c02ffe6f7a",doi:"10.1145/585265.585269",title:"On the online bin packing problem",authors:[{name:"S. Seiden",institutions:[]}],authorString:"S. Seiden",institutions:[],countries:[],year:2001,journal:"JACM",citations:358,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:79e-5,eigenvector:0},{id:285,oaid:"08dc7b19e679539f0f93db0192a8e8d11538b3dd",doi:"10.1006/COGP.1998.0694",title:"Rethinking eliminative connectionism.",authors:[{name:"G. Marcus",institutions:[]}],authorString:"G. Marcus",institutions:[],countries:[],year:1998,journal:"Cognitive Psychology",citations:357,abstract:'Humans routinely generalize universal relationships to unfamiliar instances. If we are told "if glork then frum," and "glork," we can infer "frum"; any name that serves as the subject of a sentence can appear as the object of a sentence. These universals are pervasive in language and reasoning. One account of how they are generalized holds that humans possess mechanisms that manipulate symbols and variables; an alternative account holds that symbol-manipulation can be eliminated from scientific theories in favor of descriptions couched in terms of networks of interconnected nodes. Can these "eliminative" connectionist models offer a genuine alternative? This article shows that eliminative connectionist models cannot account for how we extend universals to arbitrary items. The argument runs as follows. First, if these models, as currently conceived, were to extend universals to arbitrary instances, they would have to generalize outside the space of training examples. Next, it is shown that the class of eliminative connectionist models that is currently popular cannot learn to extend universals outside the training space. This limitation might be avoided through the use of an architecture that implements symbol manipulation.',keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://www.sciencedirect.com/science/article/pii/S0010028598906946/pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:286,oaid:"a79b694bd4ef51207787da1948ed473903b751ef",doi:null,title:"Bottom-Up and Top-Down Attention for Image Captioning and VQA",authors:[{name:"Peter Anderson",institutions:["Google Research"]},{name:"Xiaodong He",institutions:[]},{name:"Chris Buehler",institutions:[]},{name:"Damien Teney",institutions:["Idiap Research Institute","University of Adelaide"]},{name:"Mark Johnson",institutions:[]},{name:"Stephen Gould",institutions:[]},{name:"Lei Zhang",institutions:["Microsoft"]}],authorString:"Peter Anderson; Xiaodong He; Chris Buehler; Damien Teney; Mark Johnson; Stephen Gould; Lei Zhang",institutions:["Google Research","Idiap Research Institute","Microsoft","University of Adelaide"],countries:[],year:2017,journal:"arXiv.org",citations:357,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8,betweenness:0,pagerank:44e-5,eigenvector:1e-4},{id:287,oaid:"ca8f792d1abe13bb7233a0fa939dc6d5b0d2805d",doi:"10.17863/CAM.42246",title:"Turing: A Language for Flexible Probabilistic Inference",authors:[{name:"Hong Ge",institutions:[]},{name:"Kai Xu",institutions:[]},{name:"Zoubin Ghahramani",institutions:["University of Cambridge"]}],authorString:"Hong Ge; Kai Xu; Zoubin Ghahramani",institutions:["University of Cambridge"],countries:[],year:2018,journal:"",citations:357,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:58e-5,eigenvector:0},{id:288,oaid:"127ffe6d21b75bd41dd808e3313bc392b9428346",doi:"10.18653/v1/D19-1588",title:"BERT for Coreference Resolution: Baselines and Analysis",authors:[{name:"Mandar Joshi",institutions:["University of Washington"]},{name:"Omer Levy",institutions:["Meta"]},{name:"Daniel S. Weld",institutions:["Allen Institute of Artificial Intelligence","University of Washington"]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]}],authorString:"Mandar Joshi; Omer Levy; Daniel S. Weld; Luke Zettlemoyer",institutions:["Allen Institute of Artificial Intelligence","Facebook","Meta","University of Washington"],countries:[],year:2019,journal:"Conference on Empirical Methods in Natural Language Processing",citations:351,abstract:"We apply BERT to coreference resolution, achieving a new state of the art on the GAP (+11.5 F1) and OntoNotes (+3.9 F1) benchmarks. A qualitative analysis of model predictions indicates that, compared to ELMo and BERT-base, BERT-large is particularly better at distinguishing between related but distinct entities (e.g., President and CEO), but that there is still room for improvement in modeling document-level context, conversations, and mention paraphrasing. We will release all code and trained models upon publication.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D19-1588.pdf",is_oa:!0,n_refs:23,n_refs_in_core:1,degree:8,community:1,deg_w:62,betweenness:1e-4,pagerank:.00174,eigenvector:.024},{id:289,oaid:"644ca74f80463415613847ab01cff067fb58f0ad",doi:null,title:"Neuro-Symbolic Program Synthesis",authors:[{name:"Emilio Parisotto",institutions:[]},{name:"Abdel-rahman Mohamed",institutions:[]},{name:"Rishabh Singh",institutions:[]},{name:"Lihong Li",institutions:[]},{name:"Dengyong Zhou",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"Emilio Parisotto; Abdel-rahman Mohamed; Rishabh Singh; Lihong Li; Dengyong Zhou; Pushmeet Kohli",institutions:[],countries:[],year:2016,journal:"International Conference on Learning Representations",citations:349,abstract:"Recent years have seen the proposal of a number of neural architectures for the problem of Program Induction. Given a set of input-output examples, these architectures are able to learn mappings that generalize to new test inputs. While achieving impressive results, these approaches have a number of important limitations: (a) they are computationally expensive and hard to train, (b) a model has to be trained for each task (program) separately, and (c) it is hard to interpret or verify the correctness of the learnt mapping (as it is defined by a neural network). In this paper, we propose a novel technique, Neuro-Symbolic Program Synthesis, to overcome the above-mentioned problems. Once trained, our approach can automatically construct computer programs in a domain-specific language that are consistent with a set of input-output examples provided at test time. Our method is based on two novel neural modules. The first module, called the cross correlation I/O network, given a set of input-output examples, produces a continuous representation of the set of I/O examples. The second module, the Recursive-Reverse-Recursive Neural Network (R3NN), given the continuous representation of the examples, synthesizes a program by incrementally expanding partial programs. We demonstrate the effectiveness of our approach by applying it to the rich and complex domain of regular expression based string transformations. Experiments show that the R3NN model is not only able to construct programs from new input-output examples, but it is also able to construct new programs for tasks that it had never observed before during training.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12,betweenness:.0013,pagerank:6e-4,eigenvector:1e-4},{id:290,oaid:"8e759195eb4b4f0f480a8a2cf1c629bfd881d4e5",doi:"10.18653/v1/D16-1203",title:"Analyzing the Behavior of Visual Question Answering Models",authors:[{name:"Aishwarya Agrawal",institutions:[]},{name:"Dhruv Batra",institutions:[]},{name:"Devi Parikh",institutions:[]}],authorString:"Aishwarya Agrawal; Dhruv Batra; Devi Parikh",institutions:[],countries:[],year:2016,journal:"Conference on Empirical Methods in Natural Language Processing",citations:347,abstract:`Recently, a number of deep-learning based models have been proposed for the task of Visual Question Answering (VQA). The performance of most models is clustered around 60-70%. In this paper we propose systematic methods to analyze the behavior of these models as a first step towards recognizing their strengths and weaknesses, and identifying the most fruitful directions for progress. We analyze two models, one each from two major classes of VQA models -- with-attention and without-attention and show the similarities and differences in the behavior of these models. We also analyze the winning entry of the VQA Challenge 2016. Our behavior analysis reveals that despite recent progress, today's VQA models are "myopic" (tend to fail on sufficiently novel instances), often "jump to conclusions" (converge on a predicted answer after 'listening' to just half the question), and are "stubborn" (do not change their answers across images).`,keywords:[],concepts:[],pdf_url:"https://doi.org/10.18653/v1/d16-1203",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:13,betweenness:0,pagerank:54e-5,eigenvector:1e-4},{id:291,oaid:"a50b7a45f704f30d7f97dd229d4d53433d5df3b1",doi:null,title:"GENESIS: Generative Scene Inference and Sampling with Object-Centric Latent Representations",authors:[{name:"Martin Engelcke",institutions:["Google DeepMind"]},{name:"Adam R. Kosiorek",institutions:[]},{name:"Oiwi Parker Jones",institutions:["University of Oxford"]},{name:"I. Posner",institutions:[]}],authorString:"Martin Engelcke; Adam R. Kosiorek; Oiwi Parker Jones; I. Posner",institutions:["Google DeepMind","University of Oxford"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:343,abstract:"Generative latent-variable models are emerging as promising tools in robotics and reinforcement learning. Yet, even though tasks in these domains typically involve distinct objects, most state-of-the-art generative models do not explicitly capture the compositional nature of visual scenes. Two recent exceptions, MONet and IODINE, decompose scenes into objects in an unsupervised fashion. Their underlying generative processes, however, do not account for component interactions. Hence, neither of them allows for principled sampling of novel scenes. Here we present GENESIS, the first object-centric generative model of 3D visual scenes capable of both decomposing and generating scenes by capturing relationships between scene components. GENESIS parameterises a spatial GMM over images which is decoded from a set of object-centric latent variables that are either inferred sequentially in an amortised fashion or sampled from an autoregressive prior. We train GENESIS on several publicly available datasets and evaluate its performance on scene generation, decomposition, and semi-supervised learning.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:60,n_refs_in_core:6,degree:12,community:2,deg_w:69,betweenness:.0028,pagerank:.00274,eigenvector:2e-4},{id:292,oaid:"f09d36476445c7f44d46555a753eae446cfed180",doi:"10.1145/1480881.1480915",title:"Equality saturation: a new approach to optimization",authors:[{name:"R. Tate",institutions:[]},{name:"M. Stepp",institutions:[]},{name:"Zachary Tatlock",institutions:["University of Washington"]},{name:"Sorin Lerner",institutions:[]}],authorString:"R. Tate; M. Stepp; Zachary Tatlock; Sorin Lerner",institutions:["University of Washington"],countries:[],year:2009,journal:"ACM-SIGACT Symposium on Principles of Programming Languages",citations:341,abstract:"Optimizations in a traditional compiler are applied sequentially, with each optimization destructively modifying the program to produce a transformed program that is then passed to the next optimization. We present a new approach for structuring the optimization phase of a compiler. In our approach, optimizations take the form of equality analyses that add equality information to a common intermediate representation. The optimizer works by repeatedly applying these analyses to infer equivalences between program fragments, thus saturating the intermediate representation with equalities. Once saturated, the intermediate representation encodes multiple optimized versions of the input program. At this point, a profitability heuristic picks the final optimized program from the various programs represented in the saturated representation. Our proposed way of structuring optimizers has a variety of benefits over previous approaches: our approach obviates the need to worry about optimization ordering, enables the use of a global optimization heuristic that selects among fully optimized programs, and can be used to perform translation validation, even on compilers other than our own. We present our approach, formalize it, and describe our choice of intermediate representation. We also present experimental results showing that our approach is practical in terms of time and space overhead, is effective at discovering intricate optimization opportunities, and is effective at performing translation validation for a realistic optimizer.",keywords:[],concepts:[],pdf_url:"https://lmcs.episciences.org/1016/pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12.5,betweenness:5e-4,pagerank:97e-5,eigenvector:0},{id:293,oaid:"45d75a53d6df802906a6ca5fa5474cc8962a056f",doi:"10.1007/978-1-4471-0211-3",title:"Neural-symbolic learning systems - foundations and applications",authors:[{name:"A. Garcez",institutions:[]},{name:"K. Broda",institutions:[]},{name:"D. Gabbay",institutions:[]}],authorString:"A. Garcez; K. Broda; D. Gabbay",institutions:[],countries:[],year:2012,journal:"Perspectives in Neural Computing",citations:339,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:13.5,betweenness:0,pagerank:77e-5,eigenvector:2e-4},{id:294,oaid:"2c62b5fe3a8c7c4c5ee00b700b04b2d12a0bb9c7",doi:"10.1016/0166-218X(90)90094-S",title:"Lower bounds and reduction procedures for the bin packing problem",authors:[{name:"S. Martello",institutions:[]},{name:"P. Toth",institutions:[]}],authorString:"S. Martello; P. Toth",institutions:[],countries:[],year:1990,journal:"Discrete Applied Mathematics",citations:337,abstract:"",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1016/0166-218x(90)90094-s",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:79e-5,eigenvector:0},{id:295,oaid:"6602100baa3399b5d3a390d6281a7caadb626ea6",doi:"10.1145/3442381.3450043",title:"Structure-Augmented Text Representation Learning for Efficient Knowledge Graph Completion",authors:[{name:"Bo Wang",institutions:[]},{name:"Tao Shen",institutions:["Univerisity of Technology Sydney"]},{name:"Guodong Long",institutions:[]},{name:"Tianyi Zhou",institutions:["University of Maryland","University of Washington","University of Technology, Sydney","Nanyang Technological University"]},{name:"Yi Chang",institutions:[]}],authorString:"Bo Wang; Tao Shen; Guodong Long; Tianyi Zhou; Yi Chang",institutions:["Nanyang Technological University","Univerisity of Technology Sydney","University of Maryland","University of Technology, Sydney","University of Washington"],countries:[],year:2020,journal:"The Web Conference",citations:337,abstract:"Human-curated knowledge graphs provide critical supportive information to various natural language processing tasks, but these graphs are usually incomplete, urging auto-completion of them (a.k.a. knowledge graph completion). Prevalent graph embedding approaches, e.g., TransE, learn structured knowledge via representing graph elements (i.e., entities/relations) into dense embeddings and capturing their triple-level relationship with spatial distance. However, they are hardly generalizable to the elements never visited in training and are intrinsically vulnerable to graph incompleteness. In contrast, textual encoding approaches, e.g., KG-BERT, resort to graph triple’s text and triple-level contextualized representations. They are generalizable enough and robust to the incompleteness, especially when coupled with pre-trained encoders. But two major drawbacks limit the performance: (1) high overheads due to the costly scoring of all possible triples in inference, and (2) a lack of structured knowledge in the textual encoder. In this paper, we follow the textual encoding paradigm and aim to alleviate its drawbacks by augmenting it with graph embedding techniques – a complementary hybrid of both paradigms. Specifically, we partition each triple into two asymmetric parts as in translation-based graph embedding approach, and encode both parts into contextualized representations by a Siamese-style textual encoder. Built upon the representations, our model employs both deterministic classifier and spatial measurement for representation and structure learning respectively. It thus reduces the overheads by reusing graph elements’ embeddings to avoid combinatorial explosion, and enhances structured knowledge by exploring the spatial characteristics. Moreover, we develop a self-adaptive ensemble scheme to further improve the performance by incorporating triple scores from an existing graph embedding model. In experiments, we achieve state-of-the-art performance on three benchmarks and a zero-shot dataset for link prediction, with highlights of inference costs reduced by 1-2 orders of magnitude compared to a sophisticated textual encoding method.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1145/3442381.3450043",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:.0084},{id:296,oaid:"b6ce4ec0d28c050b99ec647a16e47116c939473c",doi:"10.1145/1273496.1273551",title:"Statistical predicate invention",authors:[{name:"Stanley Kok",institutions:[]},{name:"Pedro M. Domingos",institutions:[]}],authorString:"Stanley Kok; Pedro M. Domingos",institutions:[],countries:[],year:2007,journal:"International Conference on Machine Learning",citations:337,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:53e-5,eigenvector:2e-4},{id:297,oaid:"7f6245d527e84092111a6adb0f1939d0209d3360",doi:"10.1145/2814270.2814310",title:"FlashMeta: a framework for inductive program synthesis",authors:[{name:"Oleksandr Polozov",institutions:["Google"]},{name:"Sumit Gulwani",institutions:[]}],authorString:"Oleksandr Polozov; Sumit Gulwani",institutions:["Google"],countries:[],year:2015,journal:"Conference on Object-Oriented Programming Systems, Languages, and Applications",citations:334,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12.5,betweenness:.0011,pagerank:88e-5,eigenvector:0},{id:298,oaid:"c28e95a06dfcf13fc65a1cac83722f53e34f12a5",doi:"10.48550/arXiv.2205.12615",title:"Autoformalization with Large Language Models",authors:[{name:"Yuhuai Wu",institutions:[]},{name:"Albert Qiaochu Jiang",institutions:["University of Cambridge"]},{name:"Wenda Li",institutions:[]},{name:"M. Rabe",institutions:[]},{name:"Charles Staats",institutions:[]},{name:"M. Jamnik",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"Yuhuai Wu; Albert Qiaochu Jiang; Wenda Li; M. Rabe; Charles Staats; M. Jamnik; Christian Szegedy",institutions:["University of Cambridge"],countries:[],year:2022,journal:"Neural Information Processing Systems",citations:332,abstract:"Autoformalization is the process of automatically translating from natural language mathematics to formal specifications and proofs. A successful autoformalization system could advance the fields of formal verification, program synthesis, and artificial intelligence. While the long-term goal of autoformalization seemed elusive for a long time, we show large language models provide new prospects towards this goal. We make the surprising observation that LLMs can correctly translate a significant portion ($25.3\\%$) of mathematical competition problems perfectly to formal specifications in Isabelle/HOL. We demonstrate the usefulness of this process by improving a previously introduced neural theorem prover via training on these autoformalized theorems. Our methodology results in a new state-of-the-art result on the MiniF2F theorem proving benchmark, improving the proof rate from $29.6\\%$ to $35.2\\%$.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2205.12615",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:6,deg_w:17,betweenness:0,pagerank:72e-5,eigenvector:.001},{id:299,oaid:"824cd8db8a68732db04f4d8b7139eb4475e59ff2",doi:"10.18653/v1/2021.gem-1.10",title:"The GEM Benchmark: Natural Language Generation, its Evaluation and Metrics",authors:[{name:"Sebastian Gehrmann",institutions:["Google Research"]},{name:"Tosin P. Adewumi",institutions:[]},{name:"Karmanya Aggarwal",institutions:[]},{name:"Pawan Sasanka Ammanamanchi",institutions:[]},{name:"Aremu Anuoluwapo",institutions:[]},{name:"Antoine Bosselut",institutions:["EPFL"]},{name:"Khyathi Raghavi Chandu",institutions:[]},{name:"Miruna Clinciu",institutions:["Edinburgh Centre for Robotics"]},{name:"Dipanjan Das",institutions:[]},{name:"Kaustubh D. Dhole",institutions:[]},{name:"Wanyu Du",institutions:[]},{name:"Esin Durmus",institutions:["Stanford University"]},{name:"Ondrej Dusek",institutions:["Charles University"]},{name:"Chris C. Emezue",institutions:[]},{name:"Varun Prashant Gangal",institutions:["Amazon AGI","CMU LTI","ASAPP","ASAPP Inc","Carnegie Mellon University"]},{name:"Cristina Garbacea",institutions:[]},{name:"Tatsunori B. Hashimoto",institutions:[]},{name:"Yufang Hou",institutions:[]},{name:"Yacine Jernite",institutions:["Hugging Face"]},{name:"Harsh Jhamtani",institutions:["Microsoft"]},{name:"Yangfeng Ji",institutions:["University of Virginia"]},{name:"Shailza Jolly",institutions:[]},{name:"Mihir Kale",institutions:[]},{name:"Dhruv Kumar",institutions:["University of Waterloo"]},{name:"Faisal Ladhak",institutions:[]},{name:"Aman Madaan",institutions:["Carnegie Mellon University"]},{name:"Mounica Maddela",institutions:[]},{name:"Khyati Mahajan",institutions:["University of North Carolina at Charlotte"]},{name:"Saad Mahamood",institutions:[]},{name:"Bodhisattwa Prasad Majumder",institutions:["Allen Institute of AI"]},{name:"Pedro Henrique Martins",institutions:[]},{name:"Angelina McMillan-Major",institutions:[]},{name:"Simon Mille",institutions:[]},{name:"Emiel van Miltenburg",institutions:["Tilburg University"]},{name:"Moin Nadeem",institutions:["Massachusetts Institute of Technology","MIT"]},{name:"Shashi Narayan",institutions:[]},{name:"Vitaly Nikolaev",institutions:[]},{name:"Andre Niyongabo Rubungo",institutions:["Princeton University"]},{name:"Salomey Osei",institutions:["University of Deusto"]},{name:"Ankur P. Parikh",institutions:[]},{name:"Laura Perez-Beltrachini",institutions:[]},{name:"Niranjan Rao",institutions:[]},{name:"Vikas Raunak",institutions:[]},{name:"Juan Diego Rodriguez",institutions:["The University of Texas at Austin"]},{name:"Sashank Santhanam",institutions:[]},{name:"João Sedoc",institutions:[]},{name:"Thibault Sellam",institutions:[]},{name:"Samira Shaikh",institutions:[]},{name:"Anastasia Shimorina",institutions:[]},{name:"Marco Antonio Sobrevilla Cabezudo",institutions:["Institute of Mathematics and Computer Sciences","University of São Paulo","Pontifical Catholic University of Peru"]},{name:"Hendrik Strobelt",institutions:[]},{name:"Nishant Subramani",institutions:["Carnegie Mellon University"]},{name:"Wei Xu",institutions:[]},{name:"Diyi Yang",institutions:[]},{name:"Akhila Yerukola",institutions:[]},{name:"Jiawei Zhou",institutions:[]}],authorString:"Sebastian Gehrmann; Tosin P. Adewumi; Karmanya Aggarwal; Pawan Sasanka Ammanamanchi; Aremu Anuoluwapo; Antoine Bosselut; Khyathi Raghavi Chandu; Miruna Clinciu; Dipanjan Das; Kaustubh D. Dhole; Wanyu Du; Esin Durmus et al.",institutions:["ASAPP","ASAPP Inc","Allen Institute of AI","Amazon AGI","CMU LTI","Carnegie Mellon University","Charles University","EPFL","Edinburgh Centre for Robotics","Google Research","Hugging Face","Institute of Mathematics and Computer Sciences","MIT","Massachusetts Institute of Technology","Microsoft","Pontifical Catholic University of Peru","Princeton University","Stanford University","The University of Texas at Austin","Tilburg University","University of Deusto","University of North Carolina at Charlotte","University of São Paulo","University of Virginia","University of Waterloo"],countries:[],year:2021,journal:"IEEE Games Entertainment Media Conference",citations:331,abstract:"We introduce GEM, a living benchmark for natural language Generation (NLG), its Evaluation, and Metrics. Measuring progress in NLG relies on a constantly evolving ecosystem of automated metrics, datasets, and human evaluation standards. Due to this moving target, new models often still evaluate on divergent anglo-centric corpora with well-established, but flawed, metrics. This disconnect makes it challenging to identify the limitations of current models and opportunities for progress. Addressing this limitation, GEM provides an environment in which models can easily be applied to a wide set of tasks and in which evaluation strategies can be tested. Regular updates to the benchmark will help NLG research become more multilingual and evolve the challenge alongside models. This paper serves as the description of the data for the 2021 shared task at the associated GEM Workshop.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://aclanthology.org/2021.gem-1.10.pdf",is_oa:!0,n_refs:141,n_refs_in_core:2,degree:18,community:1,deg_w:108.5,betweenness:.0057,pagerank:.00274,eigenvector:.0355},{id:300,oaid:"59851fe73f811eec5e44a12d2b39934db9174a3d",doi:"10.1109/CVPR.2019.00498",title:"Strike (With) a Pose: Neural Networks Are Easily Fooled by Strange Poses of Familiar Objects",authors:[{name:"Michael A. Alcorn",institutions:[]},{name:"Qi Li",institutions:[]},{name:"Zhitao Gong",institutions:[]},{name:"Chengfei Wang",institutions:[]},{name:"Long Mai",institutions:[]},{name:"Wei-Shinn Ku",institutions:[]},{name:"Anh Totti Nguyen",institutions:["Auburn University"]}],authorString:"Michael A. Alcorn; Qi Li; Zhitao Gong; Chengfei Wang; Long Mai; Wei-Shinn Ku; Anh Totti Nguyen",institutions:["Auburn University"],countries:[],year:2018,journal:"Computer Vision and Pattern Recognition",citations:329,abstract:"Despite excellent performance on stationary test sets, deep neural networks (DNNs) can fail to generalize to out-of-distribution (OoD) inputs, including natural, non-adversarial ones, which are common in real-world settings. In this paper, we present a framework for discovering DNN failures that harnesses 3D renderers and 3D models. That is, we estimate the parameters of a 3D renderer that cause a target DNN to misbehave in response to the rendered image. Using our framework and a self-assembled dataset of 3D objects, we investigate the vulnerability of DNNs to OoD poses of well-known objects in ImageNet. For objects that are readily recognized by DNNs in their canonical poses, DNNs incorrectly classify 97% of their pose space. In addition, DNNs are highly sensitive to slight pose perturbations. Importantly, adversarial poses transfer across models and datasets. We find that 99.9% and 99.4% of the poses misclassified by Inception-v3 also transfer to the AlexNet and ResNet-50 image classifiers trained on the same ImageNet dataset, respectively, and 75.5% transfer to the YOLOv3 object detector trained on MS COCO.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1811.11553",is_oa:!0,n_refs:52,n_refs_in_core:1,degree:5,community:2,deg_w:22.5,betweenness:.001,pagerank:.00146,eigenvector:0},{id:301,oaid:"06996e180cab25c3644387bd93fb6bad6cb76556",doi:"10.1007/978-3-031-01574-8",title:"Statistical Relational Artificial Intelligence: Logic, Probability, and Computation",authors:[{name:"L. D. Raedt",institutions:[]},{name:"K. Kersting",institutions:[]},{name:"Sriraam Natarajan",institutions:[]},{name:"D. Poole",institutions:[]}],authorString:"L. D. Raedt; K. Kersting; Sriraam Natarajan; D. Poole",institutions:[],countries:[],year:2016,journal:"Statistical Relational Artificial Intelligence",citations:328,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:0,deg_w:17,betweenness:0,pagerank:96e-5,eigenvector:1e-4},{id:302,oaid:"f58ca7ba4a08b7082e86b7a5989b4b0fda2107ab",doi:null,title:"Binding Language Models in Symbolic Languages",authors:[{name:"Zhoujun Cheng",institutions:[]},{name:"Tianbao Xie",institutions:[]},{name:"Peng Shi",institutions:[]},{name:"Chengzu Li",institutions:["University of Cambridge"]},{name:"R. Nadkarni",institutions:[]},{name:"Yushi Hu",institutions:[]},{name:"Caiming Xiong",institutions:[]},{name:"Dragomir R. Radev",institutions:[]},{name:"M. Ostendorf",institutions:[]},{name:"Luke S. Zettlemoyer",institutions:[]},{name:"N. A. Smith",institutions:[]},{name:"Tao Yu",institutions:[]}],authorString:"Zhoujun Cheng; Tianbao Xie; Peng Shi; Chengzu Li; R. Nadkarni; Yushi Hu; Caiming Xiong; Dragomir R. Radev; M. Ostendorf; Luke S. Zettlemoyer; N. A. Smith; Tao Yu",institutions:["University of Cambridge"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:326,abstract:"Though end-to-end neural approaches have recently been dominating NLP tasks in both performance and ease-of-use, they lack interpretability and robustness. We propose Binder, a training-free neural-symbolic framework that maps the task input to a program, which (1) allows binding a unified API of language model (LM) functionalities to a programming language (e.g., SQL, Python) to extend its grammar coverage and thus tackle more diverse questions, (2) adopts an LM as both the program parser and the underlying model called by the API during execution, and (3) requires only a few in-context exemplar annotations. Specifically, we employ GPT-3 Codex as the LM. In the parsing stage, with only a few in-context exemplars, Codex is able to identify the part of the task input that cannot be answerable by the original programming language, correctly generate API calls to prompt Codex to solve the unanswerable part, and identify where to place the API calls while being compatible with the original grammar. In the execution stage, Codex can perform versatile functionalities (e.g., commonsense QA, information extraction) given proper prompts in the API calls. Binder achieves state-of-the-art results on WikiTableQuestions and TabFact datasets, with explicit output programs that benefit human debugging. Note that previous best systems are all finetuned on tens of thousands of task-specific samples, while Binder only uses dozens of annotations as in-context exemplars without any training. Our code is available at https://github.com/HKUNLP/Binder .",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:61,n_refs_in_core:7,degree:24,community:5,deg_w:160,betweenness:.0186,pagerank:.00467,eigenvector:.0191},{id:303,oaid:"013faec0400d315935e71a2bdfeb22cc83752b3e",doi:"10.18653/v1/2020.acl-main.141",title:"Reasoning with Latent Structure Refinement for Document-Level Relation Extraction",authors:[{name:"Guoshun Nan",institutions:[]},{name:"Zhijiang Guo",institutions:["HKUST (GZ)","HKUST"]},{name:"Ivan Sekulic",institutions:["Università della Svizzera italiana (USI)"]},{name:"Wei Lu",institutions:[]}],authorString:"Guoshun Nan; Zhijiang Guo; Ivan Sekulic; Wei Lu",institutions:["HKUST","HKUST (GZ)","Università della Svizzera italiana (USI)"],countries:[],year:2020,journal:"Annual Meeting of the Association for Computational Linguistics",citations:325,abstract:"Document-level relation extraction requires integrating information within and across multiple sentences of a document and capturing complex interactions between inter-sentence entities. However, effective aggregation of relevant information in the document remains a challenging research question. Existing approaches construct static document-level graphs based on syntactic trees, co-references or heuristics from the unstructured text to model the dependencies. Unlike previous methods that may not be able to capture rich non-local interactions for inference, we propose a novel model that empowers the relational reasoning across sentences by automatically inducing the latent document-level graph. We further develop a refinement strategy, which enables the model to incrementally aggregate relevant information for multi-hop reasoning. Specifically, our model achieves an F1 score of 59.05 on a large-scale document-level dataset (DocRED), significantly improving over the previous results, and also yields new state-of-the-art results on the CDR and GDA dataset. Furthermore, extensive analyses show that the model is able to discover more accurate inter-sentence relations.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.141.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:49e-5,eigenvector:.0066},{id:304,oaid:"d3850595d3ae7c73e9488054c9b437f75511b569",doi:null,title:"SATNet: Bridging deep learning and logical reasoning using a differentiable satisfiability solver",authors:[{name:"Po-Wei Wang",institutions:[]},{name:"P. Donti",institutions:[]},{name:"Bryan Wilder",institutions:[]},{name:"Zico Kolter",institutions:[]}],authorString:"Po-Wei Wang; P. Donti; Bryan Wilder; Zico Kolter",institutions:[],countries:[],year:2019,journal:"International Conference on Machine Learning",citations:322,abstract:'Integrating logical reasoning within deep learning architectures has been a major goal of modern AI systems. In this paper, we propose a new direction toward this goal by introducing a differentiable (smoothed) maximum satisfiability (MAXSAT) solver that can be integrated into the loop of larger deep learning systems. Our (approximate) solver is based upon a fast coordinate descent approach to solving the semidefinite program (SDP) associated with the MAXSAT problem. We show how to analytically differentiate through the solution to this SDP and efficiently solve the associated backward pass. We demonstrate that by integrating this solver into end-to-end learning systems, we can learn the logical structure of challenging problems in a minimally supervised fashion. In particular, we show that we can learn the parity function using single-bit supervision (a traditionally hard task for deep networks) and learn how to play 9x9 Sudoku solely from examples. We also solve a "visual Sudok" problem that maps images of Sudoku puzzles to their associated logical solutions by combining our MAXSAT solver with a traditional convolutional architecture. Our approach thus shows promise in integrating logical structures within deep learning.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:2e-4,pagerank:54e-5,eigenvector:1e-4},{id:305,oaid:"b9dd7a59a101fcecc6fe0e7aed517e84a7df7d2e",doi:null,title:"Learning Physical Intuition of Block Towers by Example",authors:[{name:"Adam Lerer",institutions:[]},{name:"Sam Gross",institutions:[]},{name:"R. Fergus",institutions:[]}],authorString:"Adam Lerer; Sam Gross; R. Fergus",institutions:[],countries:[],year:2016,journal:"International Conference on Machine Learning",citations:321,abstract:"Wooden blocks are a common toy for infants, allowing them to develop motor skills and gain intuition about the physical behavior of the world. In this paper, we explore the ability of deep feedforward models to learn such intuitive physics. Using a 3D game engine, we create small towers of wooden blocks whose stability is randomized and render them collapsing (or remaining upright). This data allows us to train large convolutional network models which can accurately predict the outcome, as well as estimating the block trajectories. The models are also able to generalize in two important ways: (i) to new physical scenarios, e.g. towers with an additional block and (ii) to images of real wooden blocks, where it obtains a performance comparable to human subjects.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:9,community:2,deg_w:33,betweenness:5e-4,pagerank:.00128,eigenvector:1e-4},{id:306,oaid:"5c5d99eff1377e141be293336a14ffddb323c364",doi:"10.1109/CVPR.2019.00210",title:"Heterogeneous Memory Enhanced Multimodal Attention Model for Video Question Answering",authors:[{name:"Chenyou Fan",institutions:[]},{name:"Xiaofan Zhang",institutions:[]},{name:"Shu Zhang",institutions:["Salesforce Research","JD.com","University of California Riverside"]},{name:"Wensheng Wang",institutions:[]},{name:"Chi Zhang",institutions:[]},{name:"Heng Huang",institutions:[]}],authorString:"Chenyou Fan; Xiaofan Zhang; Shu Zhang; Wensheng Wang; Chi Zhang; Heng Huang",institutions:["JD.com","Salesforce Research","University of California Riverside"],countries:[],year:2019,journal:"Computer Vision and Pattern Recognition",citations:320,abstract:"In this paper, we propose a novel end-to-end trainable Video Question Answering (VideoQA) framework with three major components: 1) a new heterogeneous memory which can effectively learn global context information from appearance and motion features; 2) a redesigned question memory which helps understand the complex semantics of question and highlights queried subjects; and 3) a new multimodal fusion layer which performs multi-step reasoning by attending to relevant visual and textual hints with self-updated attention. Our VideoQA model firstly generates the global context-aware visual and textual features respectively by interacting current inputs with memory contents. After that, it makes the attentional fusion of the multimodal visual and textual representations to infer the correct answer. Multiple cycles of reasoning can be made to iteratively refine attention weights of the multimodal data and improve the final representation of the QA pair. Experimental results demonstrate our approach achieves state-of-the-art performance on four VideoQA benchmark datasets.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1904.04357",is_oa:!0,n_refs:31,n_refs_in_core:4,degree:19,community:3,deg_w:138,betweenness:5e-4,pagerank:.00301,eigenvector:.001},{id:307,oaid:"3411535f7888a943853895e8eef2bb0b6d328c2a",doi:null,title:"Weakly-supervised Disentangling with Recurrent Transformations for 3D View Synthesis",authors:[{name:"Jimei Yang",institutions:[]},{name:"Scott E. Reed",institutions:[]},{name:"Ming-Hsuan Yang",institutions:[]},{name:"Honglak Lee",institutions:[]}],authorString:"Jimei Yang; Scott E. Reed; Ming-Hsuan Yang; Honglak Lee",institutions:[],countries:[],year:2015,journal:"Neural Information Processing Systems",citations:317,abstract:"An important problem for both graphics and vision is to synthesize novel views of a 3D object from a single image. This is particularly challenging due to the partial observability inherent in projecting a 3D object onto the image space, and the ill-posedness of inferring object shape and pose. However, we can train a neural network to address the problem if we restrict our attention to specific object categories (in our case faces and chairs) for which we can gather ample training data. In this paper, we propose a novel recurrent convolutional encoder-decoder network that is trained end-to-end on the task of rendering rotated objects starting from a single image. The recurrent structure allows our model to capture long-term dependencies along a sequence of transformations. We demonstrate the quality of its predictions for human faces on the Multi-PIE dataset and for a dataset of 3D chair models, and also show its ability to disentangle latent factors of variation (e.g., identity and pose) without using full supervision.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:1e-4},{id:308,oaid:"7dc156eb9d84ae8fd521ecac5ccc5b5426a42b50",doi:"10.24963/ijcai.2019/880",title:"A Survey of Reinforcement Learning Informed by Natural Language",authors:[{name:"Jelena Luketina",institutions:[]},{name:"Nantas Nardelli",institutions:[]},{name:"Gregory Farquhar",institutions:[]},{name:"Jakob N. Foerster",institutions:[]},{name:"Jacob Andreas",institutions:["MIT","Microsoft"]},{name:"Edward Grefenstette",institutions:[]},{name:"Shimon Whiteson",institutions:[]},{name:"Tim Rocktäschel",institutions:[]}],authorString:"Jelena Luketina; Nantas Nardelli; Gregory Farquhar; Jakob N. Foerster; Jacob Andreas; Edward Grefenstette; Shimon Whiteson; Tim Rocktäschel",institutions:["MIT","Microsoft"],countries:[],year:2019,journal:"International Joint Conference on Artificial Intelligence",citations:313,abstract:"To be successful in real-world tasks, Reinforcement Learning (RL) needs to exploit the compositional, relational, and hierarchical structure of the world, and learn to transfer it to the task at hand. Recent advances in representation learning for language make it possible to build models that acquire world knowledge from text corpora and integrate this knowledge into downstream decision making problems. We thus argue that the time is right to investigate a tight integration of natural language understanding into RL in particular. We survey the state of the field, including work on instruction following, text games, and learning from textual domain knowledge. Finally, we call for the development of new environments as well as further investigation into the potential uses of recent Natural Language Processing (NLP) techniques for such tasks.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.ijcai.org/proceedings/2019/0880.pdf",is_oa:!0,n_refs:92,n_refs_in_core:9,degree:27,community:4,deg_w:191,betweenness:.0186,pagerank:.00524,eigenvector:.0103},{id:309,oaid:"bc23dfb70e109dbe666b979f995e2779b96e1073",doi:"10.1146/annurev-control-101119-071628",title:"Robots That Use Language",authors:[{name:"Stefanie Tellex",institutions:[]},{name:"N. Gopalan",institutions:[]},{name:"H. Kress-Gazit",institutions:[]},{name:"Cynthia Matuszek",institutions:[]}],authorString:"Stefanie Tellex; N. Gopalan; H. Kress-Gazit; Cynthia Matuszek",institutions:[],countries:[],year:2020,journal:"Annu. Rev. Control. Robotics Auton. Syst.",citations:312,abstract:"This article surveys the use of natural language in robotics from a robotics point of view. To use human language, robots must map words to aspects of the physical world, mediated by the robot's sensors and actuators. This problem differs from other natural language processing domains due to the need to ground the language to noisy percepts and physical actions. Here, we describe central aspects of language use by robots, including understanding natural language requests, using language to drive learning about the physical world, and engaging in collaborative dialogue with a human partner. We describe common approaches, roughly divided into learning methods, logic-based methods, and methods that focus on questions of human–robot interaction. Finally, we describe several application domains for language-using robots.",keywords:[],concepts:[],pdf_url:"https://mdsoar.org/bitstreams/f1b5db4f-8a0f-4dc0-ba91-b0e2e8e900d1/download",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:4,deg_w:18,betweenness:0,pagerank:71e-5,eigenvector:2e-4},{id:310,oaid:"c636a2dd242908fe2e598a1077c0c57bfdea8633",doi:"10.1145/3097983.3098177",title:"ReasoNet: Learning to Stop Reading in Machine Comprehension",authors:[{name:"Yelong Shen",institutions:[]},{name:"Po-Sen Huang",institutions:[]},{name:"Jianfeng Gao",institutions:[]},{name:"Weizhu Chen",institutions:[]}],authorString:"Yelong Shen; Po-Sen Huang; Jianfeng Gao; Weizhu Chen",institutions:[],countries:[],year:2016,journal:"CoCo@NIPS",citations:309,abstract:"Teaching a computer to read and answer general questions pertaining to a document is a challenging yet unsolved problem. In this paper, we describe a novel neural network architecture called the Reasoning Network (ReasoNet) for machine comprehension tasks. ReasoNets make use of multiple turns to effectively exploit and then reason over the relation among queries, documents, and answers. Different from previous approaches using a fixed number of turns during inference, ReasoNets introduce a termination state to relax this constraint on the reasoning depth. With the use of reinforcement learning, ReasoNets can dynamically determine whether to continue the comprehension process after digesting intermediate results, or to terminate reading when it concludes that existing information is adequate to produce an answer. ReasoNets achieve superior performance in machine comprehension datasets, including unstructured CNN and Daily Mail datasets, the Stanford SQuAD dataset, and a structured Graph Reachability dataset.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1609.05284",is_oa:!0,n_refs:40,n_refs_in_core:1,degree:9,community:0,deg_w:40,betweenness:.0031,pagerank:.00136,eigenvector:8e-4},{id:311,oaid:"4ab41d9780f1d1ac34d39fa7e527e73652507fcc",doi:null,title:"GreaseLM: Graph REASoning Enhanced Language Models for Question Answering",authors:[{name:"Xikun Zhang",institutions:["Stanford University"]},{name:"Antoine Bosselut",institutions:["EPFL"]},{name:"Michihiro Yasunaga",institutions:[]},{name:"Hongyu Ren",institutions:[]},{name:"Percy Liang",institutions:[]},{name:"Christopher D. Manning",institutions:["Stanford University"]},{name:"J. Leskovec",institutions:[]}],authorString:"Xikun Zhang; Antoine Bosselut; Michihiro Yasunaga; Hongyu Ren; Percy Liang; Christopher D. Manning; J. Leskovec",institutions:["EPFL","Stanford University"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:309,abstract:"Answering complex questions about textual narratives requires reasoning over both stated context and the world knowledge that underlies it. However, pretrained language models (LM), the foundation of most modern QA systems, do not robustly represent latent relationships between concepts, which is necessary for reasoning. While knowledge graphs (KG) are often used to augment LMs with structured representations of world knowledge, it remains an open question how to effectively fuse and reason over the KG representations and the language context, which provides situational constraints and nuances. In this work, we propose GreaseLM, a new model that fuses encoded representations from pretrained LMs and graph neural networks over multiple layers of modality interaction operations. Information from both modalities propagates to the other, allowing language context representations to be grounded by structured world knowledge, and allowing linguistic nuances (e.g., negation, hedging) in the context to inform the graph representations of knowledge. Our results on three benchmarks in the commonsense reasoning (i.e., CommonsenseQA, OpenbookQA) and medical question answering (i.e., MedQA-USMLE) domains demonstrate that GreaseLM can more reliably answer questions that require reasoning over both situational constraints and structured knowledge, even outperforming models 8x larger.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:.011},{id:312,oaid:"ccd99008d942b890cecd308a31ba61240eac9e54",doi:"10.1109/CVPR.2018.00445",title:"Learning to Segment Every Thing",authors:[{name:"Ronghang Hu",institutions:[]},{name:"Piotr Dollár",institutions:["Facebook AI Research"]},{name:"Kaiming He",institutions:["Facebook AI Research"]},{name:"Trevor Darrell",institutions:[]},{name:"Ross B. Girshick",institutions:[]}],authorString:"Ronghang Hu; Piotr Dollár; Kaiming He; Trevor Darrell; Ross B. Girshick",institutions:["Facebook AI Research"],countries:[],year:2017,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:308,abstract:"Most methods for object instance segmentation require all training examples to be labeled with segmentation masks. This requirement makes it expensive to annotate new categories and has restricted instance segmentation models to ~100 well-annotated classes. The goal of this paper is to propose a new partially supervised training paradigm, together with a novel weight transfer function, that enables training instance segmentation models on a large set of categories all of which have box annotations, but only a small fraction of which have mask annotations. These contributions allow us to train Mask R-CNN to detect and segment 3000 visual concepts using box annotations from the Visual Genome dataset and mask annotations from the 80 classes in the COCO dataset. We evaluate our approach in a controlled study on the COCO dataset. This work is a first step towards instance segmentation models that have broad comprehension of the visual world.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1711.10370",is_oa:!0,n_refs:39,n_refs_in_core:1,degree:11,community:3,deg_w:58.5,betweenness:.0026,pagerank:.00174,eigenvector:5e-4},{id:313,oaid:"e837b79de602c69395498c1fbbe39bbb4e6f75ad",doi:null,title:"Learning to Transduce with Unbounded Memory",authors:[{name:"Edward Grefenstette",institutions:[]},{name:"Karl Moritz Hermann",institutions:[]},{name:"Mustafa Suleyman",institutions:[]},{name:"Phil Blunsom",institutions:[]}],authorString:"Edward Grefenstette; Karl Moritz Hermann; Mustafa Suleyman; Phil Blunsom",institutions:[],countries:[],year:2015,journal:"Neural Information Processing Systems",citations:307,abstract:"Recently, strong results have been demonstrated by Deep Recurrent Neural Networks on natural language transduction problems. In this paper we explore the representational power of these models using synthetic grammars designed to exhibit phenomena similar to those found in real transduction problems such as machine translation. These experiments lead us to propose new memory-based recurrent networks that implement continuously differentiable analogues of traditional data structures such as Stacks, Queues, and DeQues. We show that these architectures exhibit superior generalisation performance to Deep RNNs and are often able to learn the underlying generating algorithms in our transduction experiments.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:21,n_refs_in_core:1,degree:4,community:2,deg_w:28,betweenness:0,pagerank:.00111,eigenvector:4e-4},{id:314,oaid:"1301e9d11b728268ed1ff3f1a9adc155308d5250",doi:"10.15607/RSS.2021.XVII.047",title:"Language Conditioned Imitation Learning Over Unstructured Data",authors:[{name:"Corey Lynch",institutions:[]},{name:"P. Sermanet",institutions:[]}],authorString:"Corey Lynch; P. Sermanet",institutions:[],countries:[],year:2020,journal:"Robotics: Science and Systems Conference",citations:307,abstract:'Natural language is perhaps the most flexible and intuitive way for humans to communicate tasks to a robot. Prior work in imitation learning typically requires each task be specified with a task id or goal image -- something that is often impractical in open-world environments. On the other hand, previous approaches in instruction following allow agent behavior to be guided by language, but typically assume structure in the observations, actuators, or language that limit their applicability to complex settings like robotics. In this work, we present a method for incorporating free-form natural language conditioning into imitation learning. Our approach learns perception from pixels, natural language understanding, and multitask continuous control end-to-end as a single neural network. Unlike prior work in imitation learning, our method is able to incorporate unlabeled and unstructured demonstration data (i.e. no task or language labels). We show this dramatically improves language conditioned performance, while reducing the cost of language annotation to less than 1% of total data. At test time, a single language conditioned visuomotor policy trained with our method can perform a wide variety of robotic manipulation skills in a 3D environment, specified only with natural language descriptions of each task (e.g."open the drawer...now pick up the block...now press the green button..."). To scale up the number of instructions an agent can follow, we propose combining text conditioned policies with large pretrained neural language models. We find this allows a policy to be robust to many out-of-distribution synonym instructions, without requiring new demonstrations. See videos of a human typing live text commands to our agent at language-play.github.io',keywords:[],concepts:[],pdf_url:"https://doi.org/10.15607/rss.2021.xvii.047",is_oa:!0,n_refs:53,n_refs_in_core:6,degree:13,community:4,deg_w:107,betweenness:8e-4,pagerank:.00302,eigenvector:.0014},{id:315,oaid:"cfc9ef5c7ef8056cff7bf1f1cfdd75e120f28231",doi:"10.1109/CVPR.2019.00209",title:"MUREL: Multimodal Relational Reasoning for Visual Question Answering",authors:[{name:"Rémi Cadène",institutions:[]},{name:"H. Ben-younes",institutions:[]},{name:"M. Cord",institutions:[]},{name:"Nicolas Thomé",institutions:[]}],authorString:"Rémi Cadène; H. Ben-younes; M. Cord; Nicolas Thomé",institutions:[],countries:[],year:2019,journal:"Computer Vision and Pattern Recognition",citations:303,abstract:"Multimodal attentional networks are currently state-of-the-art models for Visual Question Answering (VQA) tasks involving real images. Although attention allows to focus on the visual content relevant to the question, this simple mechanism is arguably insufficient to model complex reasoning features required for VQA or other high-level tasks. In this paper, we propose MuRel, a multimodal relational network which is learned end-to-end to reason over real images. Our first contribution is the introduction of the MuRel cell, an atomic reasoning primitive representing interactions between question and image regions by a rich vectorial representation, and modeling region relations with pairwise combinations. Secondly, we incorporate the cell into a full MuRel network, which progressively refines visual and question interactions, and can be leveraged to define visualization schemes finer than mere attention maps. We validate the relevance of our approach with various ablation studies, and show its superiority to attention-based methods on three datasets: VQA 2.0, VQA-CP v2 and TDIUC. Our final MuRel network is competitive to or outperforms state-of-the-art results in this challenging context. Our code is available: github.com/Cadene/murel.bootstrap.pytorch",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1902.09487",is_oa:!0,n_refs:48,n_refs_in_core:13,degree:28,community:3,deg_w:255.5,betweenness:.0031,pagerank:.00574,eigenvector:.002},{id:316,oaid:"3a6447361b20c249f5306ae17dee43f645430e31",doi:null,title:"Neural Logic Machines",authors:[{name:"Honghua Dong",institutions:[]},{name:"Jiayuan Mao",institutions:[]},{name:"Tian Lin",institutions:[]},{name:"Chong Wang",institutions:[]},{name:"Lihong Li",institutions:[]},{name:"Denny Zhou",institutions:[]}],authorString:"Honghua Dong; Jiayuan Mao; Tian Lin; Chong Wang; Lihong Li; Denny Zhou",institutions:[],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:303,abstract:"We propose the Neural Logic Machine (NLM), a neural-symbolic architecture for both inductive learning and logic reasoning. NLMs exploit the power of both neural networks---as function approximators, and logic programming---as a symbolic processor for objects with properties, relations, logic connectives, and quantifiers. After being trained on small-scale tasks (such as sorting short arrays), NLMs can recover lifted rules, and generalize to large-scale tasks (such as sorting longer arrays). In our experiments, NLMs achieve perfect generalization in a number of tasks, from relational reasoning tasks on the family tree and general graphs, to decision making tasks including sorting arrays, finding shortest paths, and playing the blocks world. Most of these tasks are hard to accomplish for neural networks or inductive logic programming alone.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12.5,betweenness:1e-4,pagerank:72e-5,eigenvector:1e-4},{id:317,oaid:"af2e6165b68e75c911dfdb8f81f9ab6627722ab7",doi:"10.3115/v1/P15-1016",title:"Compositional Vector Space Models for Knowledge Base Completion",authors:[{name:"Arvind Neelakantan",institutions:["Google"]},{name:"Benjamin Roth",institutions:[]},{name:"A. McCallum",institutions:[]}],authorString:"Arvind Neelakantan; Benjamin Roth; A. McCallum",institutions:["Google"],countries:[],year:2015,journal:"Annual Meeting of the Association for Computational Linguistics",citations:301,abstract:"Knowledge base (KB) completion adds new facts to a KB by making inferences from existing facts, for example by inferring with high likelihood nationality(X,Y) from bornIn(X,Y). Most previous methods infer simple one-hop relational synonyms like this, or use as evidence a multi-hop relational path treated as an atomic feature, like bornIn(X,Z)→ containedIn(Z,Y). This paper presents an approach that reasons about conjunctions of multi-hop relations non-atomically, composing the implications of a path using a recurrent neural network (RNN) that takes as inputs vector embeddings of the binary relation in the path. Not only does this allow us to generalize to paths unseen at training time, but also, with a single high-capacity RNN, to predict new relation types not seen when the compositional model was trained (zero-shot learning). We assemble a new dataset of over 52M relational triples, and show that our method improves over a traditional classifier by 11%, and a method leveraging pre-trained embeddings by 7%.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.3115/v1/p15-1016",is_oa:!0,n_refs:47,n_refs_in_core:7,degree:24,community:0,deg_w:169.5,betweenness:.0149,pagerank:.0049,eigenvector:.0193},{id:318,oaid:"ab4850b6151ca9a9337dbba94115bde342876d50",doi:"10.1007/s10994-013-5335-x",title:"From machine learning to machine reasoning",authors:[{name:"L. Bottou",institutions:[]}],authorString:"L. Bottou",institutions:[],countries:[],year:2011,journal:"Machine-mediated learning",citations:297,abstract:"A plausible definition of “reasoning” could be “algebraically manipulating previously acquired knowledge in order to answer a new question”. This definition covers first-order logical inference or probabilistic inference. It also includes much simpler manipulations commonly used to build large learning systems. For instance, we can build an optical character recognition system by first training a character segmenter, an isolated character recognizer, and a language model, using appropriate labelled training sets. Adequately concatenating these modules and fine tuning the resulting system can be viewed as an algebraic operation in a space of models. The resulting model answers a new question, that is, converting the image of a text page into a computer readable text. This observation suggests a conceptual continuity between algebraically rich inference systems, such as logical or probabilistic inference, and simple manipulations, such as the mere concatenation of trainable learning systems. Therefore, instead of trying to bridge the gap between machine learning systems and sophisticated “all-purpose” inference mechanisms, we can instead algebraically enrich the set of manipulations applicable to training systems, and build reasoning capabilities from the ground up.",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007%2Fs10994-013-5335-x.pdf",is_oa:!0,n_refs:62,n_refs_in_core:4,degree:9,community:0,deg_w:43.5,betweenness:.0035,pagerank:.00216,eigenvector:1e-4},{id:319,oaid:"414ab203d8fc3ecfbf40d004960d3a4774830b48",doi:null,title:"Visual Interaction Networks: Learning a Physics Simulator from Video",authors:[{name:"Nicholas Watters",institutions:[]},{name:"Daniel Zoran",institutions:["DeepMind"]},{name:"T. Weber",institutions:[]},{name:"P. Battaglia",institutions:[]},{name:"Razvan Pascanu",institutions:["Google DeepMind"]},{name:"Andrea Tacchetti",institutions:[]}],authorString:"Nicholas Watters; Daniel Zoran; T. Weber; P. Battaglia; Razvan Pascanu; Andrea Tacchetti",institutions:["DeepMind","Google DeepMind"],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:297,abstract:"From just a glance, humans can make rich predictions about the future state of a wide range of physical systems. On the other hand, modern approaches from engineering, robotics, and graphics are often restricted to narrow domains and require direct measurements of the underlying states. We introduce the Visual Interaction Network, a general-purpose model for learning the dynamics of a physical system from raw visual observations. Our model consists of a perceptual front-end based on convolutional neural networks and a dynamics predictor based on interaction networks. Through joint training, the perceptual front-end learns to parse a dynamic visual scene into a set of factored latent object representations. The dynamics predictor learns to roll these states forward in time by computing their interactions and dynamics, producing a predicted physical trajectory of arbitrary length. We found that from just six input video frames the Visual Interaction Network can generate accurate future trajectories of hundreds of time steps on a wide range of physical systems. Our model can also be applied to scenes with invisible objects, inferring their future states from their effects on the visible objects, and can implicitly infer the unknown mass of objects. Our results demonstrate that the perceptual module and the object-based dynamics predictor module can induce factored latent representations that support accurate dynamical predictions. This work opens new opportunities for model-based decision-making and planning from raw sensory observations in complex physical environments.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:28,n_refs_in_core:8,degree:14,community:2,deg_w:84,betweenness:.0022,pagerank:.00292,eigenvector:2e-4},{id:320,oaid:"b196bc11ad516c8e6ff96f83acfc443fd7161730",doi:null,title:"ABC-CNN: An Attention Based Convolutional Neural Network for Visual Question Answering",authors:[{name:"Kan Chen",institutions:[]},{name:"Jiang Wang",institutions:[]},{name:"Liang-Chieh Chen",institutions:[]},{name:"Haoyuan Gao",institutions:[]},{name:"W. Xu",institutions:[]},{name:"R. Nevatia",institutions:[]}],authorString:"Kan Chen; Jiang Wang; Liang-Chieh Chen; Haoyuan Gao; W. Xu; R. Nevatia",institutions:[],countries:[],year:2015,journal:"arXiv.org",citations:297,abstract:"We propose a novel attention based deep learning architecture for visual question answering task (VQA). Given an image and an image related natural language question, VQA generates the natural language answer for the question. Generating the correct answers requires the model's attention to focus on the regions corresponding to the question, because different questions inquire about the attributes of different image regions. We introduce an attention based configurable convolutional neural network (ABC-CNN) to learn such question-guided attention. ABC-CNN determines an attention map for an image-question pair by convolving the image feature map with configurable convolutional kernels derived from the question's semantics. We evaluate the ABC-CNN architecture on three benchmark VQA datasets: Toronto COCO-QA, DAQUAR, and VQA dataset. ABC-CNN model achieves significant improvements over state-of-the-art methods on these datasets. The question-guided attention generated by ABC-CNN is also shown to reflect the regions that are highly relevant to the questions.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:12,betweenness:0,pagerank:5e-4,eigenvector:1e-4},{id:321,oaid:"c56aced0f0c5cfebefadb530cb08d736c3ac5c05",doi:"10.18653/v1/2021.findings-emnlp.232",title:"Retrieval Augmented Code Generation and Summarization",authors:[{name:"Md. Rizwan Parvez",institutions:[]},{name:"W. Ahmad",institutions:[]},{name:"Saikat Chakraborty",institutions:["Columbia University"]},{name:"Baishakhi Ray",institutions:[]},{name:"Kai-Wei Chang",institutions:["UCLA"]}],authorString:"Md. Rizwan Parvez; W. Ahmad; Saikat Chakraborty; Baishakhi Ray; Kai-Wei Chang",institutions:["Columbia University","UCLA"],countries:[],year:2021,journal:"Conference on Empirical Methods in Natural Language Processing",citations:295,abstract:"Software developers write a lot of source code and documentation during software development. Intrinsically, developers often recall parts of source code or code summaries that they had written in the past while implementing software or documenting them. To mimic developers' code or summary generation behavior, we propose a retrieval augmented framework, REDCODER, that retrieves relevant code or summaries from a retrieval database and provides them as a supplement to code generation or summarization models. REDCODER has a couple of uniqueness. First, it extends the state-of-the-art dense retrieval technique to search for relevant code or summaries. Second, it can work with retrieval databases that include unimodal (only code or natural language description) or bimodal instances (code-description pairs). We conduct experiments and extensive analysis on two benchmark datasets of code generation and summarization in Java and Python, and the promising results endorse the effectiveness of our proposed retrieval augmented framework.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.findings-emnlp.232.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:5,deg_w:8.5,betweenness:0,pagerank:48e-5,eigenvector:.0011},{id:322,oaid:"0b0a1cd432413978e4ef3d0418ebf3bb07af6c7a",doi:"10.24963/IJCAI.2017/179",title:"Explicit Knowledge-based Reasoning for Visual Question Answering",authors:[{name:"Peng Wang",institutions:[]},{name:"Qi Wu",institutions:[]},{name:"Chunhua Shen",institutions:[]},{name:"A. Dick",institutions:[]},{name:"Anton van den Hengel",institutions:["University of Adelaide, Commonwealth Bank of Australia"]}],authorString:"Peng Wang; Qi Wu; Chunhua Shen; A. Dick; Anton van den Hengel",institutions:["University of Adelaide, Commonwealth Bank of Australia"],countries:[],year:2015,journal:"International Joint Conference on Artificial Intelligence",citations:294,abstract:"We describe a method for visual question answering which is capable of reasoning about contents of an image on the basis of information extracted from a large-scale knowledge base. The method not only answers natural language questions using concepts not contained in the image, but can provide an explanation of the reasoning by which it developed its answer. The method is capable of answering far more complex questions than the predominant long short-term memory-based approach, and outperforms it significantly in the testing. We also provide a dataset and a protocol by which to evaluate such methods, thus addressing one of the key issues in general visual ques- tion answering.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2017/0179.pdf",is_oa:!0,n_refs:54,n_refs_in_core:5,degree:21,community:3,deg_w:170,betweenness:.0044,pagerank:.00364,eigenvector:.0013},{id:323,oaid:"d7d5bb7c5424a725d3c2b7d352aa299f0f90a5e5",doi:"10.18653/v1/2020.acl-main.374",title:"SKEP: Sentiment Knowledge Enhanced Pre-training for Sentiment Analysis",authors:[{name:"Hao Tian",institutions:[]},{name:"Can Gao",institutions:["Xiaomi, inc."]},{name:"Xinyan Xiao",institutions:[]},{name:"Hao Liu",institutions:[]},{name:"Bolei He",institutions:[]},{name:"Hua Wu",institutions:[]},{name:"Haifeng Wang",institutions:[]},{name:"Feng Wu",institutions:[]}],authorString:"Hao Tian; Can Gao; Xinyan Xiao; Hao Liu; Bolei He; Hua Wu; Haifeng Wang; Feng Wu",institutions:["Xiaomi, inc."],countries:[],year:2020,journal:"Annual Meeting of the Association for Computational Linguistics",citations:292,abstract:"Recently, sentiment analysis has seen remarkable advance with the help of pre-training approaches. However, sentiment knowledge, such as sentiment words and aspect-sentiment pairs, is ignored in the process of pre-training, despite the fact that they are widely used in traditional sentiment analysis approaches. In this paper, we introduce Sentiment Knowledge Enhanced Pre-training (SKEP) in order to learn a unified sentiment representation for multiple sentiment analysis tasks. With the help of automatically-mined knowledge, SKEP conducts sentiment masking and constructs three sentiment knowledge prediction objectives, so as to embed sentiment information at the word, polarity and aspect level into pre-trained sentiment representation. In particular, the prediction of aspect-sentiment pairs is converted into multi-label classification, aiming to capture the dependency between words in a pair. Experiments on three kinds of sentiment tasks show that SKEP significantly outperforms strong pre-training baseline, and achieves new state-of-the-art results on most of the test datasets. We release our code at https://github.com/baidu/Senta.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.374.pdf",is_oa:!0,n_refs:41,n_refs_in_core:0,degree:18,community:1,deg_w:155.5,betweenness:5e-4,pagerank:.00313,eigenvector:.1385},{id:324,oaid:"9e979667aa81c294062c02ab3a48e87e47c54987",doi:"10.18653/v1/2020.emnlp-main.99",title:"Scalable Multi-Hop Relational Reasoning for Knowledge-Aware Question Answering",authors:[{name:"Yanlin Feng",institutions:[]},{name:"Xinyue Chen",institutions:["Carnegie Mellon University"]},{name:"Bill Yuchen Lin",institutions:["Allen Institute for AI (AI2)"]},{name:"Peifeng Wang",institutions:["University of Southern California"]},{name:"Jun Yan",institutions:["Google DeepMind"]},{name:"Xiang Ren",institutions:[]}],authorString:"Yanlin Feng; Xinyue Chen; Bill Yuchen Lin; Peifeng Wang; Jun Yan; Xiang Ren",institutions:["Allen Institute for AI (AI2)","Carnegie Mellon University","Google DeepMind","University of Southern California"],countries:[],year:2020,journal:"Conference on Empirical Methods in Natural Language Processing",citations:289,abstract:"Existing work on augmenting question answering (QA) models with external knowledge (e.g., knowledge graphs) either struggle to model multi-hop relations efficiently, or lack transparency into the model's prediction rationale. In this paper, we propose a novel knowledge-aware approach that equips pre-trained language models (PTLMs) with a multi-hop relational reasoning module, named multi-hop graph relation network (MHGRN). It performs multi-hop, multi-relational reasoning over subgraphs extracted from external knowledge graphs. The proposed reasoning module unifies path-based reasoning methods and graph neural networks to achieve better interpretability and scalability. We also empirically show its effectiveness and scalability on CommonsenseQA and OpenbookQA datasets, and interpret its behaviors with case studies.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.emnlp-main.99.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:1,deg_w:13,betweenness:0,pagerank:58e-5,eigenvector:.0082},{id:325,oaid:"30834ae1497c35d362eea14857d93c28d2d12b57",doi:null,title:"Zero-Shot Task Generalization with Multi-Task Deep Reinforcement Learning",authors:[{name:"Junhyuk Oh",institutions:[]},{name:"Satinder Singh",institutions:[]},{name:"Honglak Lee",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"Junhyuk Oh; Satinder Singh; Honglak Lee; Pushmeet Kohli",institutions:[],countries:[],year:2017,journal:"International Conference on Machine Learning",citations:288,abstract:"As a step towards developing zero-shot task generalization capabilities in reinforcement learning (RL), we introduce a new RL problem where the agent should learn to execute sequences of instructions after learning useful skills that solve subtasks. In this problem, we consider two types of generalizations: to previously unseen instructions and to longer sequences of instructions. For generalization over unseen instructions, we propose a new objective which encourages learning correspondences between similar subtasks by making analogies. For generalization over sequential instructions, we present a hierarchical architecture where a meta controller learns to use the acquired skills for executing the instructions. To deal with delayed reward, we propose a new neural architecture in the meta controller that learns when to update the subtask, which makes learning more efficient. Experimental results on a stochastic 3D domain show that the proposed ideas are crucial for generalization to longer instructions as well as unseen instructions.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:4,deg_w:21,betweenness:3e-4,pagerank:8e-4,eigenvector:3e-4},{id:326,oaid:"2a561c9650d27218054aa2c87474f0121ba3f33b",doi:"10.48550/arXiv.2203.02167",title:"SimKGC: Simple Contrastive Knowledge Graph Completion with Pre-trained Language Models",authors:[{name:"Liang Wang",institutions:["Microsoft"]},{name:"Wei Zhao",institutions:["Yuanfudao Research"]},{name:"Zhuoyu Wei",institutions:[]},{name:"Jingming Liu",institutions:["Yuanfudao Research"]}],authorString:"Liang Wang; Wei Zhao; Zhuoyu Wei; Jingming Liu",institutions:["Microsoft","Yuanfudao Research"],countries:[],year:2022,journal:"Annual Meeting of the Association for Computational Linguistics",citations:287,abstract:"Knowledge graph completion (KGC) aims to reason over known facts and infer the missing links. Text-based methods such as KGBERT (Yao et al., 2019) learn entity representations from natural language descriptions, and have the potential for inductive KGC. However, the performance of text-based methods still largely lag behind graph embedding-based methods like TransE (Bordes et al., 2013) and RotatE (Sun et al., 2019b). In this paper, we identify that the key issue is efficient contrastive learning. To improve the learning efficiency, we introduce three types of negatives: in-batch negatives, pre-batch negatives, and self-negatives which act as a simple form of hard negatives. Combined with InfoNCE loss, our proposed model SimKGC can substantially outperform embedding-based methods on several benchmark datasets. In terms of mean reciprocal rank (MRR), we advance the state-of-the-art by +19% on WN18RR, +6.8% on the Wikidata5M transductive setting, and +22% on the Wikidata5M inductive setting. Thorough analyses are conducted to gain insights into each component. Our code is available at https://github.com/intfloat/SimKGC .",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2203.02167",is_oa:!0,n_refs:62,n_refs_in_core:6,degree:21,community:1,deg_w:218.5,betweenness:.0014,pagerank:.0047,eigenvector:.166},{id:327,oaid:"136c05cb8dd359fb8e0dc7947172a9ecb74ccbec",doi:null,title:"Learning by Abstraction: The Neural State Machine",authors:[{name:"Drew A. Hudson",institutions:[]},{name:"Christopher D. Manning",institutions:["Stanford University"]}],authorString:"Drew A. Hudson; Christopher D. Manning",institutions:["Stanford University"],countries:[],year:2019,journal:"Neural Information Processing Systems",citations:286,abstract:"We introduce the Neural State Machine, seeking to bridge the gap between the neural and symbolic views of AI and integrate their complementary strengths for the task of visual reasoning. Given an image, we first predict a probabilistic graph that represents its underlying semantics and serves as a structured world model. Then, we perform sequential reasoning over the graph, iteratively traversing its nodes to answer a given question or draw a new inference. In contrast to most neural architectures that are designed to closely interact with the raw sensory data, our model operates instead in an abstract latent space, by transforming both the visual and linguistic modalities into semantic concept-based representations, thereby achieving enhanced transparency and modularity. We evaluate our model on VQA-CP and GQA, two recent VQA datasets that involve compositionality, multi-step inference and diverse reasoning skills, achieving state-of-the-art results in both cases. We provide further experiments that illustrate the model's strong generalization capacity across multiple dimensions, including novel compositions of concepts, changes in the answer distribution, and unseen linguistic structures, demonstrating the qualities and efficacy of our approach.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:91,n_refs_in_core:43,degree:58,community:3,deg_w:459.5,betweenness:.064,pagerank:.01241,eigenvector:.0029},{id:328,oaid:"acfe5b5c99be70fa3120d410e7be55b9fe299f40",doi:"10.1007/978-3-030-01246-5_21",title:"Factorizable Net: An Efficient Subgraph-based Framework for Scene Graph Generation",authors:[{name:"Yikang Li",institutions:[]},{name:"Wanli Ouyang",institutions:["The University of Sydney"]},{name:"Bolei Zhou",institutions:[]},{name:"Yawen Cui",institutions:[]},{name:"Jianping Shi",institutions:[]},{name:"Xiaogang Wang",institutions:[]}],authorString:"Yikang Li; Wanli Ouyang; Bolei Zhou; Yawen Cui; Jianping Shi; Xiaogang Wang",institutions:["The University of Sydney"],countries:[],year:2018,journal:"European Conference on Computer Vision",citations:285,abstract:"Generating scene graph to describe the object interactions inside an image gains increasing interests these years. However, most of the previous methods use complicated structures with slow inference speed or rely on the external data, which limits the usage of the model in real-life scenarios. To improve the efficiency of scene graph generation, we propose a subgraph-based connection graph to concisely represent the scene graph during the inference. A bottom-up clustering method is first used to factorize the entire graph into subgraphs, where each subgraph contains several objects and a subset of their relationships. By replacing the numerous relationship representations of the scene graph with fewer subgraph and object features, the computation in the intermediate stage is significantly reduced. In addition, spatial information is maintained by the subgraph features, which is leveraged by our proposed Spatial-weighted Message Passing (SMP) structure and Spatial-sensitive Relation Inference (SRI) module to facilitate the relationship recognition. On the recent Visual Relationship Detection and Visual Genome datasets, our method outperforms the state-of-the-art method in both accuracy and speed. Code has been made publicly available (https://github.com/yikang-li/FactorizableNet).",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:66,n_refs_in_core:2,degree:17,community:3,deg_w:150,betweenness:.0027,pagerank:.00323,eigenvector:.0012},{id:329,oaid:"39c02227c37f0856e368d3dd5899f0867195a92e",doi:null,title:"Learning Visual Predictive Models of Physics for Playing Billiards",authors:[{name:"Katerina Fragkiadaki",institutions:[]},{name:"Pulkit Agrawal",institutions:[]},{name:"S. Levine",institutions:[]},{name:"Jitendra Malik",institutions:["UC Berkeley","Facebook"]}],authorString:"Katerina Fragkiadaki; Pulkit Agrawal; S. Levine; Jitendra Malik",institutions:["Facebook","UC Berkeley"],countries:[],year:2015,journal:"International Conference on Learning Representations",citations:282,abstract:'The ability to plan and execute goal specific actions in varied, unexpected settings is a central requirement of intelligent agents. In this paper, we explore how an agent can be equipped with an internal model of the dynamics of the external world, and how it can use this model to plan novel actions by running multiple internal simulations ("visual imagination"). Our models directly process raw visual input, and use a novel object-centric prediction formulation based on visual glimpses centered on objects (fixations) to enforce translational invariance of the learned physical laws. The agent gathers training data through random interaction with a collection of different environments, and the resulting model can then be used to plan goal-directed actions in novel environments that the agent has not seen before. We demonstrate that our agent can accurately plan actions for playing a simulated billiards game, which requires pushing a ball into a target position or into collision with another ball.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:2,deg_w:20,betweenness:0,pagerank:82e-5,eigenvector:1e-4},{id:330,oaid:"fd963ea665e7a6e49753652dc7efe5affba5feb0",doi:"10.1145/3453483.3454080",title:"DreamCoder: bootstrapping inductive program synthesis with wake-sleep library learning",authors:[{name:"Kevin Ellis",institutions:[]},{name:"Catherine Wong",institutions:[]},{name:"Maxwell Nye",institutions:["MIT"]},{name:"Mathias Sablé-Meyer",institutions:[]},{name:"Lucas Morales",institutions:[]},{name:"Luke B. Hewitt",institutions:[]},{name:"Luc Cary",institutions:[]},{name:"Armando Solar-Lezama",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Kevin Ellis; Catherine Wong; Maxwell Nye; Mathias Sablé-Meyer; Lucas Morales; Luke B. Hewitt; Luc Cary; Armando Solar-Lezama; J. Tenenbaum",institutions:["MIT"],countries:[],year:2021,journal:"ACM-SIGPLAN Symposium on Programming Language Design and Implementation",citations:282,abstract:'We present a system for inductive program synthesis called DreamCoder, which inputs a corpus of synthesis problems each specified by one or a few examples, and automatically derives a library of program components and a neural search policy that can be used to efficiently solve other similar synthesis problems. The library and search policy bootstrap each other iteratively through a variant of "wake-sleep" approximate Bayesian learning. A new refactoring algorithm based on E-graph matching identifies common sub-components across synthesized programs, building a progressively deepening library of abstractions capturing the structure of the input domain. We evaluate on eight domains including classic program synthesis areas and AI tasks such as planning, inverse graphics, and equation discovery. We show that jointly learning the library and neural search policy leads to solving more problems, and solving them more quickly.',keywords:[],concepts:[],pdf_url:"https://hdl.handle.net/1721.1/145949",is_oa:!0,n_refs:51,n_refs_in_core:22,degree:24,community:7,deg_w:132,betweenness:.0158,pagerank:.00809,eigenvector:1e-4},{id:331,oaid:"5e35895fc4731858f0b286cb5a1613a819cc2367",doi:"10.18653/v1/D19-1458",title:"CLUTRR: A Diagnostic Benchmark for Inductive Reasoning from Text",authors:[{name:"Koustuv Sinha",institutions:[]},{name:"Shagun Sodhani",institutions:[]},{name:"Jin Dong",institutions:[]},{name:"Joelle Pineau",institutions:[]},{name:"William L. Hamilton",institutions:[]}],authorString:"Koustuv Sinha; Shagun Sodhani; Jin Dong; Joelle Pineau; William L. Hamilton",institutions:[],countries:[],year:2019,journal:"Conference on Empirical Methods in Natural Language Processing",citations:281,abstract:"The recent success of natural language understanding (NLU) systems has been troubled by results highlighting the failure of these models to generalize in a systematic and robust way. In this work, we introduce a diagnostic benchmark suite, named CLUTRR, to clarify some key issues related to the robustness and systematicity of NLU systems. Motivated by the classic work on inductive logic programming, CLUTRR requires that an NLU system infer kinship relations between characters in short stories. Successful performance on this task requires both extracting relationships between entities, as well as inferring the logical rules governing these relationships. CLUTRR allows us to precisely measure a model’s ability for systematic generalization by evaluating on held-out combinations of logical rules, and allows us to evaluate a model’s robustness by adding curated noise facts. Our empirical results highlight a substantial performance gap between state-of-the-art NLU models (e.g., BERT and MAC) and a graph neural network model that works directly with symbolic inputs—with the graph-based model exhibiting both stronger generalization and greater robustness.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.aclweb.org/anthology/D19-1458.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:56e-5,eigenvector:1e-4},{id:332,oaid:"46c53faeaf2f52215adb165559c5ce056a71146b",doi:null,title:"Stacked Capsule Autoencoders",authors:[{name:"Adam R. Kosiorek",institutions:[]},{name:"S. Sabour",institutions:[]},{name:"Y. Teh",institutions:[]},{name:"Geoffrey E. Hinton",institutions:[]}],authorString:"Adam R. Kosiorek; S. Sabour; Y. Teh; Geoffrey E. Hinton",institutions:[],countries:[],year:2019,journal:"Neural Information Processing Systems",citations:280,abstract:"Objects are composed of a set of geometrically organized parts. We introduce an unsupervised capsule autoencoder (SCAE), which explicitly uses geometric relationships between parts to reason about objects. Since these relationships do not depend on the viewpoint, our model is robust to viewpoint changes. SCAE consists of two stages. In the first stage, the model predicts presences and poses of part templates directly from the image and tries to reconstruct the image by appropriately arranging the templates. In the second stage, SCAE predicts parameters of a few object capsules, which are then used to reconstruct part poses. Inference in this model is amortized and performed by off-the-shelf neural encoders, unlike in previous capsule networks. We find that object capsule presences are highly informative of the object class, which leads to state-of-the-art results for unsupervised classification on SVHN (55%) and MNIST (98.7%). The code is available at this https URL",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:1e-4,pagerank:58e-5,eigenvector:0},{id:333,oaid:"39e40821b7207125e54e6ed7112e55cd38c6f0c3",doi:"10.48550/arXiv.2210.07128",title:"Language Models of Code are Few-Shot Commonsense Learners",authors:[{name:"Aman Madaan",institutions:["Carnegie Mellon University"]},{name:"Shuyan Zhou",institutions:["Carnegie Mellon University"]},{name:"Uri Alon",institutions:["Carnegie Mellon University"]},{name:"Yiming Yang",institutions:[]},{name:"Graham Neubig",institutions:[]}],authorString:"Aman Madaan; Shuyan Zhou; Uri Alon; Yiming Yang; Graham Neubig",institutions:["Carnegie Mellon University"],countries:[],year:2022,journal:"Conference on Empirical Methods in Natural Language Processing",citations:280,abstract:"We address the general task of structured commonsense reasoning: given a natural language input, the goal is to generate a graph such as an event or a reasoning-graph.To employ large language models (LMs) for this task, existing approaches ‘serialize’ the output graph as a flat list of nodes and edges.Although feasible, these serialized graphs strongly deviate from the natural language corpora that LMs were pre-trained on, hindering LMs from generating them correctly. In this paper, we show that when we instead frame structured commonsense reasoning tasks as code generation tasks, pre-trained LMs of code are better structured commonsense reasoners than LMs of natural language, even when the downstream task does not involve source code at all.We demonstrate our approach across three diverse structured commonsense reasoning tasks. In all these natural language tasks, we show that using our approach, a code generation LM (codex) outperforms natural-LMs that are fine-tuned on the target task (T5) and other strong LMs such as GPT-3 in the few-shot setting.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2210.07128",is_oa:!0,n_refs:34,n_refs_in_core:4,degree:18,community:5,deg_w:99,betweenness:.0054,pagerank:.00301,eigenvector:.0059},{id:334,oaid:"d3d4273db96381330a98b1277fddc3907af95fbd",doi:"10.18653/V1/E17-1013",title:"Chains of Reasoning over Entities, Relations, and Text using Recurrent Neural Networks",authors:[{name:"A. McCallum",institutions:[]},{name:"Arvind Neelakantan",institutions:["Google"]},{name:"Rajarshi Das",institutions:[]},{name:"David Belanger",institutions:[]}],authorString:"A. McCallum; Arvind Neelakantan; Rajarshi Das; David Belanger",institutions:["Google"],countries:[],year:2016,journal:"Conference of the European Chapter of the Association for Computational Linguistics",citations:278,abstract:"Our goal is to combine the rich multi-step inference of symbolic logical reasoning with the generalization capabilities of neural networks. We are particularly interested in complex reasoning about entities and relations in text and large-scale knowledge bases (KBs). Neelakantan et al. (2015) use RNNs to compose the distributed semantics of multi-hop paths in KBs; however for multiple reasons, the approach lacks accuracy and practicality. This paper proposes three significant modeling advances: (1) we learn to jointly reason about relations, entities, and entity-types; (2) we use neural attention modeling to incorporate multiple paths; (3) we learn to share strength in a single RNN that represents logical composition across all relations. On a large-scale Freebase+ClueWeb prediction task, we achieve 25% error reduction, and a 53% error reduction on sparse relations due to shared strength. On chains of reasoning in WordNet we reduce error in mean quantile by 84% versus previous state-of-the-art.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/E17-1013.pdf",is_oa:!0,n_refs:44,n_refs_in_core:12,degree:23,community:0,deg_w:161.5,betweenness:.0049,pagerank:.0049,eigenvector:.0088},{id:335,oaid:"822f1ed9a76a57cc19d8fda7745365b97130b97a",doi:"10.3115/v1/N15-1118",title:"Injecting Logical Background Knowledge into Embeddings for Relation Extraction",authors:[{name:"Tim Rocktäschel",institutions:[]},{name:"Sameer Singh",institutions:["University of California, Irvine","Envive AI (fka Spiffy AI)"]},{name:"Sebastian Riedel",institutions:[]}],authorString:"Tim Rocktäschel; Sameer Singh; Sebastian Riedel",institutions:["Envive AI (fka Spiffy AI)","University of California, Irvine"],countries:[],year:2015,journal:"North American Chapter of the Association for Computational Linguistics",citations:278,abstract:"Matrix factorization approaches to relation extraction provide several attractive features: they support distant supervision, handle open schemas, and leverage unlabeled data. Unfortunately, these methods share a shortcoming with all other distantly supervised approaches: they cannot learn to extract target relations without existing data in the knowledge base, and likewise, these models are inaccurate for relations with sparse data. Rule-based extractors, on the other hand, can be easily extended to novel relations and improved for existing but inaccurate relations, through first-order formulae that capture auxiliary domain knowledge. However, usually a large set of such formulae is necessary to achieve generalization. In this paper, we introduce a paradigm for learning low-dimensional embeddings of entity-pairs and relations that combine the advantages of matrix factorization with first-order logic domain knowledge. We introduce simple approaches for estimating such embeddings, as well as a novel training algorithm to jointly optimize over factual and first-order logic information. Our results show that this method is able to learn accurate extractors with little or no distant supervision alignments, while at the same time generalizing to textual patterns that do not appear in the formulae.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/N15-1118.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:5,community:0,deg_w:23.5,betweenness:0,pagerank:.0011,eigenvector:3e-4},{id:336,oaid:"f5f8adf4b0b8060e7d208effad3f6e03534ec2d1",doi:null,title:"PRISM: A Language for Symbolic-Statistical Modeling",authors:[{name:"Taisuke Sato",institutions:[]},{name:"Yoshitaka Kameya",institutions:[]}],authorString:"Taisuke Sato; Yoshitaka Kameya",institutions:[],countries:[],year:1997,journal:"International Joint Conference on Artificial Intelligence",citations:273,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:1e-4,pagerank:64e-5,eigenvector:0},{id:337,oaid:"1fe7ce8e3eec85c9a35f213044d1fa3e855c3897",doi:"10.1126/science.aag2612",title:"A generative vision model that trains with high data efficiency and breaks text-based CAPTCHAs",authors:[{name:"Dileep George",institutions:[]},{name:"Wolfgang Lehrach",institutions:[]},{name:"Ken Kansky",institutions:[]},{name:"M. Lázaro-Gredilla",institutions:[]},{name:"C. Laan",institutions:[]},{name:"B. Marthi",institutions:[]},{name:"Xinghua Lou",institutions:[]},{name:"Zhaoshi Meng",institutions:[]},{name:"Yi Liu",institutions:[]},{name:"Hua-Yan Wang",institutions:[]},{name:"Alexander Lavin",institutions:[]},{name:"D. Phoenix",institutions:[]}],authorString:"Dileep George; Wolfgang Lehrach; Ken Kansky; M. Lázaro-Gredilla; C. Laan; B. Marthi; Xinghua Lou; Zhaoshi Meng; Yi Liu; Hua-Yan Wang; Alexander Lavin; D. Phoenix",institutions:[],countries:[],year:2017,journal:"Science",citations:270,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:338,oaid:"bf85a0cd645ad68919c0706741ab568a60a58af2",doi:null,title:"Neural Programmer: Inducing Latent Programs with Gradient Descent",authors:[{name:"Arvind Neelakantan",institutions:["Google"]},{name:"Quoc V. Le",institutions:[]},{name:"I. Sutskever",institutions:[]}],authorString:"Arvind Neelakantan; Quoc V. Le; I. Sutskever",institutions:["Google"],countries:[],year:2015,journal:"International Conference on Learning Representations",citations:270,abstract:"Deep neural networks have achieved impressive supervised classification performance in many tasks including image recognition, speech recognition, and sequence to sequence learning. However, this success has not been translated to applications like question answering that may involve complex arithmetic and logic reasoning. A major limitation of these models is in their inability to learn even simple arithmetic and logic operations. For example, it has been shown that neural networks fail to learn to add two binary numbers reliably. In this work, we propose Neural Programmer, an end-to-end differentiable neural network augmented with a small set of basic arithmetic and logic operations. Neural Programmer can call these augmented operations over several steps, thereby inducing compositional programs that are more complex than the built-in operations. The model learns from a weak supervision signal which is the result of execution of the correct program, hence it does not require expensive annotation of the correct program itself. The decisions of what operations to call, and what data segments to apply to are inferred by Neural Programmer. Such decisions, during training, are done in a differentiable fashion so that the entire network can be trained jointly by gradient descent. We find that training the model is difficult, but it can be greatly improved by adding random noise to the gradient. On a fairly complex synthetic table-comprehension dataset, traditional recurrent networks and attentional models perform poorly while Neural Programmer typically obtains nearly perfect accuracy.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:5,community:0,deg_w:20.5,betweenness:.001,pagerank:83e-5,eigenvector:7e-4},{id:339,oaid:"e5946ff9eacf931f87e1b5c23886735f164eda69",doi:null,title:"Tensor Networks : Deep Learning and Logical Reasoning from Data and Knowledge ⋆",authors:[{name:"L. Serafini",institutions:[]},{name:"A. Garcez",institutions:[]}],authorString:"L. Serafini; A. Garcez",institutions:[],countries:[],year:2016,journal:"",citations:270,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:2,deg_w:17.5,betweenness:2e-4,pagerank:95e-5,eigenvector:2e-4},{id:340,oaid:"0fff5c49c05c27c22ac7685130197146491f0b36",doi:null,title:"The Consciousness Prior",authors:[{name:"Yoshua Bengio",institutions:[]}],authorString:"Yoshua Bengio",institutions:[],countries:[],year:2017,journal:"arXiv.org",citations:270,abstract:"A new prior is proposed for learning representations of high-level concepts of the kind we manipulate with language. This prior can be combined with other priors in order to help disentangling abstract factors from each other. It is inspired by cognitive neuroscience theories of consciousness, seen as a bottleneck through which just a few elements, after having been selected by attention from a broader pool, are then broadcast and condition further processing, both in perception and decision-making. The set of recently selected elements one becomes aware of is seen as forming a low-dimensional conscious state. This conscious state is combining the few concepts constituting a conscious thought, i.e., what one is immediately conscious of at a particular moment. We claim that this architectural and information-processing constraint corresponds to assumptions about the joint distribution between high-level concepts. To the extent that these assumptions are generally true (and the form of natural language seems consistent with them), they can form a useful prior for representation learning. A low-dimensional thought or conscious state is analogous to a sentence: it involves only a few variables and yet can make a statement with very high probability of being true. This is consistent with a joint distribution (over high-level concepts) which has the form of a sparse factor graph, i.e., where the dependencies captured by each factor of the factor graph involve only very few variables while creating a strong dip in the overall energy function. The consciousness prior also makes it natural to map conscious states to natural language utterances or to express classical AI knowledge in a form similar to facts and rules, albeit capturing uncertainty as well as efficient search mechanisms implemented by attention mechanisms.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:22,n_refs_in_core:6,degree:9,community:2,deg_w:39.5,betweenness:.0187,pagerank:.00365,eigenvector:1e-4},{id:341,oaid:"d96997265f8146e93b4c9350f19d55e46d1317f0",doi:"10.48550/arXiv.2210.03849",title:"ConvFinQA: Exploring the Chain of Numerical Reasoning in Conversational Finance Question Answering",authors:[{name:"Zhiyu Chen",institutions:[]},{name:"SHIYANG LI",institutions:["University of California, Santa Barbara"]},{name:"Charese Smiley",institutions:[]},{name:"Zhiqiang Ma",institutions:[]},{name:"Sameena Shah",institutions:[]},{name:"William Yang Wang",institutions:[]}],authorString:"Zhiyu Chen; SHIYANG LI; Charese Smiley; Zhiqiang Ma; Sameena Shah; William Yang Wang",institutions:["University of California, Santa Barbara"],countries:[],year:2022,journal:"Conference on Empirical Methods in Natural Language Processing",citations:270,abstract:"With the recent advance in large pre-trained language models, researchers have achieved record performances in NLP tasks that mostly focus on language pattern matching. The community is experiencing the shift of the challenge from how to model language to the imitation of complex reasoning abilities like human beings. In this work, we investigate the application domain of finance that involves real-world, complex numerical reasoning. We propose a new large-scale dataset, ConvFinQA, aiming to study the chain of numerical reasoning in conversational question answering. Our dataset poses great challenge in modeling long-range, complex numerical reasoning paths in real-world conversations. We conduct comprehensive experiments and analyses with both the neural symbolic methods and the prompting-based methods, to provide insights into the reasoning mechanisms of these two divisions. We believe our new dataset should serve as a valuable resource to push forward the exploration of real-world, complex reasoning tasks as the next research focus. Our dataset and code is publicly available at https://github.com/czyssrs/ConvFinQA.",keywords:["Economics"],concepts:["Economics"],pdf_url:"http://arxiv.org/pdf/2210.03849",is_oa:!0,n_refs:32,n_refs_in_core:5,degree:20,community:5,deg_w:139.5,betweenness:.01,pagerank:.00385,eigenvector:.0246},{id:342,oaid:"4d8c55d021b38ac9a15a855b3a82bfed49e64e56",doi:null,title:"Under Consideration for Publication in Theory and Practice of Logic Programming Inference and Learning in Probabilistic Logic Programs Using Weighted Boolean Formulas",authors:[],authorString:"",institutions:[],countries:[],year:null,journal:"",citations:269,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:58e-5,eigenvector:0},{id:343,oaid:"ef2bbcd928749978b4395460a96c9869833c9c89",doi:"10.1098/rsta.2022.0050",title:"DreamCoder: growing generalizable, interpretable knowledge with wake–sleep Bayesian program learning",authors:[{name:"Kevin Ellis",institutions:[]},{name:"Catherine Wong",institutions:[]},{name:"Maxwell Nye",institutions:["MIT"]},{name:"Mathias Sablé-Meyer",institutions:[]},{name:"Luc Cary",institutions:[]},{name:"Lucas Morales",institutions:[]},{name:"Luke Hewitt",institutions:[]},{name:"Armando Solar-Lezama",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Kevin Ellis; Catherine Wong; Maxwell Nye; Mathias Sablé-Meyer; Luc Cary; Lucas Morales; Luke Hewitt; Armando Solar-Lezama; J. Tenenbaum",institutions:["MIT"],countries:[],year:2020,journal:"Philosophical Transactions of the Royal Society A",citations:266,abstract:"Expert problem-solving is driven by powerful languages for thinking about problems and their solutions. Acquiring expertise means learning these languages—systems of concepts, alongside the skills to use them. We present DreamCoder, a system that learns to solve problems by writing programs. It builds expertise by creating domain-specific programming languages for expressing domain concepts, together with neural networks to guide the search for programs within these languages. A ‘wake–sleep’ learning algorithm alternately extends the language with new symbolic abstractions and trains the neural network on imagined and replayed problems. DreamCoder solves both classic inductive programming tasks and creative tasks such as drawing pictures and building scenes. It rediscovers the basics of modern functional programming, vector algebra and classical physics, including Newton’s and Coulomb’s laws. Concepts are built compositionally from those learned earlier, yielding multilayered symbolic representations that are interpretable and transferrable to new tasks, while still growing scalably and flexibly with experience. This article is part of a discussion meeting issue ‘Cognitive artificial intelligence’.",keywords:[],concepts:[],pdf_url:"https://royalsocietypublishing.org/doi/pdf/10.1098/rsta.2022.0050",is_oa:!0,n_refs:78,n_refs_in_core:23,degree:30,community:7,deg_w:156,betweenness:.0474,pagerank:.00834,eigenvector:4e-4},{id:344,oaid:"f8909e8b359c72bc0e3257dadcc48a8787bca74b",doi:null,title:"DeepMath - Deep Sequence Models for Premise Selection",authors:[{name:"G. Irving",institutions:[]},{name:"Christian Szegedy",institutions:[]},{name:"Alexander A. Alemi",institutions:["Google"]},{name:"N. Eén",institutions:[]},{name:"François Chollet",institutions:[]},{name:"J. Urban",institutions:[]}],authorString:"G. Irving; Christian Szegedy; Alexander A. Alemi; N. Eén; François Chollet; J. Urban",institutions:["Google"],countries:[],year:2016,journal:"Neural Information Processing Systems",citations:266,abstract:"We study the effectiveness of neural sequence models for premise selection in automated theorem proving, one of the main bottlenecks in the formalization of mathematics. We propose a two stage approach for this task that yields good results for the premise selection task on the Mizar corpus while avoiding the hand-engineered features of existing state-of-the-art models. To our knowledge, this is the first time deep learning has been applied to theorem proving on a large scale.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:11,community:6,deg_w:43,betweenness:1e-4,pagerank:.00141,eigenvector:.0011},{id:345,oaid:"a1f47aeccf32009385ac25e17480eabe781cd126",doi:null,title:"On large subsets of F nq with no three-termarithmetic progression",authors:[{name:"J. Ellenberg",institutions:[]},{name:"D. Gijswijt",institutions:[]}],authorString:"J. Ellenberg; D. Gijswijt",institutions:[],countries:[],year:2017,journal:"",citations:259,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:8,deg_w:12.5,betweenness:1e-4,pagerank:95e-5,eigenvector:1e-4},{id:346,oaid:"6ac33d3dcecbed17580509a34bccdff2425f7ed8",doi:null,title:"Learning Conditioned Graph Structures for Interpretable Visual Question Answering",authors:[{name:"Will Norcliffe-Brown",institutions:[]},{name:"Efstathios Vafeias",institutions:[]},{name:"Sarah Parisot",institutions:[]}],authorString:"Will Norcliffe-Brown; Efstathios Vafeias; Sarah Parisot",institutions:[],countries:[],year:2018,journal:"Neural Information Processing Systems",citations:257,abstract:"Visual Question answering is a challenging problem requiring a combination of concepts from Computer Vision and Natural Language Processing. Most existing approaches use a two streams strategy, computing image and question features that are consequently merged using a variety of techniques. Nonetheless, very few rely on higher level image representations, which allow to capture semantic and spatial relationships. In this paper, we propose a novel graph-based approach for Visual Question Answering. Our method combines a graph learner module, which learns a question specific graph representation of the input image, with the recent concept of graph convolutions, aiming to learn image representations that capture question specific interactions. We test our approach on the VQA v2 dataset using a simple baseline architecture enhanced by the proposed graph learner module. We obtain state of the art results with 66.18% accuracy and demonstrate the interpretability of the proposed method.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:23,n_refs_in_core:1,degree:8,community:3,deg_w:64,betweenness:0,pagerank:.00153,eigenvector:4e-4},{id:347,oaid:"fc05299c68af1dc42a24ad08533268fbb67dd4db",doi:"10.1109/CVPR.2017.14",title:"Discovering Causal Signals in Images",authors:[{name:"David Lopez-Paz",institutions:[]},{name:"Robert Nishihara",institutions:[]},{name:"Soumith Chintala",institutions:[]},{name:"B. Scholkopf",institutions:[]},{name:"L. Bottou",institutions:[]}],authorString:"David Lopez-Paz; Robert Nishihara; Soumith Chintala; B. Scholkopf; L. Bottou",institutions:[],countries:[],year:2016,journal:"Computer Vision and Pattern Recognition",citations:257,abstract:"This paper establishes the existence of observable footprints that reveal the causal dispositions of the object categories appearing in collections of images. We achieve this goal in two steps. First, we take a learning approach to observational causal discovery, and build a classifier that achieves state-of-the-art performance on finding the causal direction between pairs of random variables, given samples from their joint distribution. Second, we use our causal direction classifier to effectively distinguish between features of objects and features of their contexts in collections of static images. Our experiments demonstrate the existence of a relation between the direction of causality and the difference between objects and their contexts, and by the same token, the existence of observable signals that reveal the causal dispositions of objects.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1605.08179",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:2e-4,pagerank:54e-5,eigenvector:0},{id:348,oaid:"516668a41d6106232a7cd56d20d3b3da343e5f36",doi:"10.1109/ICCV.2017.77",title:"Predicting Deeper into the Future of Semantic Segmentation",authors:[{name:"Pauline Luc",institutions:[]},{name:"N. Neverova",institutions:[]},{name:"C. Couprie",institutions:[]},{name:"J. Verbeek",institutions:[]},{name:"Yann LeCun",institutions:["Facebook","NYU"]}],authorString:"Pauline Luc; N. Neverova; C. Couprie; J. Verbeek; Yann LeCun",institutions:["Facebook","NYU"],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:256,abstract:"The ability to predict and therefore to anticipate the future is an important attribute of intelligence. It is also of utmost importance in real-time systems, e.g. in robotics or autonomous driving, which depend on visual scene understanding for decision making. While prediction of the raw RGB pixel values in future video frames has been studied in previous work, here we introduce the novel task of predicting semantic segmentations of future frames. Given a sequence of video frames, our goal is to predict segmentation maps of not yet observed video frames that lie up to a second or further in the future. We develop an autoregressive convolutional neural network that learns to iteratively generate multiple frames. Our results on the Cityscapes dataset show that directly predicting future segmentations is substantially better than predicting and then segmenting future RGB frames. Prediction results up to half a second in the future are visually convincing and are much more accurate than those of a baseline based on warping semantic segmentations using optical flow.",keywords:[],concepts:[],pdf_url:"https://hal.inria.fr/hal-01494296/file/0270.pdf",is_oa:!0,n_refs:49,n_refs_in_core:1,degree:7,community:2,deg_w:34,betweenness:8e-4,pagerank:.00138,eigenvector:0},{id:349,oaid:"bc9f3c466c6f6b386f4ef1195853d498cf3c182e",doi:"10.18653/v1/D17-1106",title:"Mapping Instructions and Visual Observations to Actions with Reinforcement Learning",authors:[{name:"Dipendra Kumar Misra",institutions:["Cornell University"]},{name:"John Langford",institutions:[]},{name:"Yoav Artzi",institutions:["Cornell University"]}],authorString:"Dipendra Kumar Misra; John Langford; Yoav Artzi",institutions:["Cornell University"],countries:[],year:2017,journal:"Conference on Empirical Methods in Natural Language Processing",citations:256,abstract:"We propose to directly map raw visual observations and text input to actions for instruction execution. While existing approaches assume access to structured environment representations or use a pipeline of separately trained models, we learn a single model to jointly reason about linguistic and visual input. We use reinforcement learning in a contextual bandit setting to train a neural network agent. To guide the agent’s exploration, we use reward shaping with different forms of supervision. Our approach does not require intermediate representations, planning procedures, or training different models. We evaluate in a simulated environment, and show significant improvements over supervised learning and common reinforcement learning variants.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D17-1106.pdf",is_oa:!0,n_refs:61,n_refs_in_core:5,degree:24,community:4,deg_w:147,betweenness:.0152,pagerank:.00396,eigenvector:.0022},{id:350,oaid:"2c69bbb3b7ba3f324276924bab6f41de467c928a",doi:"10.1007/978-3-319-60045-1_44",title:"CN-DBpedia: A Never-Ending Chinese Knowledge Extraction System",authors:[{name:"Bo Xu",institutions:[]},{name:"Yong Xu",institutions:[]},{name:"Jiaqing Liang",institutions:[]},{name:"Remy Xie",institutions:[]},{name:"Bin Liang",institutions:[]},{name:"Wanyun Cui",institutions:[]},{name:"Yanghua Xiao",institutions:[]}],authorString:"Bo Xu; Yong Xu; Jiaqing Liang; Remy Xie; Bin Liang; Wanyun Cui; Yanghua Xiao",institutions:[],countries:[],year:2017,journal:"International Conference on Industrial, Engineering and Other Applications of Applied Intelligent Systems",citations:256,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:.0088},{id:351,oaid:"7ca4abace88db259faed67686ed7bba02b46eb82",doi:null,title:"Language-Conditioned Imitation Learning for Robot Manipulation Tasks",authors:[{name:"Simon Stepputtis",institutions:[]},{name:"Joseph Campbell",institutions:[]},{name:"Mariano Phielipp",institutions:[]},{name:"Stefan Lee",institutions:[]},{name:"Chitta Baral",institutions:["Arizona State University"]},{name:"H. B. Amor",institutions:[]}],authorString:"Simon Stepputtis; Joseph Campbell; Mariano Phielipp; Stefan Lee; Chitta Baral; H. B. Amor",institutions:["Arizona State University"],countries:[],year:2020,journal:"Neural Information Processing Systems",citations:255,abstract:'Imitation learning is a popular approach for teaching motor skills to robots. However, most approaches focus on extracting policy parameters from execution traces alone (i.e., motion trajectories and perceptual data). No adequate communication channel exists between the human expert and the robot to describe critical aspects of the task, such as the properties of the target object or the intended shape of the motion. Motivated by insights into the human teaching process, we introduce a method for incorporating unstructured natural language into imitation learning. At training time, the expert can provide demonstrations along with verbal descriptions in order to describe the underlying intent (e.g., "go to the large green bowl"). The training process then interrelates these two modalities to encode the correlations between language, perception, and motion. The resulting language-conditioned visuomotor policies can be conditioned at runtime on new human commands and instructions, which allows for more fine-grained control over the trained policies while also reducing situational ambiguity. We demonstrate in a set of simulation experiments how our approach can learn language-conditioned manipulation policies for a seven-degree-of-freedom robot arm and compare the results to a variety of alternative methods.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:34,n_refs_in_core:0,degree:4,community:4,deg_w:25.5,betweenness:0,pagerank:9e-4,eigenvector:2e-4},{id:352,oaid:"0e802c0739771acf70e60d59c2df51cd7e8c50c0",doi:"10.48550/arXiv.2203.08913",title:"Memorizing Transformers",authors:[{name:"Yuhuai Wu",institutions:[]},{name:"M. Rabe",institutions:[]},{name:"DeLesley S. Hutchins",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"Yuhuai Wu; M. Rabe; DeLesley S. Hutchins; Christian Szegedy",institutions:[],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:253,abstract:"Language models typically need to be trained or finetuned in order to acquire new knowledge, which involves updating their weights. We instead envision language models that can simply read and memorize new data at inference time, thus acquiring new knowledge immediately. In this work, we extend language models with the ability to memorize the internal representations of past inputs. We demonstrate that an approximate kNN lookup into a non-differentiable memory of recent (key, value) pairs improves language modeling across various benchmarks and tasks, including generic webtext (C4), math papers (arXiv), books (PG-19), code (Github), as well as formal theorems (Isabelle). We show that the performance steadily improves when we increase the size of memory up to 262K tokens. On benchmarks including code and mathematics, we find that the model is capable of making use of newly defined functions and theorems during test time.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2203.08913",is_oa:!0,n_refs:46,n_refs_in_core:5,degree:22,community:1,deg_w:157,betweenness:.0183,pagerank:.00411,eigenvector:.035},{id:353,oaid:"9f0b217cb21ec8c19610e28bd0805d7871456e4b",doi:null,title:"Learning to Infer Graphics Programs from Hand-Drawn Images",authors:[{name:"Kevin Ellis",institutions:[]},{name:"Daniel Ritchie",institutions:[]},{name:"Armando Solar-Lezama",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Kevin Ellis; Daniel Ritchie; Armando Solar-Lezama; J. Tenenbaum",institutions:[],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:253,abstract:"We introduce a model that learns to convert simple hand drawings into graphics programs written in a subset of \\LaTeX. The model combines techniques from deep learning and program synthesis. We learn a convolutional neural network that proposes plausible drawing primitives that explain an image. These drawing primitives are like a trace of the set of primitive commands issued by a graphics program. We learn a model that uses program synthesis techniques to recover a graphics program from that trace. These programs have constructs like variable bindings, iterative loops, or simple kinds of conditionals. With a graphics program in hand, we can correct errors made by the deep network, measure similarity between drawings by use of similar high-level geometric structures, and extrapolate drawings. Taken together these results are a step towards agents that induce useful, human-readable programs from perceptual input.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:63e-5,eigenvector:0},{id:354,oaid:"65b4b25272c50dc376f5c018338931bfd349e532",doi:"10.48550/arXiv.2205.11491",title:"HyperTree Proof Search for Neural Theorem Proving",authors:[{name:"Guillaume Lample",institutions:[]},{name:"M. Lachaux",institutions:[]},{name:"Thibaut Lavril",institutions:[]},{name:"X. Martinet",institutions:[]},{name:"Amaury Hayat",institutions:[]},{name:"Gabriel Ebner",institutions:[]},{name:"Aur'elien Rodriguez",institutions:[]},{name:"Timothée Lacroix",institutions:[]}],authorString:"Guillaume Lample; M. Lachaux; Thibaut Lavril; X. Martinet; Amaury Hayat; Gabriel Ebner; Aur'elien Rodriguez; Timothée Lacroix",institutions:[],countries:[],year:2022,journal:"Neural Information Processing Systems",citations:253,abstract:"We propose an online training procedure for a transformer-based automated theorem prover. Our approach leverages a new search algorithm, HyperTree Proof Search (HTPS), inspired by the recent success of AlphaZero. Our model learns from previous proof searches through online training, allowing it to generalize to domains far from the training distribution. We report detailed ablations of our pipeline's main components by studying performance on three environments of increasing complexity. In particular, we show that with HTPS alone, a model trained on annotated proofs manages to prove 65.4% of a held-out set of Metamath theorems, significantly outperforming the previous state of the art of 56.5% by GPT-f. Online training on these unproved theorems increases accuracy to 82.6%. With a similar computational budget, we improve the state of the art on the Lean-based miniF2F-curriculum dataset from 31% to 42% proving accuracy.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2205.11491",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:6,deg_w:12.5,betweenness:0,pagerank:62e-5,eigenvector:7e-4},{id:355,oaid:"64a1dbdd7653eaca25c78e87335ee156b6f6959e",doi:"10.18653/v1/2021.emnlp-main.608",title:"Constrained Language Models Yield Few-Shot Semantic Parsers",authors:[{name:"Richard Shin",institutions:[]},{name:"C. H. Lin",institutions:[]},{name:"Sam Thomson",institutions:[]},{name:"Charles C. Chen",institutions:[]},{name:"Subhro Roy",institutions:[]},{name:"Emmanouil Antonios Platanios",institutions:[]},{name:"Adam Pauls",institutions:[]},{name:"D. Klein",institutions:[]},{name:"J. Eisner",institutions:[]},{name:"Benjamin Van Durme",institutions:[]}],authorString:"Richard Shin; C. H. Lin; Sam Thomson; Charles C. Chen; Subhro Roy; Emmanouil Antonios Platanios; Adam Pauls; D. Klein; J. Eisner; Benjamin Van Durme",institutions:[],countries:[],year:2021,journal:"Conference on Empirical Methods in Natural Language Processing",citations:251,abstract:"We explore the use of large pretrained language models as few-shot semantic parsers. The goal in semantic parsing is to generate a structured meaning representation given a natural language input. However, language models are trained to generate natural language. To bridge the gap, we use language models to paraphrase inputs into a controlled sublanguage resembling English that can be automatically mapped to a target meaning representation. Our results demonstrate that with only a small amount of data and very little code to convert into English-like representations, our blueprint for rapidly bootstrapping semantic parsers leads to surprisingly effective performance on multiple community tasks, greatly exceeding baseline methods also trained on the same limited data.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.emnlp-main.608.pdf",is_oa:!0,n_refs:60,n_refs_in_core:2,degree:18,community:5,deg_w:116.5,betweenness:.0031,pagerank:.0031,eigenvector:.0145},{id:356,oaid:"3dd61d97827e3f380bf9304101149a3f865051fc",doi:"10.18653/v1/2020.acl-main.89",title:"Injecting Numerical Reasoning Skills into Language Models",authors:[{name:"Mor Geva",institutions:["Google Research"]},{name:"Ankit Gupta",institutions:["IBM Research"]},{name:"Jonathan Berant",institutions:["Tel-Aviv University and Google DeepMind"]}],authorString:"Mor Geva; Ankit Gupta; Jonathan Berant",institutions:["Google Research","IBM Research","Tel-Aviv University and Google DeepMind"],countries:[],year:2020,journal:"Annual Meeting of the Association for Computational Linguistics",citations:249,abstract:"Large pre-trained language models (LMs) are known to encode substantial amounts of linguistic information. However, high-level reasoning skills, such as numerical reasoning, are difficult to learn from a language-modeling objective only. Consequently, existing models for numerical reasoning have used specialized architectures with limited flexibility. In this work, we show that numerical reasoning is amenable to automatic data generation, and thus one can inject this skill into pre-trained LMs, by generating large amounts of data, and training in a multi-task setup. We show that pre-training our model, GenBERT, on this data, dramatically improves performance on DROP (49.3 –> 72.3 F1), reaching performance that matches state-of-the-art models of comparable size, while using a simple and general-purpose encoder-decoder architecture. Moreover, GenBERT generalizes well to math word problem datasets, while maintaining high performance on standard RC tasks. Our approach provides a general recipe for injecting skills into large pre-trained LMs, whenever the skill is amenable to automatic data augmentation.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.89.pdf",is_oa:!0,n_refs:30,n_refs_in_core:9,degree:25,community:5,deg_w:144.5,betweenness:.0108,pagerank:.00392,eigenvector:.0446},{id:357,oaid:"c2c8482c713b94073f3d59895b373db4398ddfbb",doi:null,title:"Language as an Abstraction for Hierarchical Deep Reinforcement Learning",authors:[{name:"Yiding Jiang",institutions:[]},{name:"S. Gu",institutions:[]},{name:"K. Murphy",institutions:[]},{name:"Chelsea Finn",institutions:[]}],authorString:"Yiding Jiang; S. Gu; K. Murphy; Chelsea Finn",institutions:[],countries:[],year:2019,journal:"Neural Information Processing Systems",citations:249,abstract:"Solving complex, temporally-extended tasks is a long-standing problem in reinforcement learning (RL). We hypothesize that one critical element of solving such problems is the notion of compositionality. With the ability to learn concepts and sub-skills that can be composed to solve longer tasks, i.e. hierarchical RL, we can acquire temporally-extended behaviors. However, acquiring effective yet general abstractions for hierarchical RL is remarkably challenging. In this paper, we propose to use language as the abstraction, as it provides unique compositional structure, enabling fast learning and combinatorial generalization, while retaining tremendous flexibility, making it suitable for a variety of problems. Our approach learns an instruction-following low-level policy and a high-level policy that can reuse abstractions across tasks, in essence, permitting agents to reason using structured language. To study compositional task learning, we introduce an open-source object interaction environment built using the MuJoCo physics engine and the CLEVR engine. We find that, using our approach, agents can learn to solve to diverse, temporally-extended tasks such as object sorting and multi-object rearrangement, including from raw pixel observations. Our analysis reveals that the compositional nature of language is critical for learning diverse sub-skills and systematically generalizing to new sub-skills in comparison to non-compositional abstractions that use the same supervision.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:70,n_refs_in_core:2,degree:15,community:4,deg_w:90.5,betweenness:.0056,pagerank:.00267,eigenvector:.0013},{id:358,oaid:"caf1a5982b999a1826fed308cefb4dd3c5fa0052",doi:"10.24963/ijcai.2017/221",title:"Logic Tensor Networks for Semantic Image Interpretation",authors:[{name:"Ivan Donadello",institutions:[]},{name:"L. Serafini",institutions:[]},{name:"A. Garcez",institutions:[]}],authorString:"Ivan Donadello; L. Serafini; A. Garcez",institutions:[],countries:[],year:2017,journal:"International Joint Conference on Artificial Intelligence",citations:248,abstract:"Semantic Image Interpretation (SII) is the task of extracting structured semantic descriptions from images. It is widely agreed that the combined use of visual data and background knowledge is of great importance for SII. Recently, Statistical Relational Learning (SRL) approaches have been developed for reasoning under uncertainty and learning in the presence of data and rich knowledge. Logic Tensor Networks (LTNs) are an SRL framework which integrates neural networks with first-order fuzzy logic to allow (i) efficient learning from noisy data in the presence of logical constraints, and (ii) reasoning with logical formulas describing general properties of the data. In this paper, we develop and apply LTNs to two of the main tasks of SII, namely, the classification of an image's bounding boxes and the detection of the relevant part-of relations between objects. To the best of our knowledge, this is the first successful application of SRL to such SII tasks. The proposed approach is evaluated on a standard image processing benchmark. Experiments show that the use of background knowledge in the form of logical constraints can improve the performance of purely data-driven approaches, including the state-of-the-art Fast Region-based Convolutional Neural Networks (Fast R-CNN). Moreover, we show that the use of logical background knowledge adds robustness to the learning system when errors are present in the labels of the training data.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2017/0221.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:6,community:0,deg_w:25.5,betweenness:0,pagerank:.00137,eigenvector:2e-4},{id:359,oaid:"157f77a508c1645a2609c9b265391e9d1bfa95e4",doi:null,title:"Schema Networks: Zero-shot Transfer with a Generative Causal Model of Intuitive Physics",authors:[{name:"Ken Kansky",institutions:[]},{name:"Tom Silver",institutions:[]},{name:"David A. Mély",institutions:[]},{name:"Mohamed Eldawy",institutions:[]},{name:"M. Lázaro-Gredilla",institutions:[]},{name:"Xinghua Lou",institutions:[]},{name:"Nimrod Dorfman",institutions:[]},{name:"Szymon Sidor",institutions:[]},{name:"Scott Phoenix",institutions:[]},{name:"Dileep George",institutions:[]}],authorString:"Ken Kansky; Tom Silver; David A. Mély; Mohamed Eldawy; M. Lázaro-Gredilla; Xinghua Lou; Nimrod Dorfman; Szymon Sidor; Scott Phoenix; Dileep George",institutions:[],countries:[],year:2017,journal:"International Conference on Machine Learning",citations:247,abstract:"The recent adaptation of deep neural network-based methods to reinforcement learning and planning domains has yielded remarkable progress on individual tasks. Nonetheless, progress on task-to-task transfer remains limited. In pursuit of efficient and robust generalization, we introduce the Schema Network, an object-oriented generative physics simulator capable of disentangling multiple causes of events and reasoning backward through causes to achieve goals. The richly structured architecture of the Schema Network can learn the dynamics of an environment directly from data. We compare Schema Networks with Asynchronous Advantage Actor-Critic and Progressive Networks on a suite of Breakout variations, reporting results on training efficiency and zero-shot generalization, consistently demonstrating faster, more robust learning and better transfer. We argue that generalizing from limited data and learning causal relationships are essential abilities on the path toward generally intelligent systems.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:360,oaid:"67e68e17c851370fe996933af077e364dd05f16e",doi:"10.1007/978-3-540-73246-4",title:"Neural-Symbolic Cognitive Reasoning",authors:[{name:"A. Garcez",institutions:[]},{name:"L. Lamb",institutions:[]},{name:"D. Gabbay",institutions:[]}],authorString:"A. Garcez; L. Lamb; D. Gabbay",institutions:[],countries:[],year:2008,journal:"Cognitive Technologies",citations:238,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:65e-5,eigenvector:0},{id:361,oaid:"8926fe3197a53ec0e08ee4e50b655b4e46c13ccb",doi:"10.1016/J.COBEHA.2018.12.010",title:"Reconciling deep learning with symbolic artificial intelligence: representing objects and relations",authors:[{name:"M. Garnelo",institutions:[]},{name:"M. Shanahan",institutions:[]}],authorString:"M. Garnelo; M. Shanahan",institutions:[],countries:[],year:2019,journal:"Current Opinion in Behavioral Sciences",citations:238,abstract:"In the history of the quest for human-level artificial intelligence, a number of rival paradigms have vied for supremacy. Symbolic artificial intelligence was dominant for much of the 20th century, but currently a connectionist paradigm is in the ascendant, namely machine learning with deep neural networks. However, both paradigms have strengths and weaknesses, and a significant challenge for the field today is to effect a reconciliation. A central tenet of the symbolic paradigm is that intelligence results from the manipulation of abstract compositional representations whose elements stand for objects and relations. If this is correct, then a key objective for deep learning is to develop architectures capable of discovering objects and relations in raw data, and learning how to represent them in ways that are useful for downstream processing. This short review highlights recent progress in this direction.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://www.sciencedirect.com/science/article/pii/S2352154618301943/pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:58e-5,eigenvector:1e-4},{id:362,oaid:"19af8292ff3cc10aad6f190490f0d34691658179",doi:"10.18653/v1/2021.nlp4convai-1.20",title:"Investigating Pretrained Language Models for Graph-to-Text Generation",authors:[{name:"Leonardo F. R. Ribeiro",institutions:["Amazon, TU Darmstadt"]},{name:"Martin Schmitt",institutions:["Ludwig-Maximilians-Universität München"]},{name:"Hinrich Schütze",institutions:[]},{name:"Iryna Gurevych",institutions:[]}],authorString:"Leonardo F. R. Ribeiro; Martin Schmitt; Hinrich Schütze; Iryna Gurevych",institutions:["Amazon, TU Darmstadt","Ludwig-Maximilians-Universität München"],countries:[],year:2020,journal:"NLP4CONVAI",citations:236,abstract:"Graph-to-text generation aims to generate fluent texts from graph-based data. In this paper, we investigate two recent pretrained language models (PLMs) and analyze the impact of different task-adaptive pretraining strategies for PLMs in graph-to-text generation. We present a study across three graph domains: meaning representations, Wikipedia knowledge graphs (KGs) and scientific KGs. We show that approaches based on PLMs BART and T5 achieve new state-of-the-art results and that task-adaptive pretraining strategies improve their performance even further. We report new state-of-the-art BLEU scores of 49.72 on AMR-LDC2017T10, 59.70 on WebNLG, and 25.66 on AGENDA datasets - a relative improvement of 31.8%, 4.5%, and 42.4%, respectively, with our models generating significantly more fluent texts than human references. In an extensive analysis, we identify possible reasons for the PLMs’ success on graph-to-text tasks. Our findings suggest that the PLMs benefit from similar facts seen during pretraining or fine-tuning, such that they perform well even when the input graph is reduced to a simple bag of node and edge labels.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://aclanthology.org/2021.nlp4convai-1.20.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:.0081},{id:363,oaid:"033dd6cf61a6017e9aa9b46068d3c89082849cf3",doi:null,title:"Tracking the World State with Recurrent Entity Networks",authors:[{name:"Mikael Henaff",institutions:[]},{name:"J. Weston",institutions:[]},{name:"Arthur Szlam",institutions:[]},{name:"Antoine Bordes",institutions:[]},{name:"Yann LeCun",institutions:["Facebook","NYU"]}],authorString:"Mikael Henaff; J. Weston; Arthur Szlam; Antoine Bordes; Yann LeCun",institutions:["Facebook","NYU"],countries:[],year:2016,journal:"International Conference on Learning Representations",citations:236,abstract:"We introduce a new model, the Recurrent Entity Network (EntNet). It is equipped with a dynamic long-term memory which allows it to maintain and update a representation of the state of the world as it receives new data. For language understanding tasks, it can reason on-the-fly as it reads text, not just when it is required to answer a question or respond as is the case for a Memory Network (Sukhbaatar et al., 2015). Like a Neural Turing Machine or Differentiable Neural Computer (Graves et al., 2014; 2016) it maintains a fixed size memory and can learn to perform location and content-based read and write operations. However, unlike those models it has a simple parallel architecture in which several memory locations can be updated simultaneously. The EntNet sets a new state-of-the-art on the bAbI tasks, and is the first method to solve all the tasks in the 10k training examples setting. We also demonstrate that it can solve a reasoning task which requires a large number of supporting facts, which other methods are not able to solve, and can generalize past its training horizon. It can also be practically used on large scale datasets such as Children's Book Test, where it obtains competitive performance, reading the story in a single pass.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:33,n_refs_in_core:7,degree:23,community:2,deg_w:137,betweenness:.0105,pagerank:.00425,eigenvector:9e-4},{id:364,oaid:"73465a283cdcc790b3bfc7f71b3b433c6ea403a8",doi:"10.1007/s10710-010-9113-2",title:"Open issues in genetic programming",authors:[{name:"M. O’Neill",institutions:[]},{name:"L. Vanneschi",institutions:[]},{name:"Steven M. Gustafson",institutions:["Maana, Inc.","University of Nottingham","Kansas State University","General Electric","Noonum, Inc","BigFilter.ai","GE Global Research","University of Washington"]},{name:"W. Banzhaf",institutions:[]}],authorString:"M. O’Neill; L. Vanneschi; Steven M. Gustafson; W. Banzhaf",institutions:["BigFilter.ai","GE Global Research","General Electric","Kansas State University","Maana, Inc.","Noonum, Inc","University of Nottingham","University of Washington"],countries:[],year:2010,journal:"Genetic Programming and Evolvable Machines",citations:236,abstract:"It is approximately 50 years since the first computational experiments were conducted in what has become known today as the field of Genetic Programming (GP), twenty years since John Koza named and popularised the method, and ten years since the first issue appeared of the Genetic Programming & Evolvable Machines journal. In particular, during the past two decades there has been a significant range and volume of development in the theory and application of GP, and in recent years the field has become increasingly applied. There remain a number of significant open issues despite the successful application of GP to a number of challenging real-world problem domains and progress in the development of a theory explaining the behavior and dynamics of GP. These issues must be addressed for GP to realise its full potential and to become a trusted mainstream member of the computational problem solving toolkit. In this paper we outline some of the challenges and open issues that face researchers and practitioners of GP. We hope this overview will stimulate debate, focus the direction of future research to deepen our understanding of GP, and further the development of more powerful problem solving algorithms.",keywords:[],concepts:[],pdf_url:"http://hdl.handle.net/10197/2560",is_oa:!0,n_refs:143,n_refs_in_core:2,degree:3,community:8,deg_w:17,betweenness:0,pagerank:.00146,eigenvector:1e-4},{id:365,oaid:"376f23cce537235122fdce5524d084e3a869c403",doi:null,title:"Towards Deep Symbolic Reinforcement Learning",authors:[{name:"M. Garnelo",institutions:[]},{name:"K. Arulkumaran",institutions:[]},{name:"M. Shanahan",institutions:[]}],authorString:"M. Garnelo; K. Arulkumaran; M. Shanahan",institutions:[],countries:[],year:2016,journal:"arXiv.org",citations:236,abstract:"Deep reinforcement learning (DRL) brings the power of deep neural networks to bear on the generic task of trial-and-error learning, and its effectiveness has been convincingly demonstrated on tasks such as Atari video games and the game of Go. However, contemporary DRL systems inherit a number of shortcomings from the current generation of deep learning techniques. For example, they require very large datasets to work effectively, entailing that they are slow to learn even when such datasets are available. Moreover, they lack the ability to reason on an abstract level, which makes it difficult to implement high-level cognitive functions such as transfer learning, analogical reasoning, and hypothesis-based reasoning. Finally, their operation is largely opaque to humans, rendering them unsuitable for domains in which verifiability is important. In this paper, we propose an end-to-end reinforcement learning architecture comprising a neural back end and a symbolic front end with the potential to overcome each of these shortcomings. As proof-of-concept, we present a preliminary implementation of the architecture and apply it to several variants of a simple video game. We show that the resulting system -- though just a prototype -- learns effectively, and, by acquiring a set of symbolic rules that are easily comprehensible to humans, dramatically outperforms a conventional, fully neural DRL system on a stochastic variant of the game.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:12.5,betweenness:3e-4,pagerank:63e-5,eigenvector:1e-4},{id:366,oaid:"767ceaade8a2cfb186f20091e50c7d03641e0caa",doi:"10.18653/v1/2022.acl-long.396",title:"Subgraph Retrieval Enhanced Model for Multi-hop Knowledge Base Question Answering",authors:[{name:"Jing Zhang",institutions:[]},{name:"Xiaokang Zhang",institutions:[]},{name:"Jifan Yu",institutions:[]},{name:"Jian Tang",institutions:[]},{name:"Jie Tang",institutions:[]},{name:"Cuiping Li",institutions:[]},{name:"Hong Chen",institutions:["Renmin University of China"]}],authorString:"Jing Zhang; Xiaokang Zhang; Jifan Yu; Jian Tang; Jie Tang; Cuiping Li; Hong Chen",institutions:["Renmin University of China"],countries:[],year:2022,journal:"Annual Meeting of the Association for Computational Linguistics",citations:235,abstract:"Recent works on knowledge base question answering (KBQA) retrieve subgraphs for easier reasoning. The desired subgraph is crucial as a small one may exclude the answer but a large one might introduce more noises. However, the existing retrieval is either heuristic or interwoven with the reasoning, causing reasoning on the partial subgraphs, which increases the reasoning bias when the intermediate supervision is missing. This paper proposes a trainable subgraph retriever (SR) decoupled from the subsequent reasoning process, which enables a plug-and-play framework to enhance any subgraph-oriented KBQA model. Extensive experiments demonstrate SR achieves significantly better retrieval and QA performance than existing retrieval methods. Via weakly supervised pre-training as well as the end-to-end fine-tuning, SR achieves new state-of-the-art performance when combined with NSM (He et al., 2021), a subgraph-oriented reasoner, for embedding-based KBQA methods. Codes and datasets are available online (https://github.com/RUCKBReasoning/SubgraphRetrievalKBQA)",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2022.acl-long.396.pdf",is_oa:!0,n_refs:33,n_refs_in_core:3,degree:8,community:1,deg_w:46.5,betweenness:.0036,pagerank:.00142,eigenvector:.0205},{id:367,oaid:"540112b5f56f1572c87a4d29ab6d5250795ecf2e",doi:"10.24963/ijcai.2021/551",title:"Document-level Relation Extraction as Semantic Segmentation",authors:[{name:"Ningyu Zhang",institutions:["Zhejiang University"]},{name:"Xiang Chen",institutions:["ZheJiang University, College of Computer Science and Technology, ZJUKLAB"]},{name:"Xin Xie",institutions:[]},{name:"Shumin Deng",institutions:[]},{name:"Chuanqi Tan",institutions:[]},{name:"Mosha Chen",institutions:[]},{name:"Fei Huang",institutions:[]},{name:"Luo Si",institutions:[]},{name:"Huajun Chen",institutions:[]}],authorString:"Ningyu Zhang; Xiang Chen; Xin Xie; Shumin Deng; Chuanqi Tan; Mosha Chen; Fei Huang; Luo Si; Huajun Chen",institutions:["ZheJiang University, College of Computer Science and Technology, ZJUKLAB","Zhejiang University"],countries:[],year:2021,journal:"International Joint Conference on Artificial Intelligence",citations:233,abstract:"Document-level relation extraction aims to extract relations among multiple entity pairs from a document. Previously proposed graph-based or transformer-based models utilize the entities independently, regardless of global information among relational triples. This paper approaches the problem by predicting an entity-level relation matrix to capture local and global information, parallel to the semantic segmentation task in computer vision. Herein, we propose a Document U-shaped Network for document-level relation extraction. Specifically, we leverage an encoder module to capture the context information of entities and a U-shaped segmentation module over the image-style feature map to capture global interdependency among triples. Experimental results show that our approach can obtain state-of-the-art performance on three benchmark datasets DocRED, CDR, and GDA.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2021/0551.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:47e-5,eigenvector:.0069},{id:368,oaid:"688759d0e64a33091fa916d88f845fb9c9d94626",doi:"10.1007/s10994-015-5494-z",title:"Probabilistic (logic) programming concepts",authors:[{name:"L. D. Raedt",institutions:[]},{name:"A. Kimmig",institutions:[]}],authorString:"L. D. Raedt; A. Kimmig",institutions:[],countries:[],year:2015,journal:"Machine-mediated learning",citations:232,abstract:"",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007/s10994-015-5494-z.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:369,oaid:"21e4e58e4e32b0149714653590db6998abd2811d",doi:"10.1109/ROBOT.2009.5152776",title:"What to do and how to do it: Translating natural language directives into temporal and dynamic logic representation for goal management and action execution",authors:[{name:"Juraj Dzifcak",institutions:[]},{name:"Matthias Scheutz",institutions:[]},{name:"Chitta Baral",institutions:["Arizona State University"]},{name:"P. Schermerhorn",institutions:[]}],authorString:"Juraj Dzifcak; Matthias Scheutz; Chitta Baral; P. Schermerhorn",institutions:["Arizona State University"],countries:[],year:2009,journal:"IEEE International Conference on Robotics and Automation",citations:232,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:4,deg_w:13.5,betweenness:0,pagerank:63e-5,eigenvector:2e-4},{id:370,oaid:"a26623d52d24e03044a158cddad931ec5ab7304c",doi:"10.1109/TKDE.2023.3310002",title:"A Survey of Knowledge Enhanced Pre-Trained Language Models",authors:[{name:"Linmei Hu",institutions:["School of Computer Science, Beijing University of Posts and Telecommunications"]},{name:"Zeyi Liu",institutions:[]},{name:"Ziwang Zhao",institutions:[]},{name:"Lei Hou",institutions:[]},{name:"Liqiang Nie",institutions:[]},{name:"Juanzi Li",institutions:[]}],authorString:"Linmei Hu; Zeyi Liu; Ziwang Zhao; Lei Hou; Liqiang Nie; Juanzi Li",institutions:["School of Computer Science, Beijing University of Posts and Telecommunications"],countries:[],year:2022,journal:"IEEE Transactions on Knowledge and Data Engineering",citations:231,abstract:"Pre-trained Language Models (PLMs) which are trained on large text corpus via self-supervised learning method, have yielded promising performance on various tasks in Natural Language Processing (NLP). However, though PLMs with huge parameters can effectively possess rich knowledge learned from massive training text and benefit downstream tasks at the fine-tuning stage, they still have some limitations such as poor reasoning ability due to the lack of external knowledge. Research has been dedicated to incorporating knowledge into PLMs to tackle these issues. In this paper, we present a comprehensive review of Knowledge Enhanced Pre-trained Language Models (KE-PLMs) to provide a clear insight into this thriving field. We introduce appropriate taxonomies respectively for Natural Language Understanding (NLU) and Natural Language Generation (NLG) to highlight these two main tasks of NLP. For NLU, we divide the types of knowledge into four categories: linguistic knowledge, text knowledge, knowledge graph (KG), and rule knowledge. The KE-PLMs for NLG are categorized into KG-based and retrieval-based methods. Finally, we point out some promising future directions of KE-PLMs.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2211.05994",is_oa:!0,n_refs:136,n_refs_in_core:18,degree:33,community:1,deg_w:430.5,betweenness:.0066,pagerank:.00869,eigenvector:.3096},{id:371,oaid:"baa8f524c82735f174b8d1ab512ac5750146d67e",doi:"10.1609/aaai.v35i7.16796",title:"KG-BART: Knowledge Graph-Augmented BART for Generative Commonsense Reasoning",authors:[{name:"Ye Liu",institutions:[]},{name:"Yao Wan",institutions:[]},{name:"Lifang He",institutions:[]},{name:"Hao Peng",institutions:[]},{name:"Philip S. Yu",institutions:[]}],authorString:"Ye Liu; Yao Wan; Lifang He; Hao Peng; Philip S. Yu",institutions:[],countries:[],year:2020,journal:"AAAI Conference on Artificial Intelligence",citations:230,abstract:"Generative commonsense reasoning which aims to empower machines to generate sentences with the capacity of reasoning over a set of concepts is a critical bottleneck for text generation. Even the state-of-the-art pre-trained language generation models struggle at this task and often produce implausible and anomalous sentences. One reason is that they rarely consider incorporating the knowledge graph which can provide rich relational information among the commonsense concepts. To promote the ability of commonsense reasoning for text generation, we propose a novel knowledge graph augmented pre-trained language generation model KG-BART, which encompasses the complex relations of concepts through the knowledge graph and produces more logical and natural sentences as output. Moreover, KG-BART can leverage the graph attention to aggregate the rich concept semantics that enhances the model generalization on unseen concept sets. Experiments on benchmark CommonGen dataset verify the effectiveness of our proposed approach by comparing with several strong pre-trained language generation models, particularly KG-BART outperforms BART by 5.80, 4.60, in terms of BLEU-3, 4. Moreover, we also show that the generated context by our model can work as background scenarios to benefit downstream commonsense QA tasks.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/16796/16603",is_oa:!0,n_refs:38,n_refs_in_core:5,degree:22,community:1,deg_w:220,betweenness:.0067,pagerank:.00454,eigenvector:.1698},{id:372,oaid:"eb597cceec6e0889d1423ae688e8854bfa6f822d",doi:null,title:"Learning to See Physics via Visual De-animation",authors:[{name:"Jiajun Wu",institutions:["Stanford University"]},{name:"Erika Lu",institutions:[]},{name:"Pushmeet Kohli",institutions:[]},{name:"Bill Freeman",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Jiajun Wu; Erika Lu; Pushmeet Kohli; Bill Freeman; J. Tenenbaum",institutions:["Stanford University"],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:230,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:0,pagerank:6e-4,eigenvector:0},{id:373,oaid:"0a39442979d6e678dd36bb443ad529c14e86a86e",doi:null,title:"DocPrompting: Generating Code by Retrieving the Docs",authors:[{name:"Shuyan Zhou",institutions:["Carnegie Mellon University"]},{name:"Uri Alon",institutions:["Carnegie Mellon University"]},{name:"Frank F. Xu",institutions:[]},{name:"Zhiruo Wang",institutions:[]},{name:"Zhengbao Jiang",institutions:[]},{name:"Graham Neubig",institutions:[]}],authorString:"Shuyan Zhou; Uri Alon; Frank F. Xu; Zhiruo Wang; Zhengbao Jiang; Graham Neubig",institutions:["Carnegie Mellon University"],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:228,abstract:"Publicly available source-code libraries are continuously growing and changing. This makes it impossible for models of code to keep current with all available APIs by simply training these models on existing code repositories. Thus, existing models inherently cannot generalize to using unseen functions and libraries, because these would never appear in the training data. In contrast, when human programmers use functions and libraries for the first time, they frequently refer to textual resources such as code manuals and documentation, to explore and understand the available functionality. Inspired by this observation, we introduce DocPrompting: a natural-language-to-code generation approach that explicitly leverages documentation by (1) retrieving the relevant documentation pieces given an NL intent, and (2) generating code based on the NL intent and the retrieved documentation. DocPrompting is general: it can be applied to any programming language and is agnostic to the underlying neural model. We demonstrate that DocPrompting consistently improves NL-to-code models: DocPrompting improves strong base models such as CodeT5 by 2.85% in pass@1 (52% relative gain) and 4.39% in pass@10 (30% relative gain) in execution-based evaluation on the popular Python CoNaLa benchmark; on a new Bash dataset tldr, DocPrompting improves CodeT5 and GPT-Neo1.3B by up to absolute 6.9% exact match.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8,betweenness:0,pagerank:6e-4,eigenvector:5e-4},{id:374,oaid:"8794f6169c693fb85c809bb663172d1277d11a83",doi:"10.24963/ijcai.2020/243",title:"NeurASP: Embracing Neural Networks into Answer Set Programming",authors:[{name:"Zhun Yang",institutions:[]},{name:"Adam Ishay",institutions:[]},{name:"Joohyung Lee",institutions:[]}],authorString:"Zhun Yang; Adam Ishay; Joohyung Lee",institutions:[],countries:[],year:2020,journal:"International Joint Conference on Artificial Intelligence",citations:227,abstract:"We present NeurASP, a simple extension of answer set programs by embracing neural networks. By treating the neural network output as the probability distribution over atomic facts in answer set programs, NeurASP provides a simple and effective way to integrate sub-symbolic and symbolic computation. We demonstrate how NeurASP can make use of a pre-trained neural network in symbolic computation and how it can improve the neural network's perception result by applying symbolic reasoning in answer set programming. Also, NeurASP can make use of ASP rules to train a neural network better so that a neural network not only learns from implicit correlations from the data but also from the explicit complex semantic constraints expressed by the rules.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2020/0243.pdf",is_oa:!0,n_refs:25,n_refs_in_core:16,degree:18,community:0,deg_w:89.5,betweenness:.0243,pagerank:.00485,eigenvector:8e-4},{id:375,oaid:"8a98ef95dec142072a6f0e743b2803c2a34ee4fd",doi:null,title:"Proceedings of the Twenty-Third International Joint Conference on Artificial Intelligence Meta-Interpretive Learning of Higher-Order Dyadic Datalog: Predicate Invention Revisited ∗",authors:[],authorString:"",institutions:[],countries:[],year:null,journal:"",citations:226,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12.5,betweenness:.0015,pagerank:79e-5,eigenvector:2e-4},{id:376,oaid:"155d712236147d90516045a71b66d5d32c03846f",doi:"10.48550/arXiv.2204.10628",title:"Autoregressive Search Engines: Generating Substrings as Document Identifiers",authors:[{name:"Michele Bevilacqua",institutions:[]},{name:"G. Ottaviano",institutions:[]},{name:"Patrick Lewis",institutions:["Facebook AI Research","University College London"]},{name:"Wen-tau Yih",institutions:[]},{name:"Sebastian Riedel",institutions:[]},{name:"F. Petroni",institutions:[]}],authorString:"Michele Bevilacqua; G. Ottaviano; Patrick Lewis; Wen-tau Yih; Sebastian Riedel; F. Petroni",institutions:["Facebook AI Research","University College London"],countries:[],year:2022,journal:"Neural Information Processing Systems",citations:225,abstract:"Knowledge-intensive language tasks require NLP systems to both provide the correct answer and retrieve supporting evidence for it in a given corpus. Autoregressive language models are emerging as the de-facto standard for generating answers, with newer and more powerful systems emerging at an astonishing pace. In this paper we argue that all this (and future) progress can be directly applied to the retrieval problem with minimal intervention to the models' architecture. Previous work has explored ways to partition the search space into hierarchical structures and retrieve documents by autoregressively generating their unique identifier. In this work we propose an alternative that doesn't force any structure in the search space: using all ngrams in a passage as its possible identifiers. This setup allows us to use an autoregressive model to generate and score distinctive ngrams, that are then mapped to full passages through an efficient data structure. Empirically, we show this not only outperforms prior autoregressive approaches but also leads to an average improvement of at least 10 points over more established retrieval solutions for passage-level retrieval on the KILT benchmark, establishing new state-of-the-art downstream performance on some datasets, while using a considerably lighter memory footprint than competing systems. Code and pre-trained models at https://github.com/facebookresearch/SEAL.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2204.10628",is_oa:!0,n_refs:73,n_refs_in_core:6,degree:21,community:1,deg_w:171,betweenness:.0053,pagerank:.00418,eigenvector:.0613},{id:377,oaid:"cd0a7c58964905ccfddbad1614165320ccc56393",doi:"10.1109/CVPR.2018.00519",title:"Transparency by Design: Closing the Gap Between Performance and Interpretability in Visual Reasoning",authors:[{name:"David Mascharka",institutions:[]},{name:"Phi Vu Tran",institutions:[]},{name:"Ryan Soklaski",institutions:[]},{name:"Arjun Majumdar",institutions:[]}],authorString:"David Mascharka; Phi Vu Tran; Ryan Soklaski; Arjun Majumdar",institutions:[],countries:[],year:2018,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:225,abstract:"Visual question answering requires high-order reasoning about an image, which is a fundamental capability needed by machine systems to follow complex directives. Recently, modular networks have been shown to be an effective framework for performing visual reasoning tasks. While modular networks were initially designed with a degree of model transparency, their performance on complex visual reasoning benchmarks was lacking. Current state-of-the-art approaches do not provide an effective mechanism for understanding the reasoning process. In this paper, we close the performance gap between interpretable models and state-of-the-art visual reasoning methods. We propose a set of visual-reasoning primitives which, when composed, manifest as a model capable of performing complex reasoning tasks in an explicitly-interpretable manner. The fidelity and interpretability of the primitives' outputs enable an unparalleled ability to diagnose the strengths and weaknesses of the resulting model. Critically, we show that these primitives are highly performant, achieving state-of-the-art accuracy of 99.1% on the CLEVR dataset. We also show that our model is able to effectively learn generalized representations when provided a small amount of data containing novel object attributes. Using the CoGenT generalization task, we show more than a 20 percentage point improvement over the current state of the art.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1803.05268",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:8,community:3,deg_w:33,betweenness:0,pagerank:.001,eigenvector:3e-4},{id:378,oaid:"7eda139d737eea10fc1d95364327a41ec0cee4a4",doi:"10.18653/V1/2020.COLING-MAIN.327",title:"CoLAKE: Contextualized Language and Knowledge Embedding",authors:[{name:"Tianxiang Sun",institutions:[]},{name:"Yunfan Shao",institutions:["Fudan University"]},{name:"Xipeng Qiu",institutions:["Fudan University"]},{name:"Qipeng Guo",institutions:["Fudan University"]},{name:"Yaru Hu",institutions:[]},{name:"Xuanjing Huang",institutions:["Fudan University"]},{name:"Zheng Zhang",institutions:[]}],authorString:"Tianxiang Sun; Yunfan Shao; Xipeng Qiu; Qipeng Guo; Yaru Hu; Xuanjing Huang; Zheng Zhang",institutions:["Fudan University"],countries:[],year:2020,journal:"International Conference on Computational Linguistics",citations:224,abstract:"With the emerging branch of incorporating factual knowledge into pre-trained language models such as BERT, most existing models consider shallow, static, and separately pre-trained entity embeddings, which limits the performance gains of these models. Few works explore the potential of deep contextualized knowledge representation when injecting knowledge. In this paper, we propose the Contextualized Language and Knowledge Embedding (CoLAKE), which jointly learns contextualized representation for both language and knowledge with the extended MLM objective. Instead of injecting only entity embeddings, CoLAKE extracts the knowledge context of an entity from large-scale knowledge bases. To handle the heterogeneity of knowledge context and language context, we integrate them in a unified data structure, word-knowledge graph (WK graph). CoLAKE is pre-trained on large-scale WK graphs with the modified Transformer encoder. We conduct experiments on knowledge-driven tasks, knowledge probing tasks, and language understanding tasks. Experimental results show that CoLAKE outperforms previous counterparts on most of the tasks. Besides, CoLAKE achieves surprisingly high performance on our synthetic task called word-knowledge graph completion, which shows the superiority of simultaneously contextualizing language and knowledge representation.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.coling-main.327.pdf",is_oa:!0,n_refs:42,n_refs_in_core:4,degree:24,community:1,deg_w:301,betweenness:.0019,pagerank:.00581,eigenvector:.2541},{id:379,oaid:"fb54cbdf1b111613a3d739df7a81b5b603776ed9",doi:null,title:"An Introduction to Probabilistic Programming",authors:[{name:"Jan-Willem van de Meent",institutions:[]},{name:"Brooks Paige",institutions:[]},{name:"Hongseok Yang",institutions:[]},{name:"Frank Wood",institutions:[]}],authorString:"Jan-Willem van de Meent; Brooks Paige; Hongseok Yang; Frank Wood",institutions:[],countries:[],year:2018,journal:"arXiv.org",citations:223,abstract:"This document is designed to be a first-year graduate-level introduction to probabilistic programming. It not only provides a thorough background for anyone wishing to use a probabilistic programming system, but also introduces the techniques needed to design and build these systems. It is aimed at people who have an undergraduate-level understanding of either or, ideally, both probabilistic machine learning and programming languages. We start with a discussion of model-based reasoning and explain why conditioning as a foundational computation is central to the fields of probabilistic machine learning and artificial intelligence. We then introduce a simple first-order probabilistic programming language (PPL) whose programs define static-computation-graph, finite-variable-cardinality models. In the context of this restricted PPL we introduce fundamental inference algorithms and describe how they can be implemented in the context of models denoted by probabilistic programs. In the second part of this document, we introduce a higher-order probabilistic programming language, with a functionality analogous to that of established programming languages. This affords the opportunity to define models with dynamic computation graphs, at the cost of requiring inference methods that generate samples by repeatedly executing the program. Foundational inference algorithms for this kind of probabilistic programming language are explained in the context of an interface between program executions and an inference controller. This document closes with a chapter on advanced topics which we believe to be, at the time of writing, interesting directions for probabilistic programming research; directions that point towards a tight integration with deep neural network research and the development of systems for next-generation artificial intelligence applications.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:106,n_refs_in_core:7,degree:14,community:2,deg_w:84,betweenness:.0054,pagerank:.00345,eigenvector:2e-4},{id:380,oaid:"2b556fcf2ac634f03c1fb0ace5e602e829418e65",doi:"10.48550/arXiv.2203.07722",title:"ReACC: A Retrieval-Augmented Code Completion Framework",authors:[{name:"Shuai Lu",institutions:[]},{name:"Nan Duan",institutions:[]},{name:"Hojae Han",institutions:[]},{name:"Daya Guo",institutions:[]},{name:"Seung-won Hwang",institutions:[]},{name:"Alexey Svyatkovskiy",institutions:[]}],authorString:"Shuai Lu; Nan Duan; Hojae Han; Daya Guo; Seung-won Hwang; Alexey Svyatkovskiy",institutions:[],countries:[],year:2022,journal:"Annual Meeting of the Association for Computational Linguistics",citations:221,abstract:"Code completion, which aims to predict the following code token(s) according to the code context, can improve the productivity of software development. Recent work has proved that statistical language modeling with transformers can greatly improve the performance in the code completion task via learning from large-scale source code datasets. However, current approaches focus only on code context within the file or project, i.e. internal context. Our distinction is utilizing ”external” context, inspired by human behaviors of copying from the related code snippets when writing code. Specifically, we propose a retrieval-augmented code completion framework, leveraging both lexical copying and referring to code with similar semantics by retrieval. We adopt a stage-wise training approach that combines a source code retriever and an auto-regressive language model for programming language. We evaluate our approach in the code completion task in Python and Java programming languages, achieving a state-of-the-art performance on CodeXGLUE benchmark.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2203.07722",is_oa:!0,n_refs:69,n_refs_in_core:2,degree:17,community:5,deg_w:128.5,betweenness:.0027,pagerank:.00327,eigenvector:.0315},{id:381,oaid:"d7c4b8f15f82825de9edcf57e499b05256c7885d",doi:"10.18653/v1/2020.inlg-1.14",title:"Text-to-Text Pre-Training for Data-to-Text Tasks",authors:[{name:"Mihir Kale",institutions:[]}],authorString:"Mihir Kale",institutions:[],countries:[],year:2020,journal:"International Conference on Natural Language Generation",citations:221,abstract:"We study the pre-train + fine-tune strategy for data-to-text tasks. Our experiments indicate that text-to-text pre-training in the form of T5 (Raffel et al., 2019), enables simple, end-to-end transformer based models to outperform pipelined neural architectures tailored for data-to-text generation, as well as alternatives such as BERT and GPT-2. Importantly, T5 pre-training leads to better generalization, as evidenced by large improvements on out-ofdomain test sets. We hope our work serves as a useful baseline for future research, as transfer learning becomes ever more prevalent for data-to-text tasks.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2020.inlg-1.14.pdf",is_oa:!0,n_refs:35,n_refs_in_core:1,degree:9,community:1,deg_w:57,betweenness:3e-4,pagerank:.00153,eigenvector:.025},{id:382,oaid:"c7fc1cac162c0e2a934704184c7554fd6b6253f0",doi:null,title:"Pretrained Encyclopedia: Weakly Supervised Knowledge-Pretrained Language Model",authors:[{name:"Wenhan Xiong",institutions:[]},{name:"Jingfei Du",institutions:[]},{name:"William Yang Wang",institutions:[]},{name:"Veselin Stoyanov",institutions:["Meta AI"]}],authorString:"Wenhan Xiong; Jingfei Du; William Yang Wang; Veselin Stoyanov",institutions:["Meta AI"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:216,abstract:"Recent breakthroughs of pretrained language models have shown the effectiveness of self-supervised learning for a wide range of natural language processing (NLP) tasks. In addition to standard syntactic and semantic NLP tasks, pretrained models achieve strong improvements on tasks that involve real-world knowledge, suggesting that large-scale language modeling could be an implicit method to capture knowledge. In this work, we further investigate the extent to which pretrained models such as BERT capture knowledge using a zero-shot fact completion task. Moreover, we propose a simple yet effective weakly supervised pretraining objective, which explicitly forces the model to incorporate knowledge about real-world entities. Models trained with our new objective yield significant improvements on the fact completion task. When applied to downstream tasks, our model consistently outperforms BERT on four entity-related question answering datasets (i.e., WebQuestions, TriviaQA, SearchQA and Quasar-T) with an average 2.7 F1 improvements and a standard fine-grained entity typing dataset (i.e., FIGER) with 5.7 accuracy gains.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:52,n_refs_in_core:1,degree:22,community:1,deg_w:251,betweenness:.0043,pagerank:.00493,eigenvector:.2075},{id:383,oaid:"b71c8e582e8e56d839c962b923b0b79bada2a7f8",doi:null,title:"Learning First-Order Horn Clauses from Web Text",authors:[{name:"Stefan Schoenmackers",institutions:[]},{name:"Jesse Davis",institutions:[]},{name:"Oren Etzioni",institutions:[]},{name:"Daniel S. Weld",institutions:["Allen Institute of Artificial Intelligence","University of Washington"]}],authorString:"Stefan Schoenmackers; Jesse Davis; Oren Etzioni; Daniel S. Weld",institutions:["Allen Institute of Artificial Intelligence","University of Washington"],countries:[],year:2010,journal:"Conference on Empirical Methods in Natural Language Processing",citations:216,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:13.5,betweenness:0,pagerank:64e-5,eigenvector:7e-4},{id:384,oaid:"c611b9c82e234b344a232bcbbe5436e06da69f0b",doi:"10.1007/978-3-030-01234-2_4",title:"Explainable Neural Computation via Stack Neural Module Networks",authors:[{name:"Ronghang Hu",institutions:[]},{name:"Jacob Andreas",institutions:["MIT","Microsoft"]},{name:"Trevor Darrell",institutions:[]},{name:"Kate Saenko",institutions:[]}],authorString:"Ronghang Hu; Jacob Andreas; Trevor Darrell; Kate Saenko",institutions:["MIT","Microsoft"],countries:[],year:2018,journal:"European Conference on Computer Vision",citations:210,abstract:"In complex inferential tasks like question answering, machine learning models must confront two challenges: the need to implement a compositional reasoning process, and, in many applications, the need for this reasoning process to be interpretable to assist users in both development and prediction. Existing models designed to produce interpretable traces of their decision-making process typically require these traces to be supervised at training time. In this paper, we present a novel neural modular approach that performs compositional reasoning by automatically inducing a desired sub-task decomposition without relying on strong supervision. Our model allows linking different reasoning tasks though shared modules that handle common routines across tasks. Experiments show that the model is more interpretable to human evaluators compared to other state-of-the-art models: users can better understand the model’s underlying reasoning procedure and predict when it will succeed or fail based on observing its intermediate outputs.",keywords:[],concepts:[],pdf_url:"https://hdl.handle.net/1721.1/142868",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8,betweenness:0,pagerank:44e-5,eigenvector:1e-4},{id:385,oaid:"f696ea202d5f2af57c66b6f9f2783f124399e0dd",doi:null,title:"CATER: A diagnostic dataset for Compositional Actions and TEmporal Reasoning",authors:[{name:"Rohit Girdhar",institutions:["Facebook AI Research"]},{name:"D. Ramanan",institutions:[]}],authorString:"Rohit Girdhar; D. Ramanan",institutions:["Facebook AI Research"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:209,abstract:"Computer vision has undergone a dramatic revolution in performance, driven in large part through deep features trained on large-scale supervised datasets. However, much of these improvements have focused on static image analysis; video understanding has seen rather modest improvements. Even though new datasets and spatiotemporal models have been proposed, simple frame-by-frame classification methods often still remain competitive. We posit that current video datasets are plagued with implicit biases over scene and object structure that can dwarf variations in temporal structure. In this work, we build a video dataset with fully observable and controllable object and scene bias, and which truly requires spatiotemporal understanding in order to be solved. Our dataset, named CATER, is rendered synthetically using a library of standard 3D objects, and tests the ability to recognize compositions of object movements that require long-term reasoning. In addition to being a challenging dataset, CATER also provides a plethora of diagnostic tools to analyze modern spatiotemporal video architectures by being completely observable and controllable. Using CATER, we provide insights into some of the most recent state of the art deep video architectures.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:4,deg_w:13.5,betweenness:0,pagerank:59e-5,eigenvector:1e-4},{id:386,oaid:"07216ee1119f61b351b69e94b2e7c3698d96b026",doi:"10.3115/1690219.1690283",title:"Learning Context-Dependent Mappings from Sentences to Logical Form",authors:[{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]},{name:"M. Collins",institutions:[]}],authorString:"Luke Zettlemoyer; M. Collins",institutions:["Facebook","University of Washington"],countries:[],year:2009,journal:"Annual Meeting of the Association for Computational Linguistics",citations:209,abstract:"We consider the problem of learning context-dependent mappings from sentences to logical form. The training examples are sequences of sentences annotated with lambda-calculus meaning representations. We develop an algorithm that maintains explicit, lambda-calculus representations of salient discourse entities and uses a context-dependent analysis pipeline to recover logical forms. The method uses a hidden-variable variant of the perception algorithm to learn a linear model used to select the best analysis. Experiments on context-dependent utterances from the ATIS corpus show that the method recovers fully correct logical forms with 83.7% accuracy.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://dl.acm.org/doi/pdf/10.5555/1690219.1690283",is_oa:!0,n_refs:25,n_refs_in_core:1,degree:5,community:5,deg_w:31.5,betweenness:1e-4,pagerank:.00109,eigenvector:6e-4},{id:387,oaid:"311eb232e4bd3ed53b1ef3381d75b65615d4e29c",doi:"10.3115/v1/D14-1165",title:"Typed Tensor Decomposition of Knowledge Bases for Relation Extraction",authors:[{name:"Kai-Wei Chang",institutions:[]},{name:"Wen-tau Yih",institutions:[]},{name:"Bishan Yang",institutions:[]},{name:"Christopher Meek",institutions:["Microsoft Research"]}],authorString:"Kai-Wei Chang; Wen-tau Yih; Bishan Yang; Christopher Meek",institutions:["Microsoft Research"],countries:[],year:2014,journal:"Conference on Empirical Methods in Natural Language Processing",citations:208,abstract:"While relation extraction has traditionally been viewed as a task relying solely on textual data, recent work has shown that by taking as input existing facts in the form of entity-relation triples from both knowledge bases and textual data, the performance of relation extraction can be improved significantly. Following this new paradigm, we propose a tensor decomposition approach for knowledge base embedding that is highly scalable, and is especially suitable for relation extraction. By leveraging relational domain knowledge about entity type information, our learning algorithm is significantly faster than previous approaches and is better able to discover new relations missing from the database. In addition, when applied to a relation extraction task, our approach alone is comparable to several existing systems, and improves the weighted mean average precision of a state-of-theart method by 10 points when used as a subcomponent.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.3115/v1/d14-1165",is_oa:!0,n_refs:34,n_refs_in_core:2,degree:12,community:0,deg_w:78,betweenness:4e-4,pagerank:.00242,eigenvector:.0059},{id:388,oaid:"bdc9d7695e8ce67f6d082527031e5ea66645a439",doi:null,title:"Neural-Symbolic Learning and Reasoning: Contributions and Challenges",authors:[{name:"A. Garcez",institutions:[]},{name:"Tarek R. Besold",institutions:["Neurocat GmbH"]},{name:"L. D. Raedt",institutions:[]},{name:"Peter Földiák",institutions:[]},{name:"P. Hitzler",institutions:[]},{name:"Thomas F. Icard",institutions:[]},{name:"Kai-Uwe Kühnberger",institutions:[]},{name:"L. Lamb",institutions:[]},{name:"R. Miikkulainen",institutions:[]},{name:"Daniel L. Silver",institutions:[]}],authorString:"A. Garcez; Tarek R. Besold; L. D. Raedt; Peter Földiák; P. Hitzler; Thomas F. Icard; Kai-Uwe Kühnberger; L. Lamb; R. Miikkulainen; Daniel L. Silver",institutions:["Neurocat GmbH"],countries:[],year:2015,journal:"AAAI Spring Symposia",citations:203,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:58e-5,eigenvector:1e-4},{id:389,oaid:"96901acc92d68350443774596fa2b38bc522a0ce",doi:"10.18653/v1/P19-1598",title:"Barack’s Wife Hillary: Using Knowledge Graphs for Fact-Aware Language Modeling",authors:[{name:"IV RobertL.Logan",institutions:[]},{name:"Nelson F. Liu",institutions:["Stanford University"]},{name:"Matthew E. Peters",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Matt Gardner",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Sameer Singh",institutions:[]}],authorString:"IV RobertL.Logan; Nelson F. Liu; Matthew E. Peters; Matt Gardner; Sameer Singh",institutions:["Allen Institute for Artificial Intelligence","Stanford University"],countries:[],year:2019,journal:"Annual Meeting of the Association for Computational Linguistics",citations:203,abstract:"Modeling human language requires the ability to not only generate fluent text but also encode factual knowledge. However, traditional language models are only capable of remembering facts seen at training time, and often have difficulty recalling them. To address this, we introduce the knowledge graph language model (KGLM), a neural language model with mechanisms for selecting and copying facts from a knowledge graph that are relevant to the context. These mechanisms enable the model to render information it has never seen before, as well as generate out-of-vocabulary tokens. We also introduce the Linked WikiText-2 dataset, a corpus of annotated text aligned to the Wikidata knowledge graph whose contents (roughly) match the popular WikiText-2 benchmark. In experiments, we demonstrate that the KGLM achieves significantly better performance than a strong baseline language model. We additionally compare different language model’s ability to complete sentences requiring factual knowledge, showing that the KGLM outperforms even very large language models in generating facts.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P19-1598.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:5,community:1,deg_w:24.5,betweenness:0,pagerank:72e-5,eigenvector:.0281},{id:390,oaid:"2a16ace054364557c8b8b4bf55f7293cd6d1a9ab",doi:null,title:"Learning to Interpret Natural Language Commands through Human-Robot Dialog",authors:[{name:"Jesse Thomason",institutions:["The University of Washington"]},{name:"Shiqi Zhang",institutions:[]},{name:"R. Mooney",institutions:[]},{name:"P. Stone",institutions:[]}],authorString:"Jesse Thomason; Shiqi Zhang; R. Mooney; P. Stone",institutions:["The University of Washington"],countries:[],year:2015,journal:"International Joint Conference on Artificial Intelligence",citations:200,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8.5,betweenness:0,pagerank:48e-5,eigenvector:2e-4},{id:391,oaid:"1ae84940e212e2e3ca132c7aa0878baf0fda06cd",doi:"10.18653/v1/P17-1097",title:"From Language to Programs: Bridging Reinforcement Learning and Maximum Marginal Likelihood",authors:[{name:"Kelvin Guu",institutions:[]},{name:"Panupong Pasupat",institutions:[]},{name:"E. Liu",institutions:[]},{name:"Percy Liang",institutions:[]}],authorString:"Kelvin Guu; Panupong Pasupat; E. Liu; Percy Liang",institutions:[],countries:[],year:2017,journal:"Annual Meeting of the Association for Computational Linguistics",citations:199,abstract:"Our goal is to learn a semantic parser that maps natural language utterances into executable programs when only indirect supervision is available: examples are labeled with the correct execution result, but not the program itself. Consequently, we must search the space of programs for those that output the correct result, while not being misled by spurious programs: incorrect programs that coincidentally output the correct result. We connect two common learning paradigms, reinforcement learning (RL) and maximum marginal likelihood (MML), and then present a new learning algorithm that combines the strengths of both. The new algorithm guards against spurious programs by combining the systematic search traditionally employed in MML with the randomized exploration of RL, and by updating parameters such that probability is spread more evenly across consistent programs. We apply our learning algorithm to a new neural semantic parser and show significant gains over existing state-of-the-art results on a recent context-dependent semantic parsing task.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P17-1097.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:5,deg_w:8,betweenness:4e-4,pagerank:47e-5,eigenvector:3e-4},{id:392,oaid:"dab8424eec426ed3996e469f657371dd53e20127",doi:"10.18653/v1/2020.acl-main.622",title:"CorefQA: Coreference Resolution as Query-based Span Prediction",authors:[{name:"Wei Wu",institutions:[]},{name:"Fei Wang",institutions:["University of Southern California"]},{name:"Arianna Yuan",institutions:[]},{name:"Fei Wu",institutions:[]},{name:"Jiwei Li",institutions:[]}],authorString:"Wei Wu; Fei Wang; Arianna Yuan; Fei Wu; Jiwei Li",institutions:["University of Southern California"],countries:[],year:2019,journal:"Annual Meeting of the Association for Computational Linguistics",citations:197,abstract:"In this paper, we present CorefQA, an accurate and extensible approach for the coreference resolution task. We formulate the problem as a span prediction task, like in question answering: A query is generated for each candidate mention using its surrounding context, and a span prediction module is employed to extract the text spans of the coreferences within the document using the generated query. This formulation comes with the following key advantages: (1) The span prediction strategy provides the flexibility of retrieving mentions left out at the mention proposal stage; (2) In the question answering framework, encoding the mention and its context explicitly in a query makes it possible to have a deep and thorough examination of cues embedded in the context of coreferent mentions; and (3) A plethora of existing question answering datasets can be used for data augmentation to improve the model’s generalization capability. Experiments demonstrate significant performance boost over previous models, with 83.1 (+3.5) F1 score on the CoNLL-2012 benchmark and 87.5 (+2.5) F1 score on the GAP benchmark.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.acl-main.622.pdf",is_oa:!0,n_refs:44,n_refs_in_core:2,degree:7,community:1,deg_w:52.5,betweenness:.0015,pagerank:.00158,eigenvector:.0175},{id:393,oaid:"f9a45caaab1b6d3d777b53053d94181a3bf20cca",doi:null,title:"Bridging Machine Learning and Logical Reasoning by Abductive Learning",authors:[{name:"Wang-Zhou Dai",institutions:[]},{name:"Qiu-Ling Xu",institutions:[]},{name:"Yang Yu",institutions:[]},{name:"Zhi-Hua Zhou",institutions:[]}],authorString:"Wang-Zhou Dai; Qiu-Ling Xu; Yang Yu; Zhi-Hua Zhou",institutions:[],countries:[],year:2019,journal:"Neural Information Processing Systems",citations:195,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:0,deg_w:4,betweenness:0,pagerank:5e-4,eigenvector:0},{id:394,oaid:"209bef4a0ef7e30c506be1e65b4f2a5315e3d8f4",doi:"10.6092/issn.1972-5787/4593",title:"Hammering towards QED",authors:[{name:"J. Blanchette",institutions:[]},{name:"C. Kaliszyk",institutions:[]},{name:"Lawrence Charles Paulson",institutions:["University of Cambridge"]},{name:"J. Urban",institutions:[]}],authorString:"J. Blanchette; C. Kaliszyk; Lawrence Charles Paulson; J. Urban",institutions:["University of Cambridge"],countries:[],year:2016,journal:"Journal of Formalized Reasoning",citations:194,abstract:"",keywords:[],concepts:[],pdf_url:"https://inria.hal.science/hal-01386988/document",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:6,deg_w:18,betweenness:0,pagerank:76e-5,eigenvector:7e-4},{id:395,oaid:"654a379628716a5ec3f59c5fb4f4e184e3034f0f",doi:"10.1023/A:1008328630915",title:"The Connectionist Inductive Learning and Logic Programming System",authors:[{name:"A. Garcez",institutions:[]},{name:"Gerson Zaverucha",institutions:[]}],authorString:"A. Garcez; Gerson Zaverucha",institutions:[],countries:[],year:1999,journal:"Applied intelligence (Boston)",citations:193,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:58e-5,eigenvector:2e-4},{id:396,oaid:"ae8776059560d886904cb44faca2ca2127dcab8e",doi:"10.1016/J.ARTINT.2021.103504",title:"Neural probabilistic logic programming in DeepProbLog",authors:[{name:"Robin Manhaeve",institutions:[]},{name:"Sebastijan Dumancic",institutions:[]},{name:"A. Kimmig",institutions:[]},{name:"Thomas Demeester",institutions:[]},{name:"L. D. Raedt",institutions:[]}],authorString:"Robin Manhaeve; Sebastijan Dumancic; A. Kimmig; Thomas Demeester; L. D. Raedt",institutions:[],countries:[],year:2019,journal:"Artificial Intelligence",citations:193,abstract:"",keywords:[],concepts:[],pdf_url:"https://www.sciencedirect.com/science/article/pii/S0004370221000552",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:65e-5,eigenvector:1e-4},{id:397,oaid:"4004d4f8068645c0329829b10d53926e281eff42",doi:"10.1016/j.artint.2015.08.011",title:"Semantic-based regularization for learning and inference",authors:[{name:"M. Diligenti",institutions:[]},{name:"M. Gori",institutions:[]},{name:"Claudio Saccà",institutions:[]}],authorString:"M. Diligenti; M. Gori; Claudio Saccà",institutions:[],countries:[],year:2017,journal:"Artificial Intelligence",citations:193,abstract:"",keywords:[],concepts:[],pdf_url:"https://www.sciencedirect.com/science/article/pii/S0004370215001344/pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:13,betweenness:0,pagerank:85e-5,eigenvector:1e-4},{id:398,oaid:"a596f03145285cd05a6ca57a4e25418b23b24976",doi:null,title:"Learning to Prove Theorems via Interacting with Proof Assistants",authors:[{name:"Kaiyu Yang",institutions:[]},{name:"Jia Deng",institutions:[]}],authorString:"Kaiyu Yang; Jia Deng",institutions:[],countries:[],year:2019,journal:"International Conference on Machine Learning",citations:193,abstract:"Humans prove theorems by relying on substantial high-level reasoning and problem-specific insights. Proof assistants offer a formalism that resembles human mathematical reasoning, representing theorems in higher-order logic and proofs as high-level tactics. However, human experts have to construct proofs manually by entering tactics into the proof assistant. In this paper, we study the problem of using machine learning to automate the interaction with proof assistants. We construct CoqGym, a large-scale dataset and learning environment containing 71K human-written proofs from 123 projects developed with the Coq proof assistant. We develop ASTactic, a deep learning-based model that generates tactics as programs in the form of abstract syntax trees (ASTs). Experiments show that ASTactic trained on CoqGym can generate effective tactics and can be used to prove new theorems not previously provable by automated methods. Code is available at this https URL.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:50,n_refs_in_core:10,degree:20,community:6,deg_w:153.5,betweenness:.0124,pagerank:.00461,eigenvector:.0047},{id:399,oaid:"9648349c7f36b5543f0dfd6afc45a6f4c1b26015",doi:"10.1111/j.1551-6709.2010.01104.x",title:"A Probabilistic Computational Model of Cross-Situational Word Learning",authors:[{name:"A. Fazly",institutions:[]},{name:"A. Alishahi",institutions:[]},{name:"S. Stevenson",institutions:[]}],authorString:"A. Fazly; A. Alishahi; S. Stevenson",institutions:[],countries:[],year:2010,journal:"Cognitive Sciences",citations:192,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1551-6709.2010.01104.x",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:1e-4},{id:400,oaid:"20e6909ce6c5f12b61e5c9022d97134137360273",doi:null,title:"Learning Language-Conditioned Robot Behavior from Offline Data and Crowd-Sourced Annotation",authors:[{name:"Suraj Nair",institutions:["Stanford University"]},{name:"E. Mitchell",institutions:[]},{name:"Kevin Chen",institutions:[]},{name:"Brian Ichter",institutions:[]},{name:"S. Savarese",institutions:[]},{name:"Chelsea Finn",institutions:[]}],authorString:"Suraj Nair; E. Mitchell; Kevin Chen; Brian Ichter; S. Savarese; Chelsea Finn",institutions:["Stanford University"],countries:[],year:2021,journal:"Conference on Robot Learning",citations:191,abstract:`We study the problem of learning a range of vision-based manipulation tasks from a large offline dataset of robot interaction. In order to accomplish this, humans need easy and effective ways of specifying tasks to the robot. Goal images are one popular form of task specification, as they are already grounded in the robot's observation space. However, goal images also have a number of drawbacks: they are inconvenient for humans to provide, they can over-specify the desired behavior leading to a sparse reward signal, or under-specify task information in the case of non-goal reaching tasks. Natural language provides a convenient and flexible alternative for task specification, but comes with the challenge of grounding language in the robot's observation space. To scalably learn this grounding we propose to leverage offline robot datasets (including highly sub-optimal, autonomously collected data) with crowd-sourced natural language labels. With this data, we learn a simple classifier which predicts if a change in state completes a language instruction. This provides a language-conditioned reward function that can then be used for offline multi-task RL. In our experiments, we find that on language-conditioned manipulation tasks our approach outperforms both goal-image specifications and language conditioned imitation techniques by more than 25%, and is able to perform visuomotor tasks from natural language, such as"open the right drawer"and"move the stapler", on a Franka Emika Panda robot.`,keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:79,n_refs_in_core:11,degree:21,community:4,deg_w:177.5,betweenness:.0026,pagerank:.00491,eigenvector:.0025},{id:401,oaid:"f669b5406320a83e94b4dd439806211c8b1e95fc",doi:null,title:"Write, Execute, Assess: Program Synthesis with a REPL",authors:[{name:"Kevin Ellis",institutions:[]},{name:"Maxwell Nye",institutions:["MIT"]},{name:"Yewen Pu",institutions:[]},{name:"Felix Sosa",institutions:[]},{name:"J. Tenenbaum",institutions:[]},{name:"Armando Solar-Lezama",institutions:[]}],authorString:"Kevin Ellis; Maxwell Nye; Yewen Pu; Felix Sosa; J. Tenenbaum; Armando Solar-Lezama",institutions:["MIT"],countries:[],year:2019,journal:"Neural Information Processing Systems",citations:188,abstract:"We present a neural program synthesis approach integrating components which write, execute, and assess code to navigate the search space of possible programs. We equip the search process with an interpreter or a read-eval-print-loop (REPL), which immediately executes partially written programs, exposing their semantics. The REPL addresses a basic challenge of program synthesis: tiny changes in syntax can lead to huge changes in semantics. We train a pair of models, a policy that proposes the new piece of code to write, and a value function that assesses the prospects of the code written so-far. At test time we can combine these models with a Sequential Monte Carlo algorithm. We apply our approach to two domains: synthesizing text editing programs and inferring 2D and 3D graphics programs.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12,betweenness:.0015,pagerank:7e-4,eigenvector:.0011},{id:402,oaid:"727183c5cff89a6f2c3b71167ae50c02ca2cacc4",doi:"10.1609/AAAI.V33I01.33017152",title:"Logic Attention Based Neighborhood Aggregation for Inductive Knowledge Graph Embedding",authors:[{name:"Peifeng Wang",institutions:["University of Southern California"]},{name:"Jialong Han",institutions:[]},{name:"Chenliang Li",institutions:[]},{name:"Rong Pan",institutions:[]}],authorString:"Peifeng Wang; Jialong Han; Chenliang Li; Rong Pan",institutions:["University of Southern California"],countries:[],year:2018,journal:"AAAI Conference on Artificial Intelligence",citations:186,abstract:"Knowledge graph embedding aims at modeling entities and relations with low-dimensional vectors. Most previous methods require that all entities should be seen during training, which is unpractical for real-world knowledge graphs with new entities emerging on a daily basis. Recent efforts on this issue suggest training a neighborhood aggregator in conjunction with the conventional entity and relation embeddings, which may help embed new entities inductively via their existing neighbors. However, their neighborhood aggregators neglect the unordered and unequal natures of an entity’s neighbors. To this end, we summarize the desired properties that may lead to effective neighborhood aggregators. We also introduce a novel aggregator, namely, Logic Attention Network (LAN), which addresses the properties by aggregating neighbors with both rules- and network-based attention weights. By comparing with conventional aggregators on two knowledge graph completion tasks, we experimentally validate LAN’s superiority in terms of the desired properties.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/4698/4576",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:.0109},{id:403,oaid:"e7f6e6440f7c11adf8bf07b417c34f7143c9b1c5",doi:null,title:"Theory and Practice of Logic Programming",authors:[{name:"G. Gottlob",institutions:[]},{name:"M. Manna",institutions:[]},{name:"Andreas Pieris",institutions:[]}],authorString:"G. Gottlob; M. Manna; Andreas Pieris",institutions:[],countries:[],year:2013,journal:"",citations:186,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8,betweenness:5e-4,pagerank:72e-5,eigenvector:0},{id:404,oaid:"5346525f5022b3d60e7a954b50772ea75d967e7d",doi:"10.3115/v1/D14-1044",title:"Incorporating Vector Space Similarity in Random Walk Inference over Knowledge Bases",authors:[{name:"Matt Gardner",institutions:["Allen Institute for Artificial Intelligence"]},{name:"P. Talukdar",institutions:[]},{name:"Jayant Krishnamurthy",institutions:[]},{name:"Tom Michael Mitchell",institutions:[]}],authorString:"Matt Gardner; P. Talukdar; Jayant Krishnamurthy; Tom Michael Mitchell",institutions:["Allen Institute for Artificial Intelligence"],countries:[],year:2014,journal:"Conference on Empirical Methods in Natural Language Processing",citations:183,abstract:"Much work in recent years has gone into the construction of large knowledge bases (KBs), such as Freebase, DBPedia, NELL, and YAGO. While these KBs are very large, they are still very incomplete, necessitating the use of inference to fill in gaps. Prior work has shown how to make use of a large text corpus to augment random walk inference over KBs. We present two improvements to the use of such large corpora to augment KB inference. First, we present a new technique for combining KB relations and surface text into a single graph representation that is much more compact than graphs used in prior work. Second, we describe how to incorporate vector space similarity into random walk inference over KBs, reducing the feature sparsity inherent in using surface text. This allows us to combine distributional similarity with symbolic logical inference in novel and effective ways. With experiments on many relations from two separate KBs, we show that our methods significantly outperform prior work on KB inference, both in the size of problem our methods can handle and in the quality of predictions made.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/D14-1044.pdf",is_oa:!0,n_refs:18,n_refs_in_core:3,degree:10,community:0,deg_w:70.5,betweenness:2e-4,pagerank:.00219,eigenvector:.0038},{id:405,oaid:"c70eb74e09c41e8fcc71dd59e3b4d631f657f7cd",doi:"10.48550/arXiv.2203.05115",title:"Internet-augmented language models through few-shot prompting for open-domain question answering",authors:[{name:"Angeliki Lazaridou",institutions:[]},{name:"E. Gribovskaya",institutions:[]},{name:"Wojciech Stokowiec",institutions:[]},{name:"N. Grigorev",institutions:[]}],authorString:"Angeliki Lazaridou; E. Gribovskaya; Wojciech Stokowiec; N. Grigorev",institutions:[],countries:[],year:2022,journal:"arXiv.org",citations:181,abstract:"In this work, we aim to capitalize on the unique few-shot capabilities of large-scale language models (LSLMs) to overcome some of their challenges with respect to grounding to factual and up-to-date information. Motivated by semi-parametric language models (LMs), which ground their decisions in external retrieved evidence, we use few-shot prompting to learn to condition LMs on information returned from the web using Google Search, a broad and constantly updated knowledge source. Our approach does not involve fine-tuning or learning additional parameters, thus making it applicable to any LM, offering therefore a strong baseline. Indeed, we find that LMs conditioned on the web surpass performance of closed-book models of similar, or even larger, model sizes in open-domain question answering. Finally, we find that increasing the inference-time compute of models, achieved via using multiple retrieved evidences to generate multiple answers followed by a reranking stage that uses scores generated by the same LMs, leads to better performance and alleviates lower performance of smaller few-shot LMs. All in all, our findings suggest that it might be beneficial to slow down the race towards the biggest model and instead shift attention towards finding more effective ways to use models, including but not limited to, better prompting or increasing inference-time compute.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2203.05115",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8,betweenness:1e-4,pagerank:55e-5,eigenvector:.0011},{id:406,oaid:"df8ae2068d17d969db6ab2d27108776e99413975",doi:"10.1609/aaai.v33i01.33017208",title:"Improving Natural Language Inference Using External Knowledge in the Science Questions Domain",authors:[{name:"Xiaoyang Wang",institutions:[]},{name:"Pavan Kapanipathi",institutions:["IBM Research"]},{name:"Ryan Musa",institutions:[]},{name:"Mo Yu",institutions:["IBM Research"]},{name:"Kartik Talamadupula",institutions:["IBM Research"]},{name:"I. Abdelaziz",institutions:[]},{name:"Maria Chang",institutions:[]},{name:"Achille Fokoue",institutions:[]},{name:"B. Makni",institutions:[]},{name:"Nicholas Mattei",institutions:[]},{name:"M. Witbrock",institutions:[]}],authorString:"Xiaoyang Wang; Pavan Kapanipathi; Ryan Musa; Mo Yu; Kartik Talamadupula; I. Abdelaziz; Maria Chang; Achille Fokoue; B. Makni; Nicholas Mattei; M. Witbrock",institutions:["IBM Research"],countries:[],year:2018,journal:"AAAI Conference on Artificial Intelligence",citations:178,abstract:"Natural Language Inference (NLI) is fundamental to many Natural Language Processing (NLP) applications including semantic search and question answering. The NLI problem has gained significant attention due to the release of large scale, challenging datasets. Present approaches to the problem largely focus on learning-based methods that use only textual information in order to classify whether a given premise entails, contradicts, or is neutral with respect to a given hypothesis. Surprisingly, the use of methods based on structured knowledge – a central topic in artificial intelligence – has not received much attention vis-a-vis the NLI problem. While there are many open knowledge bases that contain various types of reasoning information, their use for NLI has not been well explored. To address this, we present a combination of techniques that harness external knowledge to improve performance on the NLI problem in the science questions domain. We present the results of applying our techniques on text, graph, and text-and-graph based models; and discuss the implications of using external knowledge to solve the NLI problem. Our model achieves close to state-of-the-art performance for NLI on the SciTail science questions dataset.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/4705/4583",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:49e-5,eigenvector:.0066},{id:407,oaid:"bf722dc893ddaad5045fca5646212ec3badf3c5a",doi:"10.18653/v1/2022.findings-emnlp.512",title:"Prompt-Learning for Fine-Grained Entity Typing",authors:[{name:"Ning Ding",institutions:["Tsinghua University"]},{name:"Yulin Chen",institutions:[]},{name:"Xu Han",institutions:[]},{name:"Guangwei Xu",institutions:[]},{name:"Pengjun Xie",institutions:[]},{name:"Haitao Zheng",institutions:[]},{name:"Zhiyuan Liu",institutions:[]},{name:"Juan-Zi Li",institutions:[]},{name:"Hong-Gee Kim",institutions:[]}],authorString:"Ning Ding; Yulin Chen; Xu Han; Guangwei Xu; Pengjun Xie; Haitao Zheng; Zhiyuan Liu; Juan-Zi Li; Hong-Gee Kim",institutions:["Tsinghua University"],countries:[],year:2021,journal:"Conference on Empirical Methods in Natural Language Processing",citations:178,abstract:"As an effective approach to tune pre-trained language models (PLMs) for specific tasks, prompt-learning has recently attracted much attention from researchers. By using \\textit{cloze}-style language prompts to stimulate the versatile knowledge of PLMs, prompt-learning can achieve promising results on a series of NLP tasks, such as natural language inference, sentiment classification, and knowledge probing. In this work, we investigate the application of prompt-learning on fine-grained entity typing in fully supervised, few-shot and zero-shot scenarios. We first develop a simple and effective prompt-learning pipeline by constructing entity-oriented verbalizers and templates and conducting masked language modeling. Further, to tackle the zero-shot regime, we propose a self-supervised strategy that carries out distribution-level optimization in prompt-learning to automatically summarize the information of entity types. Extensive experiments on three fine-grained entity typing benchmarks (with up to 86 classes) under fully supervised, few-shot and zero-shot settings show that prompt-learning methods significantly outperform fine-tuning baselines, especially when the training data is insufficient.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2022.findings-emnlp.512.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:47e-5,eigenvector:.0069},{id:408,oaid:"916a06a6d51aa93de27aac2f3e14faed08dd6706",doi:null,title:"Formal Mathematics Statement Curriculum Learning",authors:[{name:"Stanislas Polu",institutions:[]},{name:"Jesse Michael Han",institutions:[]},{name:"Kunhao Zheng",institutions:[]},{name:"Mantas Baksys",institutions:[]},{name:"Igor Babuschkin",institutions:[]},{name:"I. Sutskever",institutions:[]}],authorString:"Stanislas Polu; Jesse Michael Han; Kunhao Zheng; Mantas Baksys; Igor Babuschkin; I. Sutskever",institutions:[],countries:[],year:2022,journal:"International Conference on Learning Representations",citations:178,abstract:"We explore the use of expert iteration in the context of language modeling applied to formal mathematics. We show that at same compute budget, expert iteration, by which we mean proof search interleaved with learning, dramatically outperforms proof search only. We also observe that when applied to a collection of formal statements of sufficiently varied difficulty, expert iteration is capable of finding and solving a curriculum of increasingly difficult problems, without the need for associated ground-truth proofs. Finally, by applying this expert iteration to a manually curated set of problem statements, we achieve state-of-the-art on the miniF2F benchmark, automatically solving multiple challenging problems drawn from high school olympiads.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:46,n_refs_in_core:17,degree:28,community:6,deg_w:175.5,betweenness:.0116,pagerank:.00529,eigenvector:.0095},{id:409,oaid:"52fb239ea5cea1e9a2636f8f7922c8ede3e50ba7",doi:"10.48550/arXiv.2210.17517",title:"LILA: A Unified Benchmark for Mathematical Reasoning",authors:[{name:"Swaroop Mishra",institutions:["Arizona State University"]},{name:"Matthew Finlayson",institutions:["University of Southern California"]},{name:"Pan Lu",institutions:["Stanford University"]},{name:"Leonard Tang",institutions:["Harvard University"]},{name:"S. Welleck",institutions:[]},{name:"Chitta Baral",institutions:[]},{name:"Tanmay Rajpurohit",institutions:[]},{name:"Oyvind Tafjord",institutions:[]},{name:"Ashish Sabharwal",institutions:[]},{name:"Peter Clark",institutions:["Allen Institute for AI"]},{name:"A. Kalyan",institutions:[]}],authorString:"Swaroop Mishra; Matthew Finlayson; Pan Lu; Leonard Tang; S. Welleck; Chitta Baral; Tanmay Rajpurohit; Oyvind Tafjord; Ashish Sabharwal; Peter Clark; A. Kalyan",institutions:["Allen Institute for AI","Arizona State University","Harvard University","Stanford University","University of Southern California"],countries:[],year:2022,journal:"Conference on Empirical Methods in Natural Language Processing",citations:175,abstract:"Mathematical reasoning skills are essential for general-purpose intelligentsystems to perform tasks from grocery shopping to climate modeling.Towards evaluating and improving AI systems in this domain, we proposeLILA, a unified mathematical reasoning benchmark consisting of 23 diversetasks along four dimensions:(i) mathematical abilities e.g., arithmetic, calculus (ii) language format e.g., question-answering, fill-in-the-blanks (iii) language diversity e.g., no language, simple language (iv) external knowledge e.g., commonsense, physics. We construct our benchmark by extending 20 datasets benchmark by collecting task instructions and solutions in the form of Python programs,thereby obtaining explainable solutions in addition to the correct answer.We additionally introduce two evaluation datasets to measure out-of-distribution performance and robustness to language perturbation.Finally, we introduce BHASKARA,a general-purpose mathematical reasoning model trained on LILA. Importantly, we find that multi-tasking leads to significant improvements (average relative improvement of 21.83% F1 score vs. single-task models),while the best performing model only obtains 60.40%,indicating the room for improvement in general mathematical reasoning and understanding.",keywords:["Environmental Science"],concepts:["Environmental Science"],pdf_url:"http://arxiv.org/pdf/2210.17517",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:5,deg_w:13,betweenness:0,pagerank:64e-5,eigenvector:.001},{id:410,oaid:"37bf0bf34603145246c3311df19e2afdf6e0270a",doi:"10.1609/aaai.v36i10.21417",title:"JAKET: Joint Pre-training of Knowledge Graph and Language Understanding",authors:[{name:"Donghan Yu",institutions:[]},{name:"Chenguang Zhu",institutions:[]},{name:"Yiming Yang",institutions:[]},{name:"Michael Zeng",institutions:[]}],authorString:"Donghan Yu; Chenguang Zhu; Yiming Yang; Michael Zeng",institutions:[],countries:[],year:2020,journal:"AAAI Conference on Artificial Intelligence",citations:175,abstract:"Knowledge graphs (KGs) contain rich information about world knowledge, entities, and relations. Thus, they can be great supplements to existing pre-trained language models. However, it remains a challenge to efficiently integrate information from KG into language modeling. And the understanding of a knowledge graph requires related context. We propose a novel joint pre-training framework, JAKET, to model both the knowledge graph and language. The knowledge module and language module provide essential information to mutually assist each other: the knowledge module produces embeddings for entities in text while the language module generates context-aware initial embeddings for entities and relations in the graph. Our design enables the pre-trained model to easily adapt to unseen knowledge graphs in new domains. Experiment results on several knowledge-aware NLP tasks show that our proposed framework achieves superior performance by effectively leveraging knowledge in language understanding.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/21417/21166",is_oa:!0,n_refs:52,n_refs_in_core:8,degree:26,community:1,deg_w:299,betweenness:.0019,pagerank:.00608,eigenvector:.2466},{id:411,oaid:"6c41bedc4637f3fd504c68baa3b3d8881e056ac1",doi:null,title:"Execution-Guided Neural Program Synthesis",authors:[{name:"Xinyun Chen",institutions:[]},{name:"Chang Liu",institutions:[]},{name:"D. Song",institutions:[]}],authorString:"Xinyun Chen; Chang Liu; D. Song",institutions:[],countries:[],year:2018,journal:"International Conference on Learning Representations",citations:175,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:12,betweenness:.0015,pagerank:7e-4,eigenvector:.0011},{id:412,oaid:"ba4cf6046d420af0ae86e2f4b587a8d50d219be3",doi:null,title:"Measuring Compositionality in Representation Learning",authors:[{name:"Jacob Andreas",institutions:["MIT","Microsoft"]}],authorString:"Jacob Andreas",institutions:["MIT","Microsoft"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:171,abstract:"Many machine learning algorithms represent input data with vector embeddings or discrete codes. When inputs exhibit compositional structure (e.g. objects built from parts or procedures from subroutines), it is natural to ask whether this compositional structure is reflected in the the inputs' learned representations. While the assessment of compositionality in languages has received significant attention in linguistics and adjacent fields, the machine learning literature lacks general-purpose tools for producing graded measurements of compositional structure in more general (e.g. vector-valued) representation spaces. We describe a procedure for evaluating compositionality by measuring how well the true representation-producing model can be approximated by a model that explicitly composes a collection of inferred representational primitives. We use the procedure to provide formal and empirical characterizations of compositional structure in a variety of settings, exploring the relationship between compositionality and learning dynamics, human judgments, representational similarity, and generalization.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:51,n_refs_in_core:2,degree:7,community:2,deg_w:36.5,betweenness:.0015,pagerank:.00126,eigenvector:5e-4},{id:413,oaid:"2bd53f62ed2fcde3425e521d24a41750de2a4176",doi:"10.1007/s10817-018-9458-4",title:"Hammer for Coq: Automation for Dependent Type Theory",authors:[{name:"Lukasz Czajka",institutions:[]},{name:"C. Kaliszyk",institutions:[]}],authorString:"Lukasz Czajka; C. Kaliszyk",institutions:[],countries:[],year:2018,journal:"Journal of automated reasoning",citations:170,abstract:"Hammers provide most powerful general purpose automation for proof assistants based on HOL and set theory today. Despite the gaining popularity of the more advanced versions of type theory, such as those based on the Calculus of Inductive Constructions, the construction of hammers for such foundations has been hindered so far by the lack of translation and reconstruction components. In this paper, we present an architecture of a full hammer for dependent type theory together with its implementation for the Coq proof assistant. A key component of the hammer is a proposed translation from the Calculus of Inductive Constructions, with certain extensions introduced by Coq, to untyped first-order logic. The translation is “sufficiently” sound and complete to be of practical use for automated theorem provers. We also introduce a proof reconstruction mechanism based on an eauto-type algorithm combined with limited rewriting, congruence closure and some forward reasoning. The algorithm is able to re-prove in the Coq logic most of the theorems established by the ATPs. Together with machine-learning based selection of relevant premises this constitutes a full hammer system. The performance of the whole procedure is evaluated in a bootstrapping scenario emulating the development of the Coq standard library. For each theorem in the library only the previous theorems and proofs can be used. We show that 40.8% of the theorems can be proved in a push-button mode in about 40 s of real time on a 8-CPU system.",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007%2Fs10817-018-9458-4.pdf",is_oa:!0,n_refs:74,n_refs_in_core:6,degree:12,community:6,deg_w:104.5,betweenness:2e-4,pagerank:.00323,eigenvector:.0024},{id:414,oaid:"34273979fd2a62fd7b49ee6d14a925864ff94e74",doi:null,title:"Recurrent Relational Networks",authors:[{name:"Rasmus Berg Palm",institutions:[]},{name:"U. Paquet",institutions:[]},{name:"O. Winther",institutions:[]}],authorString:"Rasmus Berg Palm; U. Paquet; O. Winther",institutions:[],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:170,abstract:"This paper is concerned with learning to solve tasks that require a chain of interdependent steps of relational inference, like answering complex questions about the relationships between objects, or solving puzzles where the smaller elements of a solution mutually constrain each other. We introduce the recurrent relational network, a general purpose module that operates on a graph representation of objects. As a generalization of Santoro et al. [2017]'s relational network, it can augment any neural network model with the capacity to do many-step relational reasoning. We achieve state of the art results on the bAbI textual question-answering dataset with the recurrent relational network, consistently solving 20/20 tasks. As bAbI is not particularly challenging from a relational reasoning point of view, we introduce Pretty-CLEVR, a new diagnostic dataset for relational reasoning. In the Pretty-CLEVR set-up, we can vary the question to control for the number of relational reasoning steps that are required to obtain the answer. Using Pretty-CLEVR, we probe the limitations of multi-layer perceptrons, relational and recurrent relational networks. Finally, we show how recurrent relational networks can learn to solve Sudoku puzzles from supervised training data, a challenging task requiring upwards of 64 steps of relational reasoning. We achieve state-of-the-art results amongst comparable methods by solving 96.6% of the hardest Sudoku puzzles.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:36,n_refs_in_core:4,degree:19,community:2,deg_w:84,betweenness:.0105,pagerank:.00321,eigenvector:5e-4},{id:415,oaid:"9231927bc0a9ed10de64cad05640587893eba4b1",doi:null,title:"Proof Artifact Co-training for Theorem Proving with Language Models",authors:[{name:"Jesse Michael Han",institutions:[]},{name:"Jason M. Rute",institutions:[]},{name:"Yuhuai Wu",institutions:[]},{name:"Edward W. Ayers",institutions:[]},{name:"Stanislas Polu",institutions:[]}],authorString:"Jesse Michael Han; Jason M. Rute; Yuhuai Wu; Edward W. Ayers; Stanislas Polu",institutions:[],countries:[],year:2021,journal:"International Conference on Learning Representations",citations:170,abstract:"Labeled data for imitation learning of theorem proving in large libraries of formalized mathematics is scarce as such libraries require years of concentrated effort by human specialists to be built. This is particularly challenging when applying large Transformer language models to tactic prediction, because the scaling of performance with respect to model size is quickly disrupted in the data-scarce, easily-overfitted regime. We propose PACT ({\\bf P}roof {\\bf A}rtifact {\\bf C}o-{\\bf T}raining), a general methodology for extracting abundant self-supervised data from kernel-level proof terms for co-training alongside the usual tactic prediction objective. We apply this methodology to Lean, an interactive proof assistant which hosts some of the most sophisticated formalized mathematics to date. We instrument Lean with a neural theorem prover driven by a Transformer language model and show that PACT improves theorem proving success rate on a held-out suite of test theorems from 32\\% to 48\\%.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:6,deg_w:17,betweenness:0,pagerank:72e-5,eigenvector:.0016},{id:416,oaid:"e77e00286a63a32dafb9629cd79f6a77bddb1941",doi:"10.29007/8MWC",title:"Deep Network Guided Proof Search",authors:[{name:"Sarah M. Loos",institutions:[]},{name:"G. Irving",institutions:[]},{name:"Christian Szegedy",institutions:[]},{name:"C. Kaliszyk",institutions:[]}],authorString:"Sarah M. Loos; G. Irving; Christian Szegedy; C. Kaliszyk",institutions:[],countries:[],year:2017,journal:"Logic Programming and Automated Reasoning",citations:169,abstract:"Deep learning techniques lie at the heart of several significant AI advances in recent years including object recognition and detection, image captioning, machine translation, speech recognition and synthesis, and playing the game of Go.Automated first-order theorem provers can aid in the formalization and verification of mathematical theorems and play a crucial role in program analysis, theory reasoning, security, interpolation, and system verification.Here we suggest deep learning based guidance in the proof search of the theorem prover E. We train and compare several deep neural network models on the traces of existing ATP proofs of Mizar statements and use them to select processed clauses during proof search. We give experimental evidence that with a hybrid, two-phase approach, deep learning based guidance can significantly reduce the average number of proof search steps while increasing the number of theorems proved.Using a few proof guidance strategies that leverage deep neural networks, we have found first-order proofs of 7.36% of the first-order logic translations of the Mizar Mathematical Library theorems that did not previously have ATP generated proofs. This increases the ratio of statements in the corpus with ATP generated proofs from 56% to 59%.",keywords:[],concepts:[],pdf_url:"https://easychair.org/publications/open/ND13",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:9,community:6,deg_w:35,betweenness:1e-4,pagerank:.0012,eigenvector:.001},{id:417,oaid:"d03d24241fc95e018517d6b1e3be40c5dc31ee66",doi:"10.1609/AAAI.V33I01.33016473",title:"Story Ending Generation with Incremental Encoding and Commonsense Knowledge",authors:[{name:"Jian Guan",institutions:[]},{name:"Yansen Wang",institutions:["Tsinghua University","Carnegie Mellon University"]},{name:"Minlie Huang",institutions:["Tsinghua University"]}],authorString:"Jian Guan; Yansen Wang; Minlie Huang",institutions:["Carnegie Mellon University","Tsinghua University"],countries:[],year:2018,journal:"AAAI Conference on Artificial Intelligence",citations:168,abstract:"Generating a reasonable ending for a given story context, i.e., story ending generation, is a strong indication of story comprehension. This task requires not only to understand the context clues which play an important role in planning the plot, but also to handle implicit knowledge to make a reasonable, coherent story. In this paper, we devise a novel model for story ending generation. The model adopts an incremental encoding scheme to represent context clues which are spanning in the story context. In addition, commonsense knowledge is applied through multi-source attention to facilitate story comprehension, and thus to help generate coherent and reasonable endings. Through building context clues and using implicit knowledge, the model is able to produce reasonable story endings. Automatic and manual evaluation shows that our model can generate more reasonable story endings than state-of-the-art baselines1.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1609/aaai.v33i01.33016473",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:1,deg_w:18,betweenness:0,pagerank:64e-5,eigenvector:.0126},{id:418,oaid:"d941324ac6f7e255d2ba4b72dca265e224649cfe",doi:"10.1007/11844297_87",title:"Evolving Bin Packing Heuristics with Genetic Programming",authors:[{name:"E. Burke",institutions:[]},{name:"Matthew R. Hyde",institutions:[]},{name:"G. Kendall",institutions:[]}],authorString:"E. Burke; Matthew R. Hyde; G. Kendall",institutions:[],countries:[],year:2006,journal:"Parallel Problem Solving from Nature",citations:166,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:83e-5,eigenvector:0},{id:419,oaid:"d3096681c103d02d7c59fc936da35a4b03262359",doi:"10.1145/265910.265918",title:"Learning to reason",authors:[{name:"R. Khardon",institutions:[]},{name:"Dan Roth",institutions:["University of Pennsylvania, Oracle"]}],authorString:"R. Khardon; Dan Roth",institutions:["University of Pennsylvania, Oracle"],countries:[],year:1994,journal:"JACM",citations:163,abstract:"",keywords:[],concepts:[],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/265910.265918",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12,betweenness:1e-4,pagerank:84e-5,eigenvector:0},{id:420,oaid:"760561c57f68044e2f1d089088df1da6c627b09a",doi:"10.48550/arXiv.2206.02336",title:"On the Advance of Making Language Models Better Reasoners",authors:[{name:"Yifei Li",institutions:["Peking University"]},{name:"Zeqi Lin",institutions:[]},{name:"S. Zhang",institutions:[]},{name:"Qiang Fu",institutions:[]},{name:"Bei Chen",institutions:[]},{name:"Jian-Guang Lou",institutions:[]},{name:"Weizhu Chen",institutions:[]}],authorString:"Yifei Li; Zeqi Lin; S. Zhang; Qiang Fu; Bei Chen; Jian-Guang Lou; Weizhu Chen",institutions:["Peking University"],countries:[],year:2022,journal:"arXiv.org",citations:162,abstract:"",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2206.02336",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:5,deg_w:13,betweenness:0,pagerank:6e-4,eigenvector:.0015},{id:421,oaid:"61ff6872fa07788acdbe85b1319554a5fb9ce0db",doi:null,title:"XIRL: Cross-embodiment Inverse Reinforcement Learning",authors:[{name:"Kevin Zakka",institutions:[]},{name:"Andy Zeng",institutions:[]},{name:"Peter R. Florence",institutions:[]},{name:"Jonathan Tompson",institutions:[]},{name:"Jeannette Bohg",institutions:[]},{name:"Debidatta Dwibedi",institutions:[]}],authorString:"Kevin Zakka; Andy Zeng; Peter R. Florence; Jonathan Tompson; Jeannette Bohg; Debidatta Dwibedi",institutions:[],countries:[],year:2021,journal:"Conference on Robot Learning",citations:162,abstract:"We investigate the visual cross-embodiment imitation setting, in which agents learn policies from videos of other agents (such as humans) demonstrating the same task, but with stark differences in their embodiments -- shape, actions, end-effector dynamics, etc. In this work, we demonstrate that it is possible to automatically discover and learn vision-based reward functions from cross-embodiment demonstration videos that are robust to these differences. Specifically, we present a self-supervised method for Cross-embodiment Inverse Reinforcement Learning (XIRL) that leverages temporal cycle-consistency constraints to learn deep visual embeddings that capture task progression from offline videos of demonstrations across multiple expert agents, each performing the same task differently due to embodiment differences. Prior to our work, producing rewards from self-supervised embeddings typically required alignment with a reference trajectory, which may be difficult to acquire under stark embodiment differences. We show empirically that if the embeddings are aware of task progress, simply taking the negative distance between the current state and goal state in the learned embedding space is useful as a reward for training policies with reinforcement learning. We find our learned reward function not only works for embodiments seen during training, but also generalizes to entirely new embodiments. Additionally, when transferring real-world human demonstrations to a simulated robot, we find that XIRL is more sample efficient than current best methods. Qualitative results, code, and datasets are available at https://x-irl.github.io",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:54,n_refs_in_core:0,degree:8,community:4,deg_w:41,betweenness:2e-4,pagerank:.0013,eigenvector:.0014},{id:422,oaid:"e60f6be86bc88fc2309b17d3df2885886448d16e",doi:"10.1109/CVPR.2017.744",title:"Neural Scene De-rendering",authors:[{name:"Jiajun Wu",institutions:["Stanford University"]},{name:"J. Tenenbaum",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"Jiajun Wu; J. Tenenbaum; Pushmeet Kohli",institutions:["Stanford University"],countries:[],year:2017,journal:"Computer Vision and Pattern Recognition",citations:160,abstract:"We study the problem of holistic scene understanding. We would like to obtain a compact, expressive, and interpretable representation of scenes that encodes information such as the number of objects and their categories, poses, positions, etc. Such a representation would allow us to reason about and even reconstruct or manipulate elements of the scene. Previous works have used encoder-decoder based neural architectures to learn image representations, however, representations obtained in this way are typically uninterpretable, or only explain a single object in the scene. In this work, we propose a new approach to learn an interpretable distributed representation of scenes. Our approach employs a deterministic rendering function as the decoder, mapping a naturally structured and disentangled scene description, which we named scene XML, to an image. By doing so, the encoder is forced to perform the inverse of the rendering operation (a.k.a. de-rendering) to transform an input image to the structured scene XML that the decoder used to produce the image. We use a object proposal based encoder that is trained by minimizing both the supervised prediction and the unsupervised reconstruction errors. Experiments demonstrate that our approach works well on scene de-rendering with two different graphics engines, and our learned representation can be easily adapted for a wide range of applications like image editing, inpainting, visual analogy-making, and image captioning.",keywords:[],concepts:[],pdf_url:"https://dspace.mit.edu/bitstream/1721.1/126659/2/nsd_cvpr.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:8,community:3,deg_w:32.5,betweenness:3e-4,pagerank:.00113,eigenvector:2e-4},{id:423,oaid:"b1e6aa78db5478be5eaa47697382241c2b7aab1f",doi:"10.18653/V1/2020.COLING-MAIN.153",title:"Multi-Task Learning for Knowledge Graph Completion with Pre-trained Language Models",authors:[{name:"Bosung Kim",institutions:[]},{name:"Taesuk Hong",institutions:[]},{name:"Youngjoong Ko",institutions:[]},{name:"Jungyun Seo",institutions:[]}],authorString:"Bosung Kim; Taesuk Hong; Youngjoong Ko; Jungyun Seo",institutions:[],countries:[],year:2020,journal:"International Conference on Computational Linguistics",citations:159,abstract:"As research on utilizing human knowledge in natural language processing has attracted considerable attention in recent years, knowledge graph (KG) completion has come into the spotlight. Recently, a new knowledge graph completion method using a pre-trained language model, such as KG-BERT, is presented and showed high performance. However, its scores in ranking metrics such as Hits@k are still behind state-of-the-art models. We claim that there are two main reasons: 1) failure in sufficiently learning relational information in knowledge graphs, and 2) difficulty in picking out the correct answer from lexically similar candidates. In this paper, we propose an effective multi-task learning method to overcome the limitations of previous works. By combining relation prediction and relevance ranking tasks with our target link prediction, the proposed model can learn more relational properties in KGs and properly perform even when lexical similarity occurs. Experimental results show that we not only largely improve the ranking performances compared to KG-BERT but also achieve the state-of-the-art performances in Mean Rank and Hits@10 on the WN18RR dataset.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.coling-main.153.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:.0084},{id:424,oaid:"d920e8c8493efcc7bdcd96d06228b564e788806d",doi:"10.1109/ICRA.2019.8793509",title:"Propagation Networks for Model-Based Control Under Partial Observation",authors:[{name:"Yunzhu Li",institutions:["MIT"]},{name:"Jiajun Wu",institutions:["Stanford University"]},{name:"Jun-Yan Zhu",institutions:["Adobe Inc."]},{name:"J. Tenenbaum",institutions:[]},{name:"A. Torralba",institutions:[]},{name:"Russ Tedrake",institutions:["Massachusetts Institute of Technology","Toyota Research Institute"]}],authorString:"Yunzhu Li; Jiajun Wu; Jun-Yan Zhu; J. Tenenbaum; A. Torralba; Russ Tedrake",institutions:["Adobe Inc.","MIT","Massachusetts Institute of Technology","Stanford University","Toyota Research Institute"],countries:[],year:2018,journal:"IEEE International Conference on Robotics and Automation",citations:158,abstract:"There has been an increasing interest in learning dynamics simulators for model-based control. Compared with off-the-shelf physics engines, a learnable simulator can quickly adapt to unseen objects, scenes, and tasks. However, existing models like interaction networks only work for fully observable systems; they also only consider pairwise interactions within a single time step, both restricting their use in practical systems. We introduce Propagation Networks (PropNet), a differentiable, learnable dynamics model that handles partially observable scenarios and enables instantaneous propagation of signals beyond pairwise interactions. With these innovations, our propagation networks not only outperform current learnable physics engines in forward simulation, but also achieves superior performance on various control tasks. Compared with existing deep reinforcement learning algorithms, model-based control with propagation networks is more accurate, efficient, and generalizable to novel, partially observable scenes and tasks.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1809.11169",is_oa:!0,n_refs:35,n_refs_in_core:1,degree:6,community:2,deg_w:27,betweenness:1e-4,pagerank:.00104,eigenvector:1e-4},{id:425,oaid:"09a6d7e831cf496fb5fb2903415eab4c73235715",doi:null,title:"Programming with a Differentiable Forth Interpreter",authors:[{name:"Matko Bosnjak",institutions:[]},{name:"Tim Rocktäschel",institutions:[]},{name:"Jason Naradowsky",institutions:[]},{name:"Sebastian Riedel",institutions:[]}],authorString:"Matko Bosnjak; Tim Rocktäschel; Jason Naradowsky; Sebastian Riedel",institutions:[],countries:[],year:2016,journal:"International Conference on Machine Learning",citations:157,abstract:"Given that in practice training data is scarce for all but a small set of problems, a core question is how to incorporate prior knowledge into a model. In this paper, we consider the case of prior procedural knowledge for neural networks, such as knowing how a program should traverse a sequence, but not what local actions should be performed at each step. To this end, we present an end-to-end differentiable interpreter for the programming language Forth which enables programmers to write program sketches with slots that can be filled with behaviour trained from program input-output data. We can optimise this behaviour directly through gradient descent techniques on user-specified objectives, and also integrate the program into any larger neural computation graph. We show empirically that our interpreter is able to effectively leverage different levels of prior program structure and learn complex behaviours such as sequence sorting and addition. When connected to outputs of an LSTM and trained jointly, our interpreter achieves state-of-the-art accuracy for end-to-end reasoning about quantities expressed in natural language stories.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:8,community:0,deg_w:32.5,betweenness:.0016,pagerank:.00154,eigenvector:4e-4},{id:426,oaid:"91ab9a65e276cff7f62c7279dd507967804c2477",doi:"10.1007/s10817-013-9286-5",title:"Premise Selection for Mathematics by Corpus Analysis and Kernel Methods",authors:[{name:"Jesse Alama",institutions:[]},{name:"T. Heskes",institutions:[]},{name:"D. Kühlwein",institutions:[]},{name:"Evgeni Tsivtsivadze",institutions:[]},{name:"J. Urban",institutions:[]}],authorString:"Jesse Alama; T. Heskes; D. Kühlwein; Evgeni Tsivtsivadze; J. Urban",institutions:[],countries:[],year:2011,journal:"Journal of automated reasoning",citations:156,abstract:"Smart premise selection is essential when using automated reasoning as a tool for large-theory formal proof development. This work develops learning-based premise selection in two ways. First, a fine-grained dependency analysis of existing high-level formal mathematical proofs is used to build a large knowledge base of proof dependencies, providing precise data for ATP-based re-verification and for training premise selection algorithms. Second, a new machine learning algorithm for premise selection based on kernel methods is proposed and implemented. To evaluate the impact of both techniques, a benchmark consisting of 2078 large-theory mathematical problems is constructed, extending the older MPTP Challenge benchmark. The combined effect of the techniques results in a 50 % improvement on the benchmark over the state-of-the-art Vampire/SInE system for automated reasoning in large theories.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1108.3446",is_oa:!0,n_refs:49,n_refs_in_core:2,degree:7,community:6,deg_w:39.5,betweenness:4e-4,pagerank:.00147,eigenvector:.001},{id:427,oaid:"da1d6445b6b64ce9eb4587ba8abbdc490f648ec1",doi:"10.48550/arXiv.2205.12674",title:"Training Language Models with Memory Augmentation",authors:[{name:"Zexuan Zhong",institutions:[]},{name:"Tao Lei",institutions:[]},{name:"Danqi Chen",institutions:["Princeton University"]}],authorString:"Zexuan Zhong; Tao Lei; Danqi Chen",institutions:["Princeton University"],countries:[],year:2022,journal:"Conference on Empirical Methods in Natural Language Processing",citations:154,abstract:"Recent work has improved language models (LMs) remarkably by equipping them with a non-parametric memory component. However, most existing approaches only introduce mem-ories at testing time or represent them using a separately trained encoder, resulting in suboptimal training of the language model. In this work, we present TRIME, a novel yet simple training approach designed for training LMs with memory augmentation. Our approach uses a training objective that directly takes in-batch examples as accessible memory. We also present new methods for memory construction and data batching, which are used for adapting to different sets of memories—local, long-term, and external memory—at testing time. We evaluate TRIME on multiple language modeling and machine translation benchmarks and show that it is able to achieve significant improvements across all the settings. Concretely, TRIME reduces the perplexity from 18.70 to 15.37 on WIKITEXT-103, by effectively leveraging a large memory set from the training corpus. Compared to standard LM training, TRIME adds negligible computational overhead and is compatible with different neural architectures, making it a versatile solution for training memory-augmented LMs.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2205.12674",is_oa:!0,n_refs:53,n_refs_in_core:2,degree:18,community:1,deg_w:141.5,betweenness:.0094,pagerank:.00344,eigenvector:.0442},{id:428,oaid:"a1fb4e2029af4a118a045cf9dc7c00d65047f8df",doi:"10.18653/v1/D16-1146",title:"Lifted Rule Injection for Relation Embeddings",authors:[{name:"T. Demeester",institutions:[]},{name:"Tim Rocktäschel",institutions:[]},{name:"Sebastian Riedel",institutions:[]}],authorString:"T. Demeester; Tim Rocktäschel; Sebastian Riedel",institutions:[],countries:[],year:2016,journal:"Conference on Empirical Methods in Natural Language Processing",citations:152,abstract:"Methods based on representation learning currently hold the state-of-the-art in many natural language processing and knowledge base inference tasks. Yet, a major challenge is how to efficiently incorporate commonsense knowledge into such models. A recent approach regularizes relation and entity representations by propositionalization of first-order logic rules. However, propositionalization does not scale beyond domains with only few entities and rules. In this paper we present a highly efficient method for incorporating implication rules into distributed representations for automated knowledge base construction. We map entity-tuple embeddings into an approximately Boolean space and encourage a partial ordering over relation embeddings based on implication rules mined from WordNet. Surprisingly, we find that the strong restriction of the entity-tuple embedding space does not hurt the expressiveness of the model and even acts as a regularizer that improves generalization. By incorporating few commonsense rules, we achieve an increase of 2 percentage points mean average precision over a matrix factorization baseline, while observing a negligible increase in runtime.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/D16-1146.pdf",is_oa:!0,n_refs:29,n_refs_in_core:11,degree:19,community:0,deg_w:122,betweenness:.0042,pagerank:.00422,eigenvector:.0049},{id:429,oaid:"15bce8864a15c20cf483e18099f3601b94673565",doi:null,title:"Premise Selection for Theorem Proving by Deep Graph Embedding",authors:[{name:"Mingzhe Wang",institutions:[]},{name:"Yihe Tang",institutions:[]},{name:"Jian Wang",institutions:[]},{name:"Jia Deng",institutions:[]}],authorString:"Mingzhe Wang; Yihe Tang; Jian Wang; Jia Deng",institutions:[],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:151,abstract:"We propose a deep learning-based approach to the problem of premise selection: selecting mathematical statements relevant for proving a given conjecture. We represent a higher-order logic formula as a graph that is invariant to variable renaming but still fully preserves syntactic and semantic information. We then embed the graph into a vector via a novel embedding method that preserves the information of edge ordering. Our approach achieves state-of-the-art results on the HolStep dataset, improving the classification accuracy from 83% to 90.3%.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:12,community:6,deg_w:48.5,betweenness:.0042,pagerank:.00157,eigenvector:.0014},{id:430,oaid:"91075f524e74bdc618fea689416de22c1cf2a472",doi:"10.1016/J.AIOPEN.2021.03.001",title:"Neural, symbolic and neural-symbolic reasoning on knowledge graphs",authors:[{name:"Jing Zhang",institutions:[]},{name:"Bo Chen",institutions:[]},{name:"Lingxi Zhang",institutions:[]},{name:"Xirui Ke",institutions:[]},{name:"Haipeng Ding",institutions:[]}],authorString:"Jing Zhang; Bo Chen; Lingxi Zhang; Xirui Ke; Haipeng Ding",institutions:[],countries:[],year:2021,journal:"AI Open",citations:150,abstract:"Abstract Knowledge graph reasoning is the fundamental component to support machine learning applications such as information extraction, information retrieval, and recommendation. Since knowledge graphs can be viewed as the discrete symbolic representations of knowledge, reasoning on knowledge graphs can naturally leverage the symbolic techniques. However, symbolic reasoning is intolerant of the ambiguous and noisy data. On the contrary, the recent advances of deep learning have promoted neural reasoning on knowledge graphs, which is robust to the ambiguous and noisy data, but lacks interpretability compared to symbolic reasoning. Considering the advantages and disadvantages of both methodologies, recent efforts have been made on combining the two reasoning methods. In this survey, we take a thorough look at the development of the symbolic, neural and hybrid reasoning on knowledge graphs. We survey two specific reasoning tasks — knowledge graph completion and question answering on knowledge graphs, and explain them in a unified reasoning framework. We also briefly discuss the future directions for knowledge graph reasoning.",keywords:[],concepts:[],pdf_url:"https://www.sciencedirect.com/science/article/pii/S2666651021000061/pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:1,deg_w:12.5,betweenness:0,pagerank:58e-5,eigenvector:.0068},{id:431,oaid:"6eb042e98091ce96af92ea400e43212ccb982ad3",doi:null,title:"Improving Coherence and Consistency in Neural Sequence Models with Dual-System, Neuro-Symbolic Reasoning",authors:[{name:"Maxwell Nye",institutions:["MIT"]},{name:"Michael Henry Tessler",institutions:[]},{name:"J. Tenenbaum",institutions:[]},{name:"B. Lake",institutions:[]}],authorString:"Maxwell Nye; Michael Henry Tessler; J. Tenenbaum; B. Lake",institutions:["MIT"],countries:[],year:2021,journal:"Neural Information Processing Systems",citations:149,abstract:'Human reasoning can often be understood as an interplay between two systems: the intuitive and associative ("System 1") and the deliberative and logical ("System 2"). Neural sequence models -- which have been increasingly successful at performing complex, structured tasks -- exhibit the advantages and failure modes of System 1: they are fast and learn patterns from data, but are often inconsistent and incoherent. In this work, we seek a lightweight, training-free means of improving existing System 1-like sequence models by adding System 2-inspired logical reasoning. We explore several variations on this theme in which candidate generations from a neural sequence model are examined for logical consistency by a symbolic reasoning module, which can either accept or reject the generations. Our approach uses neural inference to mediate between the neural System 1 and the logical System 2. Results in robust story generation and grounded instruction-following show that this approach can increase the coherence and accuracy of neurally-based generations.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:53,n_refs_in_core:10,degree:16,community:5,deg_w:80,betweenness:.0107,pagerank:.00313,eigenvector:.0016},{id:432,oaid:"80c4185d5311841cbbcbb9f1d3555b61081ca5d8",doi:null,title:"HOList: An Environment for Machine Learning of Higher Order Logic Theorem Proving",authors:[{name:"Kshitij Bansal",institutions:[]},{name:"Sarah M. Loos",institutions:[]},{name:"M. Rabe",institutions:[]},{name:"Christian Szegedy",institutions:[]},{name:"S. Wilcox",institutions:[]}],authorString:"Kshitij Bansal; Sarah M. Loos; M. Rabe; Christian Szegedy; S. Wilcox",institutions:[],countries:[],year:2019,journal:"International Conference on Machine Learning",citations:148,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:7,community:6,deg_w:26,betweenness:0,pagerank:.00101,eigenvector:.0017},{id:433,oaid:"b17cc18e4130505b939f7d527082eb6be2a7fd5b",doi:"10.48550/arXiv.2207.00747",title:"Rationale-Augmented Ensembles in Language Models",authors:[{name:"Xuezhi Wang",institutions:[]},{name:"Jason Wei",institutions:[]},{name:"Dale Schuurmans",institutions:[]},{name:"Quoc Le",institutions:[]},{name:"Ed H. Chi",institutions:["Google"]},{name:"Denny Zhou",institutions:[]}],authorString:"Xuezhi Wang; Jason Wei; Dale Schuurmans; Quoc Le; Ed H. Chi; Denny Zhou",institutions:["Google"],countries:[],year:2022,journal:"arXiv.org",citations:146,abstract:"Recent research has shown that rationales, or step-by-step chains of thought, can be used to improve performance in multi-step reasoning tasks. We reconsider rationale-augmented prompting for few-shot in-context learning, where (input ->output) prompts are expanded to (input, rationale ->output) prompts. For rationale-augmented prompting we demonstrate how existing approaches, which rely on manual prompt engineering, are subject to sub-optimal rationales that may harm performance. To mitigate this brittleness, we propose a unified framework of rationale-augmented ensembles, where we identify rationale sampling in the output space as the key component to robustly improve performance. This framework is general and can easily be extended to common natural language processing tasks, even those that do not traditionally leverage intermediate steps, such as question answering, word sense disambiguation, and sentiment analysis. We demonstrate that rationale-augmented ensembles achieve more accurate and interpretable results than existing prompting approaches--including standard prompting without rationales and rationale-based chain-of-thought prompting--while simultaneously improving interpretability of model predictions through the associated rationales.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2207.00747",is_oa:!0,n_refs:49,n_refs_in_core:4,degree:16,community:5,deg_w:107,betweenness:.0015,pagerank:.00307,eigenvector:.0096},{id:434,oaid:"563daeb9d787f63af90e2f6d26721dcd1048aeee",doi:"10.24963/ijcai.2020/688",title:"From Statistical Relational to Neuro-Symbolic Artificial Intelligence",authors:[{name:"L. D. Raedt",institutions:[]},{name:"Sebastijan Dumančić",institutions:[]},{name:"Robin Manhaeve",institutions:[]},{name:"Giuseppe Marra",institutions:[]}],authorString:"L. D. Raedt; Sebastijan Dumančić; Robin Manhaeve; Giuseppe Marra",institutions:[],countries:[],year:2020,journal:"International Joint Conference on Artificial Intelligence",citations:146,abstract:"Neuro-symbolic and statistical relational artificial intelligence both integrate frameworks for learning with logical reasoning. This survey identifies several parallels across seven different dimensions between these two fields. These cannot only be used to characterize and position neuro-symbolic artificial intelligence approaches but also to identify a number of directions for further research.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2020/0688.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:67e-5,eigenvector:0},{id:435,oaid:"c26770f29afafe22f2a507506e3f43c413f6a619",doi:null,title:"Learning Programs: A Hierarchical Bayesian Approach",authors:[{name:"P. Liang",institutions:[]},{name:"Michael I. Jordan",institutions:[]},{name:"D. Klein",institutions:[]}],authorString:"P. Liang; Michael I. Jordan; D. Klein",institutions:[],countries:[],year:2010,journal:"International Conference on Machine Learning",citations:145,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:7,deg_w:16.5,betweenness:.001,pagerank:.00111,eigenvector:0},{id:436,oaid:"c2d574f7c6a9e3bafe396ecb4ab639179d6fd92c",doi:"10.48550/arXiv.2205.10893",title:"Thor: Wielding Hammers to Integrate Language Models and Automated Theorem Provers",authors:[{name:"Albert Qiaochu Jiang",institutions:["University of Cambridge"]},{name:"Wenda Li",institutions:[]},{name:"Szymon Tworkowski",institutions:[]},{name:"K. Czechowski",institutions:[]},{name:"Tomasz Odrzyg'o'zd'z",institutions:[]},{name:"Piotr Milo's",institutions:[]},{name:"Yuhuai Wu",institutions:[]},{name:"M. Jamnik",institutions:[]}],authorString:"Albert Qiaochu Jiang; Wenda Li; Szymon Tworkowski; K. Czechowski; Tomasz Odrzyg'o'zd'z; Piotr Milo's; Yuhuai Wu; M. Jamnik",institutions:["University of Cambridge"],countries:[],year:2022,journal:"Neural Information Processing Systems",citations:144,abstract:"In theorem proving, the task of selecting useful premises from a large library to unlock the proof of a given conjecture is crucially important. This presents a challenge for all theorem provers, especially the ones based on language models, due to their relative inability to reason over huge volumes of premises in text form. This paper introduces Thor, a framework integrating language models and automated theorem provers to overcome this difficulty. In Thor, a class of methods called hammers that leverage the power of automated theorem provers are used for premise selection, while all other tasks are designated to language models. Thor increases a language model's success rate on the PISA dataset from $39\\%$ to $57\\%$, while solving $8.2\\%$ of problems neither language models nor automated theorem provers are able to solve on their own. Furthermore, with a significantly smaller computational budget, Thor can achieve a success rate on the MiniF2F dataset that is on par with the best existing methods. Thor can be instantiated for the majority of popular interactive theorem provers via a straightforward protocol we provide.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2205.10893",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:6,deg_w:8.5,betweenness:0,pagerank:5e-4,eigenvector:7e-4},{id:437,oaid:"e854977a9c4c2effc42f2e24064726fb6307b6f5",doi:"10.18653/v1/N18-1197",title:"Learning with Latent Language",authors:[{name:"Jacob Andreas",institutions:["MIT","Microsoft"]},{name:"D. Klein",institutions:[]},{name:"S. Levine",institutions:[]}],authorString:"Jacob Andreas; D. Klein; S. Levine",institutions:["MIT","Microsoft"],countries:[],year:2017,journal:"North American Chapter of the Association for Computational Linguistics",citations:141,abstract:"The named concepts and compositional operators present in natural language provide a rich source of information about the abstractions humans use to navigate the world. Can this linguistic background knowledge improve the generality and efficiency of learned classifiers and control policies? This paper aims to show that using the space of natural language strings as a parameter space is an effective way to capture natural task structure. In a pretraining phase, we learn a language interpretation model that transforms inputs (e.g. images) into outputs (e.g. labels) given natural language descriptions. To learn a new concept (e.g. a classifier), we search directly in the space of descriptions to minimize the interpreter’s loss on training examples. Crucially, our models do not require language data to learn these concepts: language is used only in pretraining to impose structure on subsequent learning. Results on image classification, text editing, and reinforcement learning show that, in all settings, models with a linguistic parameterization outperform those without.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/N18-1197.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:4,deg_w:17.5,betweenness:6e-4,pagerank:69e-5,eigenvector:4e-4},{id:438,oaid:"d1c42c33ab3382383c9cfc7cdec7b891fa38c5fb",doi:"10.1016/0196-6774(89)90031-X",title:"On-Line Bin Packing in Linear Time",authors:[{name:"Prakash V. Ramanan",institutions:[]},{name:"Donna J. Brown",institutions:[]},{name:"C. Lee",institutions:[]},{name:"D.T Lee",institutions:[]}],authorString:"Prakash V. Ramanan; Donna J. Brown; C. Lee; D.T Lee",institutions:[],countries:[],year:1989,journal:"J. Algorithms",citations:140,abstract:"",keywords:[],concepts:[],pdf_url:"https://www.ideals.illinois.edu/items/100054/bitstreams/319640/data.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:79e-5,eigenvector:0},{id:439,oaid:"8705455a11ba05178035d29aa234a05afdd28bb5",doi:"10.1007/s10994-013-5392-1",title:"Fast relational learning using bottom clause propositionalization with artificial neural networks",authors:[{name:"M. França",institutions:[]},{name:"Gerson Zaverucha",institutions:[]},{name:"A. Garcez",institutions:[]}],authorString:"M. França; Gerson Zaverucha; A. Garcez",institutions:[],countries:[],year:2013,journal:"Machine-mediated learning",citations:139,abstract:"",keywords:[],concepts:[],pdf_url:"https://link.springer.com/content/pdf/10.1007%2Fs10994-013-5392-1.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:58e-5,eigenvector:2e-4},{id:440,oaid:"399308fa54ade9b1362d56628132323489ce50cd",doi:"10.18653/v1/K19-1063",title:"Investigating Entity Knowledge in BERT with Simple Neural End-To-End Entity Linking",authors:[{name:"Samuel Broscheit",institutions:[]}],authorString:"Samuel Broscheit",institutions:[],countries:[],year:2019,journal:"Conference on Computational Natural Language Learning",citations:138,abstract:"A typical architecture for end-to-end entity linking systems consists of three steps: mention detection, candidate generation and entity disambiguation. In this study we investigate the following questions: (a) Can all those steps be learned jointly with a model for contextualized text-representations, i.e. BERT? (b) How much entity knowledge is already contained in pretrained BERT? (c) Does additional entity knowledge improve BERT’s performance in downstream tasks? To this end we propose an extreme simplification of the entity linking setup that works surprisingly well: simply cast it as a per token classification over the entire entity vocabulary (over 700K classes in our case). We show on an entity linking benchmark that (i) this model improves the entity representations over plain BERT, (ii) that it outperforms entity linking architectures that optimize the tasks separately and (iii) that it only comes second to the current state-of-the-art that does mention detection and entity disambiguation jointly. Additionally, we investigate the usefulness of entity-aware token-representations in the text-understanding benchmark GLUE, as well as the question answering benchmarks SQUAD~V2 and SWAG and also the EN-DE WMT14 machine translation benchmark. To our surprise, we find that most of those benchmarks do not benefit from additional entity knowledge, except for a task with very small training data, the RTE task in GLUE, which improves by 2%.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/K19-1063.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:1,deg_w:13,betweenness:0,pagerank:54e-5,eigenvector:.01},{id:441,oaid:"00f5bfc2fb760249ba4e9c72b72eea4574068339",doi:"10.1109/ICCV.2017.201",title:"VQS: Linking Segmentations to Questions and Answers for Supervised Attention in VQA and Question-Focused Semantic Segmentation",authors:[{name:"Chuang Gan",institutions:[]},{name:"Yandong Li",institutions:[]},{name:"Haoxiang Li",institutions:[]},{name:"Chen Sun",institutions:[]},{name:"Boqing Gong",institutions:[]}],authorString:"Chuang Gan; Yandong Li; Haoxiang Li; Chen Sun; Boqing Gong",institutions:[],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:138,abstract:"Rich and dense human labeled datasets are among the main enabling factors for the recent advance on visionlanguage understanding. Many seemingly distant annotations (e.g., semantic segmentation and visual question answering (VQA)) are inherently connected in that they reveal different levels and perspectives of human understandings about the same visual scenes — and even the same set of images (e.g., of COCO). The popularity of COCO correlates those annotations and tasks. Explicitly linking them up may significantly benefit both individual tasks and the unified vision and language modeling.,,We present the preliminary work of linking the instance segmentations provided by COCO to the questions and answers (QAs) in the VQA dataset, and name the collected links visual questions and segmentation answers (VQS). They transfer human supervision between the previously separate tasks, offer more effective leverage to existing problems, and also open the door for new research problems and models. We study two applications of the VQS data in this paper: supervised attention for VQA and a novel question-focused semantic segmentation task. For the former, we obtain state-of-the-art results on the VQA real multiple-choice task by simply augmenting the multilayer perceptrons with some attention features that are learned using the segmentation-QA links as explicit supervision. To put the latter in perspective, we study two plausible methods and compare them to an oracle method assuming that the instance segmentations are given at the test stage.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1708.04686",is_oa:!0,n_refs:52,n_refs_in_core:7,degree:23,community:3,deg_w:266.5,betweenness:5e-4,pagerank:.00521,eigenvector:.0023},{id:442,oaid:"7c0ade464620ed604ff58d9ad64bcfa1bc37a86f",doi:"10.1016/0004-3702(90)90002-H",title:"Preface to the Special Issue on Connectionist Symbol Processing",authors:[{name:"Geoffrey E. Hinton",institutions:[]}],authorString:"Geoffrey E. Hinton",institutions:[],countries:[],year:1990,journal:"",citations:136,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:65e-5,eigenvector:0},{id:443,oaid:"c03dfb9f47b512b87a407f5bccdd250eb2d52138",doi:"10.1145/2866568",title:"Learning executable semantic parsers for natural language understanding",authors:[{name:"Percy Liang",institutions:[]}],authorString:"Percy Liang",institutions:[],countries:[],year:2016,journal:"Communications of the ACM",citations:135,abstract:"Semantic parsing is a rich fusion of the logical and the statistical worlds.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://arxiv.org/pdf/1603.06677",is_oa:!0,n_refs:40,n_refs_in_core:6,degree:17,community:5,deg_w:91.5,betweenness:.0047,pagerank:.00273,eigenvector:.0013},{id:444,oaid:"2d08cdc45bbed8cea283d92132b4b88a507a7303",doi:null,title:"Neural Module Networks for Reasoning over Text",authors:[{name:"Nitish Gupta",institutions:["Google"]},{name:"Kevin Lin",institutions:[]},{name:"Dan Roth",institutions:["University of Pennsylvania, Oracle"]},{name:"Sameer Singh",institutions:["University of California, Irvine","Envive AI (fka Spiffy AI)"]},{name:"Matt Gardner",institutions:["Allen Institute for Artificial Intelligence"]}],authorString:"Nitish Gupta; Kevin Lin; Dan Roth; Sameer Singh; Matt Gardner",institutions:["Allen Institute for Artificial Intelligence","Envive AI (fka Spiffy AI)","Google","University of California, Irvine","University of Pennsylvania, Oracle"],countries:[],year:2019,journal:"International Conference on Learning Representations",citations:134,abstract:"Answering compositional questions that require multiple steps of reasoning against text is challenging, especially when they involve discrete, symbolic operations. Neural module networks (NMNs) learn to parse such questions as executable programs composed of learnable modules, performing well on synthetic visual QA domains. However, we find that it is challenging to learn these models for non-synthetic questions on open-domain text, where a model needs to deal with the diversity of natural language and perform a broader range of reasoning. We extend NMNs by: (a) introducing modules that reason over a paragraph of text, performing symbolic reasoning (such as arithmetic, sorting, counting) over numbers and dates in a probabilistic and differentiable manner; and (b) proposing an unsupervised auxiliary loss to help extract arguments associated with the events in text. Additionally, we show that a limited amount of heuristically-obtained question program and intermediate module output supervision provides sufficient inductive bias for accurate learning. Our proposed model significantly outperforms state-of-the-art models on a subset of the DROP dataset that poses a variety of reasoning challenges that are covered by our modules.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:5,deg_w:17.5,betweenness:8e-4,pagerank:81e-5,eigenvector:.0017},{id:445,oaid:"3a8129e6fe3ad9bc3a51e44da32424e38612e4cc",doi:null,title:"TensorLog: A Differentiable Deductive Database",authors:[{name:"William W. Cohen",institutions:["Google"]}],authorString:"William W. Cohen",institutions:["Google"],countries:[],year:2016,journal:"arXiv.org",citations:133,abstract:'Large knowledge bases (KBs) are useful in many tasks, but it is unclear how to integrate this sort of knowledge into "deep" gradient-based learning systems. To address this problem, we describe a probabilistic deductive database, called TensorLog, in which reasoning uses a differentiable process. In TensorLog, each clause in a logical theory is first converted into certain type of factor graph. Then, for each type of query to the factor graph, the message-passing steps required to perform belief propagation (BP) are "unrolled" into a function, which is differentiable. We show that these functions can be composed recursively to perform inference in non-trivial logical theories containing multiple interrelated clauses and predicates. Both compilation and inference in TensorLog are efficient: compilation is linear in theory size and proof depth, and inference is linear in database size and the number of message-passing steps used in BP. We also present experimental results with TensorLog and discuss its relationship to other first-order probabilistic logics.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:18,n_refs_in_core:6,degree:11,community:0,deg_w:52,betweenness:.0028,pagerank:.00234,eigenvector:6e-4},{id:446,oaid:"554eade16fb6040bbd21a72bacf903245d7458f1",doi:"10.1609/aaai.v35i17.17765",title:"Thinking Fast and Slow in AI",authors:[{name:"G. Booch",institutions:[]},{name:"F. Fabiano",institutions:[]},{name:"L. Horesh",institutions:[]},{name:"K. Kate",institutions:[]},{name:"J. Lenchner",institutions:[]},{name:"Nick Linck",institutions:[]},{name:"Andrea Loreggia",institutions:["University of Brescia"]},{name:"K. Murugesan",institutions:[]},{name:"Nicholas Mattei",institutions:[]},{name:"F. Rossi",institutions:[]},{name:"Biplav Srivastava",institutions:[]}],authorString:"G. Booch; F. Fabiano; L. Horesh; K. Kate; J. Lenchner; Nick Linck; Andrea Loreggia; K. Murugesan; Nicholas Mattei; F. Rossi; Biplav Srivastava",institutions:["University of Brescia"],countries:[],year:2020,journal:"AAAI Conference on Artificial Intelligence",citations:133,abstract:"This paper proposes a research direction to advance AI which draws inspiration from cognitive theories of human decision making. The premise is that if we gain insights about the causes of some human capabilities that are still lacking in AI (for instance, adaptability, generalizability, common sense, and causal reasoning), we may obtain similar capabilities in an AI system by embedding these causal components. We hope that the high-level description of our vision included in this paper, as well as the several research questions that we propose to consider, can stimulate the AI research community to define, try and evaluate new methodologies, frameworks, and evaluation metrics, in the spirit of achieving a better understanding of both human and machine intelligence.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/17765/17572",is_oa:!0,n_refs:25,n_refs_in_core:3,degree:4,community:2,deg_w:18,betweenness:.0062,pagerank:.00155,eigenvector:1e-4},{id:447,oaid:"752a4929b7c2be024aed3d7281603491f6808014",doi:"10.1007/BF01064262",title:"Scientific discovery as problem solving",authors:[{name:"H. Simon",institutions:[]},{name:"P. Langley",institutions:[]},{name:"Gary L. Bradshaw",institutions:[]}],authorString:"H. Simon; P. Langley; Gary L. Bradshaw",institutions:[],countries:[],year:1981,journal:"Synthese",citations:132,abstract:"",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:448,oaid:"b99c61f6957c1b04ec1376b74f82dd1e83559695",doi:"10.18653/v1/2021.findings-acl.223",title:"JointGT: Graph-Text Joint Representation Learning for Text Generation from Knowledge Graphs",authors:[{name:"Pei Ke",institutions:[]},{name:"Haozhe Ji",institutions:[]},{name:"Yu Ran",institutions:[]},{name:"Xin Cui",institutions:[]},{name:"Liwei Wang",institutions:[]},{name:"Linfeng Song",institutions:[]},{name:"Xiaoyan Zhu",institutions:[]},{name:"Minlie Huang",institutions:["Tsinghua University"]}],authorString:"Pei Ke; Haozhe Ji; Yu Ran; Xin Cui; Liwei Wang; Linfeng Song; Xiaoyan Zhu; Minlie Huang",institutions:["Tsinghua University"],countries:[],year:2021,journal:"Findings",citations:130,abstract:"Existing pre-trained models for knowledge-graph-to-text (KG-to-text) generation simply fine-tune text-to-text pre-trained models such as BART or T5 on KG-to-text datasets, which largely ignore the graph structure during encoding and lack elaborate pre-training tasks to explicitly model graph-text alignments. To tackle these problems, we propose a graph-text joint representation learning model called JointGT. During encoding, we devise a structure-aware semantic aggregation module which is plugged into each Transformer layer to preserve the graph structure. Furthermore, we propose three new pre-training tasks to explicitly enhance the graph-text alignment including respective text / graph reconstruction, and graph-text alignment in the embedding space via Optimal Transport. Experiments show that JointGT obtains new state-of-the-art performance on various KG-to-text datasets.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.findings-acl.223.pdf",is_oa:!0,n_refs:50,n_refs_in_core:9,degree:25,community:1,deg_w:213,betweenness:.0018,pagerank:.00474,eigenvector:.1475},{id:449,oaid:"4b2137280915ccc0e06e97b604778b05876a34ad",doi:null,title:"Evaluating Large Language Models",authors:[{name:"February Friday",institutions:[]}],authorString:"February Friday",institutions:[],countries:[],year:2022,journal:"",citations:130,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:53e-5,eigenvector:2e-4},{id:450,oaid:"a58b3f2ab75fdbda082e684d027ab4f552b0b5d3",doi:"10.48550/arXiv.2204.05186",title:"Correcting Robot Plans with Natural Language Feedback",authors:[{name:"Pratyusha Sharma",institutions:["MIT"]},{name:"Balakumar Sundaralingam",institutions:[]},{name:"Valts Blukis",institutions:[]},{name:"Chris Paxton",institutions:[]},{name:"Tucker Hermans",institutions:["University of Utah","NVIDIA"]},{name:"A. Torralba",institutions:[]},{name:"Jacob Andreas",institutions:["MIT","Microsoft"]},{name:"D. Fox",institutions:[]}],authorString:"Pratyusha Sharma; Balakumar Sundaralingam; Valts Blukis; Chris Paxton; Tucker Hermans; A. Torralba; Jacob Andreas; D. Fox",institutions:["MIT","Microsoft","NVIDIA","University of Utah"],countries:[],year:2022,journal:"Robotics: Science and Systems Conference",citations:129,abstract:"When humans design cost or goal specifications for robots, they often produce specifications that are ambiguous, underspecified, or beyond planners' ability to solve. In these cases, corrections provide a valuable tool for human-in-the-loop robot control. Corrections might take the form of new goal specifications, new constraints (e.g. to avoid specific objects), or hints for planning algorithms (e.g. to visit specific waypoints). Existing correction methods (e.g. using a joystick or direct manipulation of an end effector) require full teleoperation or real-time interaction. In this paper, we explore natural language as an expressive and flexible tool for robot correction. We describe how to map from natural language sentences to transformations of cost functions. We show that these transformations enable users to correct goals, update robot motions to accommodate additional user preferences, and recover from planning errors. These corrections can be leveraged to get 81% and 93% success rates on tasks where the original planner failed, with either one or two language corrections. Our method makes it possible to compose multiple constraints and generalizes to unseen scenes, objects, and sentences in simulated environments and real-world environments.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2204.05186",is_oa:!0,n_refs:44,n_refs_in_core:4,degree:11,community:4,deg_w:61,betweenness:2e-4,pagerank:.00181,eigenvector:8e-4},{id:451,oaid:"ed62a56b81511d7fcf6d247014987163d9668982",doi:"10.1007/978-3-319-46493-0_17",title:'"What Happens If..." Learning to Predict the Effect of Forces in Images',authors:[{name:"Roozbeh Mottaghi",institutions:[]},{name:"Mohammad Rastegari",institutions:[]},{name:"A. Gupta",institutions:[]},{name:"Ali Farhadi",institutions:[]}],authorString:"Roozbeh Mottaghi; Mohammad Rastegari; A. Gupta; Ali Farhadi",institutions:[],countries:[],year:2016,journal:"European Conference on Computer Vision",citations:129,abstract:"What happens if one pushes a cup sitting on a table toward the edge of the table? How about pushing a desk against a wall? In this paper, we study the problem of understanding the movements of objects as a result of applying external forces to them. For a given force vector applied to a specific location in an image, our goal is to predict long-term sequential movements caused by that force. Doing so entails reasoning about scene geometry, objects, their attributes, and the physical rules that govern the movements of objects. We design a deep neural network model that learns long-term sequential dependencies of object movements while taking into account the geometry and appearance of the scene by combining Convolutional and Recurrent Neural Networks. Training our model requires a large-scale dataset of object movements caused by external forces. To build a dataset of forces in scenes, we reconstructed all images in SUN RGB-D dataset in a physics simulator to estimate the physical movements of objects caused by external forces applied to them. Our Forces in Scenes (ForScene) dataset contains 65,000 object movements in 3D which represent a variety of external forces applied to different types of objects. Our experimental evaluations show that the challenging task of predicting long-term movements of objects as their reaction to external forces is possible from a single image. The code and dataset are available at: http://allenai.org/plato/forces.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1603.05600",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:7,community:2,deg_w:27,betweenness:1e-4,pagerank:99e-5,eigenvector:1e-4},{id:452,oaid:"87c425f23bcac2f082968abda64a971f91522f73",doi:null,title:"GamePad: A Learning Environment for Theorem Proving",authors:[{name:"Daniel Huang",institutions:[]},{name:"Prafulla Dhariwal",institutions:[]},{name:"D. Song",institutions:[]},{name:"I. Sutskever",institutions:[]}],authorString:"Daniel Huang; Prafulla Dhariwal; D. Song; I. Sutskever",institutions:[],countries:[],year:2018,journal:"International Conference on Learning Representations",citations:127,abstract:"In this paper, we introduce a system called GamePad that can be used to explore the application of machine learning methods to theorem proving in the Coq proof assistant. Interactive theorem provers such as Coq enable users to construct machine-checkable proofs in a step-by-step manner. Hence, they provide an opportunity to explore theorem proving with human supervision. We use GamePad to synthesize proofs for a simple algebraic rewrite problem and train baseline models for a formalization of the Feit-Thompson theorem. We address position evaluation (i.e., predict the number of proof steps left) and tactic prediction (i.e., predict the next proof step) tasks, which arise naturally in tactic-based theorem proving.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:4,n_refs_in_core:1,degree:13,community:6,deg_w:57.5,betweenness:3e-4,pagerank:.00177,eigenvector:.0023},{id:453,oaid:"8d88bd8cc542cbb64aa17c4f9f6cd74e20ffa776",doi:"10.1109/CEC.2009.4983077",title:"Overcoming the bootstrap problem in evolutionary robotics using behavioral diversity",authors:[{name:"Jean-Baptiste Mouret",institutions:["Inria"]},{name:"S. Doncieux",institutions:[]}],authorString:"Jean-Baptiste Mouret; S. Doncieux",institutions:["Inria"],countries:[],year:2009,journal:"IEEE Congress on Evolutionary Computation",citations:127,abstract:"",keywords:[],concepts:[],pdf_url:"https://hal.archives-ouvertes.fr/hal-00473147/file/mouret.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:86e-5,eigenvector:0},{id:454,oaid:"401dfc5efbd182eaef6945249aea8a0a1e3cced5",doi:null,title:"Shaping Belief States with Generative Environment Models for RL",authors:[{name:"Karol Gregor",institutions:[]},{name:"Danilo Jimenez Rezende",institutions:["Google DeepMind"]},{name:"F. Besse",institutions:[]},{name:"Yan Wu",institutions:[]},{name:"Hamza Merzic",institutions:[]},{name:"Aäron van den Oord",institutions:[]}],authorString:"Karol Gregor; Danilo Jimenez Rezende; F. Besse; Yan Wu; Hamza Merzic; Aäron van den Oord",institutions:["Google DeepMind"],countries:[],year:2019,journal:"Neural Information Processing Systems",citations:125,abstract:"When agents interact with a complex environment, they must form and maintain beliefs about the relevant aspects of that environment. We propose a way to efficiently train expressive generative models in complex environments. We show that a predictive algorithm with an expressive generative model can form stable belief-states in visually rich and dynamic 3D environments. More precisely, we show that the learned representation captures the layout of the environment as well as the position and orientation of the agent. Our experiments show that the model substantially improves data-efficiency on a number of reinforcement learning (RL) tasks compared with strong model-free baseline agents. We find that predicting multiple steps into the future (overshooting), in combination with an expressive generative model, is critical for stable representations to emerge. In practice, using expressive generative models in RL is computationally expensive and we propose a scheme to reduce this computational burden, allowing us to build agents that are competitive with model-free baselines.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:61e-5,eigenvector:0},{id:455,oaid:"d3e13d2514edaf74b863bfbe45a739c32a7689e1",doi:"10.18653/v1/D18-1111",title:"Retrieval-Based Neural Code Generation",authors:[{name:"Shirley Anugrah Hayati",institutions:[]},{name:"R. Olivier",institutions:[]},{name:"Pravalika Avvaru",institutions:[]},{name:"Pengcheng Yin",institutions:[]},{name:"A. Tomasic",institutions:[]},{name:"Graham Neubig",institutions:[]}],authorString:"Shirley Anugrah Hayati; R. Olivier; Pravalika Avvaru; Pengcheng Yin; A. Tomasic; Graham Neubig",institutions:[],countries:[],year:2018,journal:"Conference on Empirical Methods in Natural Language Processing",citations:122,abstract:"In models to generate program source code from natural language, representing this code in a tree structure has been a common approach. However, existing methods often fail to generate complex code correctly due to a lack of ability to memorize large and complex structures. We introduce RECODE, a method based on subtree retrieval that makes it possible to explicitly reference existing code examples within a neural code generation model. First, we retrieve sentences that are similar to input sentences using a dynamic-programming-based sentence similarity scoring method. Next, we extract n-grams of action sequences that build the associated abstract syntax tree. Finally, we increase the probability of actions that cause the retrieved n-gram action subtree to be in the predicted code. We show that our approach improves the performance on two code generation tasks by up to +2.6 BLEU.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D18-1111.pdf",is_oa:!0,n_refs:20,n_refs_in_core:1,degree:3,community:5,deg_w:13.5,betweenness:.001,pagerank:59e-5,eigenvector:.0011},{id:456,oaid:"7e8457393ff1b40ddd099f195af9d3b14c5a934f",doi:"10.18653/v1/2020.emnlp-main.54",title:"Language Generation with Multi-hop Reasoning on Commonsense Knowledge Graph",authors:[{name:"Haozhe Ji",institutions:[]},{name:"Pei Ke",institutions:[]},{name:"Shaohan Huang",institutions:[]},{name:"Furu Wei",institutions:["Microsoft Research"]},{name:"Xiaoyan Zhu",institutions:[]},{name:"Minlie Huang",institutions:["Tsinghua University"]}],authorString:"Haozhe Ji; Pei Ke; Shaohan Huang; Furu Wei; Xiaoyan Zhu; Minlie Huang",institutions:["Microsoft Research","Tsinghua University"],countries:[],year:2020,journal:"Conference on Empirical Methods in Natural Language Processing",citations:120,abstract:"Despite the success of generative pre-trained language models on a series of text generation tasks, they still suffer in cases where reasoning over underlying commonsense knowledge is required during generation. Existing approaches that integrate commonsense knowledge into generative pre-trained language models simply transfer relational knowledge by post-training on individual knowledge triples while ignoring rich connections within the knowledge graph. We argue that exploiting both the structural and semantic information of the knowledge graph facilitates commonsense-aware text generation. In this paper, we propose Generation with Multi-Hop Reasoning Flow (GRF) that enables pre-trained models with dynamic multi-hop reasoning on multi-relational paths extracted from the external commonsense knowledge graph. We empirically show that our model outperforms existing baselines on three text generation tasks that require reasoning over commonsense knowledge. We also demonstrate the effectiveness of the dynamic multi-hop reasoning module with reasoning paths inferred by the model that provide rationale to the generation.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.emnlp-main.54.pdf",is_oa:!0,n_refs:40,n_refs_in_core:3,degree:17,community:1,deg_w:122,betweenness:.0011,pagerank:.00288,eigenvector:.0722},{id:457,oaid:"e3a9af420cd2c0c8241856da92374027fefb87be",doi:"10.48550/arXiv.2207.10342",title:"Language Model Cascades",authors:[{name:"David Dohan",institutions:["Google Brain"]},{name:"Winnie Xu",institutions:[]},{name:"Aitor Lewkowycz",institutions:[]},{name:"Jacob Austin",institutions:[]},{name:"David Bieber",institutions:["Google"]},{name:"Raphael Gontijo Lopes",institutions:[]},{name:"Yuhuai Wu",institutions:[]},{name:"H. Michalewski",institutions:[]},{name:"R. Saurous",institutions:[]},{name:"Jascha Narain Sohl-Dickstein",institutions:["Anthropic"]},{name:"Kevin Murphy",institutions:[]},{name:"Charles Sutton",institutions:[]}],authorString:"David Dohan; Winnie Xu; Aitor Lewkowycz; Jacob Austin; David Bieber; Raphael Gontijo Lopes; Yuhuai Wu; H. Michalewski; R. Saurous; Jascha Narain Sohl-Dickstein; Kevin Murphy; Charles Sutton",institutions:["Anthropic","Google","Google Brain"],countries:[],year:2022,journal:"arXiv.org",citations:120,abstract:"Prompted models have demonstrated impressive few-shot learning abilities. Repeated interactions at test-time with a single model, or the composition of multiple models together, further expands capabilities. These compositions are probabilistic models, and may be expressed in the language of graphical models with random variables whose values are complex data types such as strings. Cases with control flow and dynamic structure require techniques from probabilistic programming, which allow implementing disparate model structures and inference strategies in a unified language. We formalize several existing techniques from this perspective, including scratchpads / chain of thought, verifiers, STaR, selection-inference, and tool use. We refer to the resulting programs as language model cascades.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/2207.10342",is_oa:!0,n_refs:25,n_refs_in_core:4,degree:10,community:5,deg_w:56.5,betweenness:.002,pagerank:.00183,eigenvector:.0026},{id:458,oaid:"974d1048fa45227a3ef9f71efe5501f79683dfdf",doi:"10.18653/v1/d13-1080",title:"Improving Learning and Inference in a Large Knowledge-Base using Latent Syntactic Cues",authors:[{name:"Matt Gardner",institutions:["Allen Institute for Artificial Intelligence"]},{name:"P. Talukdar",institutions:[]},{name:"B. Kisiel",institutions:[]},{name:"Tom Michael Mitchell",institutions:[]}],authorString:"Matt Gardner; P. Talukdar; B. Kisiel; Tom Michael Mitchell",institutions:["Allen Institute for Artificial Intelligence"],countries:[],year:2013,journal:"Conference on Empirical Methods in Natural Language Processing",citations:118,abstract:"Automatically constructed Knowledge Bases (KBs) are often incomplete and there is a genuine need to improve their coverage. Path Ranking Algorithm (PRA) is a recently proposed method which aims to improve KB coverage by performing inference directly over the KB graph. For the first time, we demonstrate that addition of edges labeled with latent features mined from a large dependency parsed corpus of 500 million Web documents can significantly outperform previous PRAbased approaches on the KB inference task. We present extensive experimental results validating this finding. The resources presented in this paper are publicly available.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/D13-1080.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:8,community:0,deg_w:31.5,betweenness:0,pagerank:.00111,eigenvector:.0017},{id:459,oaid:"4b127897595af5a97c83860eec0540de5510f646",doi:"10.1609/AAAI.V34I03.5689",title:"Graph Representations for Higher-Order Logic and Theorem Proving",authors:[{name:"Aditya Sanjay Paliwal",institutions:["Google"]},{name:"Sarah M. Loos",institutions:[]},{name:"M. Rabe",institutions:[]},{name:"Kshitij Bansal",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"Aditya Sanjay Paliwal; Sarah M. Loos; M. Rabe; Kshitij Bansal; Christian Szegedy",institutions:["Google"],countries:[],year:2019,journal:"AAAI Conference on Artificial Intelligence",citations:116,abstract:"This paper presents the first use of graph neural networks (GNNs) for higher-order proof search and demonstrates that GNNs can improve upon state-of-the-art results in this domain. Interactive, higher-order theorem provers allow for the formalization of most mathematical theories and have been shown to pose a significant challenge for deep learning. Higher-order logic is highly expressive and, even though it is well-structured with a clearly defined grammar and semantics, there still remains no well-established method to convert formulas into graph-based representations. In this paper, we consider several graphical representations of higher-order logic and evaluate them against the HOList benchmark for higher-order theorem proving.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/5689/5545",is_oa:!0,n_refs:34,n_refs_in_core:6,degree:17,community:6,deg_w:113.5,betweenness:.0123,pagerank:.00345,eigenvector:.0047},{id:460,oaid:"b586d050caa00a827fd2b318742dc80a304a3675",doi:null,title:"Artificial Intelligence : A General Survey",authors:[{name:"S. Sutherland",institutions:[]},{name:"R. Needham",institutions:[]}],authorString:"S. Sutherland; R. Needham",institutions:[],countries:[],year:2012,journal:"",citations:114,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:1e-4,pagerank:63e-5,eigenvector:0},{id:461,oaid:"00672bec9dd0e755f9c375f912c0f1c3918a6b74",doi:"10.1109/ICCV.2017.312",title:"MarioQA: Answering Questions by Watching Gameplay Videos",authors:[{name:"Jonghwan Mun",institutions:[]},{name:"P. H. Seo",institutions:[]},{name:"Ilchae Jung",institutions:[]},{name:"Bohyung Han",institutions:[]}],authorString:"Jonghwan Mun; P. H. Seo; Ilchae Jung; Bohyung Han",institutions:[],countries:[],year:2016,journal:"IEEE International Conference on Computer Vision",citations:114,abstract:"We present a framework to analyze various aspects of models for video question answering (VideoQA) using customizable synthetic datasets, which are constructed automatically from gameplay videos. Our work is motivated by the fact that existing models are often tested only on datasets that require excessively high-level reasoning or mostly contain instances accessible through single frame inferences. Hence, it is difficult to measure capacity and flexibility of trained models, and existing techniques often rely on adhoc implementations of deep neural networks without clear insight into datasets and models. We are particularly interested in understanding temporal relationships between video events to solve VideoQA problems; this is because reasoning temporal dependency is one of the most distinct components in videos from images. To address this objective, we automatically generate a customized synthetic VideoQA dataset using Super Mario Bros. gameplay videos so that it contains events with different levels of reasoning complexity. Using the dataset, we show that properly constructed datasets with events in various complexity levels are critical to learn effective models and improve overall performance.",keywords:[],concepts:[],pdf_url:"http://arxiv.org/pdf/1612.01669",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:1e-4},{id:462,oaid:"db65116039a64847b1510de47f8092e29c77958b",doi:"10.1561/2500000049",title:"Neurosymbolic Programming",authors:[{name:"Swarat Chaudhuri",institutions:[]},{name:"Kevin Ellis",institutions:[]},{name:"Oleksandr Polozov",institutions:[]},{name:"Rishabh Singh",institutions:[]},{name:"Armando Solar-Lezama",institutions:[]},{name:"Yisong Yue",institutions:[]}],authorString:"Swarat Chaudhuri; Kevin Ellis; Oleksandr Polozov; Rishabh Singh; Armando Solar-Lezama; Yisong Yue",institutions:[],countries:[],year:2021,journal:"Found. Trends Program. Lang.",citations:113,abstract:"We survey recent work on neurosymbolic programming, an emerging area that bridges the areas of deep learning and program synthesis. Like in classic machine learning, the goal here is to learn functions from data. However, these functions are represented as programs that can use neural modules in addition to symbolic primitives and are induced using a combination of symbolic search and gradient-based optimization. Neurosymbolic programming can offer multiple advantages over end-to-end deep learning. Programs can sometimes naturally represent long-horizon, procedural tasks that are difficult to perform using deep networks. Neurosymbolic representations are also, commonly, easier to interpret and formally verify than neural networks. The restrictions of a programming language can serve as a form of regularization and lead to more generalizable and data-efficient Swarat Chaudhuri, Kevin Ellis, Oleksandr Polozov, Rishabh Singh, Armando SolarLezama and Yisong Yue (2021), “Neurosymbolic Programming”, Foundations and Trends® in Programming Languages: Vol. 7, No. 3, pp 158–243. DOI: 10.1561/2500000049. ©2021 S. Chaudhuri et al. The version of record is available at: http://dx.doi.org/10.1561/2500000049",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1561/2500000049",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:59e-5,eigenvector:1e-4},{id:463,oaid:"5823d18cd378898b12de537862d996443ce9c9e8",doi:"10.1109/ICCV.2017.145",title:"Structured Attentions for Visual Question Answering",authors:[{name:"Chen Zhu",institutions:[]},{name:"Yanpeng Zhao",institutions:["NA"]},{name:"Shuaiyi Huang",institutions:[]},{name:"Kewei Tu",institutions:[]},{name:"Yi Ma",institutions:[]}],authorString:"Chen Zhu; Yanpeng Zhao; Shuaiyi Huang; Kewei Tu; Yi Ma",institutions:["NA"],countries:[],year:2017,journal:"IEEE International Conference on Computer Vision",citations:112,abstract:"Visual attention, which assigns weights to image regions according to their relevance to a question, is considered as an indispensable part by most Visual Question Answering models. Although the questions may involve complex rela- tions among multiple regions, few attention models can ef- fectively encode such cross-region relations. In this paper, we demonstrate the importance of encoding such relations by showing the limited effective receptive field of ResNet on two datasets, and propose to model the visual attention as a multivariate distribution over a grid-structured Con- ditional Random Field on image regions. We demonstrate how to convert the iterative inference algorithms, Mean Field and Loopy Belief Propagation, as recurrent layers of an end-to-end neural network. We empirically evalu- ated our model on 3 datasets, in which it surpasses the best baseline model of the newly released CLEVR dataset [13] by 9.5%, and the best published model on the VQA dataset [3] by 1.25%. Source code is available at https://github.com/zhuchen03/vqa-sva.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1708.02071",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:12.5,betweenness:0,pagerank:54e-5,eigenvector:1e-4},{id:464,oaid:"941632c7941a52b9eea9b24952b35363824d6e37",doi:"10.1109/icra46639.2022.9811931",title:"StructFormer: Learning Spatial Structure for Language-Guided Semantic Rearrangement of Novel Objects",authors:[{name:"Weiyu Liu",institutions:[]},{name:"Chris Paxton",institutions:[]},{name:"Tucker Hermans",institutions:["University of Utah","NVIDIA"]},{name:"D. Fox",institutions:[]}],authorString:"Weiyu Liu; Chris Paxton; Tucker Hermans; D. Fox",institutions:["NVIDIA","University of Utah"],countries:[],year:2021,journal:"IEEE International Conference on Robotics and Automation",citations:112,abstract:"Geometric organization of objects into semantically meaningful arrangements pervades the built world. As such, assistive robots operating in warehouses, offices, and homes would greatly benefit from the ability to recognize and rearrange objects into these semantically meaningful structures. To be useful, these robots must contend with previously unseen objects and receive instructions without significant programming. While previous works have examined recognizing pairwise semantic relations and sequential manipulation to change these simple relations none have shown the ability to arrange objects into complex structures such as circles or table settings. To address this problem we propose a novel transformer-based neural network, StructFormer, which takes as input a partial-view point cloud of the current object arrangement and a structured language command encoding the desired object configuration. We show through rigorous experiments that StructFormer enables a physical robot to rearrange novel objects into semantically meaningful structures with multi-object relational constraints inferred from the language command.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2110.10189",is_oa:!0,n_refs:61,n_refs_in_core:7,degree:13,community:4,deg_w:86,betweenness:.0038,pagerank:.00248,eigenvector:.0019},{id:465,oaid:"d6b2a12446c6d87c92003de928118d094869a92f",doi:"10.24963/ijcai.2020/267",title:"Reasoning Like Human: Hierarchical Reinforcement Learning for Knowledge Graph Reasoning",authors:[{name:"Guojia Wan",institutions:[]},{name:"Shirui Pan",institutions:["Monash University"]},{name:"Chen Gong",institutions:[]},{name:"Chuan Zhou",institutions:["Academy of Mathematics and Systems Science, Chinese Academy of Sciences"]},{name:"Gholamreza Haffari",institutions:[]}],authorString:"Guojia Wan; Shirui Pan; Chen Gong; Chuan Zhou; Gholamreza Haffari",institutions:["Academy of Mathematics and Systems Science, Chinese Academy of Sciences","Monash University"],countries:[],year:2020,journal:"International Joint Conference on Artificial Intelligence",citations:110,abstract:"Knowledge Graphs typically suffer from incompleteness. A popular approach to knowledge graph completion is to infer missing knowledge by multihop reasoning over the information found along other paths connecting a pair of entities. However, multi-hop reasoning is still challenging because the reasoning process usually experiences multiple semantic issue that a relation or an entity has multiple meanings. In order to deal with the situation, we propose a novel Hierarchical Reinforcement Learning framework to learn chains of reasoning from a Knowledge Graph automatically. Our framework is inspired by the hierarchical structure through which human handle cognitionally ambiguous cases. The whole reasoning process is decomposed into a hierarchy of two-level Reinforcement Learning policies for encoding historical information and learning structured action space. As a consequence, it is more feasible and natural for dealing with the multiple semantic issue. Experimental results show that our proposed model achieves substantial improvements in ambiguous relation tasks.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2020/0267.pdf",is_oa:!0,n_refs:32,n_refs_in_core:4,degree:14,community:0,deg_w:58.5,betweenness:.0101,pagerank:.00208,eigenvector:.0119},{id:466,oaid:"b9a5aa5db8836744ff2073e8368520b7a614049f",doi:null,title:"Neural Symbolic Reader: Scalable Integration of Distributed and Symbolic Representations for Reading Comprehension",authors:[{name:"Xinyun Chen",institutions:[]},{name:"Chen Liang",institutions:["Google Brain"]},{name:"Adams Wei Yu",institutions:[]},{name:"Denny Zhou",institutions:[]},{name:"D. Song",institutions:[]},{name:"Quoc V. Le",institutions:[]}],authorString:"Xinyun Chen; Chen Liang; Adams Wei Yu; Denny Zhou; D. Song; Quoc V. Le",institutions:["Google Brain"],countries:[],year:2020,journal:"International Conference on Learning Representations",citations:109,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:6,community:5,deg_w:25.5,betweenness:4e-4,pagerank:94e-5,eigenvector:.0027},{id:467,oaid:"2163dbd2c06f0aa326995b59c226e40553c4c63b",doi:"10.18653/v1/P19-1618",title:"NLProlog: Reasoning with Weak Unification for Question Answering in Natural Language",authors:[{name:"Leon Weber",institutions:["Humboldt-Universität zu Berlin","MDC Berlin"]},{name:"Pasquale Minervini",institutions:[]},{name:"Jannes Munchmeyer",institutions:[]},{name:"U. Leser",institutions:[]},{name:"Tim Rocktäschel",institutions:[]}],authorString:"Leon Weber; Pasquale Minervini; Jannes Munchmeyer; U. Leser; Tim Rocktäschel",institutions:["Humboldt-Universität zu Berlin","MDC Berlin"],countries:[],year:2019,journal:"Annual Meeting of the Association for Computational Linguistics",citations:107,abstract:"Rule-based models are attractive for various tasks because they inherently lead to interpretable and explainable decisions and can easily incorporate prior knowledge. However, such systems are difficult to apply to problems involving natural language, due to its large linguistic variability. In contrast, neural models can cope very well with ambiguity by learning distributed representations of words and their composition from data, but lead to models that are difficult to interpret. In this paper, we describe a model combining neural networks with logic programming in a novel manner for solving multi-hop reasoning tasks over natural language. Specifically, we propose to use an Prolog prover which we extend to utilize a similarity function over pretrained sentence encoders. We fine-tune the representations for the similarity function via backpropagation. This leads to a system that can apply rule-based reasoning to natural language, and induce domain-specific natural language rules from training data. We evaluate the proposed system on two different question answering tasks, showing that it outperforms two baselines – BiDAF (Seo et al., 2016a) and FastQA( Weissenborn et al., 2017) on a subset of the WikiHop corpus and achieves competitive results on the MedHop data set (Welbl et al., 2017).",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.aclweb.org/anthology/P19-1618.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:13,betweenness:0,pagerank:76e-5,eigenvector:1e-4},{id:468,oaid:"007bc04c97f9f8bcec0487699e197315418f22e7",doi:"10.1609/aimag.v41i4.5304",title:"From 'F' to 'A' on the N.Y. Regents Science Exams: An Overview of the Aristo Project",authors:[{name:"Peter Clark",institutions:["Allen Institute for AI"]},{name:"Oren Etzioni",institutions:[]},{name:"Daniel Khashabi",institutions:["Johns Hopkins University"]},{name:"Tushar Khot",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Bhavana Dalvi",institutions:[]},{name:"Kyle Richardson",institutions:["Allen Institute for Artificial Intelligence"]},{name:"Ashish Sabharwal",institutions:[]},{name:"Carissa Schoenick",institutions:["Allen Institute for AI, Eastern Illinois University, University of Illinois at Urbana-Champaign"]},{name:"Oyvind Tafjord",institutions:[]},{name:"Niket Tandon",institutions:[]},{name:"Sumithra Bhakthavatsalam",institutions:[]},{name:"Dirk Groeneveld",institutions:[]},{name:"Michal Guerquin",institutions:[]},{name:"Michael Schmitz",institutions:["Allen Institute for AI"]}],authorString:"Peter Clark; Oren Etzioni; Daniel Khashabi; Tushar Khot; Bhavana Dalvi; Kyle Richardson; Ashish Sabharwal; Carissa Schoenick; Oyvind Tafjord; Niket Tandon; Sumithra Bhakthavatsalam; Dirk Groeneveld et al.",institutions:["Allen Institute for AI","Allen Institute for AI, Eastern Illinois University, University of Illinois at Urbana-Champaign","Allen Institute for Artificial Intelligence","Johns Hopkins University"],countries:[],year:2019,journal:"The AI Magazine",citations:106,abstract:"AI has achieved remarkable mastery over games such as Chess, Go, and Poker, and even Jeopardy!, but the rich variety of standardized exams has remained a landmark challenge. Even as recently as 2016, the best AI system could achieve merely 59.3 percent on an 8th grade science exam. This article reports success on the Grade 8 New York Regents Science Exam, where for the first time a system scores more than 90 percent on the exam’s nondiagram, multiple choice (NDMC) questions. In addition, our Aristo system, building upon the success of recent language models, exceeded 83 percent on the corresponding Grade 12 Science Exam NDMC questions. The results, on unseen test questions, are robust across different test years and different variations of this kind of test. They demonstrate that modern natural language processing methods can result in mastery on this task. While not a full solution to general question-answering (the questions are limited to 8th grade multiple-choice science) it represents a significant milestone for the field.",keywords:["Education"],concepts:["Education"],pdf_url:"https://ojs.aaai.org/aimagazine/index.php/aimagazine/article/download/5304/14933",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:.0019,pagerank:56e-5,eigenvector:.001},{id:469,oaid:"afe3a0d463e2f099305c745ddbf943844583795d",doi:"10.1007/978-3-030-01231-1_1",title:"Learning Visual Question Answering by Bootstrapping Hard Attention",authors:[{name:"Mateusz Malinowski",institutions:[]},{name:"Carl Doersch",institutions:[]},{name:"Adam Santoro",institutions:[]},{name:"P. Battaglia",institutions:[]}],authorString:"Mateusz Malinowski; Carl Doersch; Adam Santoro; P. Battaglia",institutions:[],countries:[],year:2018,journal:"European Conference on Computer Vision",citations:104,abstract:"Attention mechanisms in biological perception are thought to select subsets of perceptual information for more sophisticated processing which would be prohibitive to perform on all sensory inputs. In computer vision, however, there has been relatively little exploration of hard attention, where some information is selectively ignored, in spite of the success of soft attention, where information is re-weighted and aggregated, but never filtered out. Here, we introduce a new approach for hard attention and find it achieves very competitive performance on a recently-released visual question answering datasets, equalling and in some cases surpassing similar soft attention architectures while entirely ignoring some features. Even though the hard attention mechanism is thought to be non-differentiable, we found that the feature magnitudes correlate with semantic relevance, and provide a useful signal for our mechanism’s attentional selection criterion. Because hard attention selects important features of the input information, it can also be more efficient than analogous soft attention mechanisms. This is especially important for recent approaches that use non-local pairwise operations, whereby computational and memory costs are quadratic in the size of the set of features.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:1e-4},{id:470,oaid:"f4c491f2a54e9b1c2b18500d0787cc7a72522bff",doi:"10.1162/tacl_a_00460",title:"Multilingual Autoregressive Entity Linking",authors:[{name:"Nicola De Cao",institutions:["The University of Edinburgh","University of Amsterdam"]},{name:"Ledell Yu Wu",institutions:["Facebook AI Research"]},{name:"Kashyap Popat",institutions:["Max Planck Institute for Informatics"]},{name:"Mikel Artetxe",institutions:[]},{name:"Naman Goyal",institutions:[]},{name:"Mikhail Plekhanov",institutions:[]},{name:"Luke Zettlemoyer",institutions:["University of Washington","Facebook"]},{name:"Nicola Cancedda",institutions:[]},{name:"Sebastian Riedel",institutions:[]},{name:"F. Petroni",institutions:[]}],authorString:"Nicola De Cao; Ledell Yu Wu; Kashyap Popat; Mikel Artetxe; Naman Goyal; Mikhail Plekhanov; Luke Zettlemoyer; Nicola Cancedda; Sebastian Riedel; F. Petroni",institutions:["Facebook","Facebook AI Research","Max Planck Institute for Informatics","The University of Edinburgh","University of Amsterdam","University of Washington"],countries:[],year:2021,journal:"Transactions of the Association for Computational Linguistics",citations:103,abstract:"We present mGENRE, a sequence-to- sequence system for the Multilingual Entity Linking (MEL) problem—the task of resolving language-specific mentions to a multilingual Knowledge Base (KB). For a mention in a given language, mGENRE predicts the name of the target entity left-to-right, token-by-token in an autoregressive fashion. The autoregressive formulation allows us to effectively cross-encode mention string and entity names to capture more interactions than the standard dot product between mention and entity vectors. It also enables fast search within a large KB even for mentions that do not appear in mention tables and with no need for large-scale vector indices. While prior MEL works use a single representation for each entity, we match against entity names of as many languages as possible, which allows exploiting language connections between source input and target name. Moreover, in a zero-shot setting on languages with no training data at all, mGENRE treats the target language as a latent variable that is marginalized at prediction time. This leads to over 50% improvements in average accuracy. We show the efficacy of our approach through extensive evaluation including experiments on three popular MEL benchmarks where we establish new state-of-the-art results. Source code available at https://github.com/facebookresearch/GENRE.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://direct.mit.edu/tacl/article-pdf/doi/10.1162/tacl_a_00460/2004070/tacl_a_00460.pdf",is_oa:!0,n_refs:46,n_refs_in_core:1,degree:5,community:1,deg_w:43.5,betweenness:0,pagerank:.0012,eigenvector:.02},{id:471,oaid:"52fa450740913a6cdcb4d9395b45e203f46cab79",doi:"10.18653/v1/D19-1609",title:"Giving BERT a Calculator: Finding Operations and Arguments with Reading Comprehension",authors:[{name:"D. Andor",institutions:[]},{name:"Luheng He",institutions:[]},{name:"Kenton Lee",institutions:[]},{name:"Emily Pitler",institutions:[]}],authorString:"D. Andor; Luheng He; Kenton Lee; Emily Pitler",institutions:[],countries:[],year:2019,journal:"Conference on Empirical Methods in Natural Language Processing",citations:102,abstract:"Reading comprehension models have been successfully applied to extractive text answers, but it is unclear how best to generalize these models to abstractive numerical answers. We enable a BERT-based reading comprehension model to perform lightweight numerical reasoning. We augment the model with a predefined set of executable ‘programs’ which encompass simple arithmetic as well as extraction. Rather than having to learn to manipulate numbers directly, the model can pick a program and execute it. On the recent Discrete Reasoning Over Passages (DROP) dataset, designed to challenge reading comprehension models, we show a 33% absolute improvement by adding shallow programs. The model can learn to predict new operations when appropriate in a math word problem setting (Roy and Roth, 2015) with very few training examples.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/D19-1609.pdf",is_oa:!0,n_refs:14,n_refs_in_core:2,degree:6,community:5,deg_w:34.5,betweenness:3e-4,pagerank:.00119,eigenvector:.0042},{id:472,oaid:"c2b93ad7a0bb62242f726639e7fc9283c797c8ac",doi:null,title:"Adversarial Sets for Regularising Neural Link Predictors",authors:[{name:"Pasquale Minervini",institutions:[]},{name:"T. Demeester",institutions:[]},{name:"Tim Rocktäschel",institutions:[]},{name:"Sebastian Riedel",institutions:[]}],authorString:"Pasquale Minervini; T. Demeester; Tim Rocktäschel; Sebastian Riedel",institutions:[],countries:[],year:2017,journal:"Conference on Uncertainty in Artificial Intelligence",citations:102,abstract:"In adversarial training, a set of models learn together by pursuing competing goals, usually defined on single data instances. However, in relational learning and other non-i.i.d domains, goals can also be defined over sets of instances. For example, a link predictor for the is-a relation needs to be consistent with the transitivity property: if is-a(x_1, x_2) and is-a(x_2, x_3) hold, is-a(x_1, x_3) needs to hold as well. Here we use such assumptions for deriving an inconsistency loss, measuring the degree to which the model violates the assumptions on an adversarially-generated set of examples. The training objective is defined as a minimax problem, where an adversary finds the most offending adversarial examples by maximising the inconsistency loss, and the model is trained by jointly minimising a supervised loss and the inconsistency loss on the adversarial examples. This yields the first method that can use function-free Horn clauses (as in Datalog) to regularise any neural link predictor, with complexity independent of the domain size. We show that for several link prediction models, the optimisation problem faced by the adversary has efficient closed-form solutions. Experiments on link prediction benchmarks indicate that given suitable prior knowledge, our method can significantly improve neural link predictors on all relevant metrics.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12.5,betweenness:0,pagerank:73e-5,eigenvector:1e-4},{id:473,oaid:"19169c6de54bfb3b06a6a16e593cdf7ac1391209",doi:"10.1007/s10817-014-9301-5",title:"Machine Learning for First-Order Theorem Proving",authors:[{name:"James P. Bridge",institutions:[]},{name:"S. Holden",institutions:[]},{name:"Lawrence Charles Paulson",institutions:["University of Cambridge"]}],authorString:"James P. Bridge; S. Holden; Lawrence Charles Paulson",institutions:["University of Cambridge"],countries:[],year:2014,journal:"Journal of automated reasoning",citations:101,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:6,deg_w:8.5,betweenness:0,pagerank:5e-4,eigenvector:6e-4},{id:474,oaid:"83c4b8fcef3c214cfae45818a5b4b637372f3083",doi:"10.18653/v1/2022.naacl-main.372",title:"JointLK: Joint Reasoning with Language Models and Knowledge Graphs for Commonsense Question Answering",authors:[{name:"Yueqing Sun",institutions:["Research Center for Social Computing and Information Retrieval, Harbin Institute of Technology, Harbin, China"]},{name:"Qi Shi",institutions:["Harbin Institute of Technology"]},{name:"Le Qi",institutions:["Harbin Institute of Technology"]},{name:"Yu Zhang",institutions:[]}],authorString:"Yueqing Sun; Qi Shi; Le Qi; Yu Zhang",institutions:["Harbin Institute of Technology","Research Center for Social Computing and Information Retrieval, Harbin Institute of Technology, Harbin, China"],countries:[],year:2021,journal:"North American Chapter of the Association for Computational Linguistics",citations:101,abstract:"Existing KG-augmented models for commonsense question answering primarily focus on designing elaborate Graph Neural Networks (GNNs) to model knowledge graphs (KGs). However, they ignore (i) the effectively fusing and reasoning over question context representations and the KG representations, and (ii) automatically selecting relevant nodes from the noisy KGs during reasoning. In this paper, we propose a novel model, JointLK, which solves the above limitations through the joint reasoning of LM and GNN and the dynamic KGs pruning mechanism. Specifically, JointLK performs joint reasoning between LM and GNN through a novel dense bidirectional attention module, in which each question token attends on KG nodes and each KG node attends on question tokens, and the two modal representations fuse and update mutually by multi-step interactions. Then, the dynamic pruning module uses the attention weights generated by joint reasoning to prune irrelevant KG nodes recursively. We evaluate JointLK on the CommonsenseQA and OpenBookQA datasets, and demonstrate its improvements to the existing LM and LM+KG models, as well as its capability to perform interpretable reasoning.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2022.naacl-main.372.pdf",is_oa:!0,n_refs:43,n_refs_in_core:8,degree:16,community:1,deg_w:103.5,betweenness:.0032,pagerank:.00305,eigenvector:.0632},{id:475,oaid:"a3e0ae9da7c1b1163f886f9c5b1943c9b76b7b26",doi:"10.1613/JAIR.1.11203",title:"Lifted Relational Neural Networks: Efficient Learning of Latent Relational Structures",authors:[{name:"Gustav Sourek",institutions:["Czech Technical University in Prague"]},{name:"Vojtech Aschenbrenner",institutions:[]},{name:"F. Železný",institutions:[]},{name:"S. Schockaert",institutions:[]},{name:"Ondřej Kuželka",institutions:[]}],authorString:"Gustav Sourek; Vojtech Aschenbrenner; F. Železný; S. Schockaert; Ondřej Kuželka",institutions:["Czech Technical University in Prague"],countries:[],year:2018,journal:"Journal of Artificial Intelligence Research",citations:99,abstract:"We propose a method to combine the interpretability and expressive power of firstorder logic with the effectiveness of neural network learning. In particular, we introduce a lifted framework in which first-order rules are used to describe the structure of a given problem setting. These rules are then used as a template for constructing a number of neural networks, one for each training and testing example. As the different networks corresponding to different examples share their weights, these weights can be efficiently learned using stochastic gradient descent. Our framework provides a flexible way for implementing and combining a wide variety of modelling constructs. In particular, the use of first-order logic allows for a declarative specification of latent relational structures, which can then be efficiently discovered in a given data set using neural network learning. Experiments on 78 relational learning benchmarks clearly demonstrate the effectiveness of the framework.",keywords:[],concepts:[],pdf_url:"https://jair.org/index.php/jair/article/download/11203/26415",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:476,oaid:"5fe30f5b788627fd959915cd4fdf9a0b817cbd81",doi:"10.24963/ijcai.2020/554",title:"TransOMCS: From Linguistic Graphs to Commonsense Knowledge",authors:[{name:"Hongming Zhang",institutions:["The Hong Kong University of Science and Technology"]},{name:"Daniel Khashabi",institutions:["Johns Hopkins University"]},{name:"Yangqiu Song",institutions:[]},{name:"Dan Roth",institutions:["University of Pennsylvania, Oracle"]}],authorString:"Hongming Zhang; Daniel Khashabi; Yangqiu Song; Dan Roth",institutions:["Johns Hopkins University","The Hong Kong University of Science and Technology","University of Pennsylvania, Oracle"],countries:[],year:2020,journal:"International Joint Conference on Artificial Intelligence",citations:99,abstract:"Commonsense knowledge acquisition is a key problem for artificial intelligence. Conventional methods of acquiring commonsense knowledge generally require laborious and costly human annotations, which are not feasible on a large scale. In this paper, we explore a practical way of mining commonsense knowledge from linguistic graphs, with the goal of transferring cheap knowledge obtained with linguistic patterns into expensive commonsense knowledge. The result is a conversion of ASER [Zhang et al., 2020], a large-scale selectional preference knowledge resource, into TransOMCS, of the same representation as ConceptNet [Liu and Singh, 2004] but two orders of magnitude larger. Experimental results demonstrate the transferability of linguistic knowledge to commonsense knowledge and the effectiveness of the proposed approach in terms of quantity, novelty, and quality. TransOMCS is publicly available at: https://github.com/HKUST-KnowComp/TransOMCS.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://www.ijcai.org/proceedings/2020/0554.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:.0071},{id:477,oaid:"a6aad9ccdcb7674a3b7ab710f0a80d205834f847",doi:null,title:"Learning Symbolic Physics with Graph Networks",authors:[{name:"Miles Cranmer",institutions:["University of Cambridge"]},{name:"Rui Xu",institutions:[]},{name:"P. Battaglia",institutions:[]},{name:"S. Ho",institutions:[]}],authorString:"Miles Cranmer; Rui Xu; P. Battaglia; S. Ho",institutions:["University of Cambridge"],countries:[],year:2019,journal:"arXiv.org",citations:99,abstract:"We introduce an approach for imposing physically motivated inductive biases on graph networks to learn interpretable representations and improved zero-shot generalization. Our experiments show that our graph network models, which implement this inductive bias, can learn message representations equivalent to the true force vector when trained on n-body gravitational and spring-like simulations. We use symbolic regression to fit explicit algebraic equations to our trained model's message function and recover the symbolic form of Newton's law of gravitation without prior knowledge. We also show that our model generalizes better at inference time to systems with more bodies than had been experienced during training. Our approach is extensible, in principle, to any unknown interaction law learned by a graph network, and offers a valuable technique for interpreting and inferring explicit causal theories about the world from implicit knowledge captured by deep learning.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:15,n_refs_in_core:1,degree:5,community:2,deg_w:20,betweenness:5e-4,pagerank:93e-5,eigenvector:1e-4},{id:478,oaid:"cb4571fa905abb70868d0bb9d4681f0a612c2d0f",doi:"10.1609/AAAI.V34I04.5962",title:"Differentiable Reasoning on Large Knowledge Bases and Natural Language",authors:[{name:"Pasquale Minervini",institutions:[]},{name:"Matko Bovsnjak",institutions:[]},{name:"Tim Rocktäschel",institutions:[]},{name:"Sebastian Riedel",institutions:[]},{name:"Edward Grefenstette",institutions:[]}],authorString:"Pasquale Minervini; Matko Bovsnjak; Tim Rocktäschel; Sebastian Riedel; Edward Grefenstette",institutions:[],countries:[],year:2019,journal:"Knowledge Graphs for eXplainable Artificial Intelligence",citations:98,abstract:"Reasoning with knowledge expressed in natural language and Knowledge Bases (KBs) is a major challenge for Artificial Intelligence, with applications in machine reading, dialogue, and question answering. General neural architectures that jointly learn representations and transformations of text are very data-inefficient, and it is hard to analyse their reasoning process. These issues are addressed by end-to-end differentiable reasoning systems such as Neural Theorem Provers (NTPs), although they can only be used with small-scale symbolic KBs. In this paper we first propose Greedy NTPs (GNTPs), an extension to NTPs addressing their complexity and scalability limitations, thus making them applicable to real-world datasets. This result is achieved by dynamically constructing the computation graph of NTPs and including only the most promising proof paths during inference, thus obtaining orders of magnitude more efficient models. Then, we propose a novel approach for jointly reasoning over KBs and textual mentions, by embedding logic facts and natural language sentences in a shared embedding space. We show that GNTPs perform on par with NTPs at a fraction of their cost while achieving competitive link prediction results on large datasets, providing explanations for predictions, and inducing interpretable models. Source code, datasets, and supplementary material are available online at this https URL.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/5962/5818",is_oa:!0,n_refs:55,n_refs_in_core:17,degree:33,community:0,deg_w:191.5,betweenness:.0225,pagerank:.00686,eigenvector:.0051},{id:479,oaid:"a176b0de62840f7118006277d94bbc1547162a4d",doi:null,title:"Learning to Synthesize Programs as Interpretable and Generalizable Policies",authors:[{name:"Dweep Trivedi",institutions:[]},{name:"Jesse Zhang",institutions:["University of Washington","Allen Institute for AI"]},{name:"Shao-Hua Sun",institutions:["National Taiwan University"]},{name:"Joseph J. Lim",institutions:[]}],authorString:"Dweep Trivedi; Jesse Zhang; Shao-Hua Sun; Joseph J. Lim",institutions:["Allen Institute for AI","National Taiwan University","University of Washington"],countries:[],year:2021,journal:"Neural Information Processing Systems",citations:98,abstract:"Recently, deep reinforcement learning (DRL) methods have achieved impressive performance on tasks in a variety of domains. However, neural network policies produced with DRL methods are not human-interpretable and often have difficulty generalizing to novel scenarios. To address these issues, prior works explore learning programmatic policies that are more interpretable and structured for generalization. Yet, these works either employ limited policy representations (e.g. decision trees, state machines, or predefined program templates) or require stronger supervision (e.g. input/output state pairs or expert demonstrations). We present a framework that instead learns to synthesize a program, which details the procedure to solve a task in a flexible and expressive manner, solely from reward signals. To alleviate the difficulty of learning to compose programs to induce the desired agent behavior from scratch, we propose to first learn a program embedding space that continuously parameterizes diverse behaviors in an unsupervised manner and then search over the learned program embedding space to yield a program that maximizes the return for a given task. Experimental results demonstrate that the proposed framework not only learns to reliably synthesize task-solving programs but also outperforms DRL and program synthesis baselines while producing interpretable and more generalizable policies. We also justify the necessity of the proposed two-stage learning scheme as well as analyze various methods for learning the program embedding.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:119,n_refs_in_core:13,degree:28,community:7,deg_w:125,betweenness:.0318,pagerank:.00479,eigenvector:.0011},{id:480,oaid:"03dfada96b88c741bb26bd4ce7b5ae4232157d37",doi:null,title:"On Approximate Reasoning Capabilities of Low-Rank Vector Spaces",authors:[{name:"Guillaume Bouchard",institutions:[]},{name:"Sameer Singh",institutions:["University of California, Irvine","Envive AI (fka Spiffy AI)"]},{name:"Théo Trouillon",institutions:[]}],authorString:"Guillaume Bouchard; Sameer Singh; Théo Trouillon",institutions:["Envive AI (fka Spiffy AI)","University of California, Irvine"],countries:[],year:2015,journal:"AAAI Spring Symposia",citations:98,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:53e-5,eigenvector:2e-4},{id:481,oaid:"8400949bbf0886c1257843c9ef9a892d0e339017",doi:"10.1007/978-3-540-73954-8",title:"Perspectives of Neural-Symbolic Integration",authors:[{name:"B. Hammer",institutions:[]},{name:"P. Hitzler",institutions:[]}],authorString:"B. Hammer; P. Hitzler",institutions:[],countries:[],year:2007,journal:"Studies in Computational Intelligence",citations:97,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:62e-5,eigenvector:1e-4},{id:482,oaid:"511522bcfc44410ebc211f16cf851191e0e4be4c",doi:"10.1631/FITEE.1800514",title:"Task planning in robotics: an empirical comparison of PDDL- and ASP-based systems",authors:[{name:"Yuqian Jiang",institutions:[]},{name:"Shiqi Zhang",institutions:[]},{name:"Piyush Khandelwal",institutions:[]},{name:"P. Stone",institutions:[]}],authorString:"Yuqian Jiang; Shiqi Zhang; Piyush Khandelwal; P. Stone",institutions:[],countries:[],year:2018,journal:"Frontiers of Information Technology & Electronic Engineering",citations:96,abstract:"Robots need task planning algorithms to sequence actions toward accomplishing goals that are impossible through individual actions. Off-the-shelf task planners can be used by intelligent robotics practitioners to solve a variety of planning problems. However, many different planners exist, each with different strengths and weaknesses, and there are no general rules for which planner would be best to apply to a given problem. In this study, we empirically compare the performance of state-of-the-art planners that use either the planning domain description language (PDDL) or answer set programming (ASP) as the underlying action language. PDDL is designed for task planning, and PDDL-based planners are widely used for a variety of planning problems. ASP is designed for knowledge-intensive reasoning, but can also be used to solve task planning problems. Given domain encodings that are as similar as possible, we find that PDDL-based planners perform better on problems with longer solutions, and ASP-based planners are better on tasks with a large number of objects or tasks in which complex reasoning is required to reason about action preconditions and effects. The resulting analysis can inform selection among general-purpose planning systems for particular robot task planning domains.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8.5,betweenness:0,pagerank:6e-4,eigenvector:2e-4},{id:483,oaid:"28f3a20ebd5e2f3afa871b1784076cf7004415b8",doi:"10.24432/C5KW2W",title:"Improving Relation Extraction by Pre-trained Language Representations",authors:[{name:"Christoph Alt",institutions:["German Research Center for Artificial Intelligence"]},{name:"Marc Hübner",institutions:["German Research Center for Artificial Intelligence"]},{name:"Leonhard Hennig",institutions:["German Research Center for Artificial Intelligence (DFKI)"]}],authorString:"Christoph Alt; Marc Hübner; Leonhard Hennig",institutions:["German Research Center for Artificial Intelligence","German Research Center for Artificial Intelligence (DFKI)"],countries:[],year:2019,journal:"Conference on Automated Knowledge Base Construction",citations:95,abstract:"Current state-of-the-art relation extraction methods typically rely on a set of lexical, syntactic, and semantic features, explicitly computed in a pre-processing step. Training feature extraction models requires additional annotated language resources, which severely restricts the applicability and portability of relation extraction to novel languages. Similarly, pre-processing introduces an additional source of error. To address these limitations, we introduce TRE, a Transformer for Relation Extraction, extending the OpenAI Generative Pre-trained Transformer [Radford et al., 2018]. Unlike previous relation extraction models, TRE uses pre-trained deep language representations instead of explicit linguistic features to inform the relation classification and combines it with the self-attentive Transformer architecture to effectively model long-range dependencies between entity mentions. TRE allows us to learn implicit linguistic features solely from plain text corpora by unsupervised pre-training, before fine-tuning the learned language representations on the relation extraction task. TRE obtains a new state-of-the-art result on the TACRED and SemEval 2010 Task 8 datasets, achieving a test F1 of 67.4 and 87.1, respectively. Furthermore, we observe a significant increase in sample efficiency. With only 20% of the training examples, TRE matches the performance of our baselines and our model trained from scratch on 100% of the TACRED dataset. We open-source our trained models, experiments, and source code.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:5e-4,eigenvector:.0059},{id:484,oaid:"7890ece03cfb88e0620f8e791105569bd7128c76",doi:"10.48550/arXiv.2205.10712",title:"Housekeep: Tidying Virtual Households using Commonsense Reasoning",authors:[{name:"Yash Kant",institutions:[]},{name:"Arun Ramachandran",institutions:[]},{name:"Sriram Yenamandra",institutions:[]},{name:"Igor Gilitschenski",institutions:[]},{name:"Dhruv Batra",institutions:[]},{name:"Andrew Szot",institutions:[]},{name:"Harsh Agrawal",institutions:["Apple","Georgia Institute of Technology"]}],authorString:"Yash Kant; Arun Ramachandran; Sriram Yenamandra; Igor Gilitschenski; Dhruv Batra; Andrew Szot; Harsh Agrawal",institutions:["Apple","Georgia Institute of Technology"],countries:[],year:2022,journal:"European Conference on Computer Vision",citations:94,abstract:"We introduce Housekeep, a benchmark to evaluate commonsense reasoning in the home for embodied AI. In Housekeep, an embodied agent must tidy a house by rearranging misplaced objects without explicit instructions specifying which objects need to be rearranged. Instead, the agent must learn from and is evaluated against human preferences of which objects belong where in a tidy house. Specifically, we collect a dataset of where humans typically place objects in tidy and untidy houses constituting 1799 objects, 268 object categories, 585 placements, and 105 rooms. Next, we propose a modular baseline approach for Housekeep that integrates planning, exploration, and navigation. It leverages a fine-tuned large language model (LLM) trained on an internet text corpus for effective planning. We show that our baseline agent generalizes to rearranging unseen objects in unknown environments. See our webpage for more details: https://yashkant.github.io/housekeep/",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2205.10712",is_oa:!0,n_refs:80,n_refs_in_core:2,degree:17,community:4,deg_w:109.5,betweenness:.0079,pagerank:.00275,eigenvector:.0349},{id:485,oaid:"8668fd1cb5cab820f8b2a136b2ef4adfad6c4dc1",doi:null,title:"Knowledge-Aware Language Model Pretraining",authors:[{name:"Corby Rosset",institutions:[]},{name:"Chenyan Xiong",institutions:[]},{name:"M. Phan",institutions:[]},{name:"Xia Song",institutions:[]},{name:"Paul N. Bennett",institutions:[]},{name:"Saurabh Tiwary",institutions:[]}],authorString:"Corby Rosset; Chenyan Xiong; M. Phan; Xia Song; Paul N. Bennett; Saurabh Tiwary",institutions:[],countries:[],year:2020,journal:"arXiv.org",citations:94,abstract:"How much knowledge do pretrained language models hold? Recent research observed that pretrained transformers are adept at modeling semantics but it is unclear to what degree they grasp human knowledge, or how to ensure they do so. In this paper we incorporate knowledge-awareness in language model pretraining without changing the transformer architecture, inserting explicit knowledge layers, or adding external storage of semantic information. Rather, we simply signal the existence of entities to the input of the transformer in pretraining, with an entity-extended tokenizer; and at the output, with an additional entity prediction task. Our experiments show that solely by adding these entity signals in pretraining, significantly more knowledge is packed into the transformer parameters: we observe improved language modeling accuracy, factual correctness in LAMA knowledge probing tasks, and semantics in the hidden representations through edge probing.We also show that our knowledge-aware language model (KALM) can serve as a drop-in replacement for GPT-2 models, significantly improving downstream tasks like zero-shot question-answering with no task-related training.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:.0117},{id:486,oaid:"5b0835865e6d27e825dda1026e3a369986f3ad23",doi:null,title:"Closed Loop Neural-Symbolic Learning via Integrating Neural Perception, Grammar Parsing, and Symbolic Reasoning",authors:[{name:"Qing Li",institutions:[]},{name:"Siyuan Huang",institutions:[]},{name:"Yining Hong",institutions:[]},{name:"Yixin Chen",institutions:[]},{name:"Y. Wu",institutions:[]},{name:"Song-Chun Zhu",institutions:[]}],authorString:"Qing Li; Siyuan Huang; Yining Hong; Yixin Chen; Y. Wu; Song-Chun Zhu",institutions:[],countries:[],year:2020,journal:"International Conference on Machine Learning",citations:93,abstract:"The goal of neural-symbolic computation is to integrate the connectionist and symbolist paradigms. Prior methods learn the neural-symbolic models using reinforcement learning (RL) approaches, which ignore the error propagation in the symbolic reasoning module and thus converge slowly with sparse rewards. In this paper, we address these issues and close the loop of neural-symbolic learning by (1) introducing the \\textbf{grammar} model as a \\textit{symbolic prior} to bridge neural perception and symbolic reasoning, and (2) proposing a novel \\textbf{back-search} algorithm which mimics the top-down human-like learning procedure to propagate the error through the symbolic reasoning module efficiently. We further interpret the proposed learning framework as maximum likelihood estimation using Markov chain Monte Carlo sampling and the back-search algorithm as a Metropolis-Hastings sampler. The experiments are conducted on two weakly-supervised neural-symbolic tasks: (1) handwritten formula recognition on the newly introduced HWF dataset; (2) visual question answering on the CLEVR dataset. The results show that our approach significantly outperforms the RL methods in terms of performance, converging speed, and data efficiency. Our code and data are released at \\url{this https URL}.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:65e-5,eigenvector:1e-4},{id:487,oaid:"f1318d15d7d8ab626b92d0c70dbdc5b5d37e223f",doi:null,title:"HolStep: A Machine Learning Dataset for Higher-order Logic Theorem Proving",authors:[{name:"C. Kaliszyk",institutions:[]},{name:"François Chollet",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"C. Kaliszyk; François Chollet; Christian Szegedy",institutions:[],countries:[],year:2017,journal:"International Conference on Learning Representations",citations:90,abstract:"Large computer-understandable proofs consist of millions of intermediate logical steps. The vast majority of such steps originate from manually selected and manually guided heuristics applied to intermediate goals. So far, machine learning has generally not been used to filter or generate these steps. In this paper, we introduce a new dataset based on Higher-Order Logic (HOL) proofs, for the purpose of developing new machine learning-based theorem-proving strategies. We make this dataset publicly available under the BSD license. We propose various machine learning tasks that can be performed on this dataset, and discuss their significance for theorem proving. We also benchmark a set of simple baseline machine learning models suited for the tasks (including logistic regression, convolutional neural networks and recurrent neural networks). The results of our baseline models show the promise of applying machine learning to HOL theorem proving.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:6,deg_w:12.5,betweenness:.0018,pagerank:62e-5,eigenvector:7e-4},{id:488,oaid:"7d52fa1a9021d3596930ad2d5121e9d125113ab2",doi:"10.1109/CVPR.2017.416",title:"The VQA-Machine: Learning How to Use Existing Vision Algorithms to Answer New Questions",authors:[{name:"Peng Wang",institutions:[]},{name:"Qi Wu",institutions:[]},{name:"Chunhua Shen",institutions:["The University of Adelaide"]},{name:"Anton van den Hengel",institutions:["University of Adelaide, Commonwealth Bank of Australia"]}],authorString:"Peng Wang; Qi Wu; Chunhua Shen; Anton van den Hengel",institutions:["The University of Adelaide","University of Adelaide, Commonwealth Bank of Australia"],countries:[],year:2016,journal:"Computer Vision and Pattern Recognition",citations:90,abstract:"One of the most intriguing features of the Visual Question Answering (VQA) challenge is the unpredictability of the questions. Extracting the information required to answer them demands a variety of image operations from detection and counting, to segmentation and reconstruction. To train a method to perform even one of these operations accurately from {image, question, answer} tuples would be challenging, but to aim to achieve them all with a limited set of such training data seems ambitious at best. Our method thus learns how to exploit a set of external off-the-shelf algorithms to achieve its goal, an approach that has something in common with the Neural Turing Machine [10]. The core of our proposed method is a new co-attention model. In addition, the proposed approach generates human-readable reasons for its decision, and can still be trained end-to-end without ground truth reasons being given. We demonstrate the effectiveness on two publicly available datasets, Visual Genome and VQA, and show that it produces the state-of-the-art results in both cases.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1612.05386",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:3,deg_w:17,betweenness:0,pagerank:6e-4,eigenvector:1e-4},{id:489,oaid:"2a2d03a1534b365c5b048c824c0886e16ccf7dfa",doi:null,title:"Reading The Web with Learned Syntactic-Semantic Inference Rules",authors:[{name:"N. Lao",institutions:[]},{name:"A. Subramanya",institutions:[]},{name:"Fernando C Pereira",institutions:["Google"]},{name:"William W. Cohen",institutions:["Google"]}],authorString:"N. Lao; A. Subramanya; Fernando C Pereira; William W. Cohen",institutions:["Google"],countries:[],year:2012,journal:"Conference on Empirical Methods in Natural Language Processing",citations:90,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:8,community:0,deg_w:31.5,betweenness:0,pagerank:.00111,eigenvector:.0017},{id:490,oaid:"2fc760267d7e052e584cf55b641539e913df55ef",doi:"10.3115/v1/D14-1071",title:"Joint Relational Embeddings for Knowledge-based Question Answering",authors:[{name:"Min-Chul Yang",institutions:[]},{name:"Nan Duan",institutions:[]},{name:"M. Zhou",institutions:[]},{name:"Hae-Chang Rim",institutions:[]}],authorString:"Min-Chul Yang; Nan Duan; M. Zhou; Hae-Chang Rim",institutions:[],countries:[],year:2014,journal:"Conference on Empirical Methods in Natural Language Processing",citations:89,abstract:"Transforming a natural language (NL) question into a corresponding logical form (LF) is central to the knowledge-based question answering (KB-QA) task. Unlike most previous methods that achieve this goal based on mappings between lexicalized phrases and logical predicates, this paper goes one step further and proposes a novel embedding-based approach that maps NL-questions into LFs for KBQA by leveraging semantic associations between lexical representations and KBproperties in the latent space. Experimental results demonstrate that our proposed method outperforms three KB-QA baseline methods on two publicly released QA data sets.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/D14-1071.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:1e-4,pagerank:53e-5,eigenvector:8e-4},{id:491,oaid:"72c34aac7bcaa9446d2830a755202335486f4d3d",doi:"10.1561/2500000045",title:"QED at Large: A Survey of Engineering of Formally Verified Software",authors:[{name:"T. Ringer",institutions:[]},{name:"Karl Palmskog",institutions:[]},{name:"Ilya Sergey",institutions:[]},{name:"Miloš Gligorić",institutions:[]},{name:"Zachary Tatlock",institutions:["University of Washington"]}],authorString:"T. Ringer; Karl Palmskog; Ilya Sergey; Miloš Gligorić; Zachary Tatlock",institutions:["University of Washington"],countries:[],year:2019,journal:"Found. Trends Program. Lang.",citations:89,abstract:"Development of formal proofs of correctness of programs can increase actual and perceived reliability and facilitate better understanding of program specifications and their underlying assumptions. Tools supporting such development have been available for over 40 years, but have only recently seen wide practical use. Projects based on construction of machine-checked formal proofs are now reaching an unprecedented scale, comparable to large software projects, which leads to new challenges in proof development and maintenance. Despite its increasing importance, the field of proof engineering is seldom considered in its own right; related theories, techniques, and tools span many fields and venues. This survey of the literature presents a holistic understanding of proof engineering for program correctness, covering impact in practice, foundations, proof automation, proof organization, and practical proof development.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1561/2500000045",is_oa:!0,n_refs:483,n_refs_in_core:8,degree:15,community:6,deg_w:135,betweenness:.001,pagerank:.00398,eigenvector:.0033},{id:492,oaid:"9395a2e773e5c04c4cfb056fba2b1b86077f346e",doi:"10.1145/3591280",title:"Scallop: A Language for Neurosymbolic Programming",authors:[{name:"Ziyang Li",institutions:["Johns Hopkins University"]},{name:"Jiani Huang",institutions:[]},{name:"M. Naik",institutions:[]}],authorString:"Ziyang Li; Jiani Huang; M. Naik",institutions:["Johns Hopkins University"],countries:[],year:2023,journal:"Proc. ACM Program. Lang.",citations:86,abstract:"We present Scallop, a language which combines the benefits of deep learning and logical reasoning. Scallop enables users to write a wide range of neurosymbolic applications and train them in a data- and compute-efficient manner. It achieves these goals through three key features: 1) a flexible symbolic representation that is based on the relational data model; 2) a declarative logic programming language that is based on Datalog and supports recursion, aggregation, and negation; and 3) a framework for automatic and efficient differentiable reasoning that is based on the theory of provenance semirings. We evaluate Scallop on a suite of eight neurosymbolic applications from the literature. Our evaluation demonstrates that Scallop is capable of expressing algorithmic reasoning in diverse and challenging AI tasks, provides a succinct interface for machine learning programmers to integrate logical domain knowledge, and yields solutions that are comparable or superior to state-of-the-art models in terms of accuracy. Furthermore, Scallop's solutions outperform these models in aspects such as runtime and data efficiency, interpretability, and generalizability.",keywords:[],concepts:[],pdf_url:"https://dl.acm.org/doi/pdf/10.1145/3591280",is_oa:!0,n_refs:65,n_refs_in_core:22,degree:36,community:0,deg_w:172,betweenness:.0696,pagerank:.00754,eigenvector:.0028},{id:493,oaid:"6071b89c257d36490fd6f0877174adabad265d92",doi:"10.1145/3485447.3511921",title:"Ontology-enhanced Prompt-tuning for Few-shot Learning",authors:[{name:"Hongbin Ye",institutions:[]},{name:"Ningyu Zhang",institutions:["Zhejiang University"]},{name:"Shumin Deng",institutions:[]},{name:"Xiang Chen",institutions:[]},{name:"Hui Chen",institutions:[]},{name:"Feiyu Xiong",institutions:["MemTensor (Shanghai) Technology Co., Ltd."]},{name:"Xi Chen",institutions:[]},{name:"Huajun Chen",institutions:[]}],authorString:"Hongbin Ye; Ningyu Zhang; Shumin Deng; Xiang Chen; Hui Chen; Feiyu Xiong; Xi Chen; Huajun Chen",institutions:["MemTensor (Shanghai) Technology Co., Ltd.","Zhejiang University"],countries:[],year:2022,journal:"The Web Conference",citations:86,abstract:"Few-shot Learning (FSL) is aimed to make predictions based on a limited number of samples. Structured data such as knowledge graphs and ontology libraries has been leveraged to benefit the few-shot setting in various tasks. However, the priors adopted by the existing methods suffer from challenging knowledge missing, knowledge noise, and knowledge heterogeneity, which hinder the performance for few-shot learning. In this study, we explore knowledge injection for FSL with pre-trained language models and propose ontology-enhanced prompt-tuning (OntoPrompt). Specifically, we develop the ontology transformation based on the external knowledge graph to address the knowledge missing issue, which fulfills and converts structure knowledge to text. We further introduce span-sensitive knowledge injection via a visible matrix to select informative knowledge to handle the knowledge noise issue. To bridge the gap between knowledge and text, we propose a collective training algorithm to optimize representations jointly. We evaluate our proposed OntoPrompt in three tasks, including relation extraction, event extraction, and knowledge graph completion, with eight datasets. Experimental results demonstrate that our approach can obtain better few-shot performance than baselines.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2201.11332",is_oa:!0,n_refs:76,n_refs_in_core:4,degree:14,community:1,deg_w:103.5,betweenness:.0053,pagerank:.00257,eigenvector:.0801},{id:494,oaid:"83f355634fac2b445a475ee81b8d16bf768188ec",doi:"10.1109/CVPR.2018.00009",title:"Learning by Asking Questions",authors:[{name:"Ishan Misra",institutions:[]},{name:"Ross B. Girshick",institutions:[]},{name:"R. Fergus",institutions:[]},{name:"M. Hebert",institutions:[]},{name:"A. Gupta",institutions:[]},{name:"L. Maaten",institutions:[]}],authorString:"Ishan Misra; Ross B. Girshick; R. Fergus; M. Hebert; A. Gupta; L. Maaten",institutions:[],countries:[],year:2017,journal:"2018 IEEE/CVF Conference on Computer Vision and Pattern Recognition",citations:86,abstract:"We introduce an interactive learning framework for the development and testing of intelligent visual systems, called learning-by-asking (LBA). We explore LBA in context of the Visual Question Answering (VQA) task. LBA differs from standard VQA training in that most questions are not observed during training time, and the learner must ask questions it wants answers to. Thus, LBA more closely mimics natural learning and has the potential to be more data-efficient than the traditional VQA setting. We present a model that performs LBA on the CLEVR dataset, and show that it automatically discovers an easy-to-hard curriculum when learning interactively from an oracle. Our LBA generated data consistently matches or outperforms the CLEVR train data and is more sample efficient. We also show that our model asks questions that generalize to state-of-the-art VQA models and to novel test time distributions.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1712.01238",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:495,oaid:"b61e2ee2ce7b928299f9a9dbd8c2ecebdcfe43ff",doi:null,title:"HOUDINI: Lifelong Learning as Program Synthesis",authors:[{name:"L. Valkov",institutions:[]},{name:"Dipak Chaudhari",institutions:[]},{name:"Akash Srivastava",institutions:[]},{name:"Charles Sutton",institutions:["Google","University of Edinburgh"]},{name:"Swarat Chaudhuri",institutions:[]}],authorString:"L. Valkov; Dipak Chaudhari; Akash Srivastava; Charles Sutton; Swarat Chaudhuri",institutions:["Google","University of Edinburgh"],countries:[],year:2018,journal:"Neural Information Processing Systems",citations:86,abstract:"We present a neurosymbolic framework for the lifelong learning of algorithmic tasks that mix perception and procedural reasoning. Reusing high-level concepts across domains and learning complex procedures are key challenges in lifelong learning. We show that a program synthesis approach that combines gradient descent with combinatorial search over programs can be a more effective response to these challenges than purely neural methods. Our framework, called HOUDINI, represents neural networks as strongly typed, differentiable functional programs that use symbolic higher-order combinators to compose a library of neural functions. Our learning algorithm consists of: (1) a symbolic program synthesizer that performs a type-directed search over parameterized programs, and decides on the library functions to reuse, and the architectures to combine them, while learning a sequence of tasks; and (2) a neural module that trains these programs using stochastic gradient descent. We evaluate HOUDINI on three benchmarks that combine perception with the algorithmic tasks of counting, summing, and shortest-path computation. Our experiments show that HOUDINI transfers high-level concepts more effectively than traditional transfer learning and progressive neural networks, and that the typed representation of networks signiﬁcantly accelerates the search.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:496,oaid:"0d6e349e385ed1765e4063bd820e2f541ee93b89",doi:"10.1609/aaai.v35i6.16639",title:"Neural-Symbolic Integration: A Compositional Perspective",authors:[{name:"Efthymia Tsamoura",institutions:[]},{name:"Loizos Michael",institutions:[]}],authorString:"Efthymia Tsamoura; Loizos Michael",institutions:[],countries:[],year:2020,journal:"AAAI Conference on Artificial Intelligence",citations:85,abstract:"Despite significant progress in the development of neural-symbolic frameworks, the question of how to integrate a neural and a symbolic system in a compositional manner remains open. Our work seeks to fill this gap by treating these two systems as black boxes to be integrated as modules into a single architecture, without making assumptions on their internal structure and semantics. Instead, we expect only that each module exposes certain methods for accessing the functions that the module implements: the symbolic module exposes a deduction method for computing the function's output on a given input, and an abduction method for computing the function's inputs for a given output; the neural module exposes a deduction method for computing the function's output on a given input, and an induction method for updating the function given input-output training instances. We are, then, able to show that a symbolic module --- with any choice for syntax and semantics, as long as the deduction and abduction methods are exposed --- can be cleanly integrated with a neural module, and facilitate the latter's efficient training, achieving empirical performance that exceeds that of previous work.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/16639/16446",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:5,deg_w:8,betweenness:1e-4,pagerank:63e-5,eigenvector:0},{id:497,oaid:"f732018322ce360c03dd0c9ea31311bd6ef7f853",doi:"10.1126/scirobotics.aav3150",title:"Beyond imitation: Zero-shot task transfer on robots by learning concepts as cognitive programs",authors:[{name:"Miguel L'azaro-Gredilla",institutions:[]},{name:"Dianhuan Lin",institutions:[]},{name:"J. S. Guntupalli",institutions:[]},{name:"Dileep George",institutions:[]}],authorString:"Miguel L'azaro-Gredilla; Dianhuan Lin; J. S. Guntupalli; Dileep George",institutions:[],countries:[],year:2018,journal:"Science Robotics",citations:84,abstract:"Programs on a visual cognitive computer learned underlying concepts and generalized well to new settings without explicit demonstrations. Humans can infer concepts from image pairs and apply those in the physical world in a completely different setting, enabling tasks like IKEA assembly from diagrams. If robots could represent and infer high-level concepts, then it would notably improve their ability to understand our intent and to transfer tasks between different environments. To that end, we introduce a computational framework that replicates aspects of human concept learning. Concepts are represented as programs on a computer architecture consisting of a visual perception system, working memory, and action controller. The instruction set of this cognitive computer has commands for parsing a visual scene, directing gaze and attention, imagining new objects, manipulating the contents of a visual working memory, and controlling arm movement. Inferring a concept corresponds to inducing a program that can transform the input to the output. Some concepts require the use of imagination and recursion. Previously learned concepts simplify the learning of subsequent, more elaborate concepts and create a hierarchy of abstractions. We demonstrate how a robot can use these abstractions to interpret novel concepts presented to it as schematic images and then apply those concepts in very different situations. By bringing cognitive science ideas on mental imagery, perceptual symbols, embodied cognition, and deictic mechanisms into the realm of machine learning, our work brings us closer to the goal of building robots that have interpretable representations and common sense.",keywords:[],concepts:[],pdf_url:"https://robotics.sciencemag.org/content/robotics/4/26/eaav3150.full.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:13,betweenness:0,pagerank:84e-5,eigenvector:0},{id:498,oaid:"4814c10f84863e016d75e6af42e790f60759b9f4",doi:null,title:"Compositional Obverter Communication Learning From Raw Visual Input",authors:[{name:"E. Choi",institutions:[]},{name:"Angeliki Lazaridou",institutions:[]},{name:"Nando de Freitas",institutions:[]}],authorString:"E. Choi; Angeliki Lazaridou; Nando de Freitas",institutions:[],countries:[],year:2018,journal:"International Conference on Learning Representations",citations:84,abstract:"One of the distinguishing aspects of human language is its compositionality, which allows us to describe complex environments with limited vocabulary. Previously, it has been shown that neural network agents can learn to communicate in a highly structured, possibly compositional language based on disentangled input (e.g. hand- engineered features). Humans, however, do not learn to communicate based on well-summarized features. In this work, we train neural agents to simultaneously develop visual perception from raw image pixels, and learn to communicate with a sequence of discrete symbols. The agents play an image description game where the image contains factors such as colors and shapes. We train the agents using the obverter technique where an agent introspects to generate messages that maximize its own understanding. Through qualitative analysis, visualization and a zero-shot test, we show that the agents can develop, out of raw image pixels, a language with compositional properties, given a proper pressure from the environment.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:33,n_refs_in_core:0,degree:4,community:2,deg_w:22.5,betweenness:1e-4,pagerank:81e-5,eigenvector:2e-4},{id:499,oaid:"ef01e99f73593bcc53cb9251928d51c551068e8e",doi:"10.1609/aaai.v36i9.21248",title:"DeepStochLog: Neural Stochastic Logic Programming",authors:[{name:"Thomas Winters",institutions:["KU Leuven"]},{name:"G. Marra",institutions:[]},{name:"Robin Manhaeve",institutions:[]},{name:"L. D. Raedt",institutions:[]}],authorString:"Thomas Winters; G. Marra; Robin Manhaeve; L. D. Raedt",institutions:["KU Leuven"],countries:[],year:2021,journal:"AAAI Conference on Artificial Intelligence",citations:83,abstract:"Recent advances in neural-symbolic learning, such as DeepProbLog, extend probabilistic logic programs with neural predicates. Like graphical models, these probabilistic logic programs define a probability distribution over possible worlds, for which inference is computationally hard. We propose DeepStochLog, an alternative neural-symbolic framework based on stochastic definite clause grammars, a kind of stochastic logic program. More specifically, we introduce neural grammar rules into stochastic definite clause grammars to create a framework that can be trained end-to-end. We show that inference and learning in neural stochastic logic programming scale much better than for neural probabilistic logic programs. Furthermore, the experimental evaluation shows that DeepStochLog achieves state-of-the-art results on challenging neural-symbolic learning tasks.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/21248/20997",is_oa:!0,n_refs:46,n_refs_in_core:27,degree:30,community:0,deg_w:139,betweenness:.0436,pagerank:.00914,eigenvector:5e-4},{id:500,oaid:"eecab00a7c6d58792ec5e620ab1fc37043545a14",doi:null,title:"Still not systematic after all these years: On the compositional skills of sequence-to-sequence recurrent networks",authors:[{name:"B. Lake",institutions:[]},{name:"Marco Baroni",institutions:[]}],authorString:"B. Lake; Marco Baroni",institutions:[],countries:[],year:2017,journal:"International Conference on Learning Representations",citations:83,abstract:'Humans can understand and produce new utterances effortlessly, thanks to their systematic compositional skills. Once a person learns the meaning of a new verb "dax," he or she can immediately understand the meaning of "dax twice" or "sing and dax." In this paper, we introduce the SCAN domain, consisting of a set of simple compositional navigation commands paired with the corresponding action sequences. We then test the zero-shot generalization capabilities of a variety of recurrent neural networks (RNNs) trained on SCAN with sequence-to-sequence methods. We find that RNNs can generalize well when the differences between training and test commands are small, so that they can apply "mix-and-match" strategies to solve the task. However, when generalization requires systematic compositional skills (as in the "dax" example above), RNNs fail spectacularly. We conclude with a proof-of-concept experiment in neural machine translation, supporting the conjecture that lack of systematicity is an important factor explaining why neural networks need very large training sets.',keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:2,deg_w:12.5,betweenness:0,pagerank:79e-5,eigenvector:0},{id:501,oaid:"caf8904e7f9f841f77823cabdfe4e2d87aa20a36",doi:"10.18653/v1/2021.findings-acl.102",title:"Fusing Context Into Knowledge Graph for Commonsense Question Answering",authors:[{name:"Yichong Xu",institutions:[]},{name:"Chenguang Zhu",institutions:[]},{name:"Ruochen Xu",institutions:["Om AI"]},{name:"Yang Liu",institutions:["Microsoft"]},{name:"Michael Zeng",institutions:[]},{name:"Xuedong Huang",institutions:[]}],authorString:"Yichong Xu; Chenguang Zhu; Ruochen Xu; Yang Liu; Michael Zeng; Xuedong Huang",institutions:["Microsoft","Om AI"],countries:[],year:2020,journal:"Findings",citations:81,abstract:"Commonsense question answering (QA) requires a model to grasp commonsense and factual knowledge to answer questions about world events. Many prior methods couple language modeling with knowledge graphs (KG). However, although a KG contains rich structural information, it lacks the context to provide a more precise understanding of the concepts. This creates a gap when fusing knowledge graphs into language modeling, especially when there is insufficient labeled data. Thus, we propose to employ external entity descriptions to provide contextual information for knowledge understanding. We retrieve descriptions of related concepts from Wiktionary and feed them as additional input to pre-trained language models. The resulting model achieves state-of-the-art result in the CommonsenseQA dataset and the best result among non-generative models in OpenBookQA.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.findings-acl.102.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:1,deg_w:13,betweenness:0,pagerank:56e-5,eigenvector:.011},{id:502,oaid:"683e530c2b7e74302d7cf359286e68c07139c5da",doi:null,title:"SORNet: Spatial Object-Centric Representations for Sequential Manipulation",authors:[{name:"Wentao Yuan",institutions:["University of Washington"]},{name:"Chris Paxton",institutions:[]},{name:"K. Desingh",institutions:[]},{name:"D. Fox",institutions:[]}],authorString:"Wentao Yuan; Chris Paxton; K. Desingh; D. Fox",institutions:["University of Washington"],countries:[],year:2021,journal:"Conference on Robot Learning",citations:81,abstract:"Sequential manipulation tasks require a robot to perceive the state of an environment and plan a sequence of actions leading to a desired goal state. In such tasks, the ability to reason about spatial relations among object entities from raw sensor inputs is crucial in order to determine when a task has been completed and which actions can be executed. In this work, we propose SORNet (Spatial Object-Centric Representation Network), a framework for learning object-centric representations from RGB images conditioned on a set of object queries, represented as image patches called canonical object views. With only a single canonical view per object and no annotation, SORNet generalizes zero-shot to object entities whose shape and texture are both unseen during training. We evaluate SORNet on various spatial reasoning tasks such as spatial relation classification and relative direction regression in complex tabletop manipulation scenarios and show that SORNet significantly outperforms baselines including state-of-the-art representation learning techniques. We also demonstrate the application of the representation learned by SORNet on visual-servoing and task planning for sequential manipulation on a real robot.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:45,n_refs_in_core:4,degree:9,community:4,deg_w:67.5,betweenness:.0016,pagerank:.00195,eigenvector:8e-4},{id:503,oaid:"1b5836b463e13a79a276aaf3aa17902d9d3dc5ef",doi:"10.1126/science.1261661",title:"The atoms of neural computation",authors:[{name:"G. Marcus",institutions:[]},{name:"A. Marblestone",institutions:[]},{name:"Thomas L. Dean",institutions:[]}],authorString:"G. Marcus; A. Marblestone; Thomas L. Dean",institutions:[],countries:[],year:2014,journal:"Science",citations:79,abstract:"Does the brain depend on a set of elementary, reusable computations? The human cerebral cortex is central to a wide array of cognitive functions, from vision to language, reasoning, decision-making, and motor control. Yet, nearly a century after the neuroanatomical organization of the cortex was first defined, its basic logic remains unknown. One hypothesis is that cortical neurons form a single, massively repeated “canonical” circuit, characterized as a kind of a “nonlinear spatiotemporal filter with adaptive properties” (1). In this classic view, it was “assumed that these…properties are identical for all neocortical areas.” Nearly four decades later, there is still no consensus about whether such a canonical circuit exists, either in terms of its anatomical basis or its function. Likewise, there is little evidence that such uniform architectures can capture the diversity of cortical function in simple mammals, let alone characteristically human processes such as language and abstract thinking (2). Analogous software implementations in artificial intelligence (e.g., deep learning networks) have proven effective in certain pattern classification tasks, such as speech and image recognition, but likewise have made little inroads in areas such as reasoning and natural language understanding. Is the search for a single canonical cortical circuit misguided?",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1410.8826",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8.5,betweenness:0,pagerank:67e-5,eigenvector:0},{id:504,oaid:"632c1af2307b01d327fa1b6a622cfc081b44d762",doi:"10.1007/s10817-004-6245-1",title:"MPTP – Motivation, Implementation, First Experiments",authors:[{name:"J. Urban",institutions:[]}],authorString:"J. Urban",institutions:[],countries:[],year:2004,journal:"Journal of automated reasoning",citations:77,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:6,deg_w:18.5,betweenness:0,pagerank:79e-5,eigenvector:7e-4},{id:505,oaid:"ac772b5ed9e21eb3ee57cde9d6a4c935de39b7c1",doi:"10.1145/3019612.3019642",title:"Learning and reasoning in logic tensor networks: theory and application to semantic image interpretation",authors:[{name:"L. Serafini",institutions:[]},{name:"Ivan Donadello",institutions:[]},{name:"A. Garcez",institutions:[]}],authorString:"L. Serafini; Ivan Donadello; A. Garcez",institutions:[],countries:[],year:2017,journal:"ACM Symposium on Applied Computing",citations:75,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:1,community:2,deg_w:4,betweenness:0,pagerank:4e-4,eigenvector:0},{id:506,oaid:"0c253bb9aee9aa1ae7909700eda845bd3124197f",doi:null,title:"Neural Program Meta-Induction",authors:[{name:"Jacob Devlin",institutions:[]},{name:"Rudy Bunel",institutions:[]},{name:"Rishabh Singh",institutions:[]},{name:"Matthew J. Hausknecht",institutions:[]},{name:"Pushmeet Kohli",institutions:[]}],authorString:"Jacob Devlin; Rudy Bunel; Rishabh Singh; Matthew J. Hausknecht; Pushmeet Kohli",institutions:[],countries:[],year:2017,journal:"Neural Information Processing Systems",citations:74,abstract:"Most recently proposed methods for Neural Program Induction work under the assumption of having a large set of input/output (I/O) examples for learning any underlying input-output mapping. This paper aims to address the problem of data and computation efficiency of program induction by leveraging information from related tasks. Specifically, we propose two approaches for cross-task knowledge transfer to improve program induction in limited-data scenarios. In our first proposal, portfolio adaptation, a set of induction models is pretrained on a set of related tasks, and the best model is adapted towards the new task using transfer learning. In our second approach, meta program induction, a $k$-shot learning approach is used to make a model generalize to new tasks without additional training. To test the efficacy of our methods, we constructed a new benchmark of programs written in the Karel programming language. Using an extensive experimental evaluation on the Karel benchmark, we demonstrate that our proposals dramatically outperform the baseline induction method that does not use knowledge transfer. We also analyze the relative performance of the two approaches and study conditions in which they perform best. In particular, meta induction outperforms all existing approaches under extreme data sparsity (when a very small number of examples are available), i.e., fewer than ten. As the number of available I/O examples increase (i.e. a thousand or more), portfolio adapted program induction becomes the best approach. For intermediate data sizes, we demonstrate that the combined method of adapted meta program induction has the strongest performance.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:7,deg_w:13,betweenness:0,pagerank:84e-5,eigenvector:0},{id:507,oaid:"018987cad9845a37cd0e6f1d78596041c911d4f5",doi:"10.18653/v1/2022.findings-acl.150",title:"Dict-BERT: Enhancing Language Model Pre-training with Dictionary",authors:[{name:"W. Yu",institutions:[]},{name:"Chenguang Zhu",institutions:[]},{name:"Yuwei Fang",institutions:["Microsoft"]},{name:"Donghan Yu",institutions:[]},{name:"Shuohang Wang",institutions:[]},{name:"Yichong Xu",institutions:[]},{name:"Michael Zeng",institutions:[]},{name:"Meng Jiang",institutions:[]}],authorString:"W. Yu; Chenguang Zhu; Yuwei Fang; Donghan Yu; Shuohang Wang; Yichong Xu; Michael Zeng; Meng Jiang",institutions:["Microsoft"],countries:[],year:2021,journal:"Findings",citations:74,abstract:"Pre-trained language models (PLMs) aim to learn universal language representations by conducting self-supervised training tasks on large-scale corpora. Since PLMs capture word semantics in different contexts, the quality of word representations highly depends on word frequency, which usually follows a heavy-tailed distributions in the pre-training corpus. Therefore, the embeddings of rare words on the tail are usually poorly optimized. In this work, we focus on enhancing language model pre-training by leveraging definitions of the rare words in dictionaries (e.g., Wiktionary). To incorporate a rare word definition as a part of input, we fetch its definition from the dictionary and append it to the end of the input text sequence. In addition to training with the masked language modeling objective, we propose two novel self-supervised pre-training tasks on word and sentence-level alignment between input text sequence and rare word definitions to enhance language modeling representation with dictionary. We evaluate the proposed Dict-BERT model on the language understanding benchmark GLUE and eight specialized domain benchmark datasets. Extensive experiments demonstrate that Dict-BERT can significantly improve the understanding of rare words and boost model performance on various NLP downstream tasks.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://aclanthology.org/2022.findings-acl.150.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:.0099},{id:508,oaid:"0b22f92be890b720eaa97fa75a49560f11ff2ab2",doi:null,title:"Grounding Language to Autonomously-Acquired Skills via Goal Generation",authors:[{name:"Ahmed Akakzia",institutions:[]},{name:"Cédric Colas",institutions:[]},{name:"P. Oudeyer",institutions:[]},{name:"M. Chetouani",institutions:[]},{name:"Olivier Sigaud",institutions:[]}],authorString:"Ahmed Akakzia; Cédric Colas; P. Oudeyer; M. Chetouani; Olivier Sigaud",institutions:[],countries:[],year:2021,journal:"International Conference on Learning Representations",citations:73,abstract:"",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:4,deg_w:12.5,betweenness:0,pagerank:59e-5,eigenvector:2e-4},{id:509,oaid:"544e6168446870dddb36ed4e613e42a8b5b8c59a",doi:null,title:"Proceedings of the Twenty-Third International Joint Conference on Artificial Intelligence Bootstrap Learning via Modular Concept Discovery",authors:[],authorString:"",institutions:[],countries:[],year:null,journal:"",citations:72,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:510,oaid:"b1b88c6d1f05913be18750ff00e06edd5e1f49ef",doi:"10.1007/s10817-020-09580-x",title:"TacticToe: Learning to Prove with Tactics",authors:[{name:"Thibault Gauthier",institutions:[]},{name:"C. Kaliszyk",institutions:[]},{name:"J. Urban",institutions:[]},{name:"Ramana Kumar",institutions:[]},{name:"Michael Norrish",institutions:["Australian National University"]}],authorString:"Thibault Gauthier; C. Kaliszyk; J. Urban; Ramana Kumar; Michael Norrish",institutions:["Australian National University"],countries:[],year:2018,journal:"Journal of automated reasoning",citations:72,abstract:"We implement an automated tactical prover TacticToe on top of the HOL4 interactive theorem prover. TacticToe learns from human proofs which mathematical technique is suitable in each proof situation. This knowledge is then used in a Monte Carlo tree search algorithm to explore promising tactic-level proof paths. On a single CPU, with a time limit of 60 s, TacticToe proves 66.4% of the 7164 theorems in HOL4’s standard library, whereas E prover with auto-schedule solves 34.5%. The success rate rises to 69.0% by combining the results of TacticToe and E prover.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1804.00596",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:6,deg_w:8.5,betweenness:0,pagerank:48e-5,eigenvector:.0014},{id:511,oaid:"593499b654360101682edec1dd711fa7c09f6971",doi:null,title:"IsarStep: a Benchmark for High-level Mathematical Reasoning",authors:[{name:"Wenda Li",institutions:[]},{name:"Lei Yu",institutions:[]},{name:"Yuhuai Wu",institutions:[]},{name:"Lawrence Charles Paulson",institutions:["University of Cambridge"]}],authorString:"Wenda Li; Lei Yu; Yuhuai Wu; Lawrence Charles Paulson",institutions:["University of Cambridge"],countries:[],year:2021,journal:"International Conference on Learning Representations",citations:72,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:6,community:6,deg_w:21.5,betweenness:0,pagerank:83e-5,eigenvector:.0022},{id:512,oaid:"4f42a0782f8b25fff62214e70bc43ce88f914c19",doi:"10.18653/v1/2020.emnlp-main.722",title:"Exploiting Structured Knowledge in Text via Graph-Guided Representation Learning",authors:[{name:"Tao Shen",institutions:[]},{name:"Yi Mao",institutions:[]},{name:"Pengcheng He",institutions:["Microsoft"]},{name:"Guodong Long",institutions:[]},{name:"Adam Trischler",institutions:[]},{name:"Weizhu Chen",institutions:[]}],authorString:"Tao Shen; Yi Mao; Pengcheng He; Guodong Long; Adam Trischler; Weizhu Chen",institutions:["Microsoft"],countries:[],year:2020,journal:"Conference on Empirical Methods in Natural Language Processing",citations:72,abstract:"In this work, we aim at equipping pre-trained language models with structured knowledge. We present two self-supervised tasks learning over raw text with the guidance from knowledge graphs. Building upon entity-level masked language models, our first contribution is an entity masking scheme that exploits relational knowledge underlying the text. This is fulfilled by using a linked knowledge graph to select informative entities and then masking their mentions. In addition we use knowledge graphs to obtain distractors for the masked entities, and propose a novel distractor-suppressed ranking objective which is optimized jointly with masked language model. In contrast to existing paradigms, our approach uses knowledge graphs implicitly, only during pre-training, to inject language models with structured knowledge via learning from raw text. It is more efficient than retrieval-based methods that perform entity linking and integration during finetuning and inference, and generalizes more effectively than the methods that directly learn from concatenated graph triples. Experiments show that our proposed model achieves improved performance on five benchmark datasets, including question answering and knowledge base completion tasks.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.emnlp-main.722.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:1,deg_w:13.5,betweenness:0,pagerank:54e-5,eigenvector:.0166},{id:513,oaid:"f2b0869b17bace854d73c19b449e3f88b9fed82e",doi:"10.48550/arXiv.2203.16747",title:"How Pre-trained Language Models Capture Factual Knowledge? A Causal-Inspired Analysis",authors:[{name:"Shaobo Li",institutions:["Harbin Institute of Technology"]},{name:"Xiaoguang Li",institutions:[]},{name:"Lifeng Shang",institutions:[]},{name:"Zhenhua Dong",institutions:[]},{name:"Chengjie Sun",institutions:["Harbin Institute of Technology"]},{name:"Bingquan Liu",institutions:[]},{name:"Zhenzhou Ji",institutions:[]},{name:"Xin Jiang",institutions:[]},{name:"Qun Liu",institutions:[]}],authorString:"Shaobo Li; Xiaoguang Li; Lifeng Shang; Zhenhua Dong; Chengjie Sun; Bingquan Liu; Zhenzhou Ji; Xin Jiang; Qun Liu",institutions:["Harbin Institute of Technology"],countries:[],year:2022,journal:"Findings",citations:71,abstract:"Recently, there has been a trend to investigate the factual knowledge captured by Pre-trained Language Models (PLMs). Many works show the PLMs’ ability to fill in the missing factual words in cloze-style prompts such as ”Dante was born in [MASK].” However, it is still a mystery how PLMs generate the results correctly: relying on effective clues or shortcut patterns? We try to answer this question by a causal-inspired analysis that quantitatively measures and evaluates the word-level patterns that PLMs depend on to generate the missing words. We check the words that have three typical associations with the missing words: knowledge-dependent, positionally close, and highly co-occurred. Our analysis shows: (1) PLMs generate the missing factual words more by the positionally close and highly co-occurred words than the knowledge-dependent words; (2) the dependence on the knowledge-dependent words is more effective than the positionally close and highly co-occurred words. Accordingly, we conclude that the PLMs capture the factual knowledge ineffectively because of depending on the inadequate associations.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"http://arxiv.org/pdf/2203.16747",is_oa:!0,n_refs:29,n_refs_in_core:0,degree:15,community:1,deg_w:89,betweenness:4e-4,pagerank:.00204,eigenvector:.0725},{id:514,oaid:"c460bfcdd3cda8a787cbfe920dab41136f2dc129",doi:"10.18653/v1/P18-1168",title:"Weakly Supervised Semantic Parsing with Abstract Examples",authors:[{name:"Omer Goldman",institutions:["Bar Ilan University","Google"]},{name:"Veronica Latcinnik",institutions:[]},{name:"Udi Naveh",institutions:[]},{name:"A. Globerson",institutions:[]},{name:"Jonathan Berant",institutions:["Tel-Aviv University and Google DeepMind"]}],authorString:"Omer Goldman; Veronica Latcinnik; Udi Naveh; A. Globerson; Jonathan Berant",institutions:["Bar Ilan University","Google","Tel-Aviv University and Google DeepMind"],countries:[],year:2017,journal:"Annual Meeting of the Association for Computational Linguistics",citations:70,abstract:"Training semantic parsers from weak supervision (denotations) rather than strong supervision (programs) complicates training in two ways. First, a large search space of potential programs needs to be explored at training time to find a correct program. Second, spurious programs that accidentally lead to a correct denotation add noise to training. In this work we propose that in closed worlds with clear semantic types, one can substantially alleviate these problems by utilizing an abstract representation, where tokens in both the language utterance and program are lifted to an abstract form. We show that these abstractions can be defined with a handful of lexical rules and that they result in sharing between different examples that alleviates the difficulties in training. To test our approach, we develop the first semantic parser for CNLVR, a challenging visual reasoning dataset, where the search space is large and overcoming spuriousness is critical, because denotations are either TRUE or FALSE, and thus random programs are likely to lead to a correct denotation. Our method substantially improves performance, and reaches 82.5% accuracy, a 14.7% absolute accuracy improvement compared to the best reported accuracy so far.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/P18-1168.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:5,deg_w:8,betweenness:4e-4,pagerank:47e-5,eigenvector:3e-4},{id:515,oaid:"f6fa98b0d1f6bff608a056acd7b82e2a9dd0a68e",doi:null,title:"Learning to Reason with Third-Order Tensor Products",authors:[{name:"Imanol Schlag",institutions:[]},{name:"J. Schmidhuber",institutions:[]}],authorString:"Imanol Schlag; J. Schmidhuber",institutions:[],countries:[],year:2018,journal:"Neural Information Processing Systems",citations:70,abstract:"We combine Recurrent Neural Networks with Tensor Product Representations to learn combinatorial representations of sequential data. This improves symbolic interpretation and systematic generalisation. Our architecture is trained end-to-end through gradient descent on a variety of simple natural language reasoning tasks, significantly outperforming the latest state-of-the-art models in single-task and all-tasks settings. We also augment a subset of the data such that training and test data exhibit large systematic differences and show that our approach generalises better than the previous state-of-the-art.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:53,n_refs_in_core:3,degree:17,community:2,deg_w:88,betweenness:.0064,pagerank:.00302,eigenvector:7e-4},{id:516,oaid:"58c74cec28f3416b9a1d308bb2d6519d21d53ab0",doi:null,title:"LIME: Learning Inductive Bias for Primitives of Mathematical Reasoning",authors:[{name:"Yuhuai Wu",institutions:[]},{name:"M. Rabe",institutions:[]},{name:"Wenda Li",institutions:[]},{name:"Jimmy Ba",institutions:[]},{name:"R. Grosse",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"Yuhuai Wu; M. Rabe; Wenda Li; Jimmy Ba; R. Grosse; Christian Szegedy",institutions:[],countries:[],year:2021,journal:"International Conference on Machine Learning",citations:70,abstract:`While designing inductive bias in neural architectures has been widely studied, we hypothesize that transformer networks are flexible enough to learn inductive bias from suitable generic tasks. Here, we replace architecture engineering by encoding inductive bias in the form of datasets. Inspired by Peirce's view that deduction, induction, and abduction are the primitives of reasoning, we design three synthetic tasks that are intended to require the model to have these three abilities. We specifically design these tasks to be synthetic and devoid of mathematical knowledge to ensure that only the fundamental reasoning biases can be learned from these tasks. This defines a new pre-training methodology called"LIME"(Learning Inductive bias for Mathematical rEasoning). Models trained with LIME significantly outperform vanilla transformers on four very different large mathematical reasoning benchmarks. Unlike dominating the computation cost as traditional pre-training approaches, LIME requires only a small fraction of the computation cost of the typical downstream task. The code for generating LIME tasks is available at https://github.com/tonywu95/LIME.`,keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:64,n_refs_in_core:17,degree:32,community:6,deg_w:236.5,betweenness:.0198,pagerank:.00637,eigenvector:.0477},{id:517,oaid:"57f6e65a6a475eb764a3dad5e03aa024121d3168",doi:null,title:"Parameter Estimation in Stochastic Logic Programs",authors:[],authorString:"",institutions:[],countries:[],year:2e3,journal:"",citations:70,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:65e-5,eigenvector:0},{id:518,oaid:"0a9325741f2b838a1907688bf073052b24760c47",doi:"10.1609/aaai.v25i1.7852",title:"An Algebraic Prolog for Reasoning about Possible Worlds",authors:[{name:"A. Kimmig",institutions:[]},{name:"Guy Van den Broeck",institutions:["University of California, Los Angeles"]},{name:"L. D. Raedt",institutions:[]}],authorString:"A. Kimmig; Guy Van den Broeck; L. D. Raedt",institutions:["University of California, Los Angeles"],countries:[],year:2011,journal:"AAAI Conference on Artificial Intelligence",citations:69,abstract:"We introduce aProbLog, a generalization of the probabilistic logic programming language ProbLog. An aProbLog program consists of a set of definite clauses and a set of algebraic facts; each such fact is labeled with an element of a semiring. A wide variety of labels is possible, ranging from probability values to reals (representing costs or utilities), polynomials, Boolean functions or data structures. The semiring is then used to calculate labels of possible worlds and of queries. We formally define the semantics of aProbLog and study the aProbLog inference problem, which is concerned with computing the label of a query. Two conditions are introduced that allow one to simplify the inference problem, resulting in four different algorithms and settings. Representative basic problems for each of these four settings are: is there a possible world where a query is true (SAT), how many such possible worlds are there (#SAT), what is the probability of a query being true (PROB), and what is the most likely world where the query is true (MPE). We further illustrate these settings with a number of tasks requiring more complex semirings.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1609/aaai.v25i1.7852",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:0,deg_w:12.5,betweenness:0,pagerank:84e-5,eigenvector:0},{id:519,oaid:"7590b88332bc6ea17051d90f9da2e71246f736c3",doi:"10.4230/LIPIcs.ESA.2018.5",title:"A new and improved algorithm for online bin packing",authors:[{name:"J. Balogh",institutions:[]},{name:"J. Békési",institutions:[]},{name:"G. Dósa",institutions:[]},{name:"L. Epstein",institutions:[]},{name:"Asaf Levin",institutions:[]}],authorString:"J. Balogh; J. Békési; G. Dósa; L. Epstein; Asaf Levin",institutions:[],countries:[],year:2017,journal:"Embedded Systems and Applications",citations:68,abstract:'We revisit the classic online bin packing problem. In this problem, items of positive sizes no larger than 1 are presented one by one to be packed into subsets called "bins" of total sizes no larger than 1, such that every item is assigned to a bin before the next item is presented. We use online partitioning of items into classes based on sizes, as in previous work, but we also apply a new method where items of one class can be packed into more than two types of bins, where a bin type is defined according to the number of such items grouped together. Additionally, we allow the smallest class of items to be packed in multiple kinds of bins, and not only into their own bins. We combine this with the approach of packing of sufficiently big items according to their exact sizes. Finally, we simplify the analysis of such algorithms, allowing the analysis to be based on the most standard weight functions. This simplified analysis allows us to study the algorithm which we defined based on all these ideas. This leads us to the design and analysis of the first algorithm of asymptotic competitive ratio strictly below 1.58, specifically, we break this barrier and provide an algorithm AH (Advanced Harmonic) whose asymptotic competitive ratio does not exceed 1.5783.',keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:26,n_refs_in_core:4,degree:6,community:8,deg_w:35,betweenness:0,pagerank:.00269,eigenvector:1e-4},{id:520,oaid:"7a72fa912d699fc89862823e7f6ec242218b5c53",doi:"10.1017/fms.2017.12",title:"UPPER BOUNDS FOR SUNFLOWER-FREE SETS",authors:[{name:"Eric Naslund",institutions:[]},{name:"W. Sawin",institutions:[]}],authorString:"Eric Naslund; W. Sawin",institutions:[],countries:[],year:2016,journal:"Forum of Mathematics, Sigma",citations:66,abstract:"A collection of $k$ sets is said to form a $k$ -sunflower, or $\\unicode[STIX]{x1D6E5}$ -system, if the intersection of any two sets from the collection is the same, and we call a family of sets ${\\mathcal{F}}$ sunflower-free if it contains no $3$ -sunflowers. Following the recent breakthrough of Ellenberg and Gijswijt (‘On large subsets of $\\mathbb{F}_{q}^{n}$ with no three-term arithmetic progression’, Ann. of Math. (2) 185 (2017), 339–343); (‘Progression-free sets in $\\mathbb{Z}_{4}^{n}$ are exponentially small’, Ann. of Math. (2) 185 (2017), 331–337) we apply the polynomial method directly to Erdős–Szemerédi sunflower problem (Erdős and Szemerédi, ‘Combinatorial properties of systems of sets’, J. Combin. Theory Ser. A 24 (1978), 308–313) and prove that any sunflower-free family ${\\mathcal{F}}$ of subsets of $\\{1,2,\\ldots ,n\\}$ has size at most $$\\begin{eqnarray}|{\\mathcal{F}}|\\leqslant 3n\\mathop{\\sum }_{k\\leqslant n/3}\\binom{n}{k}\\leqslant \\left(\\frac{3}{2^{2/3}}\\right)^{n(1+o(1))}.\\end{eqnarray}$$ We say that a set $A\\subset (\\mathbb{Z}/D\\mathbb{Z})^{n}=\\{1,2,\\ldots ,D\\}^{n}$ for $D>2$ is sunflower-free if for every distinct triple $x,y,z\\in A$ there exists a coordinate $i$ where exactly two of $x_{i},y_{i},z_{i}$ are equal. Using a version of the polynomial method with characters $\\unicode[STIX]{x1D712}:\\mathbb{Z}/D\\mathbb{Z}\\rightarrow \\mathbb{C}$ instead of polynomials, we show that any sunflower-free set $A\\subset (\\mathbb{Z}/D\\mathbb{Z})^{n}$ has size $$\\begin{eqnarray}|A|\\leqslant c_{D}^{n}\\end{eqnarray}$$ where $c_{D}=\\frac{3}{2^{2/3}}(D-1)^{2/3}$ . This can be seen as making further progress on a possible approach to proving the Erdős and Rado sunflower conjecture (‘Intersection theorems for systems of sets’,J. Lond. Math. Soc. (2) 35 (1960), 85–90), which by the work of Alon et al. (‘On sunflowers and matrix multiplication’, Comput. Complexity 22 (2013), 219–243; Theorem 2.6) is equivalent to proving that $c_{D}\\leqslant C$ for some constant $C$ independent of $D$ .",keywords:[],concepts:[],pdf_url:"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/ED7A0DE48541FA919651E4533393CDD8/S2050509417000123a.pdf/div-class-title-upper-bounds-for-sunflower-free-sets-div.pdf",is_oa:!0,n_refs:9,n_refs_in_core:1,degree:2,community:8,deg_w:9.5,betweenness:0,pagerank:84e-5,eigenvector:1e-4},{id:521,oaid:"36da622533db1b55e6e918b81d47b96975d729d7",doi:"10.3115/v1/P15-2019",title:"Learning language through pictures",authors:[{name:"Grzegorz Chrupała",institutions:["Tilburg University"]},{name:"Ákos Kádár",institutions:[]},{name:"A. Alishahi",institutions:[]}],authorString:"Grzegorz Chrupała; Ákos Kádár; A. Alishahi",institutions:["Tilburg University"],countries:[],year:2015,journal:"Annual Meeting of the Association for Computational Linguistics",citations:66,abstract:"We propose Imaginet, a model of learning visually grounded representations of language from coupled textual and visual input. The model consists of two Gated Recurrent Unit networks with shared word embeddings, and uses a multi-task objective by receiving a textual description of a scene and trying to concurrently predict its visual representation and the next word in the sentence. Like humans, it acquires meaning representations for individual words from descriptions of visual scenes. Moreover, it learns to effectively use sequential structure in semantic interpretation of multi-word phrases.",keywords:["Linguistics"],concepts:["Linguistics"],pdf_url:"https://doi.org/10.3115/v1/p15-2019",is_oa:!0,n_refs:37,n_refs_in_core:1,degree:14,community:3,deg_w:83.5,betweenness:.0018,pagerank:.00202,eigenvector:6e-4},{id:522,oaid:"8ad42ba130eb32043603efd5573b6296b84fb982",doi:"10.3115/v1/W14-2409",title:"Low-Dimensional Embeddings of Logic",authors:[{name:"Tim Rocktäschel",institutions:[]},{name:"Matko Bosnjak",institutions:[]},{name:"Sameer Singh",institutions:["University of California, Irvine","Envive AI (fka Spiffy AI)"]},{name:"Sebastian Riedel",institutions:[]}],authorString:"Tim Rocktäschel; Matko Bosnjak; Sameer Singh; Sebastian Riedel",institutions:["Envive AI (fka Spiffy AI)","University of California, Irvine"],countries:[],year:2014,journal:"Annual Meeting of the Association for Computational Linguistics",citations:66,abstract:"Many machine reading approaches, from shallow information extraction to deep semantic parsing, map natural language to symbolic representations of meaning. Representations such as first-order logic capture the richness of natural language and support complex reasoning, but often fail in practice due to their reliance on logical background knowledge and the difficulty of scaling up inference. In contrast, low-dimensional embeddings (i.e. distributional representations) are efficient and enable generalization, but it is unclear how reasoning with embeddings could support the full power of symbolic representations such as first-order logic. In this proof-ofconcept paper we address this by learning embeddings that simulate the behavior of first-order logic.",keywords:["Philosophy"],concepts:["Philosophy"],pdf_url:"https://aclanthology.org/W14-2409.pdf",is_oa:!0,n_refs:20,n_refs_in_core:3,degree:9,community:0,deg_w:48,betweenness:4e-4,pagerank:.0017,eigenvector:.0013},{id:523,oaid:"45bb43cdc35324fea4350ed335c500d4a5fd6ef5",doi:null,title:"Mathematical Reasoning via Self-supervised Skip-tree Training",authors:[{name:"M. Rabe",institutions:[]},{name:"Dennis Lee",institutions:[]},{name:"Kshitij Bansal",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"M. Rabe; Dennis Lee; Kshitij Bansal; Christian Szegedy",institutions:[],countries:[],year:2020,journal:"International Conference on Learning Representations",citations:65,abstract:"",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:6,community:6,deg_w:21.5,betweenness:0,pagerank:83e-5,eigenvector:.0022},{id:524,oaid:"302ae0d991d62dee82b63530b487a50469810af4",doi:"10.1609/aaai.v32i1.12026",title:"Learning Interpretable Spatial Operations in a Rich 3D Blocks World",authors:[{name:"Yonatan Bisk",institutions:["Carnegie Mellon University"]},{name:"Kevin J. Shih",institutions:[]},{name:"Yejin Choi",institutions:[]},{name:"D. Marcu",institutions:[]}],authorString:"Yonatan Bisk; Kevin J. Shih; Yejin Choi; D. Marcu",institutions:["Carnegie Mellon University"],countries:[],year:2017,journal:"AAAI Conference on Artificial Intelligence",citations:65,abstract:"In this paper, we study the problem of mapping natural language instructions to complex spatial actions in a 3D blocks world. We first introduce a new dataset that pairs complex 3D spatial operations to rich natural language descriptions that require complex spatial and pragmatic interpretations such as “mirroring”, “twisting”, and “balancing”. This dataset, built on the simulation environment of Bisk, Yuret, and Marcu (2016), attains language that is significantly richer and more complex, while also doubling the size of the original dataset in the 2D environment with 100 new world configurations and 250,000 tokens. In addition, we propose a new neural architecture that achieves competitive results while automatically discovering an inventory of interpretable spatial operations (Figure 5).",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/12026/11885",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:13.5,betweenness:0,pagerank:59e-5,eigenvector:1e-4},{id:525,oaid:"c32612d39403ade9ef33ae764876f43f833c3a59",doi:"10.1007/978-3-319-23461-8_37",title:"ProbLog2: Probabilistic Logic Programming",authors:[{name:"A. Dries",institutions:[]},{name:"A. Kimmig",institutions:[]},{name:"Wannes Meert",institutions:["KU Leuven"]},{name:"Joris Renkens",institutions:[]},{name:"Guy Van den Broeck",institutions:["University of California, Los Angeles"]},{name:"Jonas Vlasselaer",institutions:[]},{name:"L. D. Raedt",institutions:[]}],authorString:"A. Dries; A. Kimmig; Wannes Meert; Joris Renkens; Guy Van den Broeck; Jonas Vlasselaer; L. D. Raedt",institutions:["KU Leuven","University of California, Los Angeles"],countries:[],year:2015,journal:"ECML/PKDD",citations:61,abstract:"",keywords:[],concepts:[],pdf_url:"https://lirias.kuleuven.be/handle/123456789/510204",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:58e-5,eigenvector:1e-4},{id:526,oaid:"f9c74e8650b74d78e20a8912b7dec185e477c4d1",doi:"10.18653/v1/W16-1309",title:"Learning Knowledge Base Inference with Neural Theorem Provers",authors:[{name:"Tim Rocktäschel",institutions:[]},{name:"Sebastian Riedel",institutions:[]}],authorString:"Tim Rocktäschel; Sebastian Riedel",institutions:[],countries:[],year:2016,journal:"AKBC@NAACL-HLT",citations:61,abstract:"In this paper we present a proof-of-concept implementation of Neural Theorem Provers (NTPs), end-to-end differentiable counterparts of discrete theorem provers that perform first-order inference on vector representations of symbols using function-free, possibly parameterized, rules. As such, NTPs follow a long tradition of neural-symbolic approaches to automated knowledge base inference, but differ in that they are differentiable with respect to representations of symbols in a knowledge base and can thus learn representations of predicates, constants, as well as rules of predefined structure. Furthermore, they still allow us to incorporate domainknowledge provided as rules. The NTP presented here is realized via a differentiable version of the backward chaining algorithm. It operates on substitution representations and is able to learn complex logical dependencies from training facts of small knowledge bases.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.18653/v1/w16-1309",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:4,community:0,deg_w:16.5,betweenness:1e-4,pagerank:84e-5,eigenvector:3e-4},{id:527,oaid:"03488f1a193066b5ea8b9b800e119f07df5c1d9e",doi:"10.18653/v1/2022.emnlp-main.48",title:"Reasoning Like Program Executors",authors:[{name:"Xinyu Pi",institutions:["University of Illinois at Urbana-Champaign"]},{name:"Qian Liu",institutions:["Beihang University","Sea AI Lab"]},{name:"Bei Chen",institutions:[]},{name:"Morteza Ziyadi",institutions:[]},{name:"Zeqi Lin",institutions:[]},{name:"Yan Gao",institutions:[]},{name:"Qiang Fu",institutions:[]},{name:"Jian-Guang Lou",institutions:[]},{name:"Weizhu Chen",institutions:[]}],authorString:"Xinyu Pi; Qian Liu; Bei Chen; Morteza Ziyadi; Zeqi Lin; Yan Gao; Qiang Fu; Jian-Guang Lou; Weizhu Chen",institutions:["Beihang University","Sea AI Lab","University of Illinois at Urbana-Champaign"],countries:[],year:2022,journal:"Conference on Empirical Methods in Natural Language Processing",citations:61,abstract:"Reasoning over natural language is a long-standing goal for the research community. However, studies have shown that existing language models are inadequate in reasoning. To address the issue, we present POET, a novel reasoning pre-training paradigm. Through pre-training language models with programs and their execution results, POET empowers language models to harvest the reasoning knowledge possessed by program executors via a data-driven approach. POET is conceptually simple and can be instantiated by different kinds of program executors. In this paper, we showcase two simple instances POET-Math and POET-Logic, in addition to a complex instance, POET-SQL. Experimental results on six benchmarks demonstrate that POET can significantly boost model performance in natural language reasoning, such as numerical reasoning, logical reasoning, and multi-hop reasoning. POET opens a new gate on reasoning-enhancement pre-training, and we hope our analysis would shed light on the future research of reasoning like program executors.",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2022.emnlp-main.48.pdf",is_oa:!0,n_refs:74,n_refs_in_core:9,degree:24,community:5,deg_w:182,betweenness:.0122,pagerank:.00495,eigenvector:.0647},{id:528,oaid:"826b2efc9e3f563e9aa1845e5f88ea725bcefd9e",doi:null,title:"PixL2R: Guiding Reinforcement Learning Using Natural Language by Mapping Pixels to Rewards",authors:[{name:"P. Goyal",institutions:[]},{name:"S. Niekum",institutions:[]},{name:"R. Mooney",institutions:[]}],authorString:"P. Goyal; S. Niekum; R. Mooney",institutions:[],countries:[],year:2020,journal:"Conference on Robot Learning",citations:61,abstract:"Reinforcement learning (RL), particularly in sparse reward settings, often requires prohibitively large numbers of interactions with the environment, thereby limiting its applicability to complex problems. To address this, several prior approaches have used natural language to guide the agent's exploration. However, these approaches typically operate on structured representations of the environment, and/or assume some structure in the natural language commands. In this work, we propose a model that directly maps pixels to rewards, given a free-form natural language description of the task, which can then be used for policy learning. Our experiments on the Meta-World robot manipulation domain show that language-based rewards significantly improves the sample efficiency of policy learning, both in sparse and dense reward settings.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:4,deg_w:8.5,betweenness:0,pagerank:48e-5,eigenvector:2e-4},{id:529,oaid:"92795b26fd1ebc8b91fe286d27380a4bd639c178",doi:null,title:"Lifted Relational Neural Networks",authors:[{name:"Gustav Sourek",institutions:["Czech Technical University in Prague"]},{name:"Vojtech Aschenbrenner",institutions:[]},{name:"F. Železný",institutions:[]},{name:"Ondřej Kuželka",institutions:[]}],authorString:"Gustav Sourek; Vojtech Aschenbrenner; F. Železný; Ondřej Kuželka",institutions:["Czech Technical University in Prague"],countries:[],year:2015,journal:"CoCo@NIPS",citations:60,abstract:"We propose a method combining relational-logic representations with neural network learning. A general lifted architecture, possibly reflecting some background domain knowledge, is described through relational rules which may be handcrafted or learned. The relational rule-set serves as a template for unfolding possibly deep neural networks whose structures also reflect the structures of given training or testing relational examples. Different networks corresponding to different examples share their weights, which co-evolve during training by stochastic gradient descent algorithm. The framework allows for hierarchical relational modeling constructs and learning of latent relational concepts through shared hidden layers weights corresponding to the rules. Discovery of notable relational concepts and experiments on 78 relational learning benchmarks demonstrate favorable performance of the method.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:4,community:0,deg_w:17.5,betweenness:0,pagerank:92e-5,eigenvector:2e-4},{id:530,oaid:"dfba20af7aacd819e7b22cf2bf189cd7af9da0a1",doi:null,title:"Enhancing the Transformer with Explicit Relational Encoding for Math Problem Solving",authors:[{name:"Imanol Schlag",institutions:[]},{name:"P. Smolensky",institutions:[]},{name:"Roland Fernandez",institutions:[]},{name:"N. Jojic",institutions:[]},{name:"J. Schmidhuber",institutions:[]},{name:"Jianfeng Gao",institutions:[]}],authorString:"Imanol Schlag; P. Smolensky; Roland Fernandez; N. Jojic; J. Schmidhuber; Jianfeng Gao",institutions:[],countries:[],year:2019,journal:"arXiv.org",citations:60,abstract:"We incorporate Tensor-Product Representations within the Transformer in order to better support the explicit representation of relation structure. Our Tensor-Product Transformer (TP-Transformer) sets a new state of the art on the recently-introduced Mathematics Dataset containing 56 categories of free-form math word-problems. The essential component of the model is a novel attention mechanism, called TP-Attention, which explicitly encodes the relations between each Transformer cell and the other cells from which values have been retrieved by attention. TP-Attention goes beyond linear combination of retrieved values, strengthening representation-building and resolving ambiguities introduced by multiple layers of standard attention. The TP-Transformer's attention maps give better insights into how it is capable of solving the Mathematics Dataset's challenging problems. Pretrained models and code will be made available after publication.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:2,deg_w:8,betweenness:5e-4,pagerank:55e-5,eigenvector:8e-4},{id:531,oaid:"ea3e363b222c28abc695877de50a9929744eb2c8",doi:null,title:"Learning to Prove Theorems by Learning to Generate Theorems",authors:[{name:"Mingzhe Wang",institutions:[]},{name:"Jia Deng",institutions:[]}],authorString:"Mingzhe Wang; Jia Deng",institutions:[],countries:[],year:2020,journal:"Neural Information Processing Systems",citations:59,abstract:"We consider the task of automated theorem proving, a key AI task. Deep learning has shown promise for training theorem provers, but there are limited human-written theorems and proofs available for supervised learning. To address this limitation, we propose to learn a neural generator that automatically synthesizes theorems and proofs for the purpose of training a theorem prover. Experiments on real-world tasks demonstrate that synthetic data from our approach improves the theorem prover and advances the state of the art of automated theorem proving in Metamath.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:6,deg_w:8,betweenness:0,pagerank:5e-4,eigenvector:6e-4},{id:532,oaid:"290867638c5ca520de5c48aa4336f196d426c226",doi:null,title:"Knowledge Enhanced Pretrained Language Models: A Compreshensive Survey",authors:[{name:"Xiaokai Wei",institutions:[]},{name:"Shen Wang",institutions:[]},{name:"Dejiao Zhang",institutions:[]},{name:"Parminder Bhatia",institutions:[]},{name:"Andrew O. Arnold",institutions:[]}],authorString:"Xiaokai Wei; Shen Wang; Dejiao Zhang; Parminder Bhatia; Andrew O. Arnold",institutions:[],countries:[],year:2021,journal:"arXiv.org",citations:58,abstract:"Pretrained Language Models (PLM) have established a new paradigm through learning informative contextualized representations on large-scale text corpus. This new paradigm has revolutionized the entire field of natural language processing, and set the new state-of-the-art performance for a wide variety of NLP tasks. However, though PLMs could store certain knowledge/facts from training corpus, their knowledge awareness is still far from satisfactory. To address this issue, integrating knowledge into PLMs have recently become a very active research area and a variety of approaches have been developed. In this paper, we provide a comprehensive survey of the literature on this emerging and fast-growing field - Knowledge Enhanced Pretrained Language Models (KE-PLMs). We introduce three taxonomies to categorize existing work. Besides, we also survey the various NLU and NLG applications on which KE-PLM has demonstrated superior performance over vanilla PLMs. Finally, we discuss challenges that face KE-PLMs and also promising directions for future research.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:107,n_refs_in_core:16,degree:32,community:1,deg_w:468,betweenness:.0033,pagerank:.00944,eigenvector:.3497},{id:533,oaid:"96eed42e813bc074fce623c884923a67e3c9e63e",doi:"10.1007/978-3-030-01258-8_6",title:"Interpretable Intuitive Physics Model",authors:[{name:"Tian Ye",institutions:[]},{name:"X. Wang",institutions:[]},{name:"James Davidson",institutions:[]},{name:"A. Gupta",institutions:[]}],authorString:"Tian Ye; X. Wang; James Davidson; A. Gupta",institutions:[],countries:[],year:2018,journal:"European Conference on Computer Vision",citations:58,abstract:"Humans have a remarkable ability to use physical commonsense and predict the effect of collisions. But do they understand the underlying factors? Can they predict if the underlying factors have changed? Interestingly, in most cases humans can predict the effects of similar collisions with different conditions such as changes in mass, friction, etc. It is postulated this is primarily because we learn to model physics with meaningful latent variables. This does not imply we can estimate the precise values of these meaningful variables (estimate exact values of mass or friction). Inspired by this observation, we propose an interpretable intuitive physics model where specific dimensions in the bottleneck layers correspond to different physical properties. In order to demonstrate that our system models these underlying physical properties, we train our model on collisions of different shapes (cube, cone, cylinder, spheres etc.) and test on collisions of unseen combinations of shapes. Furthermore, we demonstrate our model generalizes well even when similar scenes are simulated with different underlying properties.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1808.10002",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:1e-4},{id:534,oaid:"6a2106628da2710b7a79f35f66dfd1cc015f14ae",doi:"10.24963/ijcai.2019/847",title:"Synthesizing Datalog Programs Using Numerical Relaxation",authors:[{name:"X. Si",institutions:[]},{name:"Mukund Raghothaman",institutions:[]},{name:"K. Heo",institutions:[]},{name:"M. Naik",institutions:[]}],authorString:"X. Si; Mukund Raghothaman; K. Heo; M. Naik",institutions:[],countries:[],year:2019,journal:"International Joint Conference on Artificial Intelligence",citations:58,abstract:"The problem of learning logical rules from examples arises in diverse fields, including program synthesis, logic programming, and machine learning. Existing approaches either involve solving computationally difficult combinatorial problems, or performing parameter estimation in complex statistical models. In this paper, we present Difflog, a technique to extend the logic programming language Datalog to the continuous setting. By attaching real-valued weights to individual rules of a Datalog program, we naturally associate numerical values with individual conclusions of the program. Analogous to the strategy of numerical relaxation in optimization problems, we can now first determine the rule weights which cause the best agreement between the training labels and the induced values of output tuples, and subsequently recover the classical discrete-valued target program from the continuous optimum. We evaluate Difflog on a suite of 34~benchmark problems from recent literature in knowledge discovery, formal verification, and database query-by-example, and demonstrate significant improvements in learning complex programs with recursive rules, invented predicates, and relations of arbitrary arity.",keywords:[],concepts:[],pdf_url:"https://www.ijcai.org/proceedings/2019/0847.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8,betweenness:0,pagerank:65e-5,eigenvector:1e-4},{id:535,oaid:"0e9690cab55899facd81eb32f6e0c0f72d70582a",doi:"10.1609/aaai.v32i1.12111",title:"RelNN: A Deep Neural Model for Relational Learning",authors:[{name:"Seyed Mehran Kazemi",institutions:[]},{name:"D. Poole",institutions:[]}],authorString:"Seyed Mehran Kazemi; D. Poole",institutions:[],countries:[],year:2017,journal:"AAAI Conference on Artificial Intelligence",citations:55,abstract:"Statistical relational AI (StarAI) aims at reasoning and learning in noisy domains described in terms of objects and relationships by combining probability with first-order logic. With huge advances in deep learning in the current years, combining deep networks with first-order logic has been the focus of several recent studies. Many of the existing attempts, however, only focus on relations and ignore object properties. The attempts that do consider object properties are limited in terms of modelling power or scalability. In this paper, we develop relational neural networks (RelNNs) by adding hidden layers to relational logistic regression (the relational counterpart of logistic regression). We learn latent properties for objects both directly and through general rules. Back-propagation is used for training these models. A modular, layer-wise architecture facilitates utilizing the techniques developed within deep learning community to our architecture. Initial experiments on eight tasks over three real-world datasets show that RelNNs are promising models for relational learning.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1609/aaai.v32i1.12111",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:0,deg_w:8.5,betweenness:0,pagerank:63e-5,eigenvector:0},{id:536,oaid:"0c41d7cfadcdaa5a66694bd57fa5eaf807043ef9",doi:"10.1609/aaai.v32i1.11324",title:"Explicit Reasoning over End-to-End Neural Architectures for Visual Question Answering",authors:[{name:"Somak Aditya",institutions:["Indian Institute of Technology, Kharagpur"]},{name:"Yezhou Yang",institutions:["Arizona State University"]},{name:"Chitta Baral",institutions:["Arizona State University"]}],authorString:"Somak Aditya; Yezhou Yang; Chitta Baral",institutions:["Arizona State University","Indian Institute of Technology, Kharagpur"],countries:[],year:2018,journal:"AAAI Conference on Artificial Intelligence",citations:55,abstract:"Many vision and language tasks require commonsense reasoning beyond data-driven image and natural language processing. Here we adopt Visual Question Answering (VQA) as an example task, where a system is expected to answer a question in natural language about an image. Current state-of-the-art systems attempted to solve the task using deep neural architectures and achieved promising performance. However, the resulting systems are generally opaque and they struggle in understanding questions for which extra knowledge is required. In this paper, we present an explicit reasoning layer on top of a set of penultimate neural network based systems. The reasoning layer enables reasoning and answering questions where additional knowledge is required, and at the same time provides an interpretable interface to the end users. Specifically, the reasoning layer adopts a Probabilistic Soft Logic (PSL) based engine to reason over a basket of inputs: visual relations, the semantic parse of the question, and background ontological knowledge from word2vec and ConceptNet. Experimental analysis of the answers and the key evidential predicates generated on the VQA dataset validate our approach.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1609/aaai.v32i1.11324",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:47e-5,eigenvector:1e-4},{id:537,oaid:"87126a964ed14d0d2207747fc732b197e2fc9493",doi:"10.48550/arXiv.2212.02027",title:"Retrieval as Attention: End-to-end Learning of Retrieval and Reading within a Single Transformer",authors:[{name:"Zhengbao Jiang",institutions:[]},{name:"Luyu Gao",institutions:[]},{name:"J. Araki",institutions:[]},{name:"Haibo Ding",institutions:[]},{name:"Zhiruo Wang",institutions:[]},{name:"Jamie Callan",institutions:["Carnegie Mellon University"]},{name:"Graham Neubig",institutions:[]}],authorString:"Zhengbao Jiang; Luyu Gao; J. Araki; Haibo Ding; Zhiruo Wang; Jamie Callan; Graham Neubig",institutions:["Carnegie Mellon University"],countries:[],year:2022,journal:"Conference on Empirical Methods in Natural Language Processing",citations:54,abstract:"Systems for knowledge-intensive tasks such as open-domain question answering (QA) usually consist of two stages: efficient retrieval of relevant documents from a large corpus and detailed reading of the selected documents. This is usually done through two separate models, a retriever that encodes the query and finds nearest neighbors, and a reader based on Transformers. These two components are usually modeled separately, which necessitates a cumbersome implementation and is awkward to optimize in an end-to-end fashion. In this paper, we revisit this design and eschew the separate architecture and training in favor of a single Transformer that performs retrieval as attention (RAA), and end-to-end training solely based on supervision from the end QA task. We demonstrate for the first time that an end-to-end trained single Transformer can achieve both competitive retrieval and QA performance on in-domain datasets, matching or even slightly outperforming state-of-the-art dense retrievers and readers. Moreover, end-to-end adaptation of our model significantly boosts its performance on out-of-domain datasets in both supervised and unsupervised settings, making our model a simple and adaptable end-to-end solution for knowledge-intensive tasks.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/2212.02027",is_oa:!0,n_refs:49,n_refs_in_core:3,degree:10,community:1,deg_w:92,betweenness:1e-4,pagerank:.00227,eigenvector:.0256},{id:538,oaid:"8a79a876d65cdaf10244e0def2f5a36f34aecdb7",doi:null,title:"SCAN: Learning Abstract Hierarchical Compositional Visual Concepts",authors:[{name:"I. Higgins",institutions:[]},{name:"Nicolas Sonnerat",institutions:[]},{name:"L. Matthey",institutions:[]},{name:"Arka Pal",institutions:[]},{name:"Christopher P. Burgess",institutions:[]},{name:"M. Botvinick",institutions:[]},{name:"D. Hassabis",institutions:[]},{name:"Alexander Lerchner",institutions:["DeepMind"]}],authorString:"I. Higgins; Nicolas Sonnerat; L. Matthey; Arka Pal; Christopher P. Burgess; M. Botvinick; D. Hassabis; Alexander Lerchner",institutions:["DeepMind"],countries:[],year:2017,journal:"arXiv.org",citations:53,abstract:"The natural world is infinitely diverse, yet this diversity arises from a relatively small set of coherent properties and rules, such as the laws of physics or chemistry. We conjecture that biological intelligent systems are able to survive within their diverse environments by discovering the regularities that arise from these rules primarily through unsupervised experiences, and representing this knowledge as abstract concepts. Such representations possess useful properties of compositionality and hierarchical organisation, which allow intelligent agents to recombine a finite set of conceptual building blocks into an exponentially large set of useful new concepts. This paper describes SCAN (Symbol-Concept Association Network), a new framework for learning such concepts in the visual domain. We first use the previously published beta-VAE (Higgins et al., 2017a) architecture to learn a disentangled representation of the latent structure of the visual world, before training SCAN to extract abstract concepts grounded in such disentangled visual primitives through fast symbol association. Our approach requires very few pairings between symbols and images and makes no assumptions about the choice of symbol representations. Once trained, SCAN is capable of multimodal bi-directional inference, generating a diverse set of image samples from symbolic descriptions and vice versa. It also allows for traversal and manipulation of the implicit hierarchy of compositional visual concepts through symbolic instructions and learnt logical recombination operations. Such manipulations enable SCAN to invent and learn novel visual concepts through recombination of the few learnt concepts.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:3,community:3,deg_w:13.5,betweenness:0,pagerank:58e-5,eigenvector:1e-4},{id:539,oaid:"582b1f5c08f79d0d62e41a9c0b1185f3e7292e4e",doi:"10.18653/V1/2020.COLING-MAIN.217",title:"GenWiki: A Dataset of 1.3 Million Content-Sharing Text and Graphs for Unsupervised Graph-to-Text Generation",authors:[{name:"Zhijing Jin",institutions:[]},{name:"Qipeng Guo",institutions:["Fudan University"]},{name:"Xipeng Qiu",institutions:["Fudan University"]},{name:"Zheng Zhang",institutions:[]}],authorString:"Zhijing Jin; Qipeng Guo; Xipeng Qiu; Zheng Zhang",institutions:["Fudan University"],countries:[],year:2020,journal:"International Conference on Computational Linguistics",citations:49,abstract:"Data collection for the knowledge graph-to-text generation is expensive. As a result, research on unsupervised models has emerged as an active field recently. However, most unsupervised models have to use non-parallel versions of existing small supervised datasets, which largely constrain their potential. In this paper, we propose a large-scale, general-domain dataset, GenWiki. Our unsupervised dataset has 1.3M text and graph examples, respectively. With a human-annotated test set, we provide this new benchmark dataset for future research on unsupervised text generation from knowledge graphs.",keywords:[],concepts:[],pdf_url:"https://www.aclweb.org/anthology/2020.coling-main.217.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:.0081},{id:540,oaid:"56c549b785137c37264f4c7404fdd289c5eebe96",doi:"10.1137/1.9781611973730.94",title:"The optimal absolute ratio for online bin packing",authors:[{name:"J. Balogh",institutions:[]},{name:"J. Békési",institutions:[]},{name:"G. Dósa",institutions:[]},{name:"J. Sgall",institutions:[]},{name:"R. V. Stee",institutions:[]}],authorString:"J. Balogh; J. Békési; G. Dósa; J. Sgall; R. V. Stee",institutions:[],countries:[],year:2015,journal:"ACM-SIAM Symposium on Discrete Algorithms",citations:47,abstract:"We present an online bin packing algorithm with absolute competitive ratio 5/3, which is optimal.",keywords:[],concepts:[],pdf_url:"https://doi.org/10.1016/j.jcss.2018.11.005",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:8,deg_w:8.5,betweenness:0,pagerank:79e-5,eigenvector:0},{id:541,oaid:"a2a25a4c7b6b675332e4bacc0cc88b680bba2619",doi:"10.24963/ijcai.2022/635",title:"Online Bin Packing with Predictions",authors:[{name:"Spyros Angelopoulos",institutions:["CNRS"]},{name:"Shahin Kamali",institutions:[]},{name:"Kimia Shadkami",institutions:[]}],authorString:"Spyros Angelopoulos; Shahin Kamali; Kimia Shadkami",institutions:["CNRS"],countries:[],year:2021,journal:"International Joint Conference on Artificial Intelligence",citations:45,abstract:"Bin packing is a classic optimization problem with a wide range of applications from load balancing to supply chain management. In this work, we study the online variant of the problem, in which a sequence of items of various sizes must be placed into a minimum number of bins of uniform capacity. The online algorithm is enhanced with a (potentially erroneous) prediction concerning the frequency of item sizes in the sequence. We design and analyze online algorithms with efficient tradeoffs between the consistency (i.e., the competitive ratio assuming no prediction error) and the robustness (i.e., the competitive ratio under adversarial error), and whose performance degrades near-optimally as a function of the prediction error. This is the first theoretical and experimental study of online bin packing in the realistic setting of learnable predictions. Previous work addressed only extreme cases with respect to the prediction error, and relied on overly powerful and error-free oracles.",keywords:[],concepts:[],pdf_url:"https://jair.org/index.php/jair/article/download/14820/26993",is_oa:!0,n_refs:72,n_refs_in_core:3,degree:4,community:8,deg_w:25.5,betweenness:0,pagerank:.00195,eigenvector:1e-4},{id:542,oaid:"689ccf061a30494bc907c9ccca8b869be4a74564",doi:null,title:"Learning to Reason in Large Theories without Imitation",authors:[{name:"Kshitij Bansal",institutions:[]},{name:"Sarah M. Loos",institutions:[]},{name:"M. Rabe",institutions:[]},{name:"Christian Szegedy",institutions:[]}],authorString:"Kshitij Bansal; Sarah M. Loos; M. Rabe; Christian Szegedy",institutions:[],countries:[],year:2019,journal:"arXiv.org",citations:45,abstract:"In this paper, we demonstrate how to do automated theorem proving in the presence of a large knowledge base of potential premises without learning from human proofs. We suggest an exploration mechanism that mixes in additional premises selected by a tf-idf (term frequency-inverse document frequency) based lookup in a deep reinforcement learning scenario. This helps with exploring and learning which premises are relevant for proving a new theorem. Our experiments show that the theorem prover trained with this exploration mechanism outperforms provers that are trained only on human proofs. It approaches the performance of a prover trained by a combination of imitation and reinforcement learning. We perform multiple experiments to understand the importance of the underlying assumptions that make our exploration approach work, thus explaining our design choices.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:28,n_refs_in_core:7,degree:12,community:6,deg_w:104,betweenness:4e-4,pagerank:.00299,eigenvector:.0046},{id:543,oaid:"f1b7ea4a5c657ec359a12f619f877e36b70c0d13",doi:null,title:"Learning abstract structure for drawing by efficient motor program induction",authors:[{name:"Lucas Y. Tian",institutions:[]},{name:"Kevin Ellis",institutions:[]},{name:"Marta Kryven",institutions:[]},{name:"J. Tenenbaum",institutions:[]}],authorString:"Lucas Y. Tian; Kevin Ellis; Marta Kryven; J. Tenenbaum",institutions:[],countries:[],year:2020,journal:"Neural Information Processing Systems",citations:45,abstract:"Humans flexibly solve new problems that differ qualitatively from those they were trained on. This ability to generalize is supported by learned concepts that capture structure common across different problems. Here we develop a naturalistic drawing task to study how humans rapidly acquire structured prior knowledge. The task requires drawing visual objects that share underlying structure, based on a set of composable geometric rules. We show that people spontaneously learn abstract drawing procedures that support generalization, and propose a model of how learners can discover these reusable drawing programs. Trained in the same setting as humans, and constrained to produce efficient motor actions, this model discovers new drawing routines that transfer to test objects and resemble learned features of human sequences. These results suggest that two principles guiding motor program induction in the model - abstraction (general programs that ignore object-specific details) and compositionality (recombining previously learned programs) - are key for explaining how humans learn structured internal representations that guide flexible reasoning and learning.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:58e-5,eigenvector:1e-4},{id:544,oaid:"9d4b8ea985670b70de79059ff10d1272100f025b",doi:"10.1155/2019/9202457",title:"Anticipating Stock Market of the Renowned Companies: A Knowledge Graph Approach",authors:[{name:"Yang Liu",institutions:[]},{name:"Qingguo Zeng",institutions:[]},{name:"Joaquín B. Ordieres Meré",institutions:[]},{name:"Huanrui Yang",institutions:[]}],authorString:"Yang Liu; Qingguo Zeng; Joaquín B. Ordieres Meré; Huanrui Yang",institutions:[],countries:[],year:2019,journal:"Complex",citations:44,abstract:"An increasing number of the renowned company’s investors are turning attention to stock prediction in the search for new efficient ways of hypothesizing about markets through the application of behavioral finance. Accordingly, research on stock prediction is becoming a popular direction in academia and industry. In this study, the goal is to establish a model for predicting stock price movement through knowledge graph from the financial news of the renowned companies. In contrast to traditional methods of stock prediction, our approach considers the effects of event tuple characteristics on stocks on the basis of knowledge graph and deep learning. The proposed model and other feature selection models were used to perform feature extraction on the websites of Thomson Reuters and Cable News Network. Numerous experiments were conducted to derive evidence of the effectiveness of knowledge graph embedding for classification tasks in stock prediction. A comparison of the average accuracy with which the same feature combinations were extracted over six stocks indicated that the proposed method achieves better performance than that exhibited by an approach that uses only stock data, a bag-of-words method, and convolutional neural network. Our work highlights the usefulness of knowledge graph in implementing business activities and helping practitioners and managers make business decisions.",keywords:[],concepts:[],pdf_url:"https://downloads.hindawi.com/journals/complexity/2019/9202457.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:62e-5,eigenvector:.0056},{id:545,oaid:"0d16c41b4225c60f8312033dedfa43397e4d30f5",doi:"10.4204/EPTCS.260.9",title:"SyGuS-Comp 2017: Results and Analysis",authors:[{name:"R. Alur",institutions:[]},{name:"D. Fisman",institutions:[]},{name:"Rishabh Singh",institutions:[]},{name:"Armando Solar-Lezama",institutions:[]}],authorString:"R. Alur; D. Fisman; Rishabh Singh; Armando Solar-Lezama",institutions:[],countries:[],year:2017,journal:"SYNT@CAV",citations:42,abstract:"Syntax-Guided Synthesis (SyGuS) is the computational problem of finding an implementation f that meets both a semantic constraint given by a logical formula phi in a background theory T, and a syntactic constraint given by a grammar G, which specifies the allowed set of candidate implementations. Such a synthesis problem can be formally defined in SyGuS-IF, a language that is built on top of SMT-LIB. The Syntax-Guided Synthesis Competition (SyGuS-Comp) is an effort to facilitate, bring together and accelerate research and development of efficient solvers for SyGuS by providing a platform for evaluating different synthesis techniques on a comprehensive set of benchmarks. In this year's competition six new solvers competed on over 1500 benchmarks. This paper presents and analyses the results of SyGuS-Comp'17.",keywords:[],concepts:[],pdf_url:"https://arxiv.org/pdf/1711.11438",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:7,deg_w:8.5,betweenness:0,pagerank:69e-5,eigenvector:0},{id:546,oaid:"54b804fd5511a431bbeb49accd21152296dcad67",doi:null,title:"E-BERT: A Phrase and Product Knowledge Enhanced Language Model for E-commerce",authors:[{name:"Denghui Zhang",institutions:[]},{name:"Zixuan Yuan",institutions:[]},{name:"Yanchi Liu",institutions:[]},{name:"Fuzhen Zhuang",institutions:[]},{name:"Hui Xiong",institutions:[]}],authorString:"Denghui Zhang; Zixuan Yuan; Yanchi Liu; Fuzhen Zhuang; Hui Xiong",institutions:[],countries:[],year:2020,journal:"",citations:41,abstract:"Pre-trained language models such as BERT have achieved great success in a broad range of natural language processing tasks. However, BERT cannot well support E-commerce related tasks due to the lack of two levels of domain knowledge, i.e., phrase-level and product-level. On one hand, many E-commerce tasks require an accurate understanding of domain phrases, whereas such fine-grained phrase-level knowledge is not explicitly modeled by BERT's training objective. On the other hand, product-level knowledge like product associations can enhance the language modeling of E-commerce, but they are not factual knowledge thus using them indiscriminately may introduce noise. To tackle the problem, we propose a unified pre-training framework, namely, E-BERT. Specifically, to preserve phrase-level knowledge, we introduce Adaptive Hybrid Masking, which allows the model to adaptively switch from learning preliminary word knowledge to learning complex phrases, based on the fitting progress of two modes. To utilize product-level knowledge, we introduce Neighbor Product Reconstruction, which trains E-BERT to predict a product's associated neighbors with a denoising cross attention layer. Our investigation reveals promising results in four downstream tasks, i.e., review-based question answering, aspect extraction, aspect sentiment classification, and product classification.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8.5,betweenness:0,pagerank:45e-5,eigenvector:.0117},{id:547,oaid:"cbfbe1da18b559a74c818c61b3994168e5f6c1e1",doi:"10.18653/v1/2021.emnlp-main.604",title:"Highly Parallel Autoregressive Entity Linking with Discriminative Correction",authors:[{name:"Nicola De Cao",institutions:["The University of Edinburgh","University of Amsterdam"]},{name:"Wilker Aziz",institutions:["University of Amsterdam"]},{name:"Ivan Titov",institutions:[]}],authorString:"Nicola De Cao; Wilker Aziz; Ivan Titov",institutions:["The University of Edinburgh","University of Amsterdam"],countries:[],year:2021,journal:"Conference on Empirical Methods in Natural Language Processing",citations:41,abstract:"Generative approaches have been recently shown to be effective for both Entity Disambiguation and Entity Linking (i.e., joint mention detection and disambiguation). However, the previously proposed autoregressive formulation for EL suffers from i) high computational cost due to a complex (deep) decoder, ii) non-parallelizable decoding that scales with the source sequence length, and iii) the need for training on a large amount of data. In this work, we propose a very efficient approach that parallelizes autoregressive linking across all potential mentions and relies on a shallow and efficient decoder. Moreover, we augment the generative objective with an extra discriminative component, i.e., a correction term which lets us directly optimize the generator’s ranking. When taken together, these techniques tackle all the above issues: our model is >70 times faster and more accurate than the previous generative method, outperforming state-of-the-art approaches on the standard English dataset AIDA-CoNLL. Source code available at https://github.com/nicola-decao/efficient-autoregressive-EL",keywords:[],concepts:[],pdf_url:"https://aclanthology.org/2021.emnlp-main.604.pdf",is_oa:!0,n_refs:0,n_refs_in_core:0,degree:2,community:1,deg_w:8,betweenness:0,pagerank:46e-5,eigenvector:.0064},{id:548,oaid:"637648198f9e91654ce27eaaa40512f2dc870fc1",doi:null,title:"Survey of Visual Question Answering: Datasets and Techniques",authors:[{name:"A. Gupta",institutions:[]}],authorString:"A. Gupta",institutions:[],countries:[],year:2017,journal:"arXiv.org",citations:40,abstract:"Visual question answering (or VQA) is a new and exciting problem that combines natural language processing and computer vision techniques. We present a survey of the various datasets and models that have been used to tackle this task. The first part of the survey details the various datasets for VQA and compares them along some common factors. The second part of this survey details the different approaches for VQA, classified into four types: non-deep learning models, deep learning models without attention, deep learning models with attention, and other models which do not fit into the first three. Finally, we compare the performances of these approaches and provide some directions for future work.",keywords:[],concepts:[],pdf_url:"",is_oa:!1,n_refs:0,n_refs_in_core:0,degree:2,community:3,deg_w:8.5,betweenness:0,pagerank:46e-5,eigenvector:1e-4},{id:549,oaid:"2fab75cfd8394de70bca365572bc5bb04a1b1eb5",doi:"10.1609/aaai.v36i10.21425",title:"DKPLM: Decomposable Knowledge-enhanced Pre-trained Language Model for Natural Language Understanding",authors:[{name:"Taolin Zhang",institutions:[]},{name:"Chengyu Wang",institutions:[]},{name:"Nan Hu",institutions:[]},{name:"Minghui Qiu",institutions:[]},{name:"Chengguang Tang",institutions:[]},{name:"Xiaofeng He",institutions:[]},{name:"Jun Huang",institutions:[]}],authorString:"Taolin Zhang; Chengyu Wang; Nan Hu; Minghui Qiu; Chengguang Tang; Xiaofeng He; Jun Huang",institutions:[],countries:[],year:2021,journal:"AAAI Conference on Artificial Intelligence",citations:40,abstract:"Knowledge-Enhanced Pre-trained Language Models (KEPLMs) are pre-trained models with relation triples injecting from knowledge graphs to improve language understanding abilities.Experiments show that our model outperforms other KEPLMs significantly over zero-shot knowledge probing tasks and multiple knowledge-aware language understanding tasks. To guarantee effective knowledge injection, previous studies integrate models with knowledge encoders for representing knowledge retrieved from knowledge graphs. The operations for knowledge retrieval and encoding bring significant computational burdens, restricting the usage of such models in real-world applications that require high inference speed. In this paper, we propose a novel KEPLM named DKPLM that decomposes knowledge injection process of the pre-trained language models in pre-training, fine-tuning and inference stages, which facilitates the applications of KEPLMs in real-world scenarios. Specifically, we first detect knowledge-aware long-tail entities as the target for knowledge injection, enhancing the KEPLMs' semantic understanding abilities and avoiding injecting redundant information. The embeddings of long-tail entities are replaced by ``pseudo token representations'' formed by relevant knowledge triples. We further design the relational knowledge decoding task for pre-training to force the models to truly understand the injected knowledge by relation triple reconstruction. Experiments show that our model outperforms other KEPLMs significantly over zero-shot knowledge probing tasks and multiple knowledge-aware language understanding tasks. We further show that DKPLM has a higher inference speed than other competing models due to the decomposing mechanism.",keywords:[],concepts:[],pdf_url:"https://ojs.aaai.org/index.php/AAAI/article/download/21425/21174",is_oa:!0,n_refs:42,n_refs_in_core:5,degree:21,community:1,deg_w:220,betweenness:5e-4,pagerank:.00435,eigenvector:.1971}],n={n_papers:550,papers_with_refs:213,mean_refs:21.3,direct_citation_edges:1433,coupling_edges_kept:879,total_edges_kept:2353,data_mode:"co-citation",reference_source:"OpenAlex referenced_works"},t={papers:e,completeness:n};export{n as completeness,t as default,e as papers};
